body:
[Lemma lem:allbutone of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] Let $a,\delta>0$ and let $J$ be a kernel such that
    if $j$ is sufficiently large then $J(e) \geq (a+\delta) L\log(j)L^{-2j}$  for every edge $e$ with $|e|=L^j$. Then there exists $k_0 = k_0(\delta, L) < \infty$ such that for all $k \geq k_0$ there exists $N =N(k,J)$ and $C=C(k,J)$ such that
	\begin{align}
		\mathbb{P}_{J} \left( \Lambda_{n,n+k}\setminus\{\Lambda_n(0)\} \textnormal{ is not connected off $\Lambda_n(0)$ in $\omega_{n,n+k}$} \right)
		\leq C n^{-\frac{a}{2}}.
	\end{align}
 for all $n \geq N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi def_ALKYUtility of arXiv:2411.16464, 'Generating social networks with static and dynamic utility-maximization approaches'] We consider the set $\mathcal{U}^{\text{ALKY}}_I$ of applications $U : [0,1)^{I-1} \times (\mathbb{R}^{*}_{+})^{I-1} \longrightarrow \mathbb{R}$:
\begin{equation*}
    \begin{split}
\mathcal{U}^{\text{ALKY}}_I = \left\{\kappa>1, \gamma>1, \delta>1, \right. \\ U\left(\alpha, c \right)= \left. \sum^{I-1}_{j=1} \left[ \kappa \alpha_{j} c_{j} - \frac{\alpha_{j}^{\gamma}}{1-\alpha_{j}^{\gamma}} \right] - \left( \sum^{I-1}_{j=1} \alpha_{j} \right)^{\delta}\right\}    
\end{split}
\end{equation*}

[Lemma 7 (Large increment correlation bound) of arXiv:2606.04179, 'Functional Scaling Limits of Interpolated Correlated Random Walks in Hölder Topology'] Let \(\interpF_t^n\) be the interpolated random walk defined in \eqref{eq:
    definition random walk interpolation} and assume \(\feature \in
    L^p(\gamma)\) for \(\gamma\) the standard Gaussian measure and \(p \ge 2\).
    Then for \(t-s \ge \frac1n\)
    \[
        \norm{\interpF^n_t - \interpF^n_s}_{L^p(\Omega)}
        \le C_{p, \feature}
        \Bigl(\sum_{i,j=0}^{\floor{nt}-\floor{ns}} \abs{\rho(i-j)}^{\hermRank}\Bigr)^{\frac12}
    \]
    for a constant \(C_{p, \feature} < \infty\) that depends on \(p\) and the feature function \(\feature\).

[Thm eq:modifzakai of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{(Informal Theorem (theo:limitcrowkimura of the paper):) Limiting process of (equation eq:repmutlin of the paper)} Consider a time discretisation of the interval $[0,T]$ with step size $\delta_d$ such that $d \times \delta_d = T$.  Denote by $\{Z_t^d\}_{0 < t \leq T}$ a piecewise linear approximation with step size $\delta_d$ of an observation path generated by (equation eq:obs of the paper).  Finally, let $\mu_t^d \propto \rho_t^d$ denote the unnormalised form of $\rho_t^d$ satisfying (equation eq:repmutlin of the paper).  Then under some conditions, 
		\begin{align*}
			\mu_t^d \rightarrow q_t \quad \text{as} \quad d \rightarrow \infty, \enskip \forall \enskip  t \in [0, T],
		\end{align*}
		where $q_t$ satisfies the modified Zakai equation,
		\begin{align}

			d q_t(x) = \mathcal{L}^\ast q_t(x) -\frac{s}{2}h(x)^\top \Xi^{-1} h(x) q_t(x)  + (r-s)q_t(x) h(x)^\top \Xi^{-1} dZ_t, 
			\tag{$\textbf{ZK}$}
		\end{align}
		with $\mathcal{L}^\ast$ is as defined in (equation eq:repmutlin of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

