[Thm vector-main of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Fix integers $r_{\star}\ge1,$ $k\ge2$, and
set $t\coloneqq k/r_{\star}$. Suppose $\normzero{x_{\star}}\le r_{\star}$
and that $A\in\operatorname{rip}(\delta,k)$. If $\delta<\delta_{\mathrm{sharp}}(t)$ and the
regularization parameter $\lambda>0$ satisfies
\begin{equation}
\lambda\ge2\frac{1+\rho_{\delta,t}}{1-\rho_{\delta,t}}\norminf{A^{T}\xi},
\end{equation}
then for any sparsity level $r\ger_{\star}$, the solution $x_{\lambda,r}$
in ((eq:vector-lasso of the paper)) satisfies \begin{subequations}
\begin{align}
\normtwo{A(x_{\lambda,r}-x_{\star})} & \le\frac{4\tau_{\delta,t}}{1-\rho_{\delta,t}}\sqrt{r_{\star}}\,\lambda,\\
\normtwo{x_{\lambda,r}-x_{\star}} & \le\frac{16\tau_{\delta,t}^{2}}{(1-\rho_{\delta,t})^{2}}\sqrt{r_{\star}}\,\lambda.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2609.02784, 'Maximizing the fundamental Laplace--Neumann \\ eigenvalue on quadrilaterals'] For $\{i,j\}=\{1,2\}$, we have
\begin{equation}
 \nu_i-\widehat\nu_i
 =
 \frac{
 \operatorname{tr}\!\left(
   \operatorname{adj}\widehat F_t(\nu_i)\,E_t(\nu_i)\right)
 -\det E_t(\nu_i)}
 {d_2(\nu_i-\widehat\nu_j)},
\end{equation}
where $\operatorname{adj} A$ denotes the adjugate of the matrix $A$.

If $[\nu_i]$ contains $\nu_i$ and $\widehat\nu_i$ and
$[\nu_1]\cap[\nu_2]=\varnothing$, the denominator in
\eqref{eq:exact-root-refinement} does not contain zero, and
\begin{equation}
 L
 =\frac{\widetilde d_1}{d_2}
   +\frac{\delta_1+\delta_2}{t},\qquad
 \nu_1\nu_2
 =\frac{d_0}{d_2}
   +\widehat\nu_1\delta_2+\widehat\nu_2\delta_1
   +\delta_1\delta_2 .
\end{equation}

[Definition 1 of arXiv:2605.02771, 'Universality in Deep Neural Networks:\\ An approach via the Lindeberg exchange principle'] Fix \(L\in\N\) and \(n_0,\dots,n_{L+1}\in\N\). A \textbf{fully connected deep neural network} is a function
    \[
        z^{(L+1)}:\R^{n_0}\to\R^{n_{L+1}}
    \]
    defined recursively by
    \begin{equation}
        z^{(\ell)}=\begin{cases}
                    W^{(1)}x+b^{(1)}, & \ell=1,\\
                    W^{(\ell)}\sigma(z^{(\ell-1)})+b^{(\ell)}, & \ell=2,\dots,L+1.
                \end{cases}
    \end{equation}
    The matrices \(W^{(\ell)}\in\R^{n_l\times n_{l-1}}\) are called \textbf{weights}, and the vectors \(b^{(\ell)}\in\R^{n_l}\) are called \textbf{biases}. Here \(\sigma:\R\to\R\) is the activation function, and for a vector \(x\in\R^d\) we write
    \[
        \sigma(x)=(\sigma(x_1),\dots,\sigma(x_d))\in\R^d.
    \]
    The integer \(n_0\) is the input dimension and \(n_{L+1}\) is the output dimension of the network. We refer to \(z^{(L+1)}\) as the output of the network.

[Definition def:hoelder_sets_def of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] For $n \in \mathbb{N}$, let
    \begin{equation*}
        \mathrm{HC}_n \coloneqq \Big\{ \psi \in C_0[0,1] \,\Big|\, \forall \, x,y \in [0,1]: \; | \psi(x)-\psi(y) | \leq n\, |x-y|^{1/n} \Big\},
    \end{equation*}
    and let $\mathrm{HC} \coloneqq \bigcup_{n>0} \mathrm{HC}_n$.

[Corollary thm:diffusion_pointwise_majorization of arXiv:2609.01576, '\normalfont Pointwise Majorization for sub-Weibull and Mixed Tail Processes with Applicati'] Suppose that Assumptions (ass:diffusion_coefficients of the paper) and
(ass:diffusion_index_class of the paper) hold. Fix $\tau>0$, start the diffusion
from $X_0\sim\pi$, and fix $\mu_1,\mu_2$ before observing the trajectory.
There exists a universal constant $C_{1,2}<\infty$ such that, for every
$\delta\in(0,1)$, with probability at least $1-\delta$, simultaneously
for every $f\in\cF$,
\begin{align}
|Z_\tau(f)|
\le
C_{1,2}
\cbr{
\Phi_1(f)+\Phi_2(f)
+v_1(f)\log\frac{e}{\delta}
+v_2(f)\sqrt{\log\frac{e}{\delta}}
}.

\end{align}
If either local complexity term is infinite at $f$, the bound at that
index is understood to be vacuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma ref:lemmasize of arXiv:2508.09291, '1+O(1) asymptotics for loop percolation in five and higher dimensions'] Fix $d\ge 3$. As $m\to\infty$, it holds that
        \begin{equation}
            \mu\left[\#{\mathcal R }(\omega)|\mathrm{diam}(\omega)>m,0\in\omega\right]={\mathcal O }\rk{m^{2}}\, .
