body:
[Proposition prop:Stdefi of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] For $t \in [0,1]$,   $\underline{\Psi} = (\Psi_{j})_{j\ge 0} \in \mathbb{A}_0$ and $\underline{A} = ( A_j )_{j\ge 0} \in \prod_{j=0}^{\infty} \D_j (\alpha)$,
there exists a linear map $\underline{S}^t (\underline{A}) = (S_j^t (A_j) )_{j \ge 0} : \mathbb{A}_0 \rightarrow \mathbb{A}$ such that $\underline{B} = \underline{S}^t (\underline{A}) \underline{\Psi}$ satisfies
\begin{align}
	B_{j+1} = D \tilde{\Phi}^t_{j+1} (A_j) B_j + \Psi_{j+1} \quad \text{for each} \quad j\ge 0.  
\end{align}
Moreover,  it satisfies
\begin{itemize}
\item[(1)] $\norm{\underline{S}^t (\underline{A}) } \lesssim 1$;  and
\item[(2)] if $\norm{\Psi_j}_{X_j \times Y_j \times Z_j} \le O_L (1) g^{9/4} r_j^{\kt}$ for each $j$,  then $\norm{D_{\underline{A} } \underline{S}^t (\underline{A}) \underline{\Psi} }\le O_L (1)$.
\end{itemize}

