	        \expt{\|\Psi^{\tau,\nu}_t-\Psi^{\tau,\nu}_s\|_{H^{-\vartheta}}^\gamma}
	        &\lesssim_{\gamma,T,\psi_0} (t-s)^{\gamma/2}.
    \end{align*}

