[Theorem mix of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under (main_assm of the paper), given any $k\in[\![{1,DN}]\!]$, suppose there exists a constant $\varepsilon_A>0$ such that
\begin{equation}
\|A\|_{\text{\rm{HS}}}\ge N^{1/3+\varepsilon_A}{\mathfrak{r}}\left({k}\right)^{-1/3} .
\end{equation}
Then, there exists a constant $c>0$ such that 
\begin{equation}
\mathbb P\left( \max_{a\in\llbracket D\rrbracket}\left|{\bf v}_k^* E_{a}  {\bf v}_k-D^{-1}\right|\ge N^{-c}\right)\le N^{-c},
\end{equation}
where $E_a\in \mathbb{C}^{DN\times DN}$ denotes the block identity matrix restricted to $\mathcal I_a$, i.e., $(E_{a})_{ij}={\bf 1}(i=j\in {\mathcal I}_a)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Ratio identities and diagonal normalization) of arXiv:2511.12623, 'The eigenvector bead process'] For $g_i,g_j\neq0$ and any $k$,
\begin{equation}
\frac{\Omega^{(N)}_{k,j}}{\Omega^{(N)}_{k,i}}
=\frac{\Delta_{k,i}^{(N)}}{\Delta_{k,j}^{(N)}}\cdot \frac{g_j^{(N)}}{g_i^{(N)}},
\qquad
\frac{\Omega^{(N)}_{k,N+1}}{\Omega^{(N)}_{k,i}}
=\frac{\Delta_{k,i}^{(N)}}{g_i^{(N)}}.
\end{equation}
In addition, for $k=i$,
\begin{equation}
\bigl(\Omega^{(N)}_{i,i}\bigr)^2
=
\left[
\left(\frac{\Delta_{i,i}^{(N)}}{|g_i^{(N)}|}\right)^{\!2}
\left(1+\sum_{j=1}^N \left(\frac{|g_j^{(N)}|}{\Delta_{i,j}^{(N)}}\right)^{\!2}\right)
\right]^{-1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (\citeauthor{D65}, \citeyear{D65}, \S6.10) of arXiv:2606.06739, 'The relationship between the transition functions of the labeled and unlabeled versions of'] Let $E$ and $E_0$ be complete separable metric spaces, and let $\Phi:E\mapsto E_0$ be Borel measurable and surjective.  Let $P(t,x,\cdot)$ be the transition function for a Markov process $X$ in $E$. If for each $t>0$ the condition 
\begin{equation}
P(t,x,\Phi^{-1}(\cdot))\text{ depends on }x\text{ only through }\Phi(x)
\end{equation}
holds, then $Y:=\Phi\circ X$ is a Markov process in $E_0$ with transition function
\begin{equation}
Q(t,y,\cdot):=P(t,x,\Phi^{-1}(\cdot)),\text{ where }x\in\Phi^{-1}(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $\mathbf{A} = (A, N)$ be a random element in $\Rcal$ such that $\pbb(N = n) > 0$ for every $n \in \nbb$. Then $\mathbf{A}$ satisfies
    \begin{enumerate}[label=(\roman*)]
        \item (Finite exchangeability) For all $n \geq 1$ and all permutations $\pi$ of $\{1,\dots,n\}$:
        \begin{equation*}
            A \mid (N = n) \overset{d}{=} A \circ \pi \mid (N = n)
        \end{equation*}
        \item (Compatibility) For all $n \geq 1$ and all $m \geq n$:
        \begin{equation*}
            A \mid (N = n) \overset{d}{=} A[n] \mid (N = m)
        \end{equation*}
    \end{enumerate}
    if and only if there exist an infinite jointly exchangeable matrix $A^{(\infty)} \in \rbb^{\nbb \times \nbb}$ such that for all $n \geq 1$:
    \begin{equation} 
        A \mid (N = n) \overset{d}{=} A^{(\infty)}[n]
    \end{equation}
    In that case, $A^{(\infty)}$ is unique in distribution.

[Lemma lem:592 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] \textnormal{(i) (Lower bound)} There exist $c=c(u_1)>0$ and $n_1(u_1)>0$, such that for all $z\in S_i$ and $n>n_1(u_1)$, we have
    \begin{equation}
        \mathbb{P}_z\Big(\tau_{T_{i,j}}<\tau_{\partial \widetilde{B}(z)}\Big)>\frac{c}{n}.
    \end{equation}
    \textnormal{(ii) (Upper bound)} There exist $c'=c'(u_1)>0$ and $n_2(u_1)>0$, such that for $z\inS_i$, $z'\in\widetilde{B}(z)$ and $n>n_2(u_1)$, we have
    \begin{equation}
        \mathbb{P}_{z'}\Big(\tau_{T_{i,j}}<\tau_{\partial \widetilde{B}(z)}\Big)<\frac{c'(\log(r(z')/|z'-|z'|v_{i,j}|)+1)}{n}.
    \end{equation}

