[Theorem th:near-critical-scaling of arXiv:2606.11503, 'Percolation on hierarchical lattices'] For any $\lambda \in \mathbb{R}$,
  \begin{equation}

    f_{k} \Big( p_\star + \frac{\lambda}{\zeta^k} \Big) \to h^{-1}(\lambda),
  \end{equation}
  where the diffeomorphism $h: (0, 1) \to \mathbb{R}$ is characterized as the unique linear conjugation of $f$ (that is, $h \circ f = \zeta \cdot h$) such that $h'(p_\star) = 1$.

  \nc{c:tail_h_1}
  \nc{c:tail_h_2}
  Moreover, there exist constants $\uc{c:tail_h_1}, \uc{c:tail_h_2} > 0$ such that
  \begin{equation}

    \exp \Big( -\uc{c:tail_h_1} |\lambda|^\nu \Big)
    \leq h^{-1}(\lambda)
    \leq \exp \Big( -\uc{c:tail_h_1}^{-1} |\lambda|^\nu \Big),
    \text{ as $\lambda \to -\infty$}
  \end{equation}
  and
  \begin{equation}

    1 - \exp \Big( -\uc{c:tail_h_2} \lambda^\mu \Big)
    \leq h^{-1}(\lambda)
    \leq 1 - \exp \Big( -\uc{c:tail_h_2}^{-1} \lambda^\mu \Big),
    \text{ as $\lambda \to \infty$},
  \end{equation}
  where the exponents $\mu$ and $\nu$ are the ones appearing in (th:off-critical-decay of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] Let $k<n,\,f\colon \mathbb{R}^k \to \mathbb{R}$ be a bounded measurable function, then there exist $C, C' > 0$, such that
    \begin{equation*}
        \bigl|\mathbb{E}_\pi[f(Z_1, \dots, Z_k) G_\beta(Z_1) G_\beta(U_n)] - \mathbb{E}_\pi[f(Z_1, \dots, Z_k) G_\beta(Z_1)]\, \mathbb{E}_\pi[G_\beta(Z_n)] \bigr| \leq C \e^{-C'(n-k)}.
    \end{equation*}

[Proposition prop: tightness eigenvectors of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists a random variable $e_0$ defined on the coupling space that is a measurable function of $W^0_\infty+Z^0_\infty$, i.e.\ $e_0=e_0(W^0_\infty+Z^0_\infty)$, such that $\|e_0\|_{L^2(\mathbb P^0)}=1$ and, up to a subsequence, 
\begin{equation}e_0^T(W_T^0+Z^0_T) \rightarrow e_0(W^0_\infty+Z^0_\infty),	
\end{equation}
 where the convergence can be taken as either $\mathbb P^0$-almost sure or in $L^2(\mathbb P^0)$. Furthermore, $e_0>0$ almost surely with respect to $\mathbb P^0$ and for every $\alpha \geq 1$, there exists $C>0$ such that
\begin{equation}\|e_0\|_{L^2 (\log_+L)^\alpha (\mathbb P^0)} \leq C.
\end{equation}

[Proposition 30 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For every $x,\wt x\in\R$ with $x\neq\wt x$,
  \begin{align}
    \frac{\partial}{\partial x}
    \EE\bigl[
      F_{\wt x}^{\al,\be}F_{x}^{\al,\be}
    \bigr]
    =\lim_{\eps\downarrow0}
    \EE\left[
      \frac1\be\log \cZ_{\wt x}^\eps
      \frac{\partial}{\partial x}
      \frac1\be\log \cZ_x^\eps
    \right].
  \end{align}

[Proposition 24 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] For all $x \in \hcV^{(\rm h)}_{\nu}$, $\sigma \in \{\pm 1\}$, define
  \begin{equation*}
    Z_{x} = 2 + \frac{2}{\#\Sib^{-}(x)}\ind_{\{\#\Sib^{-}(x) \neq 0\}}\,,
  \end{equation*}
  and
  \begin{equation*}
    \b u_{\sigma}(x) = \frac{1}{\sqrt{Z_{x}}} \Biggl( \b 1_{x} + \sigma\frac{\b 1_{S_{1}^{\pp -}(x)}}{\sqrt{D_{x}^{\pp -}}} - \frac{\b 1_{\Sib^{-}(x)}}{\#\Sib^{-}(x)}\Biggr)\,.
  \end{equation*}
  The family $(\b u_{\sigma}(x))_{x \in \hcV^{(\rm h)}_{\nu}, \sigma\in \{\pm 1\}}$ is orthonormal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition control_growth_large_r of arXiv:2606.27357, '\textbf{Typical distances in high-genus triangulations}'] For any $\varepsilon,\eta > 0$, we have 
 \begin{align*}
\mathbb{P}\bigg(
\somme{r=\log(n)^{1/2}+1}{(1-\varepsilon)D_{\theta}\log(n)-1}{
\indi{|B_{r}^{\bullet}|\le n^{1-\varepsilon+\eta}}\bigg|\log\bigg(\frac{|\partial^{*}B_{r+1}^{\bullet}|}{|\partial^{*}B_{r}^{\bullet}|}\bigg)-D_{\theta}^{-1}\bigg|}
\ge \frac{\eta}{4}\log(n)\bigg) \underset{n \to +\infty}{\longrightarrow}0.
 \end{align*}

