[Theorem 19 (Dirichlet-to-Neumann convergence in $L^2$) of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $0<s<1$. If $\frac12\le s<1$ and $u\in \Dom(\Le^s)$, or if $0<s<\frac12$ and $u\in \Dom(\Le^{\frac14+\frac s2})$, then the strong limit in $L^2(\RNu)$
\begin{equation}
-\ \underset{z\to 0^+}{\lim}\ \frac{\Gamma(s)e^{i\pi s/2}}{2^{1-2s}\Gamma(1-s)} \ z^a \p_z U(\cdot,z,\cdot)\ =\  
\Le^s u.
\end{equation}

[Theorem 72 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] For any $p\geq d_{0}+1$  
\begin{equation}

\|G_{\cA}\|_{L_{p/(p-1)}(\bR^{d+1}_{0})}\leq N(\delta,d  )\lambda^{(d+2)/(2p)-1}P(\cA)
\end{equation}
In particular, for any Borel $f\geq0$ given on $\bR^{d+1}$ (and $\lambda\geq \varkappa_{0}^{2}\rho_{b}^{-2}$) on $\{\tau<\infty\}$ we have
\begin{equation}

E_{\cF_{\tau}}\int_{0}^{\infty}e^{-\lambda t}f(t,x_{\tau+t})\,dt
\leq N(\delta,d )
\lambda^{(d+2)/(2d_{0}+2)-1}\|f\|_{L_{d_{0}+1}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let $\xi,g$ satisfy (H1) and (H3). Assume that $(Y,Z,A,A')$ solves
    \begin{align*}
        Y_t=\xi+\int_t^T g(s,Y_s,Z_s)d\langle B\rangle_s-\int_t^T Z_sdB_s+(A_T-A_t)-(A'_T-A'_t),
    \end{align*}
    where 
    \begin{align*}
        (Y,Z)\in S_G^\infty(0,T)\times H^2_G(0,T),
    \end{align*}
    and $A$, $A'$ are continuous nondecreasing processes with $A_0=A'_0=0$.

 \begin{itemize}
     \item[(1)] Suppose that $A'_T\in L^\infty_G(\Omega_T)$.  Then, for any $\alpha\geq 1$, there exist two constants 
     \begin{align*}
         &C_1:=C_1(\|Y\|_{S^\infty_G},\|A'_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma}),\\
         &C_2:=C_2(\|Y\|_{S^\infty_G},\|A'_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma},\alpha),
     \end{align*}
     such that 
    \begin{align*}
        \|Z\|_{BMO_G}\leq C_1,\  \hat{\E}[|A_T|^\alpha]\leq C_2.
    \end{align*}
    \item[(2)] Suppose that $A_T\in L^\infty_G(\Omega_T)$.  Then, for any $\alpha\geq 1$, there exist two constants 
    \begin{align*}
         &C'_1:=C'_1(\|Y\|_{S^\infty_G},\|A_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma}),\\
         &C'_2:=C'_2(\|Y\|_{S^\infty_G},\|A_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma},\alpha),
     \end{align*}
     such that 
    \begin{align*}
        \|Z\|_{BMO_G}\leq C'_1,\  \hat{\E}[|A'_T|^\alpha]\leq C'_2.
    \end{align*}
 \end{itemize}

