[Definition def:cuts_rays_paths of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] For any type path or ray $\pi=(s_0\rightarrow s_0s_1 \rightarrow s_0s_1s_2 \rightarrow \dots)$ with length $|\pi|$, and for any $1\leq i \leq |\pi|-1$, we define
    \begin{align*}
        &\pi^{(i)}:=(s_i\rightarrow s_is_{i+1}\rightarrow \dots)\textrm{ if }\pi\textrm{ is an infinite type ray; }  \\&\pi^{(i)}:=(s_i\rightarrow s_is_{i+1}\rightarrow \dots \rightarrow s_is_{i+1}\dots s_k)\textrm{ if }\pi\textrm{ is finite and }|\pi|=k.\addtocounter{equation}{1}\tag{\theequation} 
    \end{align*}
Similarly, for any $0\leq i\leq |\pi|$, we define the path $\pi_{(i)}$ as
\begin{align*}
    \pi_{(i)}:=(s_0\rightarrow s_0s_1 \rightarrow \dots \rightarrow s_0s_1\dots s_{i}).\addtocounter{equation}{1}\tag{\theequation} 
\end{align*}

[Lemma 38 (Gaussian regression and Wick decoupling) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $m\ge1$, let $B$ be a real or complex Banach space, and let
$h_1,\ldots,h_N$ be an orthonormal family in a real Hilbert space $\cH$.
For a finite array $b=(b_{i_1\cdots i_m})_{1\le i_1,\ldots,i_m\le N}$ in
$B$ and a real isonormal Gaussian process $V$ over $\cH$, set
\begin{equation*}
  \mathcal I_b(V)
  :=\sum_{i_1,\ldots,i_m=1}^N
    b_{i_1\cdots i_m}
    \wick{V(h_{i_1})\cdots V(h_{i_m})}.
\end{equation*}
Let $W^{(1)},\ldots,W^{(m)}$ be independent real isonormal Gaussian
processes over $\cH$, and define
\begin{equation*}
  \mathcal D_b(W^{(1)},\ldots,W^{(m)})
  :=\sum_{i_1,\ldots,i_m=1}^N
    b_{i_1\cdots i_m}
    \prod_{\nu=1}^m W^{(\nu)}(h_{i_\nu}).
\end{equation*}
Set
\begin{equation*}
  \overline W:=m^{-1/2}\sum_{\nu=1}^m W^{(\nu)},
  \qquad
  \overline{\mathcal G}:=\sigma\{\overline W(h):h\in\cH\}.
\end{equation*}
Then $\overline W$ is a real isonormal Gaussian process over $\cH$, and
\begin{equation}

  \E\left[
    \mathcal D_b(W^{(1)},\ldots,W^{(m)})
    \middle|\overline{\mathcal G}
  \right]
  =m^{-m/2}\mathcal I_b(\overline W).
\end{equation}
Consequently, for every convex nondecreasing function
$\Phi:[0,\infty)\to[0,\infty)$,
\begin{equation}

  \E\,\Phi\!\left(m^{-m/2}\|\mathcal I_b(\overline W)\|_B\right)
  \le
  \E\,\Phi\!\left(
    \|\mathcal D_b(W^{(1)},\ldots,W^{(m)})\|_B
  \right).
\end{equation}
In particular, for every $p\ge1$,
\begin{equation}

  \|\mathcal I_b(\overline W)\|_{L^p(\Omega;B)}
  \le m^{m/2}
  \|\mathcal D_b(W^{(1)},\ldots,W^{(m)})\|_{L^p(\Omega;B)}.
\end{equation}
The same two inequalities hold with $\overline W$ replaced by any real
isonormal Gaussian process over $\cH$.

[Theorem mintheorem of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Fix $\beta \in (0,\infty)$, and let $\tilde W:{\mathcal C }_\beta\to \mathbb{R}$ defined as $\tilde W(\omega)=\int_0^\beta W(\omega(s)) {\rm d} s$ for all $\omega \in {\mathcal C }_\beta$, where $W$ is a Soft-wall potential. Denote by  $\varphi:\mathbb{R} ^ d \to \mathbb{R}$ the $L^2(\mathbb{R}^d)$-normalized eigenfunction of the operator $-\Delta +W$ which corresponds to the principle eigenvalue 
        \begin{equation}
        \lambda(W)=\sup_{\varphi\in H^1(\mathbb{R}^d)\colon , \|\varphi\|_2=1}\Big(\langle W,\varphi^2\rangle-\|\nabla\varphi\|_2^2\Big).
    \end{equation}
    \noindent Then, setting
    \begin{equation}
     q^*({\rm d} x,{\rm d} y):=\varphi(x)\varphi(y)\frac{\mathbb{E}_x\left[e^{\tilde W -\beta\lambda (W)}; B_\beta \in {\rm d} y\right]}{{\rm d} y}\,{\rm d} x {\rm d} y,  
    \end{equation}
 we have that $\mu^*_{g,{\mathfrak m},W}$ defined in (equation minimizergen of the paper) with $q^*_{g,{\mathfrak m},W}$ replaced by $q^*$ in (equation pairscr of the paper) is an ergodic Markov process which corresponds to the solution to the problem
 \begin{equation}
     {\rm d} X_t=\frac{\nabla \varphi}{\varphi}{\rm d} t+{\rm d} B_t,\quad X_0 \text{ has distibution with density } \varphi^2 \text{ with respect to the Lebesgue measure}
 \end{equation}
 with invariant measure with density $\phi^2$, and it is the unique minimizer of $I_{{\mathfrak m},W,g}^{(sym)}$, when ${\mathfrak m}={\rm Leb}$ and $g\equiv p_\beta$. Moreover, $\mu^*_{g,{\mathfrak m},W}$ is a solution to the optimal transport problem:
$$\inf\{H(Q|\mathbb{P}_{\mathfrak m}): Q\circ\pi_0^{-1}=\phi^2(x){\rm d} x,Q\circ\pi_\beta^{-1}=\phi^2(x){\rm d} x\}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro:chromatic-signed of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Let $\Sigma$ be a signed graph, then 
\begin{equation}
\chi_\Sigma ^b (2t) = \phi_t\circ \Psi (\Sigma) = \zeta^{\ast t}(\Sigma).
\end{equation}

