[Lemma 34 (Exact positive ledger) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For every common-module split,
\begin{align}
 0\le\mathcal N_q&\le a_QR^2\Id,
 \\
 \mathfrak H_Q(A,r)
 &=\sum_{b=1}^{d}\sum_{q=1}^{Q}
   \ip{r_{b,q}}{\mathcal N_qr_{b,q}}.

\end{align}
Moreover the coherent residual and mixed Malliavin--Stein defects satisfy
\begin{equation}
 \Delta_{\mathrm{res}}(r)+\Delta_{\mathrm{mix}}(A,r)
 \le\mu_Q\mathfrak H_Q(A,r).

\end{equation}

[Theorem th:metric_scaling of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Suppose that $\Gamma$ has the law described at the beginning of Section~(subsec:main_statement of the paper) \emph{conditioned} on the event that $\mathcal {L} \subseteq \mathbf{D}$. Let $\met{\cdot}{\cdot}{\Gamma}$ be a non-trivial ${\rm CLE}_{\kappa'}${} metric. There is a constant $\median[\lambda]{} > 0$ for each $\lambda \in (0,1]$ such that the family $\{ ((\median[\lambda]{})^{-1}\metres{\lambda V}{\lambda\cdot}{\lambda\cdot}{\lambda\Gamma})_{V \in \metregions} \}_{\lambda \in (0,1]}$ is tight and its subsequential limits are non-trivial. Moreover, the constants satisfy
 \[ r^{d_{\rm SLE}+o(1)}\median[\lambda]{} \le \median[r\lambda]{} \le r^{{d_{{\mathrm{dbl}}}}+o(1)}\median[\lambda]{} \]
 for $r,\lambda \in {(0,1]}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: increasing sequence of stopping times of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Given a stopping time $T$, there exist stopping times $\setc{T_k}{k \geq 0}$ such that $T_k \uparrow T$ as $k \to \infty$ almost surely and the following properties hold surely for each $k \geq 1$.
	\begin{enumerate}
		\item[(a)] There exists a constant $K \geq 0$ such that $T_k \leq K$.

		\item[(b)] There exists $\eta \in (0, \kappa)$ such that $a_i \wedge T_k - a_{i - 1} \wedge T_k \leq \eta$ for all $i \geq 1$.

		\item[(c)] There exists a compact set $(0, 0) \in C \subset U_g$ such that
		\begin{equation*}
			\left(\boldsymbol{x}_i(t), \boldsymbol{y}_i(t)\right) \in C \quad \text{for all} \quad 1 - M \leq i \leq \mathcal{R}\left(T_k\right) \quad \text{and} \quad t \in [0, T_k].
		\end{equation*}
	\end{enumerate}

