[Lemma 2 (Full-path tube closure) of arXiv:2608.30261, 'Estimating Population-Risk Curves Along Nonconvex Gradient Flows from the Training Sample'] \label[lemma]{lem:full-path-tube}
Under \cref{ass:tube}, for every $i\in[n]$ and $\lambda\in\Lambda$ the deleted flow
$\theta_{-i,t}^\lambda$ and the response $d_{i,t}^\lambda$ exist uniquely on
$[0,T]$.
Moreover, for $0\leq t\leq T$,
\begin{equation}
 \max\{\|\theta_{-i,t}^\lambda-\theta_t^\lambda\|,\|d_{i,t}^\lambda\|\}
 \leq(n-1)^{-1}M\phi_\kappa(t)<r_{\rm tube}.
\end{equation}
Consequently, at each time $t$, the line segments joining any two of
$\theta_t^\lambda$, $\theta_{-i,t}^\lambda$, and
$\theta_t^\lambda+d_{i,t}^\lambda$ are contained in
$B(\theta_t^\lambda,r_{\rm tube})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $S_n$ be a TMERW. Assume that $\DD$ is a collection of nested sequences having an underlying renewal structure, that is,  
the assumptions (\textbf{A1}) and (\textbf{A2}) hold. Then, as $n \to \infty$,
    \begin{equation}

       \frac{S_n}{n} \longrightarrow \frac{(2\lambda-1)\E[\sigma]}{\mu - (2p-1)\E[\tau]} \; \text{ a.s.},
    \end{equation}
where $\mu = \E[\tau]+ \E[\sigma]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: partition procedure in sle of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Fix a sufficiently small constant $\iota>0$, and set
$M=\iota r^{3\kappa}N.$
We introduce the following partition procedure. 
    We first partite $\Lambda_N$ into $M$-boxes. For each box $\mathsf{B}$, we have two possible \begin{itemize}
        \item If $\sum_{x\in \mathsf{B}}{\operatorname{dist}}(x,\gamma)^{-\frac{1}{4}}\ge M^{\frac{7}{4}}$, then we divide $\mathsf{B}$ into two small boxes $\mathsf{C}_1$ and $\mathsf{C}_2$ such that \begin{equation}
            \max\Big\{\sum_{x\in \mathsf{C}_1}{\operatorname{dist}}(x,\gamma)^{-\frac{1}{4}},\sum_{x\in \mathsf{C}_2}{\operatorname{dist}}(x,\gamma)^{-\frac{1}{4}}\Big\}\le (\frac{1}{2}+\kappa)\cdot\sum_{x\in \mathsf{B}}{\operatorname{dist}}(x,\gamma)^{-\frac{1}{4}}.
        \end{equation}
        \item If $\sum_{x\in \mathsf{B}}{\operatorname{dist}}(x,\gamma)^{-\frac{1}{4}}< M^{\frac{7}{4}}$, then we turn to the next box.
    \end{itemize}

[Lemma 18 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $\eta>0$,
\begin{displaymath}
\lim_{\varepsilon\to 0}
\E\Big[
\big\Vert
\psi_{n,A}
-
\E\big[:\Phi^{n}_{\varepsilon}:\vert A\big]
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big] = 0.
\end{displaymath}

[Corollary 54 of arXiv:2607.18201, 'Finding Adam in noisy trees'] For any $\delta>0$ we have
    \begin{align*}
        \Prob{\kH'_n(\alpha,\delta)=\kH_n(\alpha)},\Prob{\bC_{\alpha,\delta}(1)=\bC_{H,\alpha}(1)}\to 1.
    \end{align*}
    where by $\bC_{\alpha,\delta}(1)$ we denote the component of $1$ in $\kH'_n(\alpha,\delta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 1.3 of arXiv:2411.07158, 'Markov chains on trees: almost lower and upper directed cases'] Consider  ${\sf U}$  an irreducible {\sf AUD}\xspace transition matrix of a finite or infinite tree $T$.  For any node $u$ of $T$, consider the weighted graph $({}^uG,{}^{u}{{\sf U}})$ with set of nodes ${}^uV:=\cro{\varnothing,u}$, and in which the weight of
\[{}^{u}{{\sf U}}_{a,b} = ({\sf U}_{a,T_b}-{\sf U}_{a,T_{{\sf s}(b,u)}})\1_{b\in \cro{p(a),p(u)}} +\1_{b=u}{\sf U}_{a,T_u}\]
is defined for all $a\in\cro{\varnothing,p(u)}$ and $b\in\cro{\varnothing, u}$. Set
\begin{eqnarray}
\pi(u) = \pi(\varnothing)\frac{{\sf Weight}( \cro{\varnothing,u}, {}^{u}{\sf U}, u)}{{\displaystyle\prod_{v \in \cror{  \varnothing,  u}} {\sf U}_{v,p(v)} }}=\pi(\varnothing)\frac{\det (({\sf Id}-{}^{u}{{\sf U}})^{(u)})}{\displaystyle\prod_{v \in \cror{  \varnothing,  u}} {\sf U}_{v,p(v)} }.
\end{eqnarray}
\begin{itemize} \topsep0pt   \itemsep=0pt   \partopsep=0pt   \parsep=0pt \setcounter{c}{0}
\addtocounter{c}{1}\item[($\roman{c}$)] The measure $\pi$ is an invariant measure of ${\sf U}$ (with positive coordinates).
\addtocounter{c}{1}\item[($\roman{c}$)] An {\sf AUD}\xspace transition matrix is positive recurrent if and only if $\sum \pi(u)<+\infty$.\end{itemize}\vspace{-2em}~ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop remove plaquette from loop of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] Suppose that $(\ell, K)$ is a balanced loop plaquette assignment, and let $e$ be an edge contained in $\ell$. Assume that $e$ is connected to infinity via a path of plaquettes $\mathfrak{p} = \{p_i\}_{i=1}^{\infty}$, where the first plaquette is given by $p_1 = e\, e_1\, e_2 \, e_3$. Then, each string plaquette assignment $(s,\mathcal{K})= \{(\ell_1, K_1), \dots, (\ell_m , K_m)\}$ labeling a leaf of $\mathcal{T}_{e,\mathfrak{p}}(\ell,K)$  satisfies the following properties:
        \begin{enumerate}
            \item $\supp(s)\cap\mathfrak{p} = \emptyset$;
            \item $\mathcal{K}(q) = K(q)$ for all $q\in \mathcal{P}\setminus \mathfrak{p}$;
            \item $h_{s}(q)= h_{\ell}(q)$ for all $q\in \mathcal{P}\setminus \{p_{1}^{\pm 1}\}$;
            \item $n_{\Tilde{e}}(s) \leq n_{\Tilde{e}}(\ell)$ for all $\Tilde{e}\in E\setminus \{e_1^{\pm 1}, e_2^{\pm 1}, e_3^{\pm 1}\}$; 
            \item $n_{\Tilde{e}}(s) + n_{\Tilde{e}^{-1}}(s)\leq \Big(n_{\Tilde{e}}(\ell) + n_{\Tilde{e}^{-1}}(\ell)\Big) + \Big(n_e(\ell) + n_{e^{-1}}(\ell)\Big)$ for all $\Tilde{e}\in \{e_1, e_2, e_3\}$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 28 of arXiv:2609.02197, '2609.02197'] Let $\theta \in \left]-\infty,2-\frac{d}{2}\right[.$
\begin{enumerate}
\item
There exists a stochastic process $\left(\widetilde{X}_{r,1}\right)_{r \in \mathbb{R}_+}$ with state space $\left(\mathscr{C}^\theta,\mathcal{B}\left(\mathscr{C}^\theta\right)\right)$ such that the sample paths of $\left(\widetilde{X}_{q,1}\right)_{q \in \mathbb{R}_+}$ are continuous and for $\mathds{P}$-almost every $\omega \in \Omega,\left(\widetilde{X}_{r,1}\left(\omega\right)\right)\left(\varphi\right)=\left(X_{r,1}\left(\varphi\right)\right)\left(\omega\right).$
\item For all $\left(r,q\right) \in \mathbb{R}_+\times \mathbb{R}_+^*,$ let \gls{sto3}$:=\zeta_q*\widetilde{X}_{r,1}.$ For every $\left(U,\varsigma\right) \in \mathbb{R}_+\times \mathbb{R}_+^*,$ $$\lim_{\epsilon\downarrow 0}\mathds{P}\left(\sup_{r \in \left[0,U\right]}\left\Vert \widetilde{X}_{r,\epsilon,1}-\widetilde{X}_{r,1}\right\Vert_{\mathscr{C}^\theta}>\varsigma\right)=0.$$
\end{enumerate}

[Lemma lemma1 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] For all $k\in \{2,...,\lfloor \beta \rfloor +1\}$, $t\in [0,1)$ and $x\in \mathbb{R}^d$, we have
    \begin{align*}
    \|\nabla^{k} V(t,x)\|\leq &  C \sum_{l=1}^{k-1} \Biggl( \|\int f^{l}(y)\nabla^2_x p^{t,x}(y)d\lambda^d(y)\| \prod_{j=1}^{k-2}\left(\|\int f^{j}(y) dp^{t,x}(y)\|\vee 1\right)^{k-2}\\
    &+ \|\int f^{l}(y) \nabla_x p^{t,x}(y)d\lambda^d(y)\|\sum_{j=1}^{k-2}\|\int f^{j}(y) \nabla_x p^{t,x}(y)d\lambda^d(y)\|\prod_{i=1}^{k-3}\left(\|\int f^{i}(y)  dp^{t,x}(y)\|\vee 1\right)^{k-3}\Biggl).
\end{align*}

