body:
[Definition 26 (Real isonormal Gaussian process) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $\cH$ be a real Hilbert space.  A \emph{real isonormal Gaussian process}
over $\cH$ is a real-linear map
\[
  W:\cH\longrightarrow L^2(\Omega;\R)
\]
such that $W(h)$ is centered Gaussian for every $h\in\cH$ and
\begin{equation*}
  \E[W(h)W(k)]=\ip{h}{k}_{\cH},
  \qquad h,k\in\cH.
\end{equation*}

[Lemma 12 of arXiv:2609.02423, '2609.02423'] Let $H$ be a Hilbert space.  If $f:\R\to H$ has Fourier support in $|\xi|\le C\lambda$, then
\begin{equation}
 \sup_{x_0\in\R}\norm{f(x_0)}_H^2
 \lesssim_R
 \lambda\sup_{x_0\in\R}
 \int_\R a'\left(\frac{\lambda(x-x_0)}R\right)
 \norm{f(x)}_H^2\dd x.
\end{equation}
The analogous statement holds in the $y$ variable.

[Lem LM24 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Let $x\in E$ and $B\in \mathscr{B}^n(E)$. Then the following statements hold:
\begin{itemize}
    \item[(1)] If $B$ is finely open (in particular, if $B$ is open), then $d(x,B)=\widetilde{d}(x,B)$. 
    \item[(2)] If $B\subset \overline{\mathrm{int}^f(B)}$, then $d(x,B)=\widetilde{d}(x,B)$. In particular, if $B$ is the closure of an open subset of $E$, then $d(x,B)=\widetilde{d}(x,B)$. 
\end{itemize}

[Proposition 15 of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[proposition]{prop:ll_R123_ucp_zero}
For \(\ell=1,2,3\),
\begin{equation}
    R^{(\ell),n}
    \xrightarrow{\mathrm{ucp}}0 .
\end{equation}

[Definition 34 of arXiv:2607.18104, '2607.18104'] Define the \textbf{patched last passage times} $\Tpat$ on $(R_n)^2_{\uparrow}$ of length $N^{3/2}$ via a maximization procedure over the last passage times on the restricted rectangles. More precisely, we take $\Tpat_{u,v}$ when $u,v \in R_{n}^{i}$ for some $i\in \lbr n\rbr$ as in \eqref{def:PatchedShort}. For all $u,v \in R_n$ such that $u \in R_n^{i}$ and $v \in R_n^{j}$ with  $1\leq i<j \leq n$, we proceed by induction as in Definition~\ref{def:PatchedDLExt}. When $j=i+1$, 
\begin{equation}
\Tpat_{u,v} :=   \sup_{w\in \partial \bar{R}_n^{i}} \big(\Tpat_{u,w} +  \Tpat_{w,v}\big).   
\end{equation} 
When $k=j-i>1$, suppose that the patched last passage times have been defined for all $i^{\prime},j^{\prime}<k$, and set
\begin{equation}
\Tpat_{u,v} :=   \sup_{w\in \partial \bar{R}_n^{j-1}} \big(\Tpat_{u,w} +  \Tpat_{w,v}\big).   
\end{equation}

