[Lem genbb of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $P,Q$ be distinct plaques, with separating sides $g_P\subset\partial P$ and $g_Q\subset\partial Q$ oriented parallel.  The change of canonical snake basis of $g_P$ to that of a side $g_Q^\prime$ of $Q$ is given by a matrix 
\begin{equation}
 T\bigl(t_\rho(Q)\bigr)^{\delta}
 \;\Sigma_\rho(g_Q,g_P)\;
 E\bigl(e_\rho(P,Q)\bigr),
 \qquad \delta\in\{+1,-1\},
\end{equation}
where $\Sigma_\rho(g_Q,g_P)$ is a slithering map.

[Definition Def_UniversalSpaceOfDiracBundles of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Denote by $\mathbf{Met} \subseteq \Gamma\paren{X,\Hom(S^2TX,\mathbb{R})}$ the space of Riemannian metrics on $X$.
  The \defined{space of Dirac bundle structures} on $S$ is the tame Fréchet submanifold
  \begin{equation*}
    \mathbf{Dir}
    \coloneq
    \set*{
      (g;\gamma,\nabla) \in \mathbf{Met} \times \Gamma\paren{X,\Hom(TX,{\mathfrak o}(S))} \times \mathscr{A}(S)
      :
      \begin{aligned}
        & (\gamma,\nabla)
        ~\text{is a Dirac bundle structure} \\
        & 
        ~\text{with respect to}~
        g              
      \end{aligned}
    }.
  \end{equation*}
  In the following a triple $(g;\gamma,\nabla) \in \mathbf{Dir}$ is often abbreviated to ${\mathbf{p}}$
  (which, of course, stands for parameter).
  \qedhere

[Prop approx_maximal of arXiv:2608.30048, 'Counterexamples for generalizations of the non-elliptic Schr\"{o}dinger maximal operator'] Let $0<c_0<1/2$ be a small constant and $\delta_0$ be as in (equation eqn:phi_delta of the paper). Suppose $\sigma \leq 1$, if $Q_{k-i}$ vanishes for all $d\leq i \leq k$, and otherwise, suppose $\sigma\leq (d-1)/d$. Then there exist constants $0< c_1(\delta_0,P_k),c_2(P_k)<1$ such that for all  $c_1<c_1(\delta_0,P_k),c_2<c_2(P_k)$ and $0<c_3<1$ as small as we like, the following holds. 

Let $R$ be sufficiently large depending on $c_1,c_2,\phi,\sigma,P_k$.
Let $x\in [-c_1,-c_1/2]\times [-c_1,c_1]^{n-1}$ and suppose $t\in (0,1)$ satisfies  
    \begin{align*}
        t &= \frac{-x_1}{\partial_1 P_k(0,R')} + \tau, \qquad \text{where } |\tau| \leq \frac{c_2\delta_0}{S_1R^{k-1}},\qquad \text{and }
        t \leq \frac{c_3}{R^{k-1}},
    \end{align*}
    where $R'=(R_2,...,R_n)$ with $R_j=0$ for $2\leq j \leq m$ and $R_j = N_j R$ for $m+1\leq j \leq n$.

Then $ |T_t^{P}f(x)| \geq (2\pi)^{-n}(1-c_0)^n + E$, where $ E \ll_{\phi,n,P_k}c_3.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm lln_local of arXiv:2509.07729, 'Permuton and local limits for the Luce model'] Fix $k\geq 1$ and $\pi\in\mathcal S_k$. Assume that $\sigma_n\sim \Luce(\theta_1,\dots,\theta_n)$ and that
	\begin{equation}
		\Lambda(\pi):=\lim_{n\to +\infty}\frac{1}{n}\sum_{i=0}^{n-k}p\mathopen{}\mathclose\bgroup\originalleft(\theta_{i+\pi^{-1}(1)},\dots, \theta_{i+\pi^{-1}(k)}\aftergroup\egroup\originalright)
	\end{equation}
	exists. 
	Then, the following convergence in probability holds
	\begin{equation*}
		\pcocc(\pi,\sigma_n)\to\Lambda(\pi).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2607.04012, 'Hölder regularity for backward stochastic Volterra integral equations and applications to '] Suppose that Assumption \ref{assumption-Holder-BSVIE} holds, and let $(Y,Z)$ be the unique solution to the BSVIE \eqref{eq:bsvie-intro}. 

    Let $\pi$ be a partition of $[0,T]$. For each $k\in\{0,\dots,N-1\}$, define
    \begin{gather}
        \Psi_k^\pi
        \coloneqq
        \frac{1}{\Delta_k}
        \int_{t_k}^{t_{k+1}}\Psi(t)\,dt.
    \end{gather}
    Moreover, for $0\leq k\leq N-1$ and $s\in[t_k,T]$, define
    \begin{gather}
        G_k^\pi(s,y,z)
        \coloneqq
        \begin{cases}
        0, & s\in[t_k,t_{k+1}), \\[0.4em]
        \displaystyle
        \frac{1}{\Delta_k}
        \int_{t_k}^{t_{k+1}}
        G(r,s,y,z)\,dr,
        & s\in[t_{k+1},T].
        \end{cases}
    \end{gather}
    Let $\big(Y^\pi(t_k,\cdot),Z^\pi(t_k,\cdot)\big)_{k=0}^{N-1}$ be the solution of the BSDE system associated with the data $(\Psi^\pi,G^\pi)$. Then
    \begin{flalign}
        \mathbb E\bigg[
        \int_0^T |Y(t)-Y^\pi(\tau(t),t)|^2\,dt
        \bigg]
        +
        \mathbb E\bigg[
        \int_0^T\int_t^T
        |Z(t,s)-Z^\pi(\tau(t),s)|^2\,ds\,dt
        \bigg]
        \longrightarrow 0
    \end{flalign}
    whenever $|\pi|\to0$.

