[Theorem ref:MainThm of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] For all $\lambda>0$ and $\beta \geq 0$, there exists a mass $m_{*}=m_{*}(\lambda,\beta)$ and a constant $C=C(\lambda,\beta)$ independent of $N$ with the following property.  Any infinite volume limit $\nu^{N}=\nu^{N,\lambda,\beta}$ of the Linear Sigma Model on $\mathbb{R}^{2}$ obtained from periodic b.c. satisfies 
\begin{equation}
\bigg | \int_{\mathcal{D}'(\mathbb{R}^{2})}F(\Psi)d( P_{i} \nu^{N}-\mu_{m_{*}} )(\Psi)  \bigg | \lesssim_{F}\frac{C}{N^{\frac{1}{2}}}   
\end{equation}
for all $i \in [N]$ and suitable cylindrical functionals $F: \mathcal{D}'(\mathbb{R}^{2}) \mapsto \mathbb{R}$, where the limiting mass $m_{*}$ satisfies
\begin{equation}
\ln m_{*}=-2\pi \beta+O\big (\lambda^{-1} \big). 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] Suppose $1 \leq k \leq n$. If $M_{k,k}$ is non-singular, then there is a canonical isomorphism of groups equipped with a symmetric pairing:
\begin{equation}

V_k^{\perp} \Big/ V_k \cong \Ker(M_{k,k}) \times \Q_p^{n-k} 
\end{equation}
where the pairing on the right hand side is the sum of the pairing on $\Ker(M_{k,k})$, and some symmetric pairing on $\Q_p^{n-k}$. The pairing on the left hand side is the pairing induced by $M_{n,n}$.

[Theorem thm:rectangular Appell polynomials of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{f_{n}\}\subset\mathcal{LPI}$ and satisfy Assumption (assump:main assumption of the paper). If $\beta\equiv\beta_n$ and $\frac{n}{n+\beta}\rightarrow \lambda\in (0,1]$, then \begin{equation}
		\left\llbracket f_n\left(\frac{\lambda}{n}\mathscr{L}_\beta\right)z^{n}\right\rrbracket\Rightarrow\mathsf{MP}_{1,\lambda}\boxtimes \mu_{c,\Sigma},
	\end{equation} 
	 where $\mu_{c,\Sigma}$ is the $\boxplus$-ID limit of the Appell polynomials $A_{n,g_n}$ from Theorem (thm:main result, general of the paper) and $\mathsf{MP}_{1,\lambda}$ is the standard Marchenko--Pastur distribution with density 
	\begin{align*}
		\mathrm{d}\mathsf{MP}_{1,\lambda}(x)
		=\frac 1 {2\pi\lambda x} \sqrt{\big((1+\sqrt{\lambda})^2-x\big) \big(x-(1-\sqrt{\lambda}\big)^2  }\big)\mathrm{d} x \text{ on } x\in[(1-\sqrt{\lambda})^2, (1+\sqrt{\lambda})^2].
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:dilation of arXiv:2607.24705, 'Derangetropy Operators'] Let $f \in \mathcal{D}$. Then:
		\begin{enumerate}[label=\normalfont(\roman*), leftmargin=*]
			\item $U_{f}$ is an isometry; for $f \in \mathcal{D}_{+}$ it is
			unitary onto $L^{2}(\operatorname{supp}f)$, with inverse
			\begin{equation*}
				\psi \;\longmapsto\; (\psi\circ Q)\,\sqrt{Q'}.
			\end{equation*}
			\item For every unit vector $g \in L^{2}(0,1)$,
			\begin{equation*}
				|U_{f}\,g|^{2} = \rho_{|g|^{2}}[f]:
			\end{equation*}
			the modulation family $\{\rho_{v}[f] : v \in \mathcal{W}\}$ is
			exactly the set of squared moduli of unit amplitudes transported by
			$U_{f}$. In particular,
			\begin{equation*}
				\rho_{w_{k}}[f] = \big|\psi_{k}[f]\big|^{2},
				\qquad
				\psi_{k}[f] := U_{f}\,\varphi_{k},
			\end{equation*}
			and, for $f \in \mathcal{D}_{+}$, the family
			$\{\psi_{k}[f]\}_{k\ge1}$ is an orthonormal basis of
			$L^{2}(\operatorname{supp}f)$; for general $f \in \mathcal{D}$ the
			support is read as $\{f > 0\}$ modulo null sets. The word dilation
			is used in the loose sense of a lift to a larger space.
			\item For every increasing differentiable homeomorphism $T$ with
			positive derivative, equivariance is unitarily implemented:
			\begin{equation*}
				U_{T_{\#}f} = V_{T}\,U_{f},
				\qquad
				V_{T}\,\psi = (\psi\circ T^{-1})\,\sqrt{\big|(T^{-1})'\big|};
			\end{equation*}
			for decreasing $T$ the rank reflection intervenes,
			$U_{T_{\#}f} = V_{T}\,U_{f}R$ with $(Rg)(z) = g(1-z)$.
		\end{enumerate}

