[Definition 1 of arXiv:2608.04937, '2608.04937'] We say that a stochastic process $X$ is a solution to the mean-field stochastic differential equation on $[0,T]$ with initial condition $\xi$, generator $B$, diffusion coefficient $\sigma$, and given processes $Y,Z$ (\textnormal{MF-SDE}$^T(\xi,B,\sigma,Y,Z)$ for short) if
\begin{enumerate}
\item[(a)] $\int^T_0|B(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))|\,dr<\infty$,
\item[(b)] $X_t=\xi+\int^t_0 B(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))\,dr+\sigma W_t$, $t\in[0,T]$.
\end{enumerate}

[Proposition 20 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Let $\widehat X$ be a strong solution of \eqref{eq: fully regularized SDE}. Then $\widehat X\in \mathbb L^{1,2}$, and in particular for every $i=1,\dots,N$
\begin{align*}
    \int_0^T \int_0^T \mathbb{E}[|D_s^i \widehat X_t|^2]\,ds\,dt\leq C,
\end{align*}
where $C$ does not depend on $N, \frs$ or $h$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma shifting RW of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] Let $(X_n)_{n\in\mathbb{N}}$ be a random walk on a hyperbolic group $G$ with symmetric step distribution $\mu$ whose support is finite and generates $G$ and starting point $X_0=o$. Fix $m\in \mathbb{N}$ and set
\begin{align*}
\bar Z^m_n &:= X_m^{-1}X_{m-n} &&\text{ for } n=0,...,m;\\
Z^m_n &:= X_m^{-1}X_{m+n} &&\text{ for } n\geq m\\
\end{align*}
Then the following hold:
\begin{itemize}
\item $\big(\bar Z^m_n\big)_{n=0}^m$ and $\big(Z^m_n\big)_{i=0}^{\infty}$ are independent for any $m\in\mathbb{N}$. 
\item Furthermore, they converge in distribution to independent random walks $\big(\bar Z_n\big)_{n\in \mathbb{N}}$ and $\big(Z_n\big)_{n\in\mathbb{N}}$ with step distribution $\mu$ and starting point $o$.
\item Finally, $\big(\bar Z_n\big)_{n\in \mathbb{N}}$ and $\big(Z_n\big)_{n\in\mathbb{N}}$ converge a.s to points $Z_{\infty}$ and $Z_{-\infty}$ on $\partial G$.
\end{itemize}

