body:
[Cor cor_bounded_st_times of arXiv:2606.23648, '\textsc{Optimal Stopping for a Diffusion with Unobserved Bernoulli Drift}'] Fix \(x\ge0\), and let \(y_x^*\) be as in Proposition (prop_stopping_for_large_y of the paper). In the fixed-\(x\) problem (equation 2d_value_func_def of the paper) with value $U_x(\cdot)$, it is enough to minimize over stopping times \(\tau\) satisfying
    \begin{equation}
        \tau\le \tau_{-x,y_x^*} \quad 
        \text{ a.s., where }
        \qquad
        \tau_{\xi,\zeta}
        \coloneqq
        \inf\{t\ge0:Y_y(t)\notin(\xi,\zeta)\}.
    \end{equation}

[Lemma 8 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] (i) Let $\phi(x)=\left(1+\frac{1}{x^2}\log \frac{2x-1}{2(x-1)}\right)^{\frac{1}{2}}-1$ and $1<q<\infty$. Suppose that $\|Z\|_{BMO_G}<\phi(q)$. Then, we have 
    \begin{align*}
        \sup_{\P\in\mathcal{P}}\sup_{\tau\in \mathcal{T}_0^T}\left\|\E^{\P}_\tau\left[\frac{\mathcal{E}(Z)_T^q}{\mathcal{E}(Z)_\tau^q}\right]\right\|_{L^\infty(\P)}\leq C_q,
    \end{align*}
    where $C_q>0$ is a constant depending only on $q$. 

    \noindent (ii) Given $1<r<\infty$, suppose that $\|Z\|_{BMO_G}<\frac{\sqrt{2}}{2}(\sqrt{r}-1)$. Then, we have
    \begin{align*}
        \sup_{\P\in\mathcal{P}}\sup_{\tau\in \mathcal{T}_0^T}\left\|\E^{\P}_\tau\left[\left(\frac{\mathcal{E}(Z)_\tau}{\mathcal{E}(Z)_T}\right)^{\frac{1}{r-1}}\right]\right\|_{L^\infty(\P)}\leq C_r,
    \end{align*}
    where $C_r>0$ is a constant depending only on $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.27545, 'A simple proof of rapid mixing on random regular graphs beyond uniqueness'] Let $\mathcal{X} \subseteq \{0,1\}^V$ be a non-empty downward closed set family and suppose $\mu$ is a distribution fully supported on $\mathcal{X}$.  Suppose that for $\delta \in (0,1)$ we have that for all $\sigmabf \in \mathcal{X}$ the matrix $M_{\sigmabf}\in \R^{V\times V}$ given by
		\begin{equation}
			M_{\sigmabf}(u,v)=(1 - \delta)r_v(\sigmabf)\one_{u = v} - r_v(\sigmabf)(r_u(\sigmabf\cup \{v\}) - r_u(\sigmabf))  
		\end{equation}
		is positive semidefinite. Then continuous time Glauber dynamics for $\mu$ has spectral gap at least $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 31 (Deterministic bias, mixed-damping regime) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, for the mixed-damping regime \(\eta\gtrsim(1-\rho)^2\), the deterministic bias decomposes into $\cS_{\nesterov}(k) = \cS_{\mathrm{over}}(k) + \cS_{\mathrm{under}}(k)$, where the overdamped tail satisfies the two-sided bounds:
\begin{equation*}
    \cS_{\mathrm{over}}(k)
    \eqsim
    \begin{cases}
    \left(\frac{(1-\rho)^2}{\eta}\right)^s, &\qquad k\lesssim\frac{1}{1-\rho},\\
    \left(\frac{1-\rho}{\eta k}\right)^s, &\qquad k\gtrsim\frac{1}{1-\rho},
    \end{cases}
\end{equation*}
and $\cS_{\mathrm{under}}(k)$ represents the underdamped transient whose properties are formally established in Lemma~\ref{lem:nes_underdamped_transient_properties}.

[Proposition 7 (Additive-mixture identity) of arXiv:2608.21466, 'Spectral partitioning for $k$-block averaging kernels of finite Markov chains'] Let $k\in\llbracket 2,n-1\rrbracket$.
	For every $k$-block partition $\mathcal O$,
	\begin{equation}
		H(\mathcal O)
		=\operatorname{Tr}\left(
		\frac{P^2}{4}
		+\frac{G_{\mathcal O}P}{2}
		+\frac{G_{\mathcal O}}{4}
		-\Pi
		\right).

	\end{equation}
	Moreover,
	\begin{equation}
		H(\mathcal O)
		=C_{P,k}
		+\frac12\operatorname{Tr}(Q_{\mathcal O}P),

	\end{equation}
	where
	\begin{equation}
		C_{P,k}
		:=\frac14\operatorname{Tr}(P^2)+\frac{k-2}{4}.

	\end{equation}
	Consequently, for fixed $P$ and $k$,
	\begin{equation*}
		\operatorname*{argmin}_{|\mathcal O|=k}H(\mathcal O)
		=
		\operatorname*{argmin}_{|\mathcal O|=k}
		\operatorname{Tr}(Q_{\mathcal O}P).

	\end{equation*}

[Lemma 13 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Define a mapping $ \Tilde{\Lambda} : (\rd \times \R) \times \mathsf{N}_{s,m}(\rd\times \R) \rightarrow \Fd$ by the formula
    \begin{equation*} 
        \Tilde{\Lambda}(\bfx,\varphi)\coloneqq \begin{cases} L(\bfx,\varphi), &\bfx \in \varphi, \\
        B(0,1), &\bfx \notin \varphi.
        \end{cases}
    \end{equation*}
 Then such a mapping is measurable \wrt\,$\borel(\rd \times \R) \otimes \mathcal{N}_{s,m}(\rd\times \R)$ and $\borel(\Fd)$. Furthermore, the mapping $\Lambda:(\rd \times \R) \times \mathsf{N}_{s,m}(\rd\times \R) \rightarrow \FdAp$ defined by the formula
    \begin{equation} 
        \Lambda(\bfx,\varphi)\coloneqq \begin{cases} \Tilde{\Lambda}(\bfx,\varphi), &\mathrm{int}(\Tilde{\Lambda}(\bfx,\varphi)) \neq \emptyset, \\
        B(0,2), & \mathrm{int}(\Tilde{\Lambda}(\bfx,\varphi)) = \emptyset,
        \end{cases}
    \end{equation}
     is measurable \wrt\,$\borel(\rd \times \R) \otimes \mathcal{N}_{s,m}(\rd\times \R)$ and $\borel(\FdAp)$.

