body:
[Lemma 6 of arXiv:2606.14170, 'Uniform-in-time error estimates for McKean-Vlasov SDEs with common noise and stochastic al'] Suppose that Assumptions \ref{A1} and \ref{N1} hold with $\lambda_1>2\lambda_2$. Then for any $p\ge 1$ and $h\in (0,h_p]$ with$$h_p=1\wedge\frac{\lambda_1-2\lambda_2}{2p(1+\lambda_2)^p},$$ there exists a constant $C>0$ such that for all $n\ge 0$ and $i\in\mathbb{S_N}$,
\begin{align*}
\mathbb{E}|X_{nh}^{i,N, h}|^p\le {\rm e}^{-\gamma^*nh}\mathbb{E}|X_0^{i,N,h}|^p+C, 
\end{align*}
in case of $\mathbb{E}|X_0^{i,N,h}|^p<\infty$, where $\gamma^*=\frac{\lambda_1-2\lambda_2}{2+3(2\lambda_1-3\lambda_2)}$.

[Lemma 42 (Outlier test-function convergence) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Assume \(|\theta|>1\), and let \(\varphi\) be analytic on a neighborhood of
\(\rho_\theta\).  Then
\begin{equation}
 \varphi\bigl(\lambda_{\rm out}(M_N^f)\bigr)
 =\varphi(\rho_\theta)+o_{\mathbb P}(1).
\end{equation}

[Proposition 20 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] The process
\begin{equation}
 M_t^\beta
 = \mathrm e^{\lambda(\beta)t-\beta A_t}
   \frac{\phi_\beta(W_t)}{\phi_\beta(x)},
 \qquad t\ge0,
 \nonumber
\end{equation}
is a positive mean-one  $(\mathcal F_t) $-martingale under
 $\mathbb P_x $.  The consistent measures
\[
 \de \mathbb P_x^\beta|_{\mathcal F_t}
 =M_t^\beta\,\de \mathbb P_x|_{\mathcal F_t}
\]
define the law of the diffusion
\begin{equation}
 \de X_t=\de B_t+\nabla\log\phi_\beta(X_t)\,\de t,
 \qquad X_0=x.

\end{equation}

[Definition 8 (Information flow associated with coordinate $i$) of arXiv:2607.20823, 'Fluctuation impossibility results for stochastic burst networks'] Assuming that the series below is absolutely convergent, define
\begin{align}
(\dot I)_{X_i}
&:=
\sum_{n\ge0}
\sum_{v\in\mathbb Z_{\ge0}^{N-1}}
\sum_{k\ge1}
\pi(n,v)f_i(v)p_{i,k}
\log\frac{\pi_{n+k}^i(v)}{\pi_n^i(v)}
\notag\\
&\quad+
\sum_{n\ge1}
\sum_{v\in\mathbb Z_{\ge0}^{N-1}}
\pi(n,v)\frac{n}{\tau_i}
\log\frac{\pi_{n-1}^i(v)}{\pi_n^i(v)}.

\end{align}

[Lemma lemma-iteration-trick of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] Let $R>0$, $N,M\in \mathbb{N}$. Let $V,E, A, \left\{ U_i \right\}_{i=1}^N, \left\{F_j\right\}_{j=1}^M$ be non-negative, locally bounded functions defined on $[0,R)$ such that $A,F_j$ are non-increasing for all $j=1,\dots, M$. We assume that there exist $L_i,c_i, \tilde c, \ell_j\in [0,\infty)$, such that for any $s\ge 0$ and $\delta>0$ with $s+\delta \leq R$ we have  
    \begin{equation}

        \begin{split}
        V(s+\delta) + E(s+\delta)& \leq A(s) + \sum_{i=1}^N \left(\frac{2}{\delta}\right)^{L_i} U_i\left(s+\frac{\delta}{2}\right) \\
        & \leq A(s) + \varepsilon\sum_{i=1}^N c_i\left(\frac{4}{\delta}\right)^{L_i}U_i\left(s + \frac{\delta}{4} \right) + \varepsilon \, \tilde c \, E\left(s\right) + C_\varepsilon\sum_{j=1}^M \left( \frac{2}{\delta}\right)^{\ell_j} F_j(s),
        \end{split}
    \end{equation}for any $\varepsilon>0$ and a constant $C_\varepsilon<\infty$. Then, there exists a  constant $C^*\in (0,\infty)$ depending only on the preceding parameters, such that for any $s,\delta$:
    \begin{equation}

        V(s+\delta) \leq C^* \left(A(s) + \sum_{j=1}^M\delta^{-\ell_j} F_j(s)\right).
    \end{equation}

