[Definition GWS of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] A stochastic process $\boldsymbol{\mathcal{Y}}(t):=\boldsymbol{\mathcal{Y}}(t;\mathfrak{r},\omega,\boldsymbol{\mathcal{Y}}_{\mathfrak{r}})$ is a $\textsl{global (analytic) weak solution}$ of the system (equation STGF of the paper) for $t\geq\mathfrak{r}$ and $\omega\in\Omega$ if for $\mathbb{P}$-a.s. $\omega\in\Omega$
		\begin{align*}
			\boldsymbol{\mathcal{Y}}(\cdot)\in\mathrm{C}([\mathfrak{r},\infty);\mathbb{H})\cap\mathrm{L}^{2}_{\mathrm{loc}}(\mathfrak{r},\infty;\mathbb{V})\cap \mathrm{L}^{4}_{\mathrm{loc}}(\mathfrak{r},\infty;\mathbb{W}^{1,4}(\mathbb{Q}))
		\end{align*}
		and 
		\begin{align*}
			&(\boldsymbol{\mathcal{Y}}(t),\boldsymbol{\psi})+\nu\int_{\mathfrak{r}}^{t}(\nabla\boldsymbol{\mathcal{Y}}(\xi),\nabla\boldsymbol{\psi})\/\mathrm{d}\/\xi+\int_{\mathfrak{r}}^{t}b(\boldsymbol{\mathcal{Y}}(\xi),\boldsymbol{\mathcal{Y}}(\xi),\boldsymbol{\psi})\/\mathrm{d}\/\xi\nonumber\\&=(\boldsymbol{\mathcal{Y}}_{\mathfrak{r}},\boldsymbol{\psi}) - \alpha \int_{\mathfrak{r}}^{t}\langle\mathrm{J}(\boldsymbol{\mathcal{Y}}(\xi)), \boldsymbol{\psi}\rangle \/\mathrm{d}\/\xi - \beta \int_{\mathfrak{r}}^{t}\langle\mathrm{K}(\boldsymbol{\mathcal{Y}}(\xi)) , \boldsymbol{\psi}\rangle \/\mathrm{d}\/\xi +\int_{\mathfrak{r}}^{t}(\boldsymbol{\mathfrak{K}}(\xi),\boldsymbol{\psi})\/\mathrm{d}\/\xi +\sigma\int_{\mathfrak{r}}^{t}(\boldsymbol{\mathcal{Y}}(\xi),\boldsymbol{\psi})\/\mathrm{d}\/\mathrm{W}(\xi),
		\end{align*}
		for every $t\geq\mathfrak{r}$ and for every $\boldsymbol{\psi}\in\mathbb{X}$.

