[Theorem 1 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] When \(t \rightarrow \infty\),
		\begin{equation}
			\PR(\D\geq t) = C_d (d\kappa_d)^d t^{d(d-1)} e^{-\kappa_d t^d} + \mathcal{O}( t^{d(d-2)} e^{-\kappa_d t^d})
		\end{equation}
		where 
		\begin{equation}
			C_d = \frac{1}{2^{d-1}\sqrt{\pi}(d-1)!} \frac{\Gamma\left(\frac{d}{2}\right)^d}{\Gamma\left(\frac{d+1}{2}\right)^{d-1}}.

		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition energy-inequality of arXiv:2609.02769, 'Divergence-Free Approximation in Sobolev and Lebesgue Spaces on general unbounded domains '] We say that $\boldsymbol{u}$ is a \emph{Leray-Hopf weak solution} of the CBF equations (equation abstract-CBF of the paper), with initial data $\boldsymbol{u}_0\in\mathbb{H}$, if it is a weak solution in the sense of Definition (weakd of the paper) that additionally satisfies the following properties:
	\begin{enumerate}
		\item  \emph{strong energy inequality}:
		\begin{align}
			&	\|\boldsymbol{y}(t_1)\|_{\mathbb{H}}^2+2\mu\int_{t_0}^{t_1}\|\nabla\boldsymbol{y}(s)\|_{\mathbb{H}}^2\/\mathrm{d}\/ s+2\alpha\int_{t_0}^{t_1}\|\boldsymbol{y}(s)\|_{\mathbb{H}}^{2}\/\mathrm{d}\/ s+2\beta\int_{t_0}^{t_1}\|\boldsymbol{y}(s)\|_{\mathbb{L}_{\sigma}^{r+1}}^{r+1}\/\mathrm{d}\/ s\nonumber\\&\leq\|\boldsymbol{y}(t_0)\|_{\mathbb{H}}^2+2\int_{t_0}^{t_1}\langle\boldsymbol{g}(s),\boldsymbol{y}(s)\rangle\/\mathrm{d}\/ s,
		\end{align}
		for almost every $t_0\in[0, T)$, including zero, and all $t_1\in(t_0, T)$.
		\item $\lim\limits_{t\downarrow 0}\|\boldsymbol{y}(t)-\boldsymbol{y}_0\|_{\mathbb{H}}=0$.
	\end{enumerate}

[Proposition p:main theorem inversion of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d,\infty]$. Suppose that $\Phi$ is an invariant locally absolutely square-integrable random complex measure which is (beyond) $p$-uniform. Then there exists an invariant transport kernel $K$ such that $\Phi = K\lambda_d$, and such that $K$ and $\lambda_d$ satisfy the conditions of Theorem~(t:main theorem of the paper).
\begin{proof}
Such a transport kernel $K$ is explicitly constructed in Appendix~(ss:Reduction to Lebesgue of the paper). There, it is named $L$, and we also do so in this proof. As in~(equation e:L of the paper), we choose it as
\begin{equation}
    L(x,B) := \kappa_d^{-1}\Phi(B\cap(B_1+x)), \quad x\in\R^d, B\in\cB^d.
\end{equation}
By Lemma~(l: simplification to lebesgue of the paper), it is invariant and $\Phi=L\lambda_d$. It also trivially fulfills Condition~(c:condition square-integrable stealthy of the paper) with respect to $\Phi$ and any $\varepsilon>0$. To apply Theorem~(t:main theorem of the paper), it remains to analyze the components of $\Psi_q$ for $q\in\N_0$ as defined in~(equation e:Psi_q definition of the paper). Let $q\in\N_0$ and suppose that $q_1,...,q_d\in\{0,...,q\}$ such that $q_1+\dots +q_d=q$. Then,
\begin{equation*}
    \int x_1^{q_1}\cdots x_d^{q_d}\, L^\ast(y, dx) = \frac{1}{\kappa_d}\int_{B_1+y}(x_1-y_1)^{q_1}\cdots(x_d-y_d)^{q_d} \, \Phi(dx).
\end{equation*}
Therefore, for $f\in\cC_c^\infty$ the $(q_1,...,q_d)$-component $\Psi_{q;q_1,...,q_d}$ of $\Psi_q$ satisfies
\begin{align*}
    \Psi_{q;q_1,...,q_d}(f) &= \int g(y) \int x^q\, L^\ast(y, dx) \, dx\nonumber\\
    &= \frac{1}{\kappa_d}\iint_{B_1+x} f(y) (x_1-y_1)^{q_1}\cdots(x_d-y_d)^{q_d} \, dy \, \Phi(dx).
\end{align*}
The inner integral is a convolution of $f$ with a bounded function with bounded support, and therefore is in $\cC_c^\infty$ as a function of $x$. Now, an application of Theorem~(t:asymptotic variance test function of the paper) and Theorem~(t: stealthy characterization of the paper) yields that if $\Phi$ is (beyond) $p$-uniform (with some radius), then $\Psi_{q;q_1,...,q_d}$ also is, which concludes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

