[Definition of arXiv:2412.09532, 'Percolation on the stationary distributions of the voter model with stirring'] $\mathcal T: T_N \to \mathbb{Z}^d$ is a \textit{proper embedding} of $T_N$ if 
    \begin{enumerate}
        \item $\mathcal T(\{ \varnothing \}) = 0$;
        \item for all $0 \leq k \leq N$ and $m \in T_{(k)}$ we have $\mathcal T(m) \in \mathcal L_{N-k}$;
        \item for all $0 \leq k \leq N$ and $m \in T_{(k)}$ we have 
        $$|\mathcal T(m_1)- \mathcal T(m)| =  L_{N-k}, \qquad |\mathcal T(m_2)- \mathcal T(m)| = 2L_{N-k}.$$
    \end{enumerate}
    We denote by $\mathcal P_N$ the set of proper embeddings of $T_N$ into $\mathbb{Z}^d$.

[Lem 59 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For $f\in \BL^{\kappa}(M)$, define $g:M\to\R$ by $g=\overline{(G^{\alpha})^{\circ 2}f}$ 
with the exponent of the McShane extension being $1$.
Then, for any 
$x\in F,\;x_n\in F_n,\;\kappa\in [1/2,1],\;p\in [1,\infty],\;\alpha\in (0,\alpha_n),$ and $t>0$,
under the condition $1_{\kappa,p}$,
it holds that
\begin{align*}
  \Big|E_x[g(X_t)]-E_{x_n}^n[g(X^n_t)]\Big|
  \lesssim &\g{c}{sg2,n}
    \Bigl\{ \|f\|_{K_n}(d_{\rm{H}}(F,F_n)+d_{\rm{H}}(F,F_n)^{\kappa}+d(x,x_n))+\|f\|_{\BL^{\kappa}(K_n)}d_{\BL^{\kappa}}(\mu,\mu_n)\Bigr\}\\
    \leq&\g{c}{sg2,n}\|f\|_{\BL^{\kappa}(K_n)}
    \Bigl\{d_{\rm{H}}(F,F_n)+d_{\rm{H}}(F,F_n)^{\kappa}+d(x,x_n)+d_{\BL^{\kappa}}(\mu,\mu_n)\Bigr\},
\end{align*}
where 
\begin{align*}
  \g{c}{sg2,n}:=\g{c}{sg1,n}+\alpha^{-1}\g{c}{estres,n}(1+\mu_n(F_n)\g{c}{continuity,1.n})+\alpha^{-2}\Big[\mu(F)\g{c}{continuity,1}+\mu_n(F_n)\g{c}{continuity,1.n}\Big].
\end{align*}

