[Proposition 18 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] \begin{align}
K_X(s,t) &=  1 - \sum_{i=1}^d \int_s^t \int_s^r K_X(s,u) K_X(u,r)  dX^\iota_u dX^\iota_r\\
&= 1 - \sum_{\iota=1}^d \int_s^t \int_s^r K_X(u,r) K_X(r,t)  dX^\iota_u dX^\iota_r. 
\end{align}

