body:
[Theorem thm:BDG of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $n\geqslant 1, \mathsf{M}_{ n}$ a non-negative    random measure on $  \mathbb  T  _{ n}^{ d}$ with $   \mathsf{M}_{ n}(  \mathbb  T  _{ n}^{ d}) = n^{ d}$ a.s.. 
  \begin{itemize}
\item {(a)} [LrY] Assume $ \mathsf{M}_{ n}$ is $  \mathbb  T _{ n}^{ d}$-invariant,  and  that   for some finite  $ c,\varepsilon >0 $, \begin{itemize}
\item {(i)} for some $ f\in \mathscr B_{ c}( \mathbb{R}^{ d})$ such that $ \int_{}f\neq 0$, for $R\in [1,n]$,
$$  \textrm{Var}\left(\mathsf{P}_{ n}(f_{ R})\right)\leqslant c 
\begin{cases} 
R^{ d}$  if $d\geqslant 3\\
 R^{ d}\ln(R)^{ -1-\varepsilon }$  if $d = 1,2\end{cases}$$
\item or (ii) its spectral measure $ \mathsf{S}_{ n}$ satisfies  for  some $ \rho   _{ 0}>0$, for $ 0<\rho   <\rho   _{ 0}$,
\begin{align}

\mathsf{S}_{ n}(B_{\rho   })\leqslant c\times 
 \begin{cases} 
\rho   ^{ d}$  if $d\geqslant 3\\
\rho   ^{ d}{ | \ln(\rho ) | ^{ -1 - \varepsilon }}$  if $d = 1,2
  \end{cases}
\end{align}
\end{itemize}
holds. Then  for some constant $ c'$  depending  on $ c,\rho _{ 0} ,d$
\begin{align}

 \widetilde{   \mathsf W}_{ 2}^{ 2}(\Leb_{ n},\mathsf{M}_{ n}) \leqslant c'n^{ d}.
\end{align} 
\item  {(b)} [BDG]  Let $ p\geqslant 1$. Assume that $ \mathsf{M}_{ n}$ has intensity $ \Leb_{  \mathbb  T  _{ n}^{ d}}$, and   that for some finite $c, \varepsilon >0$, for any square $ B\subset  \mathbb  T  _{ n}^{ d}$ with $ \Leb(B)>1,$
\begin{align}

\sup_{ n} \mathbf E  \left|
 {  \mathsf{M}_{ n}(B)-\Leb(B)}\right|  ^{ p}\leqslant  { c} \Leb(B)^{ p/2}\times 
 \begin{cases} 
{\ln(\Leb[2](B))^{ -p - \varepsilon }}$  if $d = 2.\\
1$  if $ d\neq 2.
  \end{cases}
\end{align}
\end{itemize}
Then   for some constant $ c'$ not depending  on $ n$
\begin{align*}
   \mathsf W_{ p}^{ p}(\Leb_{ n},\mathsf{M}_{ n})\leqslant c'n^{ d}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

