body:
[Lemma LEM:SW of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $\xi \in \mathbb{R}$.

\begin{itemize}
\item[(1)]  The linearized operator $\mathcal{L}_\xi$, defined in (equation lin1 of the paper),  is self-adjoint. Its spectrum is given by
\begin{align*}
\sigma(\mathcal{L}_\xi)=\sigma_d \cup \sigma_c=\{0\}\cup [1,\infty).
\end{align*}

\smallskip

\item[(2)] The eigenfunction corresponding to the zero eigenvalue arises from the tangent vector $\partial_{\xi} m_{\xi}$ to the soliton manifold $\{ m(\cdot-\xi) \}_{\xi\in \mathbb{R}}$, which is associated with translation invariance
\begin{align}
\mathcal{L}_\xi (\partial_{\xi} m_{\xi})=0.

\end{align}

\smallskip

\item[(3)] The linearized operator $\mathcal{L}_\xi$  satisfies the following coercivity: there exists $\lambda_0 \in [1,\infty ) $ such that  
\begin{align}
\jb{\mathcal{L}_\xi v,v   } \ge \lambda_0 \|v \|_{H^1}^2.

\end{align}

\noindent
for every $v \in H^1(\mathbb{R})$ with $\jb{v, \partial_{\xi} m_{\xi}}_{L^2(\mathbb{R})}=0$.

\end{itemize}

