body:
[Defi 5 (Martingale correction) of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] Let $ ( \alpha, \beta, \epsilon ) $ be damping factors, let $ ( X, U ) $ be an innovation,
and let $ \varrho $ be as in \cref{def:varrho}.
For every $ \theta \in \R^d $ for which $ X(  \theta,U ) $ is integrable we define the function
\bas{
  \Psi_{\theta} \colon \ell_{ \varrho }^d \to \R^d
}
that takes $\bx=(x_k)_{k\in-\N_0}\in \ell_\varrho^d$ to
\bas{
\Psi_{\theta}(\bx):=\sum_{m=1}^{\infty} \E\bigl[g(\bX^{\bx,\theta}(m)) -f(\theta)\bigr],}
where $f$ is the \Adam\ vector field,
where $\bX^{\bx,\theta}(m)=(\bX^{\bx,\theta}_{k}(m))_{k\in-\N_0}$ is the $\ell_{\varrho}^d$-valued random variable given by
\bas{
\bX^{\bx,\theta}_{k}(m)=\begin{cases}x_{m+k},&\text{ if }m+k\le0 , \\
X(\theta, U_{m+k}),&\text{ if } m+k>0 ,
\end{cases}
}
and where $(U_k)_{k\in\N}$ are independent copies of $U$.
$\Psi_{\theta}$ is called \emph{martingale correction in the state $\theta$}.

[Defn 22 (Test Function $\mathbb{W}_{x}$) of arXiv:2609.03821, 'Condensation and Metastability in the Supercritical Two-Species Zero-Range Process via Res'] Fix $x\in S_{\star}$. For $u,w\ge0$ and $y\in S_{\star}\setminus\{x\}$,
define
\begin{equation}
W_{N}(u,w):=\int^{u+w}_{0}U_{\epsilon}(s)\,{\rm d}s+\omega_{N}(x,y)U_{\epsilon}(u+w)(u-(u+w)\rho_{N}).
\end{equation}
Then, define a function $\mathcal{W}_{x,y}:\Omega_{N}\to\mathbb{R}$
for each $y\in S_{\star}\setminus\{x\}$ as 
\begin{equation}
\mathcal{W}_{x,y}(\bm{\eta}):=W_{N}(\mathcal{X}^{1}_{x,y}(\bm{\eta}),\mathcal{X}^{2}_{x,y}(\bm{\eta})).
\end{equation}
Finally, via the partition of unity \eqref{eq:PoU}, the global test
function $\mathbb{W}_{x}:\Omega_{N}\to\mathbb{R}$ is defined as
\begin{equation}
\mathbb{W}_{x}(\bm{\eta}):=\sum_{y\in S_{\star}\setminus\{x\}}\Theta^{x,y}_{\epsilon}\left(\frac{\bm{\eta}}{N}\right)\mathcal{W}_{x,y}(\bm{\eta}).
\end{equation}

