[Theorem thm:ChenFrankWethSphere of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] There exists a constant $C=C (n,\gamma) >0$ such that
    \begin{equation*}
        \frac{\| w \|_{H^\gamma (\mathbb{S}^n)}^2 }{\|w\|_{L^{2^*} (\mathbb{S}^n)}^2} - \frac{1}{S(n,\gamma)} \geq C \frac{\text{dist}(w,\mathcal{M}_{\mathbb{S}^n} )^2}{\|w\|_{L^{2^*} (\mathbb{S}^n)}^2}
         \quad \forall w\in H^{\gamma } (\mathbb{S}^n),
    \end{equation*}
    where $\mathcal{M}_{\mathbb{S}^n } = \{v \in H^\gamma (\mathbb{S}^n) : \mathcal{P}v \in \mathcal{M}_{\mathbb{R}^n} \} $ and $\mathcal{P}$ is the isometric isomorphism given by the stereographic projection. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:conditional-cf-short of arXiv:2608.05123, 'A central limit theorem for the random assignment problem'] For every fixed \(t\), under \(\mathbb P_n^{\mathrm{ref}}\),
\begin{equation}
 \mathbb E\left[\exp\left\{\frac{it}{\sqrt n}
 \sum_i(D_i-m_{i,n})\right\}\middle|U\right]
 =\exp\left\{-\frac{t^2}{2n}\sum_iv_{i,n}+o_{\mathbb P}(1)\right\}.
\end{equation}

[Theorem thm:DimIntermediateSpectrumConnComp of arXiv:2508.08150, 'Recent Progress on Fractal Percolation'] For any $d\geq 2$, $N\geq 2$ and $p\geq p_d(N)$, almost surely and conditioned on non-extinction, 
\begin{equation*}
\dim_{\mathrm{H}}F^c=\dim_{\theta=0} F^c  < \dim_{\theta} F^c = \dim_{\mathrm{B}} F^c \;\text{ for every } \theta\in(0,1].
\end{equation*}

