[Lemma 14 (Label-noise contribution) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] There exist constants $C,c_-,c_+>0$ such that if
\begin{equation}

    k\ge
    C
    \max\left\{
        \frac{1}{1-\rho},
        \frac{1-\rho}{\eta}
    \right\},
\end{equation}
then the finite-time label-noise contribution satisfies
\begin{equation}

    c_-\frac{\sigma^2\eta}{B(1-\rho)}
    \le
    \frac{\eta^2\sigma^2}{B}\sum_{\tau=0}^{k-1}\mathcal{K}_{\polyak}(\tau)
    \le
    c_+\frac{\sigma^2\eta}{B(1-\rho)}.
\end{equation}
In particular,
\[
    \frac{\eta^2\sigma^2}{B}\sum_{\tau=0}^{k-1}\mathcal{K}_{\polyak}(\tau)
    \eqsim
    \frac{\sigma^2}{B}\frac{\eta}{1-\rho}.
\]

[Lemma tightness_tau_k of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix a choice sequence $\mathbf x$ that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) and~(item:lb of the paper). Then, for any sequence $(I_n)_{n\in\mathbb{N}}$ with $I_n\geq I_{\hyperref[ass:A]{\mathbf{x}}}$ for all large $n$, there exists $\zeta\in(0,1)$ such that
\begin{equation}
\mathbb{P}(\tau_{k,\ell}\geq I_n)= o(I_n^{-\zeta}).
\end{equation}
\proof
Let $(U_n^w)_{w\in[\ell]}$ be $\ell$ distinct uniform elements of $\mathcal{F}_n$. Here, $U_n^w$ corresponds to the step at which the frozen vertex $f_w$ is activated. By conditioning on $(U_n^w)_{w\in[\ell]}$, we obtain 
\begin{equation} 
\P{\tau_{k,\ell}<I_n}=\E{\P{\tau_{k,\ell}<I_n\,|\, (U_n^{w})_{w\in[\ell]}}}=\E{\P{\tau_{k,\ell}<I_n\,\Big|\, ( U_n^{(w)})_{w\in[\ell]}}},
\end{equation} 
where the $ U_n^{(w)}$ are the order-statistics of the $U_n^w$. That is, $ U_n^{(1)}>\cdots > U_n^{(\ell)}$. Conditionally on these random variables, the event $\{\tau_{k,\ell}<I_n\}$ holds when at each step $i\in[I_n,n]$ such that $x_i=1$ and $ U_n^{(w-1)}>i> U_n^{(w)}$ for some $w\in[\ell+1]$ (where we set $ U_n^{(0)}=n+1$ and $ U_n^{(\ell+1)}=1$), the $(m+1)\wedge A_i$ many roots that are selected contain at most one of the $k+w-1$ many active roots of interest (the active roots labelled $a_1,\ldots,a_k$ and the first $w-1$ roots that are activated among $f_1,\ldots,f_\ell$). As a result, we have 
\begin{equation}\begin{aligned}

\mathbb P\big(\tau_{k,\ell}<I_n\,\big|\, ( U_n^{(w)})_{w\in[\ell]}\big)= \prod_{w=1}^{\ell+1} \prod_{\substack{i=\max\{ U_n^{(w)}+1,I_n\}\\ x_i=1}}^{ U_n^{(w-1)}-1} \!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\P{\text{At most one root among $k+w-1$ chosen in step $i$}}
\end{aligned}\end{equation} 
By Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:lb of the paper),  we have $A_i\geq m+1$ for all $i\geq I_n$ and all large $n$. For $w\in[\ell+1]$, if $ U_n^{(w-1)}-1>I_n$ and $i\in[\max\{ U_n^{(w)}+1,I_n\}, U_n^{(w-1)}-1]$, we then have 
\begin{equation}\begin{aligned} 
\mathbb P({}&\text{At most one root among $k+w-1$ chosen in step $i$})\\ 
&=\frac{1}{\binom{A_i}{m+1}}\bigg(\binom{A_i-(k+(w-1))}{m+1}+(k+(w-1))\binom{A_i-(k+(w-1))}{m}\bigg)\\ 
&=1-\frac{1}{\binom{A_i}{m+1}}\bigg(\binom{A_i}{m+1}-\binom{A_i-(k+(w-1))}{m+1}-(k+(w-1))\binom{A_i-(k+(w-1))}{m}\bigg).
\end{aligned}\end{equation} 
By repeatedly applying Pascal's rule, we find that, for integers $s,t,r\geq 0$ such that $t-s\geq r$,
\begin{equation} 
\binom{t}{r}=\binom{t-1}{r-1}+\binom{t-1}{r}=\cdots=\binom{t-s}{r}+\sum_{\ell=1}^s \binom{t-\ell}{r-1}.
\end{equation} 
Applying this equality with $(1)$: $t=A_i$, $r=m+1$, and $s=k+(w-1)$ and $(2)$: $t=A_i-\ell$, $r=m+1$, and $s=k+(w-1)-\ell$, where $\ell\in[k+(w-1)-1]$, we arrive at 
\begin{equation}\begin{aligned} 
\binom{A_i}{m+1}{}&-\binom{A_i-(k+(w-1))}{m+1}-(k+(w-1))\binom{A_i-(k+(w-1))}{m}\\ 
={}&\sum_{\ell=1}^{k+(w-1)-1}\sum_{x=\ell+1}^{k+(w-1)}\binom{A_i-x}{m-1}\leq (k+(w-1))^2\binom{A_i-2}{m-1}\leq (k+(w-1))^2 A_i^{m-1}.
\end{aligned}\end{equation} 
As a result, we have the lower bound
\begin{equation} 
\mathbb P(\text{At most one root among $k+w-1$ chosen in step $i$})\geq 1-\frac{(k+(w-1))^2 A_i^{m-1}}{\binom{A_i}{m+1}}\geq 1-C A_i^{-2}, 
\end{equation} 
where the constant $C>0$ does not depend on $i$ and $w$. We use this in~(equation eq:ptaukl of the paper) to obtain 
\begin{equation} 
\P{\tau_{k,\ell}<I_n}\geq \mathbb E\Bigg[\prod_{w=1}^{\ell-1}\prod_{\substack{i=\max\{ U_n^{(w)}+1,I_n\}\\ x_i=1}}^{ U_n^{(w)-1}}\big(1-C A_i^{-2}\big)\Bigg]\geq 1-C\sum_{w=1}^{\ell-1}\mathbb E\Bigg[\sum_{\substack{i=\max\{ U_n^{(w)}+1,I_n\}\\ x_i=1}}^{ U_n^{(w)-1}} A_i^{-2}\Bigg].
\end{equation} 
We can further bound the right-hand side from below by $1-C\sum_{i=I_n}^n A_i^{-2}$. By using Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:lb of the paper), we finally obtain
\begin{equation} 
\P{\tau_{k,\ell}<I_n}=1-\mathcal{O}(I_n^{-2\delta}).
\end{equation} 
Choosing $\zeta\in(0,2\delta)$ concludes the proof.\qed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:reflection-increment of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Suppose $(\zeta(x))_{x\in\mathbb{Z}^d}$ are i.i.d.\ with mean zero. Then $\mathbb{E} u_t(0)$
	is nondecreasing and concave in $t$, and
	\begin{equation}
		\mathbb{E} u_{t+1}(0)-\mathbb{E} u_t(0)=\mathbb{E}(-\zeta(0)-Pu_t(0))_+\, .
	\end{equation}

[Conjecture Pure coulomb gas no spin of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For irrational $\kappa \in(0,8)$, $\nu=n(\kappa)$ the pure partition functions are related to Coulomb gas integrals by affine meander matrix:
\begin{equation}
\mathcal{J}_\beta^{(m,n,\eta)}(\boldsymbol{\theta})=\sum_{\alpha \in \operatorname{LP}(n,m)} \mathcal{M}_{\kappa}(\alpha, \beta) \mathcal{Z}_{\alpha}^{\eta}(\boldsymbol{\theta}), \quad  \beta \in \mathrm{LP}(n,m).
\end{equation}

Conversely, we have 

\begin{equation}
\mathcal{Z}_{\beta}^{\eta}(\boldsymbol{\theta})=\sum_{\alpha \in \operatorname{LP}(n,m)} \mathcal{M}_\kappa(\alpha, \beta)^{-1} \mathcal{J}_\alpha^{(m,n,\eta)}(\boldsymbol{\theta}), \quad  \beta \in \mathrm{LP}(n,m).
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem thm:large_t of arXiv:2512.17808, 'Zeros of polynomial powers under the heat flow'] Fix a closed disk $K\subseteq \mathbb{C}$ centered at $\frac 1  \alpha \sum_{j=1}^d\alpha_j\lambda_j$.  Then, for sufficiently large $t>0$,
\begin{align}
	U_t(z)=\max_{j=1,\dots,d+1}G\big(z,u_t^j(z)\big), \quad z\in K
	\end{align}
	and	$\supp(\mu_t)\cap K$
	consists of a single smooth curve that converges, as $t\to\infty$, in Hausdorff metric to a horizontal segment through the center of mass $\frac 1  \alpha \sum_{j=1}^d\alpha_j\lambda_j$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For every smooth function \(\Phi\in C^\infty(X)\),
\begin{equation}
        \int_X J_\pi\,\Phi\,\omega^{m+r}
        =
        \frac{(m+r)!}{r!\,m!}
        \int_{Y^\circ}
        \left(
        \int_{F_y}\Phi\,\omega_y^r
        \right)
        \eta^m .
\end{equation}

[Definition 8 (Homogeneous $\alpha$-H\"{o}lder norm) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $\alpha\in(0,1]$. For any path $\mathbf{x}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$, the homogeneous $\alpha$-H\"{o}lder norm of $\mathbf{x}$ is defined as
    \begin{equation*}
        \lVert \mathbf{x}\rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]} := \sup_{0\leq s<t\leq T}\frac{d_{cc}(\mathbf{x}_s,\mathbf{x}_t)}{|t-s|^\alpha}.
    \end{equation*}
    Then, for any $\mathbf{x},\mathbf{y}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$, the homogenous $\alpha$-H\"{o}lder distance between $\mathbf{x}$ and $\mathbf{y}$ is defined as
    \begin{equation*}
        d_{\textup{hom $\alpha$-H\"{o}l};[0,T]}(\mathbf{x},\mathbf{y}) := \sup_{0\leq s<t\leq T}\frac{d_{cc}(\mathbf{x}_{s,t},\mathbf{y}_{s,t})}{|t-s|^\alpha},
    \end{equation*}
    where $\mathbf{x}_{s,t}:=\mathbf{x}_s^{-1}\bullet \mathbf{x}_t$.

