[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:lattice_animal}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and let $J : G \times G \to \mathbf{R}_+$ be transitive, and suppose that $J(x,y) = \Theta(d_G(x,y))^{-d \alpha}$ with $\alpha > 1$.

    The finite cluster of the origin $K$ has a unique block decomposition $\mathcal{B}(K)$, the block graph $\mathcal{H}(\mathcal{B}(K))$ is connected, and the block decomposition is $\mathcal{B}(K)$-isolated. 

    In particular,

    \begin{equation}
        \mathbf{P}_{\beta}
        \left(
            \#K <\infty 
        \right)
        \leq
        \sum_{\substack{
            b \in \mathbf{N},
            \mathbf{m} \in \mathbf{N}^{b}
            \\
            \mathbf{B} \in \mathcal{A}(b,\mathbf{m})
        }}
        \mathbf{P}_{\beta}
        \left(
            \mathcal{B}(K)
            =
            \mathbf{B},
            \mathcal{H}(\mathbf{B})
            \text{ is connected},
            \mathbf{B}
            \text{ is }
            \mathcal{B}(K)
            \text{-isolated}
        \right).
    \end{equation}

[Theorem thm:constant-overshoot of arXiv:2607.04620, 'The Exact Ville Identity\\ \large From the Absorbing Case to the General Law\\ with an App'] Suppose there is a constant $\omega\ge0$ such that, on $\{T_b<\infty\}$, the conditional landing value obeys
\begin{equation}
  \mathbb{E}[M_{T_b}\mid \mathcal{F}_{T_b-1},T_b=n]\le b+\omega
  \quad\text{a.s., for every }n.

\end{equation}
Then $O_b\le\omega$ and $\mathbb{P}(T_b<\infty)\ge(1-D_b-R_b)/(b+\omega)$, with equality throughout when (equation eq:landing-bound of the paper) holds with equality. In particular, if the conditional overshoot is a level-independent constant $\omega$, then $O_b=\omega$ and $\mathbb{P}(T_b<\infty)=(1-D_b-R_b)/(b+\omega)$.

[Corollary strict-drop-iterates of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Fix $n\geq 0$. Let the zeros of 
\begin{equation}
G_{n}(u)=w(T_{n}(u))-w(T_{n}(1-u))  
\end{equation}
on $(0,\tfrac{1}{2})$ be 
\begin{equation}
0=\xi _{0}<\xi _{1}<\cdots <\xi _{m}<\xi _{m+1}=\frac{1}{2},  
\end{equation}
and define the corresponding nodal masses 
\begin{equation}
M_{k}^{(n)}=\int_{\xi _{k-1}}^{\xi _{k}}G_{n}(u)\,du,\qquad k=1,\dots ,m+1.

\end{equation}
If 
\begin{equation}
|M_{1}^{(n)}|\geq |M_{2}^{(n)}|\geq \cdots \geq |M_{m+1}^{(n)}|,

\end{equation}
then 
\begin{equation}
Z(D_{n+1})<Z(D_{n}).  
\end{equation}

