[Prop 27 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $V$ satisfy \ref{potentialh1} and \ref{potentialh2} and fix $\gamma > 0$.

Then there is a constant $C >0$ (which may depend on $\gamma$) such that, for $N$ sufficiently large, the upper bound holds

\begin{align}

\mc{I}(\bs{\la}^+_N ; \veps_N) \leq \mathrm{e}^{CN^{1- \frac{1}{4}}} \sqrt{\frac{ \mc{T}(\boldsymbol{\lambda}^+_N) \mc{T}(\boldsymbol{\lambda}^-_N)}{\Delta(\boldsymbol{\lambda}_N^+) \Delta(\boldsymbol{\lambda}_N^-)} } \cdot  \prod_{j=1}^N \max\{ \ln |\lambda_j^+ - \lambda_j^-|^{-1}   , \gamma N \} \;.

\end{align}

Above, given $\boldsymbol{x}_N\in \mathbb R^{N}$ we agree upon:

\begin{align}
    \mc{T}(\boldsymbol{x}_N) =  \prod_{k=1}^N \Big( 1 + \frac{1}{\gamma N} \ln^2(1+|x_k|) \Big)^5 \prod_{j=1}^N \Big( 1 + \frac{6}{\gamma N^{\frac{5}{4}}} \sum_{\substack{ i = 1 \\ i \neq j}}^N \ln^2|x_i - x_j| \Big)^4  \, .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Variationalppties of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] For every $u \in \mathcal{B}$, the first variation of $I_{\gamma}$ on $\mathcal{B}$ is given by
    \begin{align*}
        \frac{1}{2} \nabla_{\mathcal{B}} I_{\gamma} [u] (\phi) = \int_M \phi P_\gamma^{\hat{h}}(u) d\sigma_{\hat{h}},
    \end{align*}
    for every $\phi \in H^\gamma (M) $. The second variation over $\mathcal{B}$ is given by
    \begin{align*}
        \frac{1}{2} \nabla_{\mathcal{B}}^2 I_{\gamma} [u](\phi, \psi) = \int_M \phi P_\gamma^{\hat{h}}(\psi) d\sigma_{\hat{h}} - (2^* - 1)I_\gamma [u] \int_M u^{\frac{4\gamma}{n-2\gamma}}\phi \psi d\sigma_{\hat{h}}.
    \end{align*}
    for every $\phi,\psi \in H^{\gamma}(M) $. Moreover, the following properties hold
    \begin{enumerate}
        \item For $\alpha \in (0,1)$ such that $2\gamma + \alpha \notin \mathbb{N}$, the map $u \mapsto \frac{\nabla_{\mathcal{B}}^2 I_\gamma [u](\phi,-)}{\|\phi\|_{C^{2\gamma + \alpha}} }$ is locally continuous from $C^{2\gamma + \alpha}(M) \cap \mathcal{B} \to C^{ \alpha}(M)$ with a modulus of continuity uniform over $\phi\in C^{2\gamma + \alpha}(M)$.
        \item The function $u \mapsto \frac{\nabla_{\mathcal{B}}^2 I_\gamma [u](\phi,\psi)}{\|\phi\|_{H^\gamma } \|\psi\|_{H^\gamma  }}$ is a locally continuous function from $ \mathcal{B} \to \mathbb{R}$ with a modulus of continuity uniform over $\phi,\psi \in H^\gamma (M)$.
    \end{enumerate}

