[Theorem 31 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is $r$-monotonically complete;
\item[(ii)] Every directed dominable subset of $\Ba_{F_{+}}$ has a supremum in $F$ of norm at most $r$;
\item[(iii)] $F$ is norm complete and every disjoint $D\subset F_{+}$ such that $D^{\vee}\subset\Ba_{F}$ has a supremum of norm at most $r$;
\item[(iv)] The order adherence of $\Ba_{F}$ in $F^{u}$ is contained in $r\Ba_{F}$;
\item[(v)] Every uo-Cauchy net in $\Ba_{F}$ has a uo-limit in $r\Ba_{F}$.

[Definition 28 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] [$\mathfrak{e}_{z;q},\md_z,\td_z,\te_{z;q}$]

	 Given  $z \in \mathfrak{X}_{a, b, c}$ let $\ell_z $ denote the side of $\partial \mathfrak{X}_{a, b, c}$ closest to $z$ (if two such sides exist, we select one arbitrarily) and $\mathfrak{d}_z = \dist (z, \ell_z)^{1/2}$.  We let $\bm{v} = \bm{v}_z \in \big\{ (1, 0), (-1, 0), (0, 1), (0, -1), (1, 1), (-1, -1) \big\}$ denote the vector
        parallel to $\ell_z$; as for its orientation, we orient the boundary of the hexagon anti-clockwise, and we let $\bm{v}$ be oriented like the side $\ell_z$ that defines it. { We also let $\bm{v}^{\perp} = \bm{v}_z^{\perp}$ denote the vector obtained by a $\pi/2$ clockwise rotation of $\bm{v}$ (so that it is in particular orthogonal to $\bm{v}$, in the $(x,y)$ coordinate system).} Given $q\in\mathbb R$, we let $\bm{w} = \bm{w}_{z;q}$ denote the
unit        vector pointing from $z$ to the closest point of 
        $\mathfrak{A}_{q; {a}, {b},
          {c}}$.  Finally,   we let $\bm{u} = \bm{u}_{z;q}$ denote the
    unit   pointing from  $z$ and tangent to
        $\mathfrak{A}_{q; {a}, {b},
          {c}}$ (note that it is orthogonal to $\bm{w}$). The orientation of $\bm{u}$ is chosen by orienting  $\mathfrak{A}_{q; {a}, {b},
          {c}}$ anti-clockwise. If the points involved in the definition of $\bw,\bu$ are not unique, then choose one arbitrarily.\footnote{The distinction between the directions $\bu$ and $\bw$ will be only important  for points $z$ close to the arctic boundary, in which case the choice is unique.} 

        Moreover, we let (see Fig. \ref{fig:ed})
        \begin{eqnarray}

          \mathfrak{e}_{z;q}:=\dist_{\bm{v}} (z, \mathfrak{A}_{q;a,b,c}).
        \end{eqnarray}
        If $z$ is outside the liquid region, we set $\mathfrak{e}_{z;q}=0$. We further set 
   \begin{flalign}
     \mathtt{d}_z = \max \{ \mathfrak{d}_z, N^{-1/2} \}; \qquad \mathtt{e}_{z;q} = \max \{ \mathfrak{e}_{z;q}, \mathtt{d}_z^{-1/3} N^{-2/3} \}.

   \end{flalign}

  \begin{figure}[h]
 \begin{center} \includegraphics[width=5cm]{ed.pdf}
  \caption{A point $z$ in $\mL_{q;a,b,c}$. The distance from $z$ to $\partial\mX_{a,b,c}$ is $\md_z^2$ (in this case, $\ell_z$ is the southwest side of the hexagon). The distance from $z$ to the arctic boundary $\mA_{q;a,b,c}$ in the direction parallel to $\ell_z$ is $\me_{z;q}$. The unit vector $\bw_{z;q}$ points to the closest point on the arctic boundary, and $\bu_{z;q}$ is perpendicular to it.
}

\end{center}
\end{figure}

[Theorem 11 (transition distribution) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] For $x>0$, the transition distribution $P_x(u_{T_\alpha}\in\cdot)$
  admits the resolvent representation
  \begin{equation}
    \mathbb{P}(u_{T_\alpha}\in A\mid u_0=x)
    = \frac{\alpha}{\mu}\,G^{\rm sticky}_\alpha(x,0)\,\mathbf{1}_{0\in A}
    + \alpha\int_{A\cap(0,\infty)} G^{\rm sticky}_\alpha(x,y)\,m'(y)\,dy,
  \end{equation}
  equivalent to the three-component mixture
  \begin{equation}
    \mathbb P(u_{T_\alpha}\in A\mid u_0=x)
    = w_0(x)\,\mathbf{1}_{0\in A}
    + w_<(x)\,\nu_<(A)
    + w_>(x)\,\nu_>(A),
  \end{equation}
  where $\nu_<$ and $\nu_>$ are the probability measures with Lebesgue
  densities
  \[
    \frac{d\nu_<(y)}{dy}  \propto  f_0^{\rm sticky}(y)\,m'(y)\,\mathbf{1}_{(0,x)}(y),
    \qquad
    \frac{d\nu_>(y)}{dy}  \propto  U(a,b,z_y)\,m'(y)\,\mathbf{1}_{(x,\infty)}(y),
  \]
  and the weights are
  \begin{align}
    w_0(x) &= -c_\mu\,U(a,b,z_x), \\
    w_<(x) &= \frac{\alpha\,U(a,b,z_x)}{|\mathcal{W}|}
               \int_0^x f_0^{\rm sticky}(y)\,m'(y)\,dy, \\
    w_>(x) &= \frac{\alpha\,f_0^{\rm sticky}(x)}{|\mathcal{W}|}
               \int_x^\infty U(a,b,z_y)\,m'(y)\,dy, 
  \end{align}
  satisfying $w_0(x)+w_<(x)+w_>(x)=1$.

[Thm convnex_entropy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\Pi_i\in \mathcal P_{s,1}( \mathsf{S})$, $i=0,1$ and assume that $\mathscr  W_{gap,p}(\Pi_0,\Pi_1)<\infty$ for $p>1$. Then, there exists an optimal coupling  $\mathsf U\in  \mathsf{Cpl}_s(\Pi_0,\Pi_1)$, such that for any $0\leq t\leq 1$ \begin{align}
       \mathcal E^*((T_t)_{\#}\mathsf U) \leq (1-t) \mathcal E^*(\Pi_0)+t\mathcal E^*(\Pi_1).
    \end{align}
    In particular, for $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$ with $\mathscr  W_{p}(\mathsf{P}_0,\mathsf{P}_1)<\infty$ there exists an optimal coupling  $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$, such that for $\mathsf{P}_t:= \mathsf{gap}^{-1}((T_t)_{\#}\iota( \mathsf{Q}))$ we have \begin{align}
       \mathcal E(\mathsf{P}_t)\leq (1-t)  \mathcal E(\mathsf{P}_0)+t\mathcal E(\mathsf{P}_1)
    \end{align}

