[Proposition prop:global_hajek_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \widehat{\mathsf{N}}_G(x) \coloneqq \mathsf{N}_G(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{E}(x).
\end{equation}
Then, for all $\zeta \in (0,1)$, there is some $c > 0$ such that 
\begin{equation}
    \mathbb{P} \mleft[
        \mleft|
            \widehat{\mathsf{N}}_G(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G(X)\mright]
        \mright| > n^{\mathsf{v}-1.5+\zeta}
    \mright] \leq \exp\mleft(-cn^\zeta\mright).
\end{equation}
In particular, for all $\xi > 0$, we have
\begin{equation}
    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2606.11043, 'Thick points under Gaussian free field dynamics'] Let $(\vec{x},t,\Psi)$ be sampled from $\mathbb{Q}_{\varepsilon}^{\gamma,N}$. The conditional law of  $(\vec{x},t)$ given $\Psi$ is 
    \begin{equation*}
        \nu_{\varepsilon}^{\gamma,N}(d\vec{x}dt):=\frac{\exp\left(\gamma\sum_{i=1}^N\Psi_{\varepsilon}(x_i,t)
        -\frac{\gamma^2}{2}\mathbb E[(\sum_{i=1}^N\Psi_{\varepsilon}(x_i,t))^2]\right)
        }{\mu_{\varepsilon}^{\gamma,N}(D^N_T)}d\vec{x}dt.
    \end{equation*}
    And on the other hand, the law of $\Psi$ conditionally on $(\vec{x},t)$, is equal to 
    \begin{equation*}
        \hat{\Psi} + \gamma\sum_{i=1}^{N}\mathrm{cov}(\cdot, \Psi_{\varepsilon}(x_i,t)),
    \end{equation*}
    where $\hat{\Psi}$ has the law of the SHEF on $Ps(D, [0,T])$.

[Proposition p:Collisions of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Assume~(equation eq:QNPP of the paper). Then,~$\tau^\mbfs_c\equiv 0$ $P^\mbfs_{\boldsymbol\nu}$-a.s.\ for every~$\mbfs\in\mbfT_*$.

\begin{proof}
For simplicity of notation, throughout the proof let~$a_i\eqdef s_i^{-1}$ for every~$i\in{\mathbb N}_1$. 
It is clear from~(equation eq:Intro:FCT of the paper) that, for every~$i,j$ with~$i\neq j$,
\begin{align*}
\tau^\mbfs_c\leq \tau^{s_i,s_j}_c\eqdef&\ \sup\set{t>0: X^\mbfs_{i,r}\neq X^\mbfs_{j,r} \text{ for all } r\in(0, t)}
\\
=&\ \inf\set{t>0 : (X^\mbfs_{i,t}, X^\mbfs_{j,t}) \in \Delta M } \,\mathrm{.}
\end{align*}
In light of Proposition~(p:BendikovSaloffCosteRescaling of the paper) and Theorem~(t:BendikovSaloffCoste of the paper)(i:t:BendikovSaloffCoste:5 of the paper), we further have~$X^\mbfs_{i,t} \overset{d}{=} X_{a_i t}$ for every~$i\in {\mathbb N}_1$, and thus~$\tau^{s_i,s_j}_c \overset{d}{=} \tau^{a_i,a_j}_{\Delta M}$ is the hitting time of the diagonal for the process~$\mssW^{a_i,a_j}$ properly associated with the regular product Dirichlet form~$\tparen{\mssE^{a,b},\dom{\mssE^{a,b}}}$ in~\S(sss:AppCapacityRescaling of the paper) with~$a=a_i$ and~$b=a_j$.

Thus, it suffices to show that, for every~$\mbfs\in\mbfT_*$
\[
\limsup_{\substack{i,j\to\infty\\ i\neq j}} \tau^{a_i,a_j}_{\Delta M} = 0 \as{P_{\nu^{\scriptscriptstyle\otimes 2}}} \,\mathrm{.}
\]

We show the following (strictly) stronger statement.

\nparagraph{Claim: for every~$\mbfs\in\mbfT_*$,
\begin{equation}
\lim_{\substack{i,j\to\infty\\ i\neq j}} E_{\nu^{\scriptscriptstyle\otimes 2}}\braket{\exp\tbraket{-\tau^{a_i,a_j}_{\Delta M} }} = 1 \,\mathrm{.}
\end{equation}
}
Since the product form~$\tparen{\mssE^{a_i,a_j},\dom{\mssE^{a_i,a_j}}}$ is conservative,
\begin{equation}
E_{\nu^{\scriptscriptstyle\otimes 2}}\braket{\exp\tbraket{-\tau^{a_i,a_j}_{\Delta M}}}=\mathrm{cap}_{a_i,a_j}(\Delta M)\,\mathrm{.}
\end{equation}
By Lemma~(l:ProductPointHitting of the paper) with~$a=a_i$ and~$b=a_j$ we further have, for~$\kappa_\mssE$ as in~(equation eq:NonPolarityConstant of the paper),
\begin{equation}
\mathrm{cap}_{a_i,a_j}(\Delta M) \geq \kappa_\mssE^{1/(a_i\wedge a_j)} \,\mathrm{.}
\end{equation}
Combining~(equation eq:p:Collisions:1 of the paper) and~(equation eq:p:Collisions:2 of the paper),
\[
\lim_{\substack{i,j\to\infty\\ i\neq j}} E_{\nu^{\scriptscriptstyle\otimes 2}}\braket{\exp\tbraket{-\tau^{a_i,a_j}_{\Delta M} }} \geq \lim_{\substack{i,j\to\infty\\ i\neq j}} \kappa_\mssE^{s_i\vee s_j} \,\mathrm{.}
\]

Since~$\mbfs\in\mbfT_*$, we can choose~$s_i\vee s_j$ arbitrarily close to~$0$, and~(equation eq:p:Collisions:0 of the paper) follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:pole-short-time-calibration of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Assume (equation eq:pole-coefficient-class of the paper), take
$K=K_\theta^\star(a)$, and let
$0\leq\alpha<1/2$ and $0<\theta<1-4/(C_\alpha^{\mathrm{Br}})^2$, with
$\Delta_{\mathrm{hi}}$ as in Theorem~(thm:pole-calibration of the paper).  There are
\begin{equation*}
 \begin{aligned}
 N_{\mathrm H}&=N_{\mathrm H}
   (\lambda,\Lambda,\alpha,\Delta_{\mathrm{hi}}^{-1})\in\mathbb N,\qquad
 r_{\mathrm{loc}}=r_{\mathrm{loc}}
   \bigl(T,\lambda,\Lambda,\alpha,\theta,\Delta_{\mathrm{hi}}^{-1},
                  \mathcal M_d(a)\bigr)\in(0,T],
 \end{aligned}
\end{equation*}
and $C=C\bigl(T,\lambda,\Lambda,\alpha,\theta,\Delta_{\mathrm{hi}}^{-1}\bigr)>0$
such that the following holds.

Let $0<r<r_{\mathrm{loc}}$, $I_r=(0,r)$, and
$F\in\mathfrak D(I_r,\overline w_{\alpha,K})$.  Put $u=S_{I_r}F$ and
\begin{equation*}
 G(s,\xi)=rF(rs,\sqrt{rs}\,\xi),\qquad
 q(s,\xi)=u(rs,\sqrt{rs}\,\xi).
\end{equation*}
Then $\mathcal P_rq=G$ and
\begin{equation}
 \left\lVert \mathcal J_rq\right\rVert_{\mathscr Y_{\alpha,K,r}}
 \leq\bigl(C_\alpha^{\mathrm{Br}}+C\mathcal M_d(a)r\bigr)
       \left\lVert G\right\rVert_{\mathscr X_{\alpha,K,r}}.

\end{equation}
The exact scaling identities are
\begin{equation}
 \left\lVert G\right\rVert_{\mathscr X_{\alpha,K,r}}^2
 =r^{1-\alpha}\left\lVert F\right\rVert_{\overline w_{\alpha,K};I_r}^2,
 \qquad
 \left\lVert \mathcal J_rq\right\rVert_{\mathscr Y_{\alpha,K,r}}^2
 =r^{1-\alpha}\norm{\operatorname{Hess}_gu}_{\overline w_{\alpha,K},g;I_r}^2.

\end{equation}
Consequently, Theorems~(thm:bochner-source-density of the paper)
and~(thm:causal-reweighting of the paper) give
\begin{equation}
 C_{w_{\alpha,K;\kappa},I_r}(X^a)
 \leq C_\alpha^{\mathrm{Br}}+C\mathcal M_d(a)r,
 \qquad 0<r<r_{\mathrm{loc}},\quad \kappa\geq0.

\end{equation}

[Lemma th:comb of arXiv:2510.00748, '\bf On irreducible central limit theorems'] If $C \subseteq V_n$ satisfies
$|C| \ge u \, n^2$ for some $u \in (0,1)$, then for any $u' < u$
\begin{gather*}
	\big| \big\{ a \in \{1,\ldots,n\} \colon\ |C(a,\cdot)| > u' \, n \big\} \big| \ge 
	\frac{u-u'}{1-u'}
\, n \ge (u-u') \, n \,.
\end{gather*}

