[Lemma 7 of arXiv:2609.00483, 'On Embedding Hamming Spheres with Applications to Positive Curvature'] Let $d \ge 1$.
\begin{enumerate}
\item \cite{Rankin} Any collection of $d+2$ vectors in $\mathbb{R}^d$ contains two whose angle is non-obtuse; equivalently, if $v_1,\dots,v_{d+2}\in\mathbb{R}^d$, then $v_i\cdot v_j\ge 0$ for some $i\ne j$.

\item \cite{Ru3} If $v_1,\dots,v_N\in S^{d-1}\subseteq\mathbb R^d$ satisfy $v_i\cdot v_j\le-\varepsilon$ for all $i\neq j$, where $\varepsilon>0$, then $N\le \min\{d+1, \floor{1+\frac1\varepsilon}\}$.
\end{enumerate}

[Lem 13 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $a>0$ and 
\begin{equation}
	C_1\ge C_1^* := \dfrac{2\sigma_d(d-2)}{M_c} \left(\dfrac{m\zeta(0)}{m-1} + 1 \right)\,.  
\end{equation}
Then there is $C_2>0$ such that, for any $u\in\Sigma_a$,
\begin{equation*}
	\phi'(u(0)) + C_1 \inf_{\mathbb{B}_\rho} \phi'(u) \le C_2\rho^{2-d}\,,\quad \rho\in (0,R]\,.
\end{equation*}

