[Lemma 16 (Orientation of the replicon crossing) of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] At marginality,
\begin{equation}
 \Gamma_\mu(q)-(p-1)\xi'(q)
 \E[\cosh^{-4}(M(q))e^{W_\mu(q)}]=0,

\end{equation}
and
\begin{equation}
 \frac{\partial}{\partial m}\Big\{
 \Gamma_\mu(q)-(p-1)\xi'(q)
 \E[\cosh^{-4}(M(q))e^{W_\mu(q)}]\Big\}>0.

\end{equation}
At a point satisfying both \eqref{mt:eq:mass} and
\eqref{mt:eq:marginal-residual}, the strict oriented-minor inequality is
\begin{align}
 &\frac{\partial}{\partial\xi'(q)}
  \{\text{left-hand side of \eqref{mt:eq:mass}}\}
 \frac{\partial}{\partial m}
  \{\text{left-hand side of \eqref{mt:eq:marginal-residual}}\}\notag\\
 &\quad-
 \frac{\partial}{\partial m}
  \{\text{left-hand side of \eqref{mt:eq:mass}}\}
 \frac{\partial}{\partial\xi'(q)}
  \{\text{left-hand side of \eqref{mt:eq:marginal-residual}}\}>0.

\end{align}
Along the stationary level curve at the marginal base point,
\begin{equation}
 \frac d{dm}\Big\{
 \Gamma_\mu(q)-(p-1)\xi'(q)
 \E[\cosh^{-4}(M(q))e^{W_\mu(q)}]\Big\}>0,
 \qquad
 \frac d{dm}\Gamma_\mu'(q)<0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 24 of arXiv:2609.02808, 'Minimizers of Laplace eigenvalues under a lower curvature bound'] For $g\in\overline\Cc$, the eigenvalue counting function
$N_g(x)=\#\{k\ge1:\lambda_k(g)\le x\}$ satisfies
\begin{equation}
N_g(x)=\frac{\Area(g)}{4\pi}\,x+o(x)
\qquad(x\to\infty).
\end{equation}

[Proposition prop:asymptotic_contraction of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] There exist $R, K, \beta > 1$ with the following property. For every
    $\delta \in (0,1)$ there is a $\delta_\star \in (0, \delta)$ such that, with $\tau$ the
    stopping time~(equation eq:stopping_time_tau of the paper) at that $\delta$,
    \begin{equation}
      \mathbb{P}( \tau = \infty ) \ >\ 0 , \qquad
      \forall z_0, z'_0 \in \mathcal{C}_R \ \text{ with } \ \|z_0 - z'_0\| \leqslant \delta_\star .
    \end{equation}
    In particular the two copies synchronize with positive probability,
    \begin{equation}
      \mathbb{P}\Bigl( \lim_{n \to \infty}\|z_{2n} - z'_{2n}\| = 0 \Bigr) \ >\ 0 .
    \end{equation}

