body:
[Proposition 39 (Unimodularity of the embedded Delaunay graph) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $G$ be a non-compact connected semisimple real Lie group and $(X,d_X)$ be its symmetric space. Let $\mathbf Y$ be a Poisson point process $Y$ on $X$ with intensity $c \, {\rm vol}$ for some $c>0$ and with iid ${\rm Unif}[0,1]$-marks. Let $Y_0=Y\cup\{o\}$ and $\mathbf Y_0=\mathbf Y \cup \{\mathbf o\}$, where $\mathbf o$ is the origin equipped with an independent ${\rm Unif}[0,1]$-mark. Let $\mathcal G$ denote the Delaunay graph associated to ${\rm Vor}(Y_0)$ and let $\rho$ denote the vertex corresponding to the cell of the origin. Then the following hold:
\begin{itemize}
\item[{\rm(1)}] The Delaunay graph $(\mathcal G,\rho)$ defines a unimodular random graph. 
\item[{\rm(2)}] Let $\psi$ denote the marking of the embedded Delaunay graph. Then $(\mathcal G,\rho,\psi)$ satisfies 
\begin{equation}
\mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,\rho,x,\psi) \bigg] = \mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,x,\rho,\psi) \bigg]
\end{equation}
for every non-negative measurable function $f$ of bi-rooted embedded graphs $(H,u,v,\varphi)$ with the additional property that
\begin{equation} 
f(H,u,v,\tau \circ \varphi)= f(H,u,v,\varphi)
\end{equation}
for every isometry $\tau$ of $X$ which interchanges $\varphi(u)$ and $\varphi(v)$. 
\item[{\rm(3)}] Let $\Psi$ denote the marking of the embedded Delaunay graph with labels. Then $(\mathcal G,\rho,\Psi)$ satisfies 
\begin{equation}
\mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,\rho,x,\Psi) \bigg] = \mathbb E \bigg[ \sum_{x\in V(\mathcal G)} f(\mathcal G,x,\rho,\Psi) \bigg]
\end{equation}
for every non-negative measurable function $f$ of bi-rooted embedded labeled graphs $(H,u,v,\Phi=(\varphi,\varphi'))$ with the additional property that 
\begin{equation} 
f(H,u,v,\tau \circ \Phi)= f(H,u,v,\Phi)
\end{equation} 
for every isometry $\tau$ of $X$ which interchanges $\varphi(u)$ and $\varphi(v)$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:coupling_nondeg of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Fix any $ \zeta \in \mathcal{H} \setminus \{0 \}$. Then there exists a $j \in \mathbf{Z}^2_*$ such that
  \begin{equation}
    P_1 L^0_{\bar w}\zeta \ne 0 ,
  \end{equation}
  where $\bar w = c e_j + \bar c e_{-j}$ for some $c \in \{1, \iota\}$.

[Lemma eq: RI cover level of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] For $\gamma>0$, let $\displaystyle\lim_{N\to\infty}R_N/N^\gamma=1$ and $v_N = u_N(\gamma)(1+\rho_N)$ with \\ $\displaystyle\lim_{N\to\infty}\rho_N\log N=0$. 
    One has
    \begin{equation}

        \lim_{N\to \infty} \mathbb{P}\big(Q(0,R_N)\subset \mathcal{I}^{v_N}\big) = \mathrm{e}^{-1}.
    \end{equation}

