body:
[Lemma 6 of arXiv:2605.30091, 'Computing lower expectations with respect to total variation distance and chi-squared dive'] Consider any $q\in B_{\chi^2}(p,\delta)$ and any $i,j\in\{1,\ldots,n\}$ such that $q(x_i)=0$ and $q(x_j)>0$. Then there is some $0<\epsilon<q(x_j)$ such that the $q'\in\Sigma_\mathcal{X}$ defined by 
\begin{equation*}
q'(x_k)=
\begin{cases}
\epsilon & \text{if } k=i,\\
q(x_j)-\epsilon & \text{if } k=j,\\
q(x_k) & \text{if } k\in\{1,\ldots,n\}\setminus\{i,j\}
\end{cases}
\end{equation*}
is also an element of $B_{\chi^2}(p,\delta)$. The corresponding expectation is given by $E_{q'}(f)=E_q(f)+\epsilon(f(x_i)-f(x_j))$.

[Defn of arXiv:2602.08739, '\large \bf MOMENTS OF C$\beta$E FIELD PARTITION FUNCTION, $\mathsf{Sine}_{\beta}$ CORRELAT'] Define the Hua-Pickrell point process $\mathcal{HP}_{\beta,\delta}$ with parameters $\beta,\delta >0$:
\begin{equation}
\mathcal{HP}_{\beta,\delta}\overset{\mathrm{d}}{=}\left\{\lambda \in \mathbb{R}:\mathsf{p}^{(\beta,\delta)}_\lambda(0)=\boldsymbol{\Theta}_\delta \ \mathrm{mod} \ 2\pi\right\}.
\end{equation}

[Lemma lem:large_jump_comono_coup of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\alpha \in (0,2)\setminus\{1\}$ and $q \in (0,\alpha)\cap(0,1]$ satisfy $\int_{\mathbb{R}^d\setminus B_{\bm{0}}(1)}|\bm{w}|^q\nu_{\bm{X}}(\mathrm{d}\bm{w})<\infty$, where $q\ne\alpha/(p+1)$ and $q\ne\alpha/(\alpha\delta+1)$. Then, under Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}) we have, as $t \downarrow 0$,
\begin{align*}
\mathcal{W}_q\big(\bm{L}^{\bm{S}^t}, \bm{L}^{\bm{Z}}\big) 
&= \mathcal{O}\big(G_2(t)^q 
    +(1+G_1(t))^qt^{\min\{1-q/\alpha,q\delta\}}     
    +G(t)^{pq}(1+G_1(t))^{q(1+p)}t^{\min\{1-q/\alpha,pq/\alpha\}}\big).
\end{align*}

