\begin{equation} 
\lvert B(y,t) \rvert \xrightarrow[t \to \infty]{} 0 \; \text{ in probability},
\end{equation}

\begin{equation} 
C(y,t)  \xrightarrow[t \to \infty]{} 0  \; \text{ in probability}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Let $A_1,A_2\subset \BX$, $A=A_1 \cup A_2$, and $v\in A$. If $A_1\cap A_2\ne\emptyset$, then
    \begin{align*}
        D(A)\le \min(D(A_1)+D(A_2), 2 d_m(v,A)).
    \end{align*}

