-|x|^{1+\varepsilon}+\nu\cdot x\leq-|x|^{1+\varepsilon}+|\nu|\, |x|\leq \varepsilon |\nu|^{(1+\varepsilon)/\varepsilon}. 
\]
The last inequality is a consequence of the fact that the function $g(z)=-z^{1+\varepsilon}+|\nu|z$ for $z\geq 0$, attains its maximum at $z_0=\left(\frac{|\nu|}{1+\varepsilon}\right)^{1/\varepsilon}$ with $g(z_0)=\varepsilon\left(\frac{|\nu|}{1+\varepsilon}\right)^{(1+\varepsilon)/\varepsilon}\leq \varepsilon |\nu|^{(1+\varepsilon)/\varepsilon}$. 
Consequently,

\begin{equation}
e^{-|x|^{1+\varepsilon}}
\leq e^{\varepsilon |\nu|^{(1+\varepsilon)/\varepsilon}} e^{-\nu\cdot x}, 
\end{equation}

which implies ...","release_manifest_digest":"sha256:401510672dc3dce92e06b7dd07a386bbc5520a3049d22fa429541b317a6e9f97","revision_digest":"sha256:fa4e0f46c6327835d9a48cd7baf40e4fa4a19176f161b8ff4bf686bcaf6a6b4e","source_id":"arxiv:2609.00257","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Definition def:jump_path of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] Given a healing rate $\delta \in [0, \infty]$, a \emph{genealogical path} is a càdlàg function
  $\gamma:[s_{0},s_{1}] \to \mathbb{Z}^d$ ($0 \leq s_{0} \leq s_{1}$) such that:
  \begin{enumerate}[label=(\roman*)]
    \item whenever $\gamma(t)\neq\gamma(t-)$ for $t \in [s_{0}, s_{1}]$, a particle at position $\gamma(t-)$ jumps to $\gamma(t)$ at
      time $t$;
    \item $\eta_t(\gamma(t)) \ge 1$ for all $t \in [s_{0}, s_{1}]$;
    \item for every $t \in [s_0,s_1]$ such that $\eta_{t}(\gamma(t)) = 1$, $t$ is not an arrival of the Poisson process $\mathcal{R}_{\gamma(t)}$.
  \end{enumerate}

[Theorem thm_IW-Theorem II.7.4-PRM of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that
\[
\mathfrak{A}=\bigl( {\Omega}, {\mathscr{F}}, {\mathbb{P}}, {\mathbb{F}} \bigr), \mbox{ where } {\mathbb{F}}=({\mathscr{F}}_t)_{t\geq 0} ,
\]
is a  filtered probability space. Assume that $(\mathbf{X},\mathscr{B}_\mathbf{X})$ is a measurable space and
$\eta$ is a  random measure on $\mathfrak{A}$ and $(\mathbf{X},\mathscr{B}_\mathbf{X})$.
Assume that $\eta$ is of class \textbf{(QL)} and there exists
an $\mathbb{F}$-predictable generalized process
\begin{equation}

q\colon (0,\infty)\times \mathscr{B}_\mathbf{X} \times \Omega \to [0,\infty]
\end{equation}
such that  the compensator $\widehat{\eta}$  of $\eta$ satisfies, for  $\mathbb{P}$-almost every  $\omega\in \Omega$
\begin{equation}

\begin{aligned}
\widehat{\eta}\bigl((0,t]\times A;\omega\bigr)&=\int_{(0,t]}\int_A q(s,\mathrm{d} x,\omega) \, \mathrm{d}s, \mbox{ for all $t\in (0,\infty)$, $A\in \mathscr{B}_\mathbf{X}$}.
\end{aligned}
\end{equation}
Suppose  that $(Y,\mathscr{Y})$ is a standard measurable space and  $m$ is a  $\sigma$-finite non-negative measure on it. Suppose  also that
\[
\theta\colon  (0,\infty) \times Y\times \Omega \to \mathbf{X}^\ast\coloneqq\mathbf{X} \cup \{ \partial\}
\]
is another  $\mathbb{F}$-predictable generalized process
such that for  $\mathbb{P}$-almost every  $\omega\in \Omega$
\begin{equation}
  m(\{ u \in Y: \theta(t,u,\omega) \in A\}) = q(t,A,\omega),  \mbox{ for all } t\in (0,\infty), \;\; A\in \mathscr{B}_\mathbf{X}.
\end{equation}
Then there exists an extension $\bigl(\tilde{\mathfrak{A}}, \pi  \bigr)$ of  $\mathfrak{A}$,
where
\[
\tilde{\mathfrak{A}}=\bigl( \tilde{\Omega}, \tilde{\mathscr{F}}, \tilde{\mathbb{P}}, \tilde{\mathbb{F}}  \bigr), \mbox{ with } \tilde{\mathbb{F}}=(\tilde{\mathscr{F}}_t)_{t\geq 0},
\]
 and there exists an  $Y$-valued stationary Poisson point process $\tilde{p}$ on $\tilde{\mathfrak{A}}$,
with  the  corresponding  Poisson random measure  denoted by ${\eta}_{\tilde{p}}$,  such that
\begin{trivlist}
\item[(i)] the characteristic measure of $\tilde{p}$ is equal to the measure $m$,
\item[(ii)] and the following equality holds for 
{$\widetilde{\mathbb{P}}$}-almost every  
{$\tilde{\omega}\in \widetilde{\Omega}$}
 \end{trivlist}
 \begin{equation}
 \begin{aligned}
 \eta\bigl((0,t]\times A, \pi(\tilde{\omega})\bigr)&=
 \int_0^t \int_{Y} (\1_A\circ \theta)(s,u,\pi(\tilde{\omega}))\, {\eta}_{\tilde{p}}(\mathrm{d} s, \mathrm{d} u)
 \\&= \# \bigl\{ s \in \mathrm{Dom}({\tilde{p}(\tilde{\omega})}) \cap (0,t]: \theta(s,{\tilde{p}}(s,\tilde{\omega}),\pi(\tilde{\omega})) \in A \bigr\},
 \\&\mbox{for all  $t\in [0,\infty)$, $A\in \mathscr{B}_\mathbf{X}$}.
\end{aligned}
\end{equation}

[Lemma tme of arXiv:2507.20324, 'Non-existence of several random fractals in Brownian motion and Brownian loop soup'] For all three cases, there exists $c>0$, such that for all $n\geq N(\delta)$ and any $n$-boxes $S,T,U\subset\mathcal{A}(0,\iota,1-\iota)$ such that $S,T,U\in\mathcal{S}_{n}$, we have
\[\mathbb{P}(S,T,U\in\mathfrak{S}_{n})\leq cD_{1}^{-d}D_{2}^{-d}2^{-3dn},\]
where 
\begin{center}
$D_{1}=\min\{\mathrm{dist}(S,T),\mathrm{dist}(T,U),\mathrm{dist}(U,S)\}$ and $D_{2}=\max\{\mathrm{dist}(S,T),\mathrm{dist}(T,U),\mathrm{dist}(U,S)\}$.     
\end{center}

[Definition Zeta distribution of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $s>1$. Suppose that
    \begin{equation}
        \BQ = \frac{1}{\zeta(s)} \sum_{n=1}^\infty \frac{1}{n^s} \delta_n,
    \end{equation}
    where
    \begin{equation}
        \zeta(s) := \sum_{n=1}^\infty \frac{1}{n^s}.
    \end{equation}
    Then $\BQ$ is a \textit{zeta distribution} with parameter $s$.

[Lemma 9 of arXiv:2604.23462, 'Invariant measures for the open KPZ equation: the Gaussian case'] Given $T > 0$, there is a finite positive constant $C = C(T,\kappa)$ such that, for all $t \in (0,T]$ and $\bm{x} \in \R^4$, we have that
        \begin{align*}
            C^{-1} \leq \bm{Z}(t,\bm{x}) \leq C \quad \text{and} \quad |\bm{U}(t,\bm{x})| \leq C |\log\ep|
        \end{align*}
        with the latter holding for $\ep$ sufficiently small.

[Lemma lem : LDP/ContinuousMetric/ExpEquiv of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] For all $n\ge 1$, almost surely
	\begin{equation}

		\mathfrak d_\infty\p{\SPT^{(b)}, \TightSPT} \le \frac{2b d}{n}.
	\end{equation}
	In particular, replacing $\SPT^{(b)}$ by $\TightSPT$ in the definition of $\FdTsup^{(b)}$ (see~(equation eqn : Intro/def_FdTsup of the paper)), $\FdTinf^{(b)}$ (see~(equation eqn : Intro/def_FdTinf of the paper)) and $\FdT^{-, (b)}$ (see~(equation eqn : Intro/main_thm/def_FdTmonsup of the paper) and~(equation eqn : Intro/main_thm/def_FdTmoninf of the paper) defines the same functions.

[Lemma LEM:coord of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $L\ge 1$. Given small $\varepsilon_1>0$, there exists $\varepsilon=\varepsilon(\varepsilon_1)>0$ such that
\begin{align*}
U_\varepsilon^L\subset \Big\{ \phi \in L^2(\mathbb{T}_{L^2}): \; \phi=e^{i\theta}Q^{\eta_L}_{x_0}+h \quad &\text{for some $x_0\in \mathbb{T}_{L^2}$, $\theta\in \mathbb{R}$,}\\
&\text{  and $h\in V^{L^2}_{x_0,\theta}$ with $\|h \|_{L^2(\mathbb{T}_{L^2})}<\varepsilon_1$} \Big\},
\end{align*}

\noindent
where, at each point $e^{i\theta}Q^{\eta_L}_{x_0}$ on the manifold $\bar \mathcal{M}_L$, $V^{L^2}_{x_0,\theta}$ represents the normal space to the soliton manifold
\begin{align}
V_{x_0,\theta}^{L^2}=\big\{\phi \in L^2(\mathbb{T}_{L^2}): \;  &\jb{\phi, (1-\partial_x^2) \partial_{x_0}( e^{i\theta}Q^{\eta_L}_{x_0} )  }=0 \notag \\  
&\jb{\phi, (1-\partial_x^2) \partial_{\theta}( e^{i\theta}Q^{\eta_L}_{x_0})  }=0 \big\}.

\end{align}

\noindent
Here, the inner product on $L^2(\mathbb{T}_{L^2})$, defined in (equation INER of the paper), means the real inner product. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 16 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Assume Assumption \ref{a.050201}. For $m$-a.e. $\sigma\in\Sigma$,
    \begin{align*}
      \limsup_{\eps\to0}\eps\ln\mu_{\sigma}^{\eps}(F)
      \leq -\inf_{u\in F}E_{\Ac(\sigma)}(u),
      \qquad \text{for any closed } F\subset H .
    \end{align*}

