[Theorem Thm: alpha-mixing GSDE of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] If Assumption (Assumption G-SDE of the paper) holds, then the sublinear Markovian system $\{T_t\}_{t\geq 0}$ defined by (equation def: T_t by G-SDEintroduction of the paper) has a unique invariant sublinear expectation $\tilde{T}$, and for any $m\geq 1$, the $m$-dimensional sublinear expectation system $(\Omega, (Lip(\Omega))^m, (U_t)_{t\geq 0}, \hat{\mathbb{E}}^{\tilde{T}})$ is $\alpha$-mixing, continuous and regular.

        Moreover, let $L_G^1(\Omega)$ be
        the completion of $Lip(\Omega)$ under $\hat{\mathbb E}[|\cdot|]$. Then $(\Omega, L_G^1(\Omega), \hat{\mathbb{E}}^{\tilde{T}})$ is a regular mixing sublinear expectation space. 

        Denote by $\mathcal{P}$ the set of probabilities on $(\Omega,\sigma(L_G^1(\Omega)))$ generated by $(\Omega, L_G^1(\Omega), \hat{\mathbb{E}}^{\tilde{T}})$ as in (equation P of sub exp of the paper). Then for any fixed $X\in (Lip(\Omega))^m$ and $\tau>0$,
\begin{enumerate}
    \item for any $\phi\in C_{lip}(\mathbb{R}^d)$,
		\begin{equation*}
			\lim_{n\to\infty}\left|\hat{\mathbb{E}}\left[\phi\left(\frac{1}{n}\sum_{k=0}^{n-1}U_\tau^kX\right)\right]-\max_{x\in \Gamma_{*}}\phi(x) \right|=0, \ \Gamma_*:=\bigcap_{n\geq 1}\left\{\frac{1}{n}\sum_{k=0}^{n-1}\mathbb{E}_P[U_{\tau}^kX]: P\in \mathcal{P}\right\};
		\end{equation*}
\item it holds
     \begin{equation*}
         \lim_{n\to\infty}dist\left(\frac{1}{n}\sum_{k=0}^{n-1}U_\tau^kX,\Gamma_*\right)=0, \ \text{$\hat{\mathbb{E}}$-q.s.};
         \end{equation*}
  \item  if in addition, assume that $\overline{X},\underline{X}\in (L_G^1(\Omega))^m$ or $X$ has no mean-uncertainty, there exists a constant $c_X\in\mathbb{R}$ such that 
			\[\lim_{n\to\infty}\frac{1}{n}\sum_{k=0}^{n-1}U_\tau^kX=c_X,\text{ }\hat{\mathbb{E}}\text{-q.s.}\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Phiconv of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] The potential $\Phi$ is strictly convex and we have for all $x\in \mathbb{R}^m$:
  \begin{equation}
    g_x= \frac{1}{2} D^2_x\Phi
  \end{equation}
  where $D^2_x\Phi$ is the Hessian of the function $\Phi$ considered here as a quadratic form.

