body:
[Theorem t:main of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Let $\alpha \in [0,d)$ and let $f$ be an SGF on $\mathbb{R}^d$ or $\mathbb{Z}^d$ satisfying (equation e:blowup of the paper), (equation e:sing of the paper) and (equation e:capcon of the paper). Then, as $T \to \infty$,
\begin{equation}

  \theta_\mu(T) \sim  m (d-\alpha)   \text{\textup{Cap}}_f\big(B(T)\big) \log T,
 \end{equation}
 where $m = \|\mu_{a.c.}\| > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 27 of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $G$ be a connected higher rank semisimple real Lie group and let $(X,d_X)$ be its symmetric space.
    Then for every $\eps>0$, $D>0$ and $R>0$ there is $\lambda_0\in (0,1]$ such that for
    \begin{align}
        E^{(\lambda)}_{R,D} := \Big\{ \forall i,j \in \mathbb{N} \  C^{(\lambda)}_i\cap \mathcal{B}_R(o) & \not=\emptyset\not= C^{(\lambda)}_j\cap \mathcal{B}_R(o) \nonumber \\  
        & \Rightarrow\exists z\in C^{(\lambda)}_i\cap C^{(\lambda)}_j \text{ such that } \mathcal{B}_D(z)\subseteq C^{(\lambda)}_i\cup C^{(\lambda)}_j  \Big\},
    \end{align}
    we have that
    \begin{equation}
        \inf_{0<\lambda\le\lambda_0} \mathbb{P} \left(E^{(\lambda)}_{R,D}\right)>1-\eps.
    \end{equation}

[Lemma 5 (One-cell estimates) of arXiv:2609.02156, 'The higher-dimensional Shepp problem: an exact criterion for random ball coverings of tori'] For $1\le p\le M_k$,
\begin{align}
 m_{k,p-1}
 &\le C_d\ell_k^{-d}\e^{-a_{k,p-1}},\\
 \inf_{\substack{\alpha\in\mathcal I_k\\
                  \varnothing\ne A\subseteq Q_{k,\alpha}\text{ compact}}}
 \Pp(A\setminus\Cov(\boldsymbol\Pi_{k,p})=\varnothing)
 &\ge1-\e^{-q_db_{k,p}}
 \ge(1-\e^{-q_d})b_{k,p},
 \qquad q_d:=(3/4)^d.

\end{align}

[Conjecture 1 of arXiv:2608.19976, 'Random valuations'] Each locally finite $\sigma$-continuous valuation $\phi$ is
  representable as
  \begin{equation}

    \phi(K)=\mu(\sC_K),\quad K\in\Kd,
  \end{equation}
  for a locally finite signed measure $\mu$ on $\sC$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

