[Proposition 65 (Permutation-stable tensor algebra) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Let \(1\leq p<\infty\).  For \(m,n\geq1\) and algebraic finite tensors
\(K\in H^{\otimes_{\mathrm{alg}}m}\) and
\(L\in H^{\otimes_{\mathrm{alg}}n}\),

\begin{equation}
 \|K\otimes L\|_{\mathfrak A_p^{(m+n)}}
 =\|K\|_{\mathfrak A_p^{(m)}}
  \|L\|_{\mathfrak A_p^{(n)}}.

\end{equation}

The tensor product therefore extends to the completions and the same equality
holds there; with the scalar convention it also holds if \(m=0\) or \(n=0\).
Every tensor-leg permutation is an isometry.  More generally,
if \(Q=\sum_{\pi\in\mathfrak S_n}c_\pi U_\pi\) is a fixed element of the
permutation algebra, then

\begin{equation}
 \|QK\|_{\mathfrak A_p^{(n)}}
 \leq\left(\sum_{\pi\in\mathfrak S_n}|c_\pi|\right)
 \|K\|_{\mathfrak A_p^{(n)}}.

\end{equation}

Consequently every fixed Young projector and every
Dynkin--Specht--Wever/free-Lie projector extends to
\(\mathfrak A_p^{(n)}(H)\), with norm independent of the dimension of \(H\).
For \(1\leq p\leq2\) and \(N\geq0\), set

\begin{equation}
 \mathfrak A_{p,\leq N}(H)
 :=\bigoplus_{n=0}^N\mathfrak A_p^{(n)}(H),
 \qquad
 \|(K_0,\ldots,K_N)\|_{\mathfrak A_{p,\leq N}}
 :=\sum_{n=0}^N\|K_n\|_{\mathfrak A_p^{(n)}}.

\end{equation}

With truncated concatenation

\begin{equation}
 (K\diamond_N L)_k:=\sum_{i+j=k}K_i\otimes L_j,
 \qquad 0\leq k\leq N,

\end{equation}

this is a unital graded Banach algebra, and

\begin{equation}
 \|K\diamond_NL\|_{\mathfrak A_{p,\leq N}}
 \leq
 \|K\|_{\mathfrak A_{p,\leq N}}
 \|L\|_{\mathfrak A_{p,\leq N}}.

\end{equation}

[Theorem 5 (Asymptotic  hyperuniformity for $ d = 2,3$) of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] Let $ x_{ N}\in B(0,\rho _{ N}^-),N\geqslant 1$, $ \P^{ d,\beta }$ a limit point of $   \{  \tau _{ -x_{ N}}\X^{ d,\beta }_{ N};N\geqslant 1\}$ in the vague topology, $ \gamma>0,\varphi \in \F_{ \gamma }$ continuous  $ \Leb$-a.e..

\begin{itemize}
\item  {\bf 2D:}  $  \P^{ 2,\beta }$ is stationary (by  \cite{Leble-stationary}) and $ 2$-hyperuniform:  as $ R\to \infty $ 
\begin{align*}
  \textrm{Var}\left(\P^{ 2,\beta }( \varphi _{ R})\right)  = O(R^{ 2-\min(\gamma,2) }\ln(R)^{ {\bf 1}\{ \gamma  = 2 \}}).
 \end{align*}
\item  {\bf 3D:} There is $ R^{ \circ}\geqslant 1$ such that for $R\geqslant R ^{\circ }, L \geqslant  { R^{ 2d + 1-\min(1,\gamma )}},$  
\begin{align}

\sup_{ x_{ 0}\in \mathbb{R}^{ d}}\displaystyle\int_{ [-L/2,L/2 ]^{ d}}  \textrm{Var}\left(\P^{ 3,\beta }(\tau _{ x_{ 0} + x}\varphi _{ R})\right)\frac{ dx}{L^{ d}}\leqslant C_{ \varphi }R^{ 3-\gamma }\ln(R)^{ {\bf 1}\{ \gamma  = 1 \}}.
 \end{align}
 If $ \P^{ 3,\beta }$ is stationary, it is $ 1$-hyperuniform: 
\begin{align*}
  \textrm{Var}\left(\P^{ 3,\beta }(\varphi _{ R})\right) = O(R^{ 3-\gamma }\ln(R)^{ {\bf 1}\{ \gamma  = 1 \}}).
\end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: regularized boundary measure of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $T>0$, the \emph{regularized interacting boundary measure} is the probability measure $\nu^0_T$ on $S'(\mathbb T^2)$ with Radon-Nikodym derivative
\begin{equation}
\nu^0_T(d\varphi^0)=\frac{1}{\mathcal Z_T^0}\exp(-V_T^0(\varphi^0)) \mu^0(d\varphi^0),
\end{equation}
where $\mathcal Z_T^0 = \mathbb{E}_{\mu^0}[\exp(-V_T^0(\varphi^0))]$ is a normalization constant. For every $f \in C^\infty(\mathbb T^2)$, the unnormalized Laplace transform of $f$ under $\nu^0_T$ is the quantity 
\begin{equation}
\mathcal{Z}_T^0(f) := \mathbb E_{\mu^0} [\exp( \langle f, \varphi^0 \rangle_{\mathbb T^2}-V_T^0(\varphi^0)],
\end{equation}
where $\langle \cdot,\cdot \rangle_{\mathbb T^2}$ is the $L^2(\mathbb T^2)$ inner product.

[Definition of arXiv:2505.01739, 'Stochastic dominance for linear combinations of infinite-mean risks'] For two random variables $X$ and $Y$,
 \begin{enumerate}[(i)]
 \item  
 $X$ is less than $Y$ in \emph{convex transform order}, denoted $X \leq_{\rm c} Y$, if $G^{-1}\(F(x)\)$ is convex in $x$, where $F$ and $G$ are the distribution functions of $X$ and $Y$, respectively;

     \item  $X$ is smaller than $Y$ in \emph{likelihood ratio order}, denoted by $X\le_{\rm lr}Y$, if $g(x)/f(x)$ is increasing in $x$, where $f$ and $g$ are the densities of $X$ and $Y$, respectively.
 \end{enumerate}

[Lemma 8 of arXiv:2603.27712, 'Bridging Schr\"odinger and Bass: A Semimartingale Optimal Transport Problem with Diffusion'] For every $\phi\in\Cc^{\rm conv}_{w,\uparrow}$ with $\phi(0)=0$, we have:
\begin{enumerate}
\item[\rm (i)] There is a constant $\nu_\eta$ (depending on $\beta,T,d,\eta$) such that
\begin{equation}
-\nu_\eta\le U^\phi_\eta
\le
-\frac d2\log(\eta)+\inf_{x\in\R^d} u^\phi_T(x)+\frac{|x|^2}{2(1-\eta)T}.
\end{equation}

\item[\rm (ii)] There exists a constant $\nu'_\eta$ (depending on $\beta,T,d,\eta$), such that for all $x\in\R^d$:
\begin{subequations}
\begin{align}
\hspace{-15mm}u_s^\phi(x)
& \ge
    -\frac{\beta|x|^2}{2}
    +\1_{\{s>0\}}\Big(\frac{\beta^2|x|^2}{4s}-\frac{(\nu'_\eta\!+\!U^\phi_\eta)^2}{\beta^2s}\Big)
    \!-\!\1_{\{s=0\}}(\nu'_\eta\!+\!U^\phi_\eta)|x|,
~s\!\in\![0,T],
\\
\hspace{-15mm} u^\phi_s(x)
&\le
U^\phi_\eta+\nu_\eta
-\frac d2\log\Big(1-\frac{s}{\eta T}\Big)
+\frac{|x|^2}{2(\eta T-s)},
~s\in[0,\eta T).

\end{align}
\end{subequations}
\end{enumerate}

