[Defi 16 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For all $t \in [K]$, we let
        \begin{equation}
            \ileft^{(t)}=\inf\Big\{l \geq 0:\frac{n^{(t)}_l}{N} \geq \chi\Big\},\quad 
             \iright^{(t)}=\sup\Big\{l \leq k-1:\frac{n^{(t)}_l}{N} \geq \chi\Big\}
        \end{equation}
        be the first and last piles with at least $\chi N$ cards in the $t$-th shuffle.
        Note that $\ileft^{(t)} < \iright^{(t)}$ if and only if $t$ is a $\chi$-good shuffle, and that if no pile sizes are small for shuffle $t$ then $\ileft^{(t)}=0$ and $\iright^{(t)}=k-1$.

[Definition def:rwcre_kernel of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] Given a resampling map $\tau$ and an i.i.d. environment sequence
$\bar{\omega}\sim\mu^{{\mathbb {N}}}$, the \emph{random walk in cooling random
environment} (RWCRE) is the Markov chain $X=(X_n)_{n\in{\mathbb {N}}_0}$ on ${\mathbb {Z}}$
with transition kernel
\begin{equation}
P^{\bar{\omega},\tau}(X_{n+1}=x+e\mid X_n=x)=
\begin{cases}
\omega_{\ell_n}(x), & e=+1,\\
1-\omega_{\ell_n}(x), & e=-1,
\end{cases}
\quad x\in{\mathbb {Z}},\ n\in{\mathbb {N}}_0,
\end{equation}
where $\ell_n$ is given by (equation eq:ell_def of the paper). We denote by
$P_x^{\bar{\omega},\tau}$ the quenched law and by
\begin{equation}
P_x^{\mu,\tau}(\,\cdot\,):=\int_{[(0,1)^{{\mathbb {Z}}}]^{{\mathbb {N}}}}
P_x^{\bar{\omega},\tau}(\,\cdot\,)\,\mu^{{\mathbb {N}}}(d\bar{\omega})
\end{equation}
the corresponding annealed law.

[Definition def: markov of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] A map $T: \mathbb{R}_+\times C_{lip}(\mathbb{X})\to C_{lip}(\mathbb{X})$ is called a sublinear Markovian system if
		\begin{itemize}
			\item [(i)] for each fixed $(t,x)\in \mathbb{R}_+\times\mathbb{X}$, $T_t[\cdot](x)$ is a sublinear expectation on $C_{lip}(\mathbb{X})$;
			\item [(ii)] $T_0[\phi](x)=\phi(x)$ for each $\phi\in C_{lip}(\mathbb{X})$;
			\item [(iii)] $\{T_t\}_{t\geq 0}$ satisfies the following Chapman semigroup formula:
			\begin{equation*}
				T_t\circ T_s[\phi]=T_{t+s}[\phi], \ \text{ for all } \ \phi\in C_{lip}(\mathbb{X})\text{ and }s,t\ge0.
			\end{equation*}
		\end{itemize}

