[Definition def_PRM of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] A measurable function  
\begin{equation}
    \eta\colon \Omega \to M_{\overline{\mathbb{N}}}(E)
    \end{equation}
    is a Poisson random measure if and only if 
\begin{enumerate}
\item for any $A\in \mathscr{E}$, the function
\begin{equation*}
\eta(A)\colon \Omega \ni \omega \mapsto \eta(\omega)(A) \in \overline{\mathbb{N}}
\end{equation*}
 is a Poisson random variable with parameter $\mathbb{E} \left[ \eta(A) \right]$ if $\mathbb{E} \left[ \eta(A) \right] < \infty$, and $\eta(A)=\infty $ $\mathbb{P}$-a.s.\ otherwise.
\item[(ii)] For every finite family $A_1,A_2,\ldots A_n \in \mathscr{E}$ of pairwise  disjoint sets, the random variables $\eta(A_1),\ldots, \eta(A_n)$ are independent.
\end{enumerate}
By the \emph{intensity measure} of a PRM $\eta$  we understand   the measure
\begin{equation}
\mu\colon \mathscr{E} \ni A \mapsto   \mathbb{E} \left[ \eta(A) \right] \in \overline{\mathbb{N}}_+.
\end{equation}

