body:
[Lemma l: fourier smooth multiplication of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $f\in L^1(\R, \C)$ be Fourier-smooth with exponent $p\in[-1, \infty)$, and define $g:\R^d\to\C$ by
    \begin{equation}
        g(x) := \prod_{j=1}^d f(x_j), \quad x\in\R^d.
    \end{equation}
    Then $g$ is Fourier-smooth with exponent $p-(d-1)$.
    \begin{proof}
        Since $f$ is Fourier-smooth with exponent $p$, there is a $c>0$ such that
        \begin{equation*}
            |\hat{f}(k)| \leq c \frac{1}{(1+ |k|)^\frac{1+p}{2}}, \quad k\in\R.
        \end{equation*}
        Therefore,
        \begin{equation*}
            |\hat{g}(k)| \leq c^d \prod_{j=1}^d \frac{1}{(1+|k_j|)^\frac{1+p}{2}} \leq c^d\frac{1}{(1+\|k\|_\infty)^\frac{1+p}{2}} \leq c^d\frac{1}{(1+\|k\|)^\frac{d+p-(d-1)}{2}}, \quad k\in\R^d,
        \end{equation*}
        which shows the first part of the asserted Fourier-smoothness of $g$.

        For the second part, we can calculate that, for $r>0$,
        \begin{align*}
            \int_{B_2^c} \sup_{s\in B_1} |\hat{g}(r(k+s))|^2\, dk &= \int_{B_2^c} \sup_{s\in B_1} \prod_{j=1}^d|\hat{f}(r(k_j+s_j))|^2\, dk\nonumber\\
            &\leq d \int_{B_2^c} \I\{k_d\leq 2\} \sup_{s\in B_1} \prod_{j=1}^d|\hat{f}(r(k_j+s_j))|^2\, dk\nonumber\\
            &\quad \ \ + \bigg(\int_{(-2,2)^c}\sup_{s\in(-1,1)}|\hat{f}(r(k+s))|^2\, dk\bigg)^d\nonumber\\
            &\leq 4cd \int_{B_2^c}  \sup_{s\in B_1} \prod_{j=1}^{d-1}|\hat{f}(r(k_j+s_j))|^2\, dk\nonumber\\
            &\quad \ \ + \bigg(\int_{(-2,2)^c}\sup_{s\in(-1,1)}|\hat{f}(r(k+s))|^2\, dk\bigg)^d.
        \end{align*}
        Note that $B_2$ in the second-to-last integral does not refer to the ball in $\R^d$ but in $\R^{d-1}$. By the assumption that $f$ is Fourier-smooth with exponent $p$, the second summand of the bound is $O(r^{-(d+dp)})$ as $r\to\infty$, and since $p\geq-1$, this fact also implies that it is $O(r^{-(d+p-(d-1))})$. For the first summand of the bound, we can use induction to see that it also is \linebreak $O(r^{-(1+p)})=O(r^{-(d+p-(d-1))})$, which concludes the proof.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

