[Lemma 29 of arXiv:2608.29585, '2608.29585'] The interpolation-basis filtration on $\cZ_{n,\mathrm{fin}}$ is
separated, and for every $m\ge0$ there is a canonical isomorphism
\begin{equation}
 \cZ_{n,\mathrm{fin}}/\cZ_{n,\mathrm{fin}}^{(m)}
 \cong
 \bigoplus_{\substack{\ell(\lambda)\le n\\|\lambda|\le m}}
 (R_{\mathrm{ev}}/I_m)\sigma_\lambda.
\end{equation}
Consequently, taking inverse limits identifies
\begin{equation}
 \widehat\cZ_n^{\mathrm{BG}}
 \cong
 \prod_{\ell(\lambda)\le n}
 \widehat R_{\mathrm{ev}}^{\mathrm{BG}}\sigma_\lambda
\end{equation}
as topological modules.

[Theorem 4 of arXiv:2604.23572, '2604.23572'] In any work-conserving single-server queue with nonpreemptive
services, satisfying Assumptions~\ref{assumption-1} to
\ref{assumption-3}, the mean waiting time $\E[W_k]$ ($k \in \K$) of
class $k$ customers in steady state satisfies

\begin{eqnarray*}
\sum_{k \in \K} \rho_k \E[W_k] 
&=&
\frac{\rho\ds\sum_{k \in \K} \rho_k \E[\tilde{H}_k]}{1-\rho} 
+ \frac{\ds\sum_{k \in \K} \rho_k(\rho -\rho_k)}{2(1-\rho)} 
+ \frac{\ds\sum_{k \in \K} 
\rho_k \E[H_k] \left( 
\E[\tilde{\Lambda}_k] 
- 
\pi_k^{[\on]} \ds\frac{\E[C_k \Lambda_k ]}{\E[C_k]}
\right)}{1-\rho} 
\nonumber
\\
&& 
\qquad {}
+ 
\sum_{k \in \K} \pi_k^{[\on]} \rho_k 
\left( 1 + \frac{\rho_k}{1-\rho} \right)
\left(1 + \E[\tilde{C}_k] \right)
-
\sum_{k \in \K} \pi_k^{[\on]} \E[H_k] \E[\Lambda_k(\tilde{C}_k)].
\end{eqnarray*}

[Theorem 1 ({ULDP on $C([0,T) of arXiv:2608.19753, 'Uniform large deviation principles for the stochastic heat equation over unbounded sets of'] ;C(D))$}] Let Assumption \ref{asm} hold.  Suppose that $q\in[1,\infty)$ and  
\begin{equation*} 
2\lambda<q, 
\end{equation*}
where $\lambda$ is the growth rate of $\sigma$ from \eqref{asm}. 
Then, the family $\{X_x^{\eps}:\eps>0,x\in C(D)\}$ of mild solutions to \eqref{eq:SHE} satisfies the ULDP on $C([0,T];C(D))$, uniformly over initial data in $L^q(D)$-bounded subsets of $C(D)$, with rate functions $I_x\col C([0,T];C(D))\to [0,+\infty]$ given by 
\begin{align}
\begin{split}
I_x(\varphi)\ceqq \frac12\inf\{\|u&\|_{L^2(0,T;L^2(D))}^2 :     u\in L^2(0,T;L^2(D)),\,\varphi=X_x^{0,u}\}, 
\end{split}
\end{align}
where $\inf\varnothing\ceqq +\infty$ and $X_x^{0,u}$ is the mild solution to 
\begin{equation*} 
\begin{cases}
\frac{\partial X}{\partial t}(t, \xi) = \Delta X(t, \xi) +b(X(t,\xi))+ \sigma(X(t, \xi))u(t,\xi), \quad  \xi \in D, t \in(0,T], \\ 
X(0, \xi) = x(\xi), \quad\xi\in D.
\end{cases} 
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def: TruncatedPageRank of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] {\normalfont \rmfamily} 
We define the \textbf{truncated undirected PageRank on the directed multi-type PAM} $\vec{G}_n$ by
\begin{equation*}
R^{1,\mathrm{dirTr}}_v(\vec{G}_n):=c(1-c)\sum_{\substack{u \in V(\vec{G}_n)\\u \rightarrow v}}\frac{1}{m_{X_u}+d_u^-},    \quad v \in \vec{G}_n,
\end{equation*}
where $u \rightarrow v$ indicates that the sum runs over all vertices $u$ that have an edge directed to $v$.

[Proposition prop:criticalh of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $P_\beta$ be the transition matrix of the MH chain with ergodic proposal $N$ and target distribution $\pi_\beta$, and $Q \in \mathcal{I}(\pi_\beta) \cap \mathcal{L}$. We have
	\begin{itemize}
		\item(Similarity preserves critical height) \begin{align*}
			h(P_\beta) &= h(Q P_\beta Q).
		\end{align*}

		\item(Optimality of $\alpha = 1/2$) For $\alpha \in [0,1]$, 
		\begin{align*}
			h(\overline{(P_\beta)}_\alpha(Q)) \leq h(P_\beta).
		\end{align*}
		In particular, 
		\begin{align*}
			\min_{\alpha \in [0,1]} h(\overline{(P_\beta)}_\alpha(Q)) = h(\overline{(P_\beta)}_{1/2}(Q)).
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem CM mom LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Fix $x_0 \in M$, $r \in (0, 1 \wedge r_*)$, and $n, N \in \mathbb{N}$ with $2n \leq N$ and $c_1 Nr^{d^{\mathrm{min}}_\mathrm{w}} < 1 \wedge t_*$.
  It then holds that 
  \begin{equation} 
    \sup_{\bm{x} \in M^k}
    \hat{E}_{\bm{x}}\!\left[\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r))^n\right]
    \leq
    \begin{cases}
      n! \bigl( \tilde{c}_1 r^{d_{\mathrm{cp}}} \bigr)^n,& \text{if}\quad \hat{d}_{\mathrm{s}} > 2,\\
      n! \bigl( \tilde{c}_1 r^{d_{\mathrm{f}}} \log(N/n) \bigr)^n,& \text{if}\quad \hat{d}_{\mathrm{s}} = 2,
    \end{cases}
  \end{equation}
  and 
  \begin{equation} 
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{E}_{\bm{x}}\!\left[\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r))^n\right]
    \geq
    \begin{cases}
      n! \bigl( \tilde{c}_2 r^{d_{\mathrm{cp}}} \bigr)^n,& \text{if}\quad \hat{d}_{\mathrm{s}} > 2,\\
      n! \bigl( \tilde{c}_2 r^{d_{\mathrm{f}}} \log(N/n) \bigr)^n,& \text{if}\quad \hat{d}_{\mathrm{s}} = 2.
    \end{cases}
  \end{equation}

