[Definition def:Pisigmaxi of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\mathbf{n}\in {\mathbb N}^3$. For ${\boldsymbol \sigma}, {\boldsymbol \tau}\in \mathcal S_{\mb{n}}$, define the functions 
\begin{equation}  \begin{split}
    \Pi^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}(\boldsymbol{\xi}, \boldsymbol{\eta}) 
    = &\mathrm{K}(\boldsymbol{\eta}^{123}, \boldsymbol{\eta}^{12}, \boldsymbol{\eta}^1  | \boldsymbol{\xi}^{123}, \boldsymbol{\xi}^{12}, \boldsymbol{\xi}^1) \, 
    \mathrm{K}(\boldsymbol{\xi}^1, \boldsymbol{\eta}^{23}, \boldsymbol{\eta}^2 | \boldsymbol{\eta}^1,  \boldsymbol{\xi}^{23}, \boldsymbol{\xi}^2) \, \\
    &\times \mathrm{K}( \boldsymbol{\xi}^{12}, \boldsymbol{\xi}^2, \boldsymbol{\eta}^3 | \boldsymbol{\eta}^{12}, \boldsymbol{\eta}^2, \boldsymbol{\xi}^3) \,
    \mathrm{K}( \boldsymbol{\xi}^{123}, \boldsymbol{\xi}^{23}, \boldsymbol{\xi}^3 | \boldsymbol{\eta}^{123}, \boldsymbol{\eta}^{23},  \boldsymbol{\eta}^3) 
    \mathrm{S}( \boldsymbol{\xi}^{123}, \boldsymbol{\xi}^{23}, \boldsymbol{\xi}^3 | \boldsymbol{\eta}^{123}, \boldsymbol{\eta}^{23},  \boldsymbol{\eta}^3), 
\end{split} \end{equation}
and
\begin{equation}
    {\mathsf{F}}_{L}^{{\boldsymbol \sigma}|{\boldsymbol \tau}} (\boldsymbol{\xi}, \boldsymbol{\eta}) 
    = \frac{\prod_{*\in \mathcal A_3} \prod_{i=1}^{a_*} {\mathsf{f}}_{L, *} (\xi_i^*)}{\prod_{*\in \mathcal A_3} \prod_{i=1}^{b_*} {\mathsf{f}}_{L, *} (\eta_i^*)}
\end{equation}
where 
\begin{equation*}   
    (a_{123}, a_{12}, a_{23}, a_1,a_2,a_3)=\type({\boldsymbol \sigma}), \qquad 
    (b_{123}, b_{12}, b_{23}, b_1,b_2,b_3)=\type({\boldsymbol \tau}). 
\end{equation*}
Here,  $\boldsymbol{\xi} = ( \boldsymbol{\xi}^{123}, \boldsymbol{\xi}^{12}, \boldsymbol{\xi}^{23}, \boldsymbol{\xi}^1, \boldsymbol{\xi}^2, \boldsymbol{\xi}^3)$ 
and $\boldsymbol{\eta} = ( \boldsymbol{\eta}^{123}, \boldsymbol{\eta}^{12}, \boldsymbol{\eta}^{23}, \boldsymbol{\eta}^1, \boldsymbol{\eta}^2, \boldsymbol{\eta}^3)$, 
with $\boldsymbol{\xi}^{*} = (\xi^*_1,\cdots,\xi^*_{a_*}) \in {\mathbb C}^{a_*}$ and $\boldsymbol{\eta}^{*} = (\eta^*_1,\cdots,\eta^*_{b_*}) \in {\mathbb C}^{b_*}$
for each $* \in \mathcal A_3$.

[Lemma lm:interp of arXiv:2607.05345, 'The local product condition implies cutoff'] Fix two measures $\mu,\pi\in\mathcal {P}({\mathbb{X}})$ with $\mathrm{d}_{\textsc{tv}}(\mu,\pi)<1$. Then, there is a   measure $\nu\in\mathcal {P}({\mathbb{X}})$ which is absolutely continuous w.r.t. both $\mu$ and $\pi$, such that
		\begin{eqnarray*}
			\left\|\frac{\mathrm{d} \nu}{\mathrm{d} \mu}\right\|_\infty\vee\ \ \left\|\frac{\mathrm{d}\nu}{\mathrm{d}\pi}\right\|_\infty	 & \leq & \frac{1}{1-\mathrm{d}_{\textsc{tv}}(\mu,\pi)}.
		\end{eqnarray*}

