[Lemma EHI:l:CloseToSubmultiplicative of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X \in \mathcal{I}(d, r_0)$, and let $T$ be a random variable with Exponential($\lambda$) distribution, independent of $X$. For all $r > 0$ and $m \in \mathbb{N}$,
    \begin{equation*}
        \mathbb{P}_0 \left( \tau_{B(0, mr+(m-1)r_0)} < T \right) \leq \left( \mathbb{P}_0 \left( \tau_{B(0, r)}<T \right)\right)^m.
    \end{equation*}

