[Definition 11 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Let $\Lambda \subset V$ be finite with boundary conditions $(\xi, \sfb)$ on $\Lambda$, $\beta \geq 0$, and $\rho$ an admissible single-site measure.
The random cluster measure on $\Lambda$ is the probability measure $\Psi_{\Lambda, \beta, \rho}^{(\xi, \sfb)}$ on pairs $(\sfa, \omega) \in (\mathbb{R}^{+})^{\overline{\Lambda}} \times \{0,1\}^{\overline{E}(\Lambda)}$ satisfying $\sfa_x = \sfb_x$ for all $x \in \partial^{\mathrm{ext}} \Lambda$ defined by
\begin{equation*}
    \mathrm{d} \Psi_{\Lambda, \beta, \rho}^{(\xi, \sfb)}[(\mathsf{a}, \omega)] = \frac{\mathbbm{1}_{\{\sfa|_{\partial^{\mathrm{ext}} \Lambda} = \sfb\}}2^{k^{\xi}(\omega)}}{Z_{\Lambda, \beta, \rho}^{(\xi, \sfb)}} \left( \prod_{xy \in \overline{E}(\Lambda)} \sqrt{1-p_{xy}(\mathsf{a})} \left(\frac{p_{xy}(\mathsf{a})}{1-p_{xy}(\mathsf{a})}\right)^{\omega_{xy}}\right) \prod_{x \in \Lambda} \mathrm{d} \rho(\sfa_x),
\end{equation*}
where $p_{xy}(\mathsf{a}) = 1 - \exp(-2\beta \mathsf{a}_x \mathsf{a}_y)$ and $Z_{\Lambda, \beta, \rho}^{(\xi, \sfb)}$ is the normalising constant that makes $\Psi_{\Lambda, \beta, \rho}^{(\xi, \sfb)}$ a probability measure. We will write $\chi_{\Lambda, \beta, \rho}^{(\xi, \sfb)}$ and $\Phi_{\Lambda, \beta, \rho}^{(\xi, \sfb)}$ for the marginal distributions of $\sfa$ and $\omega$ respectively. As for the spin model we will often omit $\rho$ from the notation. We also allow the boundary field $\sfb$ to be an element of $(\mathbb{R}^{+})^{V}$ instead of $(\mathbb{R}^{+})^{\partial^{\mathrm{ext}} \Lambda}$, as this is more convenient when defining boundary conditions for a family of measures with varying $\Lambda$.

[Proposition 51 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Lemma \ref{Lem.PrelimitKernelBot} with $\mathcal{T} \subset (0, \infty)$, and recall the contours $\mathcal{C}_z^{\varphi}$ from Definition \ref{Def.S1Contours}. Fix $x_{\infty},y_{\infty} \in \mathbb{R}$, $s,t \in \mathcal{T}$ and sequences $x_N \in \Lambda_s(N)$, $y_N \in \Lambda_{t}(N)$ such that $\lim_{N \rightarrow \infty} x_N = x_{\infty}$ and $\lim_{N \rightarrow \infty} y_N = y_{\infty}$. Then, we have the following limits.
\begin{equation}
\begin{split}
&\lim_{N \rightarrow \infty}  (1-c)^{-2}\sigma_1^{-2}N^{-2/3} I^N_{11}(s,x_N;t,y_N) = I^{\infty}_{11}(s,x_{\infty};t,y_{\infty}) \mbox{, where } I^{\infty}_{11}(s,x;t,y) \\
& = \frac{1}{(2\pi \im)^{2}}\int_{\mathcal{C}^{\pi/3}_{\sigma_1}} dz\int_{\mathcal{C}^{\pi/3}_{\sigma_1}} dw e^{z^3/3 + w^3/3 - f_1 s z^2 - f_1 t w^2 - xz - yw  } \frac{z-w  }{zw (z + w)},
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&\lim_{N\rightarrow \infty} I^N_{12}(s,x_N;t,y_N) = I^{\infty}_{12}(s,x_{\infty};t,y_{\infty}) , \mbox{ where }  I^{\infty}_{12}(s,x;t,y) \\
&= \frac{1}{(2\pi \im)^{2}}\int_{\mathcal{C}^{\pi/3}_{\sigma_1}} dz\int_{\mathcal{C}^{2\pi/3}_{-\sigma_1}} dw e^{z^3/3 - w^3/3 - f_1 s z^2 + f_1 t w^2 - xz + yw  } \frac{z+w }{2z(z-w) },
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&\lim_{N \rightarrow \infty} (1-c)^{2}\sigma_1^{2}N^{2/3} I^N_{22}(s,x_N;t,y_N) =  I^{\infty}_{22}(s,x_{\infty};t,y_{\infty}) , \mbox{ where }  I^{\infty}_{22}(s,x;t,y)  \\
& = \frac{1}{(2\pi \im)^{2}}\int_{\mathcal{C}^{2\pi/3}_{-\sigma_1}} dz\int_{\mathcal{C}^{2\pi/3}_{-\sigma_1}} dw e^{-z^3/3 - w^3/3 + f_1 s z^2 + f_1 t w^2 + xz + y w  } \frac{z-w}{4(z+w) },
\end{split}
\end{equation}
\begin{equation} 
\lim_{N \rightarrow \infty} R^N_{12}(s,x_N;t,y_N) = R^{\infty}_{12}(s,x_{\infty};t,y_{\infty}) ,\mbox{ where } R^{\infty}_{12}(s,x;t,y) = \frac{- {\bf 1}\{s < t\}}{\sqrt{4\pi f_1 (t-s)}} \cdot e^{-\frac{(y - x)^2}{4 f_1 (t-s)}}. 
\end{equation}
In addition,   we have 
\begin{equation}
\lim_{N \rightarrow \infty} (1-c)^{2}\sigma_1^{2}N^{2/3} R^N_{22}(s,x_N;t,y_N) = R^{\infty}_{22}(s,x_{\infty};t,y_{\infty}),
\end{equation} 
where
\begin{equation}
R^{\infty}_{22}(s,x;t,y)=-\frac{1}{4\pi\im}\int_{\mathcal{C}^{2\pi/3}_{-\sigma_1}} dw \cdot w e^{f_1 (s + t)w^2+w(y - x )  } . 
\end{equation}

