body:
[Theorem 2 of arXiv:2605.31471, 'Convergence Rates of Continuous-Time Random Walks to Time-Fractional Diffusions with Unbou'] Fix $\alpha\in\R$ and $r\in\N_0$. Let Assumptions
    \ref{asm:classical}, \ref{asm:weighted-regular}, \ref{asm:rw}, and
    \ref{asm:rw-bounded} hold, and let the walk satisfy
    Assumption~\ref{asm:rw-weighted-stability}.  Suppose also that
    Assumption~\ref{asm:classical} is valid for an order $m\ge r+5$.
    Let $F_t$ be the semigroup of \eqref{eq:SDE-flow}. Then, for every
    $f\in \cC^{r+4}_{\alpha,\infty}(\cX)$,
    \begin{equation} 
        \sup_{s\le t}
        \|U_h^{\lfloor s/h\rfloor}f-F_s f\|_{\alpha,r}
        \le
        C_{\alpha,r} e^{\mu_{\alpha,r}t}h
        \|f\|_{\alpha,r+4}.
    \end{equation}
    For the killed semigroups, if $c\ge0$, then
    \begin{equation} 
        \sup_{s\le t}
        \|e^{-c\lfloor s/h\rfloor h}U_h^{\lfloor s/h\rfloor}f-e^{-cs}F_s f\|_{\alpha,r}
        \le
        C'_{\alpha,r}e^{(\mu_{\alpha,r}-c)t}h
        \|f\|_{\alpha,r+4}.
    \end{equation}
    The estimate holds for all sufficiently small $h>0$.  The constants
    depend on $\alpha,r,K_{\alpha,r},d,R_\xi$, and the moment constants in
    Assumption~\ref{asm:rw}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:polynomial_identities of arXiv:2607.27810, 'Perturbed Beta Corners Process'] For $2\le k\le N$ and $1\le i\le k$,
\begin{align}
	\sum_{j=1}^k\prod_{m\ne j}(u-\mathsf{y}_m^k)
		&= k\prod_{q=1}^{k-1}(u-\mathsf{y}_q^{k-1}), \\
	\prod_{j\ne i}(\mathsf{y}_i^k - \mathsf{y}_j^k)
		&= k\prod_{q=1}^{k-1}(\mathsf{y}_i^k - \mathsf{y}_q^{k-1}), 
\end{align}
and consequently,
\begin{equation}

	\sum_{j\ne i}\frac{1}{\mathsf{y}_i^k - \mathsf{y}_j^k}
	= \frac{1}{2}\sum_{q=1}^{k-1}\frac{1}{\mathsf{y}_i^k - \mathsf{y}_q^{k-1}}.
\end{equation}

