[Proposition prop:Gcomp_characterisation of arXiv:2608.13716, 'Graph Causal Optimal Transport \\ and Wasserstein Distances'] Let $G$ be a DAG and $\mu \in \probabilities{\mathcal{X}}$. The following are equivalent:
    \begin{enumerate}
        \item[1)] $\mu \in \Gprobabilities{\mathcal{X}}$;
        \item[2)] There exists a random variable $X \sim \mu$, independent $\mathbb{R}$-valued random variables $(U_i)_{i\in V}$, and measurable functions $f_i \colon \mathcal{X}_{\mathrm{pa}_{i}} \times \mathbb{R} \to \mathcal{X}_i, i\in V$ such that $X_i = f_i(X_{\mathrm{pa}_{i}}, U_i), \, \forall \, i \in V$.
    \end{enumerate}
    If $G$ is a sorted DAG, the above are further equivalent to the following:
    \begin{enumerate}
        \item[3)] $\mu$ admits a disintegration $\mu(dx) = \bigotimes_{i=1}^n \mu_i(dx_i \vert x_{\mathrm{pa}_{i}})$;
        \item[4)] If $X\sim \mu$ then 
        $$ \condindep{X_i}{X_{\mathrm{pa}_{i}}}{X_{1:i-1}},\qquad 2\leq i \leq n.$$ 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Graph-rate separation) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] \emph{Center classification and wedge-scale separation.} At $p=\pc$:
\begin{enumerate}[label=(\alph*)]
\item a one-edge component has rate $\Jn$;
\item a two-edge connected component has rate $\Kn$;
\item a matching of two edges has rate $2\Jn>\Kn$;
\item every connected component containing at least three edges has rate strictly larger than $\Kn$.
\end{enumerate}
Consequently, for fixed $k,t,\delta$, there is a neighborhood $U$ of $\pc$ and a number $\eta>0$ such that every inclusion--exclusion term in $\mathcal R_n$ has probability at most
\begin{equation}
 C(n+1)^ke^{-n(\Kn+2\eta)},
 \qquad p\in U.

\end{equation}
Its first two derivatives with respect to $p$ are $O(e^{-n(\Kn+\eta)})$, uniformly on $U$. Therefore
\begin{equation}
 \|\mathcal R_n\|_{C^2(U)}=O(e^{-n(\Kn+\eta)}).

\end{equation}

\emph{Local edge-dominance separation.} After shrinking $U$ if necessary, there is also $\gamma>0$ such that every connected two-edge graph and every other non-single-edge graph occurring in \eqref{eq:exact-graph-decomp} satisfies
\begin{equation*}
 \mathcal I_p(G)\ge I_1(p)+\gamma,
 \qquad p\in U.
\end{equation*}
For $j=0,1,2$, the $j$th derivative of the sum of all such terms is bounded by
\begin{equation*}
 C_j n^{C_j}e^{-n(I_1(p)+\gamma)},
 \qquad p\in U.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:restvk of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For every tuple $(j,q,s,\nu,\mu)$ satisfying $s+\nu+2\mu \le r+3$, $q\le 2j$ there exist polynomials $H_\eta$ of degree $\eta$, 
$\eta\le\lfloor \frac{r+3}{2} \rfloor$ such that 
\begin{multline*}
    z^{q-s+\nu}
    \sum_{k=2}^{n-1}
        \frac{
        v_k^{(s+\nu+2\mu)}
        e^{-\frac{z^2}{2(n-k)}}
        }
        {
        (n-k)^{j+\nu+\mu+1/2}
        }
=
    \frac{z^{q-s+\nu}}{n^{j+\nu+\mu+1/2}}
    e^{-\frac{z^2}{2n}}
    \sum_{\eta=0}^{\lfloor \frac{r+3}{2} \rfloor}
        \frac{H_\eta(z^2/n)}{n^{\eta}}
\\
+
    O\left(\frac{1}{(\min(\sqrt{n},1+|z|))^{r+2}}\right).
\end{multline*}

