[Lemma priori-basic-1 of arXiv:2609.01488, 'Stabilization by a background magnetic field: global well-posedness of the full compressib'] Assume $(\rho,\mathbf u,p,\mathbf h)$ is a smooth solution to   the system (equation no-heat-mhd3 of the paper) on $\mathbb T^3\times[0,T]$ for some $T>0$, and
\begin{equation}
\frac{1}{2}\underline{\rho}\leq\rho\leq2\bar\rho,\ \ \text{in}\ \mathbb T^3\times[0,T].
\end{equation}
Then there hold,
\begin{equation}
\frac{d}{dt}\mathcal A (t)+\|\sqrt\rho\mathbf u_t\|_0^2+\|\nabla\mathbf u\|_0^2\lesssim\big(1+\|(\mathbf u,p,\mathbf h)\|_2\big)\|(\mathbf u,p,\mathbf h)\|_2^3,
\end{equation}
and
\begin{equation}
A_1\big(\|(\mathbf u,p,\mathbf h)\|_0^2+\|\nabla\mathbf u\|_0^2\big)\leq\mathcal A(t)\leq A_2\big(\|(\mathbf u,p,\mathbf h)\|_0^2+\|\nabla\mathbf u\|_0^2\big),
\end{equation}
where the two positive constants $A_1,A_2$ depend only on $\mu,\lambda,\gamma,\bar P,|\mathbf n|,\underline{\rho},\bar\rho,$ and
\begin{align*}\mathcal A(t):=&\mu_3\|(\sqrt{\rho}\mathbf u(\cdot,t),(\gamma\bar P)^{-\frac12} p(\cdot,t),\mathbf h(\cdot,t))\|^2_{0}+\mu\|\nabla\mathbf u(\cdot,t)\|_0^2+(\mu+\lambda)\|\mathrm{div}\mathbf u(\cdot,t)\|_0^2\\
&-2\int \big(p(x,t)+\mathbf h(x,t)\cdot\mathbf n\big)\mathrm{div}\mathbf u(x,t)dx+2\int\mathbf h(x,t)\cdot (\mathbf n\cdot\nabla)\mathbf u(x,t)dx
\end{align*}
with $\mu_3:=\max\big\{(4|\mathbf n|^2+\gamma\bar P+1)\mu^{-1},\frac{4\gamma\bar P}{\mu}+1,\frac{16|\mathbf n|^2}{\mu}+1\big\}.$

