[Theorem thm: extreme-cases of arXiv:2601.13426, 'A uniformity principle for spatial matching'] In the dual service range model, 
\begin{enumerate}
    \item[\( \mathrm{(i)} \)] If $r = 0$, the expected size of a maximum matching satisfies
    \begin{align}
        \frac 1 n \, \nu_n(0, b, p) = 
            \frac{e^{2 p b} - e^{2b}}{e^{2 p b} - \frac 1 p e^{2b}}   \,+\, o(1) \, .
    \end{align}
    \item[\( \mathrm{(ii)} \)] If $b = 0$ or $p=0$, the expected size of a maximum matching satisfies
    \begin{align}
        \frac 1 n \, \nu_n(r, 0 ,p) =  \, \nu_m(r, b , 0) = \frac{r}{r + 1/2}  \,+\,  o(1) \, . 
    \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:polyrep of arXiv:2411.07809, 'Pirogov--Sinai Theory Beyond Lattices'] Let $\Lambda$ be a finite induced subgraph of $G$ with
  $\partial\Lambda=\partial_{\text{ext}}\Lambda$. Then
  \begin{equation}

    \Xi_{\Lambda}^{\textsf{e}}   =  \sum_{\substack{\Gamma \subseteq
        \overline{\mathcal C}^{\textsf{e}}(\Lambda) \\compatible}} \prod_{\gamma \in \Gamma}
    \widetilde{w}_\gamma, \qquad 
        \Xi_{\Lambda}^{\textsf{o}}   =  \sum_{\substack{\Gamma \subseteq
        \overline{\mathcal C}^{\textsf{o}}(\Lambda) \\compatible}} \prod_{\gamma \in \Gamma}
    \widetilde{w}_\gamma.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 26 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $v$ be any local place of $F$. We have
	\begin{multline*}
		\int_{K_{n,v}}\M^\vee_v\left(\M_v\varphi_{\lambda_{\mathrm{E}}(\frac{1}{2}-s),v}\cdot\M_v\bar{f}_v\right)\cdot f_{s,v}\\
		=\Delta_v^{-n+\frac 32-ns}\frac{\zeta_v(1-ns)\zeta_v(-\frac{n-2}{2})}{\zeta_v(n-1)\zeta_v(ns)\zeta_v(\tfrac n2)}
		\optionA{\P_v\left(\lambda_{\mathrm{E}}(\tfrac{1}{2}-s);\varphi_v,f_v,f_{v,s}\right)}
		\optionB{\P_v\left(s,\lambda_{\mathrm{E}}(\tfrac{1}{2}-s);\varphi_v,\Phi_v\right)}
	\end{multline*}
	for $s$ in general position. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem S<=00003DPhi of arXiv:2603.27144, 'On the critical fugacity of the hard-core model on regular bipartite graphs'] \begin{comment}
For the hypercube (and generally with reasonable local expansion properties
(that I'm not sure what would be a good way to formulate)) we may
replace $(p+\frac{1}{\delta})$ with $(p+\frac{1}{\delta^{C}})$ for
any $C$. I expect this to be of use when refining the critical fugacity
estimate to $\lambda_{c}\sim\frac{e}{\delta}$.
\end{comment}
Let $\boldsymbol{A}$ be a random subset of $V$, independent of $\boldsymbol{\varphi}$
and satisfying $\mathbb{P}(v\in\boldsymbol{A})\le p$ for every $v\in V$.
Then
\begin{equation}
S(\boldsymbol{\varphi}_{\boldsymbol{A}}\,|\,\boldsymbol{A})\le C_{\mathrm{LE}}|V|\left(2(p+\frac{1}{\delta})\cdot S(\mathbb{E}\boldsymbol{\Phi})+\frac{\log2}{\delta M_{\mathrm{LE}}}\right).
\end{equation}

[Prop 33 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] Take $u\in L^1_{\loc}(\R^d)$. Then 
the following are equivalent to each other. 
\begin{enumerate}
\item[\rm(1)] $\Psi(m^{\frac{1}{\alpha}}|\cdot|)\left(1\land\frac{1}{|\,\cdot\,|} \right)|u|\in L^1(\R^d)$. 
\item[\rm(2)] For any $U\Subset V\Subset \R^d$, 
with $0\in V$, 
\begin{align*}
\int_{U\times V^c}|u(x)-u(y)|\frac{\Psi(m^{\frac{1}{\alpha}}|x-y|)}{|x-y|^{d+\alpha}}{\d} x{\d} y<\infty.
\end{align*}
\end{enumerate}
Moreover, take $u\in L^2_{\loc}(\R^d)$. Then the following are equivalent to each other.
\begin{enumerate}
\item[\rm(3)] $\Psi(m^{\frac{1}{\alpha}}|\cdot|)\left(1\land\frac{1}{|\,\cdot\,|} \right)|u|^2\in L^1(\R^d)$. 
\item[\rm(4)] For any $U\Subset V\Subset \R^d$, 
\begin{align*}
\int_{U\times V^c}|u(x)-u(y)|^2\frac{\Psi(m^{\frac{1}{\alpha}}|x-y|)}{|x-y|^{d+\alpha}}{\d} x{\d} y<\infty.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

