[Lemma lem:ratio-ub of arXiv:2608.23554, 'Provably adaptive sampling with uniform and remasking \\ discrete diffusion models'] Let \(p, q \in [\alpha, 1]\) for some \(\alpha > 0\). Then,
    \begin{equation*}
        \frac{\frac p q  - 1 - \log \frac p q}{q\left(\frac p q \log \frac p q - \frac p q + 1 \right)}  \leq \frac 1 {\min(p, q)} \leq \frac 1 \alpha.   
    \end{equation*}
    The case \(p = q\) is interpreted by continuity. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lkzeta of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp For any {\small$(\s,\t,\x,\y)\in[0,\infty)^{2}\times\Z^{2}$} with {\small$\s\leq\t$}, we have

\begin{align}
\mathbf{K}^{N,\zeta,\sim}_{\s,\t,\x,\y}&=\mathbf{L}^{N,\zeta,\sim}_{\s,\t,\x,\y}+\int_{\s}^{\t}\sum_{\w\in\Z}\mathbf{L}^{N,\zeta,\sim}_{\r,\t,\x,\w}\cdot\boldsymbol{\Phi}_{\r}[\mathbf{K}^{N,\zeta,\sim}_{\s,\r,\cdot,\y}]_{\w}\d\r,
\end{align}

where, for convenience, {\small$\boldsymbol{\Phi}_{\r}$} is the operator acting on {\small$\w\mapsto\mathbf{K}^{N,\zeta}_{\s,\r,\w,\y}$} arising from the second line in (equation eq:kzetasim-sde of the paper):

\begin{align}
\boldsymbol{\Phi}_{\r}[\mathbf{K}^{N,\zeta,\sim}_{\s,\r,\cdot,\y}]_{\w}&:=N\boldsymbol{\chi}^{(\zeta)}_{\x}{\ocolor{red}\mathbf{1}_{\mathfrak{t}_{\mathrm{ap}}\geq\r}}\sum_{\substack{\n=1,\ldots,\mathrm{K}\\{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\lesssim \mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\boldsymbol{\Phi}_{\r}^{\n,{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}[\mathbf{K}^{N,\zeta,\sim}_{\s,\r,\cdot,\y}]_{\w},\\
\boldsymbol{\Phi}_{\r}^{\n,{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}[\mathbf{K}^{N,\zeta,\sim}_{\s,\r,\cdot,\y}]_{\w}&:=\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n}}_{\r,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{K}^{N,\zeta,\sim}_{\s,\r,\cdot,\y})]_{\w}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

