[Proposition 5 of arXiv:2606.20908, 'On It\^o-Stratonovich formula for rough sheets'] Consider the product introduced in Definition~\ref{def:pdt-increments-1d}.
  \begin{enumerate}
  \item If $g,h\in\cac_{1}$, then $gh\in\cac_{1}$ and
    \begin{equation}
      \delta(gh)=\delta g\,h+g\,\delta h.
    \end{equation}
  \item If $g\in\cac_{1}$ and $h\in\cac_{2}$, then $gh\in\cac_{2}$ and
    \begin{equation}
      \delta(gh)=-\delta g\,h+g\,\delta h.
    \end{equation}
  \item If $g\in\cac_{2}$ and $h\in\cac_{1}$, then $gh\in\cac_{2}$ and
    \begin{equation}
      \delta(gh)=\delta g\,h+g\,\delta h.
    \end{equation}
  \end{enumerate}

