body:
[Theorem thm:debruijn of arXiv:2510.22778, 'Free denoising diffusion models'] Along the free OU flow (equation eq:forward of the paper), for $t>0$,
\begin{equation}
  \frac{\mathrm{d}}{\mathrm{d} t}\mathcal{D}(\mu_{t}\Vert\gamma)=-\tfrac{\beta(t)}{2}\,I(\mu_{t}\Vert\gamma),
\end{equation}
and consequently
\begin{equation}
  \mathcal{D}(\mu_{t}\Vert\gamma)\le e^{-\Lambda(t)}\mathcal{D}(\mu_{0}\Vert\gamma),
  \qquad
  W_{2}(\mu_{t},\gamma)\le e^{-\Lambda(t)/2}\,W_{2}(\mu_{0},\gamma).
\end{equation}

[Prop p.UpperBoundSec5 of arXiv:2606.11043, 'Thick points under Gaussian free field dynamics'] For $\gamma \in (0,2\sqrt{2})$, we have that
    \begin{equation}

        \dim_H(T^{\gamma}) \leq \min \left \{ 4-\frac{\gamma^2}{2}, 3- \frac{\gamma^{2}}{4}\right \}
    \end{equation}
    and if $\gamma > 2\sqrt{2}$ then, $T^{\gamma}$ is empty. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop reg_plus of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] {PV26}}] 
Let $\beta_0,h_0 \geq 0$.  There exists a measure $\zeta=\zeta(\rho,\beta_0,h_0)$ supported on $\mathbb R^+$ and which has all Gaussian moments,
such that the following holds for $\beta\leq \beta_0$ and $\mathsf{h}\in (\mathbb R^+)^{\mathbb Z^d}$ such that $\mathsf{h}\leq h_0$.
\begin{enumerate}
    \item[$(i)$] The measures $\nu^{\zeta}_{\Lambda,\beta,\mathsf{h}}$ converge weakly to the measure $\nu_{\beta,\mathsf{h}}^+$ defined in Proposition \textup{(prop: existence of plus state extremal of the paper)} as $\Lambda\nearrow \mathbb Z^d$.
\item[$(ii)$] There exist $a=a(\beta_0,h_0),b=b(\beta_0,h_0)>0$  such that, for every finite $\Lambda\subset \mathbb Z^d$, the measure $\nu^\zeta_{\Lambda,\beta,\mathsf{h}}$ is $(a,b)$-regular, in the following sense. For every $\Delta \subset \overline{\Lambda}$, the restriction measure $(\nu^\zeta_{\Lambda,\beta,\mathsf{h}})^{(\Delta)}$ has a density with respect to $\prod_{x\in \Delta \cap \Lambda}\mathrm{d}\rho(\tau_x)\prod_{x\in \partial^{\textup{ext}}\Lambda\cap \Delta}\mathrm{d}\zeta(\tau_x)$ satisfying
\begin{equation}
 \frac{\mathrm{d}(\nu^\zeta_{\Lambda,\beta,\mathsf{h}})^{(\Delta)}(\tau)}{\prod_{x\in \Delta\cap \Lambda}\mathrm{d}\rho(\tau_x)\prod_{x\in \Delta\cap \partial^{\textup{ext}}\Lambda}\mathrm{d}\zeta(\tau_x)} \leq \prod_{x\in \Delta}e^{a\tau_x^2+b}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:dsh-recursion of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] For all $n < N-1$,
    \begin{align*}
        (\mathtt d^\mathsf{sh}_{n+1})^2
        &\leqslant L_n\, (\mathtt d^\mathsf{sh}_n)^2 + \frac{1}{\gamma_{nh}^2}\, O\Bigl(\frac{(\bar{\mathcal{E}}^{\rm w})^2}{(\omega_+ + \eta_{nh}^\mathsf{p})\,h} + \bigl(1+\frac{\beta^2 h}{\gamma_{nh}^2\,(\omega_+ + \eta_{nh}^\mathsf{p})}\bigr)\, (\bar{\mathcal{E}}^{\rm s})^2\Bigr)\,.
    \end{align*}
    Here, $L_n < 1$ is an effective contraction constant (derived in Lemma~(lem:discrete_contraction of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] Let $a\in[1/2,1]$. Then
\begin{equation*}
    \argmax_{x\geq 0} \frac{1-\upe^{-x}}{x^{a}} \leq \frac{2(1-a)}{a}.
\end{equation*}

