[Theo thm:mf-spec of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] The multifractal spectrum of $W$ on  the space $ \Omega^\mathrm{crit}$  endowed with the uniform norm is fully described by 
    \[ f_\mathrm{crit} ( \xi)  =
    \begin{dcases}
    1 + \frac{\xi}{2}  &  \text{ if } \xi \ge 2  \\
    - \infty   &  \text{ if }  0 < \xi < 2 \;. 
    \end{dcases}
    \]
   Consequently, on the whole space $ \Omega$ it holds
    \[  f ( \xi) \ge   1 + \frac{\xi}{2}
    \qquad \text{ if } \xi \ge 2 \;. \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:ap1:wellPosed of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Fix $\kappa, d \in \ensuremath{\mathbb{N}}$ and $T \in (0, \infty)$. Suppose $\lambda \in \mathcal{Q}_{\kappa, d}$ and $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper). Suppose that $(\mu, \gamma)$ is a linear growth solution to the $\kappa$-MLFE{} with potentials $(U, W)$ and initial condition $\lambda$. Then the following properties hold: 
\begin{enumerate}
    \item The time-marginals of $\mu$ have uniformly bounded second moments, that is
\begin{equation*}
    \sup_{t \in [0, T]} \int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} |\mathbf{x}|^2 \mu_t(d\mathbf{x}) < \infty;
\end{equation*}
        \item There exists a positive locally H\"older continuous function $\mu:[0, T] \times (\ensuremath{\mathbb{R}}^d)^{1 + \kappa} \rightarrow (0, \infty)$ such that $\mu_t(d\mathbf{x}) = \mu_t(\mathbf{x}) d\mathbf{x}$. Moreover, the H\"older coefficient and exponent of $\mu$ depends only on $(\kappa, d, T)$, the linear growth constant of $(\gamma, \nabla U, \nabla W)$, and the initial condition $\lambda$.
    \item  We have $\mu_t \in W^{1, 1}((\ensuremath{\mathbb{R}}^d)^{1 + \kappa})$ for almost every $t \in (0, T)$. Moreover the following estimate holds:
\begin{equation*}
    \int_0^T \int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} \frac{|\nabla_{\mathbf{x}} \mu_t(\mathbf{x})|^2}{\mu_t(\mathbf{x})} d\mathbf{x} dt < \infty.
\end{equation*}
\item For all $t \in [0, T]$, we have
\begin{equation*}
    \int \mu_t(\mathbf{x}) |\log \mu_t(\mathbf{x})| d\mathbf{x} < \infty.
\end{equation*}
\end{enumerate}
In particular, if $\lambda \in \mathcal{Q}_{\kappa, d}$ and $(\mu, \gamma)$ is a linear growth solution of the $\kappa$-MLFE{} on $[0, T]$ with initial condition $\lambda$, then $\mu_t \in \mathcal{Q}_{\kappa, d}$ for all $t \in [0, T]$.

[Lemma 42 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ with $d\neq 6$, there exist $\Cl,\cl,\cl,\cl>0$ such that for any $n\ge \Cref{const_point_to_boundary1}$, $N\ge \Cref{const_point_to_boundary1}n$, $\psi\in \Psi(n,N)$ and $\diamond \in \{\mathrm{in},\mathrm{out}\}$, the following hold:
 	  	   	 \begin{align}
 	&\text{when}\ 3\le d\le 5,\   \mathbb{P}\big( \mathsf{C}^{\diamond}[\psi, \cref{const_point_to_boundary2}]  \big) \asymp  m^{d-2}_{\diamond} \cdot 	\mathbb{P}\big(  \mathsf{C}[\psi]  \big)  \asymp    \mathbb{P}\big( \widehat{\mathsf{C}}^{\diamond}[\psi, \cref{const_point_to_boundary2},\cref{const_point_to_boundary3},\cref{const_point_to_boundary4}]  \big);   \\ 
 	&\text{when}\ d\ge 7,  \ \ \ \ \ \   \mathbb{P}\big( \mathsf{C}^{\diamond}[\psi, \cref{const_point_to_boundary2}]  \big) \asymp  m_{\diamond}^{2d-8}\cdot 	\mathbb{P}\big(  \mathsf{C}[\psi]  \big)\asymp    \mathbb{P}\big( \widehat{\mathsf{C}}^{\diamond}[\psi, \cref{const_point_to_boundary2},\cref{const_point_to_boundary3}]  \big) . 
 \end{align}

