body:
[Thm 14 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] The measures $P_n$ converge weakly to a signed probability measure $P$ on the set of generalised snake configurations on the lattice, whose correlations are given explicitly by 
    \begin{equation*}
        P\left(\prod_{i=1}^k \{ \rho x^i = y^i \}\right) = \left(\prod_{i=1}^k K_{(0,0)}(x^i, y^i )\right)\det_{i,j = 1}^{k}L(x^{i},y^{j}),
    \end{equation*}
    where $x^1,\dots,x^k, y^1,\dots,y^k \in \midedge$ such that for each $i$, $y^i - x^i \in \{(0,0), e^1, e^2, e^3\}$, and
    \begin{equation}  
        L(x,y) = \oint\!\oint_{|w_1|=|w_2|=1} \frac{dw_1}{2\pi i w_1}\,\frac{dw_2}{2\pi i w_2}\,w_1^{y_1 -x_1 }w_2^{y_2 - x_2}\big[M(w_1,w_2)^{-1}\big]_{c(x),\,c(y)}.
    \end{equation}

[Proposition lemma:dg of arXiv:2410.23509, 'Dynkin Games for L\'evy Processes'] Consider a pair $(\tilde{\sigma},\tilde{\tau})$ of stopping times  for the problem  in Definition (def:dg of the paper) and a real valued function $\widetilde{V}(x)$, defined by 
\begin{align}
\widetilde{V}(x)&={\operatorname{\mathbf{M}}_x}(\tilde{\sigma},\tilde{\tau}).\tag{MG}
\end{align}
Assume that the two following conditions hold
\begin{align}
\widetilde{V}(x)&\geq{\operatorname{\mathbf{M}}_x}(\tilde{\sigma},\tau),
\quad\text{ for all $\tau\in\mathcal{M}$},\tag{SPMG}\\
&\notag\\
\widetilde{V}(x)&\leq{\operatorname{\mathbf{M}}_x}(\sigma,\tilde{\tau}),
\quad\text{ for all $\sigma\in\mathcal{M}$}.\tag{SBMG}
\end{align}
Then, the DG in Definition (def:dg of the paper)
has value function $\widetilde{V}(x)$, and $(\tilde{\sigma},\tilde{\tau})$  is a  pair of optimal stopping times  for the problem, meaning that (equation eq:dg of the paper) holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

