[Lem 17 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] One has 
\begin{equation}
\underset{t\rightarrow\infty}{\overline{\lim}}\frac{1}{\beta(t)}\log\Big\langle\sum_{k=1}^{\infty}e^{\beta(t)\lambda_{k}^{\xi_{t}}(\Sigma_{r})}\Big\rangle\leqslant-\chi_{r},
\end{equation}
where $\chi_{r}$ is defined by (\ref{eq:ChiR}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:2BM of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\mathbf{q} \in \mathcal{Q}$ and $k \in {\mathbb{N}}$ satisfy the assumption of Theorem (thm:main of the paper) ((item:1 of the paper)) {and ${\mathbb{E}}_{\nu_\mathbf{q}}\left[ {s_{\infty}\left(1\right)}^2 \right] < \infty$}. Then, for any $u, v \in {\mathbb{R}}$ and $\mathbf{T} > 0$, we have the following weak convergence in $D\left([0,\mathbf{T}]\right)^2$ under $\nu_{\mathbf{q}}$.
                \begin{align}
                    &\lim_{\varepsilon \to 0}\left( \frac{1}{n} Y^{\left(\left\lfloor n u \right\rfloor\right)}_{k}\left( \left\lfloor n^2 t \right\rfloor \right) - nt v^{\mathrm{eff}}_{k}\left( \mathbf{q} \right), \frac{1}{n} Y^{\left(\left\lfloor n v \right\rfloor\right)}_{k}\left(\left\lfloor n^2 t \right\rfloor \right) - nt v^{\mathrm{eff}}_{k}\left( \mathbf{q} \right) \right) \\ &= \left(B_{k}\left(t\right), B_{k}\left(t\right)\right),
                \end{align}
            where $B_{k}\left(\ \cdot \ \right)$ is the centered Brownian motion with variance $D_{k}\left(\mathbf{q}\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $m \ge 0$ and $\tau$ be an ultrametric oriented tree with node depths $x_1, \dots, x_{k-1}  \in  \{1,\ldots, T\}$ and  $x_0=T$. The likelihood function of the parameters $(p,r)$ given $\{\mathbf{T}_k = \tau, N_T=k+m\}$ is

\begin{equation*}
\begin{split}
  & \mathcal{L}(p, r\mid \tau,k, m )
  ={ k+m \choose k }^{-1} \underset{\mathbf{m}\in \mathbf{M}_{k,m}}{\sum}\mathbb{P}(H>T)\mathbb{P}(H\leq T)^{m_0} \underset{i=1}{\overset{k-1}{\prod}}
    \left( \mathbb{P}(H\leq x_i)^{m_i+1} -\mathbb{P}(H<x_i)^{m_i+1} \right)  ,
    \end{split}
\end{equation*}
where $\mathbf{M}_{k,m}:=\{(m_0,m_1,\dots, m_{k-1})\in\mathbb{Z}_+^k: m_0+\cdots +m_{k-1}=m\}$.

