where
\begin{equation*}
A(T,y)=\frac{\alpha \rho +1}{T^{1+\alpha \rho }}\int_{0}^{\infty }w^{\alpha
\rho }\mathbf{P}\left( -w\leq \min_{0\leq s\leq 1}Y_{s}\leq y-w;Y_{1}\leq
T-w\right) dw
