[Definition 13 of arXiv:2609.01996, 'Baumslag--Solitar Subgroups Obstruct Model Companions for Fields with Group Actions'] Let \(\Sigma(c,e,g)\) be the partial type consisting of
  \begin{enumerate}
    \item \(\tau(B_{\sigma^m}(c))=B_{\sigma^n}(c)\);
    \item \(eg\neq0\);
    \item for every \(\gamma\in\ker\beta\), the formulas \(\gamma(g)=g\) and \(\gamma(e)=g^{q\ell(\gamma)}e\);
    \item all formulas in \(\left\{ B_\gamma(c)=B_\delta(c) \colon \beta(\gamma)=\beta(\delta) \right\} \cup \left\{ B_\gamma(c)\neq B_\delta(c) \colon \beta(\gamma)\neq\beta(\delta) \right\}\);
  \end{enumerate}

[Lemma lem:mmt-unif of arXiv:2411.10419, 'Lower bounds on the top Lyapunov exponent for linear PDEs driven by the 2D stochastic Navi'] Fix any $t_{0} > 0$. There exists an $ \mathbf{r} >1 $ such that the following holds: for any $ p > 0, 2<  \beta < \mathbf{a}/2 $ and $t>t_{0} $, there exists a $C(t_{0})>0$ such that for any $u_{0}\in H^{\mathbf{b}}$ with $\mathbf{b}= (\mathbf{a}-3)/2$ 
\begin{equ}
 \mathbb{E} \left[ \sup_{t_{0} \leqslant s \leqslant t}  \left( \| X_{s} \|_{\mathcal{C}^{\beta}
}^{p} + \| u_{s} \|_{\mathcal{C}^{\beta}
}^{p} \right) \right] \leqslant C(t_{0}) (\| u_{0} \|_{H^{\mathbf{b}}} + 1)^{p \mathbf{r} } \;.      
\end{equ} Moreover, there exists a $C>0$ such that for any $u_{0}\in \mathcal{C}^{\beta} $ 
\begin{equ}
 \mathbb{E} \left[ \sup_{0 \leqslant s \leqslant t}  \left( \| X_{s} \|_{\mathcal{C}^{\beta}
}^{p} + \| u_{s} \|_{\mathcal{C}^{\beta}
}^{p} \right) \right] \leqslant C (\| u_{0} \|_{\mathcal{C}^{\beta}} + 1)^{p \mathbf{r} } \;.
\end{equ} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_ugly_log of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] For any $s \in (0,1)$ and $t \in \mathbb{R}$ we have
    \begin{align}
       \lim_{\alpha \to \infty} \gamma(\alpha) \cdot \left(V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) - s\right)=  \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)}.
    \end{align}
    \begin{proof} First we show that
  $  \gamma(\alpha) \cdot \left(V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) - s\right) \leqslant  \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} +\delta  $ holds for any $\delta>0$ if $\alpha$ is big enough. By $V_\alpha(x,y)=u_\alpha^{-1}(u_\alpha(x) + u_\alpha(y))$ and the strict monotonicity of $u_\alpha(\cdot)$ we only need to check that if $\alpha$ is large enough then we have
  \begin{equation}
  u_{\alpha}\left( s + \frac{t}{\gamma(\alpha)}\right) + u_{\alpha}\left( s - \frac{t}{\gamma(\alpha)} \right) \leqslant
  u_{\alpha}\left( s + \frac{1}{\gamma(\alpha)}\cdot \left(\frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} +\delta \right) \right).
  \end{equation}
Dividing both sides of (equation uuu_delta_ineq of the paper) by $u_\alpha(s)$, letting $\alpha \to \infty$ and using Corollary (cor_uu_frac_lim of the paper) three times we obtain that (equation uuu_delta_ineq of the paper) indeed holds is $\alpha$ is big enough. The proof of the fact that for any $\delta>0$ the inequality $  \gamma(\alpha) \cdot \left(V_\alpha\Big(s+\frac{t}{\gamma(\alpha)}, s - \frac{t}{\gamma(\alpha)}\Big) - s\right) \geq  \frac{\ln(e^{\psi(s)t} + e^{-\psi(s)t})}{\psi(s)} -\delta  $ holds for big enough $\alpha$ is analogous and we omit it.  Since $\delta>0$ was arbitrary, we obtain
(equation ugly_logarithm of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] [\cite{Minh:LogDet2016}]
			 Assume that {$\dim(\H) = \infty$} and that {$(A+\gamma I), (B+ \mu I) \in \PC_1(\H)$}.
			For {$0 \leq \alpha \leq 1$},
			{
				\begin{align*}
					\detX[\alpha (A+\gamma I) + (1-\alpha)(B + \mu I)] \geq \left(\frac{\gamma}{\mu}\right)^{\alpha - \delta}\detX(A+\gamma I)^{\delta}\detX(B+\mu I)^{1-\delta},
				\end{align*}
			}
			where {$\delta = \frac{\alpha \gamma}{(\alpha \gamma + (1-\alpha)\mu)}$, $1-\delta = \frac{(1-\alpha)\mu}{(\alpha \gamma + (1-\alpha)\mu)}$}.
			For {$0 < \alpha < 1$}, equality occurs if and only if {$A = B$} and {$\gamma = \mu$}. In particular, for {$\gamma = \mu$},
			{
				\begin{align}
					\detX[\alpha (A+\gamma I) + (1-\alpha)(B + \gamma I)] \geq \detX(A+\gamma I)^{\alpha}\detX(B+\gamma I)^{1-\alpha}.
				\end{align}
			} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_iteration of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small constants $\epsilon,\tau>0$.  Assume that for any $z_i \in {\mathbb C}$ and $\eta_i \in {\mathbb R }$ satisfying $|z_i| \leq 1+\tau$, $\min_{i=1}^2 \{|\eta_i| \rho_i \} \geq n^{-1+\epsilon}$, $\gamma \gtrsim  \eta_*/\rho^*$, the following hold for some $0\leq b < 1$, \emph{i.e., }
	\begin{align}
		&\Big| \big(G^{z_1}(\mathrm{i} \eta_1) A_1 G^{z_2}(\mathrm{i} \eta_2)-M_{12}^{A_1}\big)_{{\bm x} {\bm y}}\Big|\prec\frac{(\rho^*)^{\frac{1-b}{2}}}{\sqrt{n}(\eta_*)^{\frac{3-b}{2}} \gamma^{\frac{b}{2}}},
	\end{align}
	\begin{align}
		&\Big|\big(G^{z_1}(\mathrm{i} \eta_1)A_1G^{z_2}(\mathrm{i} \eta_2)A_2G^{z_1}(\mathrm{i} \eta_1)-M_{121}^{A_1,A_2}\big)_{{\bm x} {\bm y}}\Big| \prec \frac{1}{\eta_*^{2-b} \gamma^{b}},
	\end{align}
	  uniformly for any deterministic bounded  matrices $A_i~(i=1,2)$ and unit vectors ${\bm x}, {\bm y}$, where $\gamma$ is defined in ((parameter of the paper)) and  $M_{12}^{A_1}$,
	$M_{121}^{A_1,A_2}$ are defined in ((eq:defM12 of the paper)), ((eq:defM121 of the paper)).
		Then the following also hold for a larger  $b'=\min\big\{b+\theta,~1\big\}$ with some $0<\theta\leq \epsilon/10$,
	\begin{align}
		&\Big| \big(G^{z_1}(\mathrm{i} \eta_1) A_1 G^{z_2}(\mathrm{i} \eta_2)-M_{12}^{A_1}\big)_{{\bm x} {\bm y}}\Big|\prec\frac{(\rho^*)^{\frac{1-b'}{2}}}{\sqrt{n}(\eta_*)^{\frac{3-b'}{2}} \gamma^{\frac{b'}{2}}},
	\end{align}
	\begin{align}
		&\Big|\big(G^{z_1}(\mathrm{i} \eta_1)A_1G^{z_2}(\mathrm{i} \eta_2)A_2G^{z_1}(\mathrm{i} \eta_1)-M_{121}^{A_1,A_2}\big)_{{\bm x} {\bm y}}\Big| \prec \frac{1}{\eta_*^{2-b'} \gamma^{b'}}.
	\end{align}
  uniformly for any deterministic bounded  matrices $A_i~(i=1,2)$ and unit vectors ${\bm x}, {\bm y}$.

