[Lemma lem:denominator of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Let $\lambda_1,\ldots,\lambda_N\ge0$ and $q_1,\ldots,q_N\ge0$. Put
\[
  u(z)=\sum_{j=1}^N\frac{q_j}{\lambda_j-z},
  \qquad z=E+i\eta\in\mathbb{C}_+.
\]
Then
\begin{equation}
  \boxed{|1+u(z)|^{-1}\le\frac{|z|}{\eta}.}

\end{equation}

[Lemma lem:empirical-radii of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Assume (equation eq:base-assumptions of the paper), (equation eq:critical-scaling of the paper), and
$p/m\to c\in(0,\infty)$.
\begin{equation}
  \frac1m\sum_{\alpha=1}^m\delta_{R_{n,\alpha}}
  \longrightarrow\nu_{\lambda,v}
  \quad\text{in $W_2$, in probability}.

\end{equation}
Moreover,
\begin{equation}
  \frac1m\sum_{\alpha=1}^mR_{n,\alpha}
  \xrightarrow{p}1.

\end{equation}

