\begin{equation}
    V_{g}(x,y) = \begin{cases} \frac{1}{\beta} \ln\left( \frac{e^{\beta(x+1)}+e^{\beta(y+1)}-e^{\beta(x+y)}-e^{\beta}  }{e^{\beta}-1} \right) & \text{ if } \; \; \beta \neq 0, \\
     x+y-xy  & \text{ if } \; \; \beta =0.
   \end{cases}
    \end{equation}
 \item    In the case of the $k$CM model (cf.\ (equation eq_g_kCM of the paper)) the formula (equation V_in_terms_of_u of the paper) becomes \begin{equation}
     V_{g}(x,y) = \begin{cases} 1 - ((1-x)^{1-k} + (1-y)^{1-k} -1)^{\frac{1}{1-k}} & \text{ if } \; \; k =2,3,\dots, \\
     x+y-xy  & \text{ if } \; \; k =1.
     \end{cases}
     \end{equation}
     \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition ppo:decay_H_ab of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Assume that ${\bf p}(t)=\{p_n(t)\}_{n\geq 0}$ is a classical solution of (equation eq:law_limit of the paper)-(equation eq:two-classes of the paper) such that ${\bf p}(0) \in \mathcal{P}(\mathbb N)$ with mean $\mu \in \mathbb N_+$, then
\begin{equation}

\frac{\mathrm{d}}{\mathrm{d} t} \mathcal{H}_{ab}[{\bf p}]  \leq - \lambda_r \log \lambda_r \sum_{n=b+1}^{\infty} p_n - \lambda_g \log \lambda_g \sum_{n=0}^{a-1} p_n,
\end{equation}
with $\lambda_r$ and $\lambda_g$ defined as in (equation eq:two-classes of the paper).

