[Theorem 25 (\cite{Motivic_Igusa_Zeta_Function}) of arXiv:2609.03976, '2609.03976'] Let $X$ be a smooth complex algebraic variety, let $\mathfrak a\subseteq\mathcal O_X$ be a nonzero coherent ideal sheaf, and let
		$\mu:Y\longrightarrow X$ be a log resolution of $\mathfrak a$. Suppose $E_{i}(i \in S)$ are the irreducible components of $\mu^{*}(\mathfrak{a})$ and relative canonical divisor $K_{Y/X}$ such that $\mu^{*}(\mathfrak{a})=\sum_{i \in S}N_{i}E_{i}$ and $K_{Y/X}=\sum_{i \in S}(\nu_{i}-1)E_{i}$. Then the motivic zeta function of $\mathfrak{a}$, denoted by $Z^{\mathrm{mot}}_{\mathfrak{a}}(s)$, can be calculated by
		\begin{flalign*}
			Z^{\mathrm{mot}}_{\mathfrak{a}}(s)=\sum_{J \subset S}[\mathring{E}_{J}]\prod_{i \in J}\frac{\mathbb{L}-1}{\mathbb{L}^{N_{i}s+\nu_{i}}-1},
		\end{flalign*}
		where $\mathring{E}_{J}:=(\cap_{i \in J}E_{i})\setminus (\cup_{j \notin J}E_{j})$. Here we call $(N_{i},\nu_{i})(i \in S)$ the data of the log resolution. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2609.02464, 'When does propagation of chaos in the critical Curie-Weiss model stop?'] For every $N$ and $k\leq N$, the following is true

\begin{enumerate}
\item If $k$ is even, then $(p_{N,k}(j))_{j=0}^k$ is log-concave, and hence
unimodal, if and only if
\begin{equation}
k\,\mathbb E_{\rho_{N,k}}[\sinh^2X]\le 1.
\end{equation}
If the reverse strict inequality holds, then the midpoint $k/2$ is a strict
local minimum and the distribution is not unimodal.

\item If $k$ is odd, then $(p_{N,k}(j))_{j=0}^k$ is log-concave, and hence
unimodal, if and only if
\begin{equation}
(k-1)\mathbb E_{\widehat\rho_{N,k}}[\sinh^2X]\le 1.
\end{equation}
If the reverse strict inequality holds, then the two midpoints $(k-1)/2$ and $(k+1)/2$ are a
local minimum and the distribution is not unimodal.
\end{enumerate}

[Theorem 6 of arXiv:2607.23305, 'On extremes of a random walk with positive drift\\ over an intermediate regularly varying '] Let $\E\xi=-a<0$ and let 
