[Proposition of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:prop:polynomial_volume_implies_polynomial_growth}
    Suppose that $(G_n)_{n \in \mathbf{N}}$ is a sequence of transitive graphs converging locally to $G$ a transitive graph of polynomial growth with $d \geq 1$. 
    Then there exists a constant $C = C(d,G) > 0$ such that $\# B_{G_n}(r) \leq C r^d$ for all $n$ and $r$ sufficiently large. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cd of arXiv:2601.10624, 'Source localisation in simple random walks'] For each $d \geqslant 5$, we have $c(d) > 0$. Further, we have
    \begin{equation*}
        c(d) = 1 - O(1/d).
    \end{equation*}

[Proposition 7 of arXiv:2607.02406, 'On the range of competing random walks'] We have the following identity 
    \begin{equation}

        \mathcal R_n^{j\rightarrow k}=\sum_{\ell=1}^{2^p}\mathcal R_{n,p,\ell}^{j\rightarrow k}+\sum_{q=1}^{p}\sum_{m=1}^{2^{q-1}}\mathcal I_{n,q,m}^{j\rightarrow k}+\varepsilon_{n,p}^{j\rightarrow k},
    \end{equation}
    where for each $p\ge1$, $\ell\in[\![2^p]\!]$, $q\in[\![p]\!]$, $m\in[\![2^{q-1}]\!]$, we define 
    \begin{equation}

        \mathcal R_{n,p,\ell}^{j\rightarrow k}\eqdef\sum_{x\in\ZZ^d}\1\left(T_x^j\circ\theta_{\frac{\ell-1}{2^p}n}\le T_x^k\circ\theta_{\frac{\ell-1}{2^p}n}\le n/2^p\right),
    \end{equation}
    \begin{equation}

        \mathcal I_{n,q,m}^{j\rightarrow k}\eqdef\sum_{x\in\ZZ^d}\1\left(T_x^j\circ\theta_{\frac{m-1}{2^{q-1}}n}<n/2^q<T_x^k\circ\theta_{\frac{m-1}{2^{q-1}}n}\le n/2^{q-1}\right),
    \end{equation}
    and where $\varepsilon_{n,p}^{j\rightarrow k}$ is an error term such that 
    \begin{equation*}
        \underset{n\rightarrow\infty}\lim\frac{h(n)^4b(n)^{2d}}{n^4}\EE\left[(\varepsilon_{n,p}^{j\rightarrow k})^2\right]=0.
    \end{equation*}
    The variables $(\mathcal R_{n,p,\ell}^{j\rightarrow k})_{1\le \ell\le 2^p}$ are mutually independent and equal in distribution to $\mathcal R_{n/2^p}^{j\rightarrow k}$.

[Lemma of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let $\varphi$ be such that for some $\alpha>0,L\geq0$ 
\begin{equation*}
\kappa_{(\varepsilon^{-1}\varphi+U_\rho)}(r)\geq \alpha-\varepsilon^{-1}-r^{-1} f_L(r)\, \quad \forall r>0
\end{equation*}
holds. Then we have
\begin{equation*}
\kappa_{\Phi^\rho_0(\varphi)}(r)\geq \frac{\varepsilon \alpha -1}{\varepsilon\alpha}- \frac{L}{\varepsilon\alpha^2} \quad \forall r>0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Convex ordering of point processes) of arXiv:2605.28766, 'Convex order and faster transmission in first contact percolation'] Given two simple point processes $\X,\X'$ on $\R$, we say that $\X$ is more {\em reliable} than $\X'$ if for every finite collection of Borel sets $B_1,\dots,B_k\in\mathcal{B}(\R)$ and every decreasing convex function $\varphi\colon\R^k\to\R$, we have
    \begin{align}
    \bbE[\varphi(\X(B_1),\dots,\X(B_k))] \leq \bbE[\varphi(\X'(B_1),\dots,\X'(B_k))].
    \end{align}
    In this case, we write $\X\gg\X'$.

