body:
[Proposition 10 of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Let  $\delta_1\ge 0$, $\delta_2,\delta_3\in \bR$, $b\ge 0$ and $r_0,z\in \bR$. Let $Y$ be the ${\rm BESQ}(\delta_1\,|_z\, \delta_2)$ flow line starting from $(b,r_0)$ driven by $\cW$ and $\cS$ be the ${\rm BESQ}(\delta_1+\delta_3 \,|_z\, \delta_2+\delta_3)$ flow driven by $\cW$. Write $\zeta$ for the absorption time of $Y$, i.e. $\zeta:=\inf\{r\ge \max(r_0,z)\,:\, Y_r =0\}$ if $\delta_2<0$ and $\zeta=\infty$ otherwise.

    (i) The flow $\cS^+$ defined by
\begin{equation}
\cS^+_{r,x}(a):= \max(\cS_{r,x}(a+Y_r)-Y_x,0),\qquad r_0\le r\le x, a\ge 0
\end{equation}

\noindent is on $\bR_+\times [r_0,+\infty)$ a ${\rm BESQ}(\delta_3\,|_{\zeta} \,\delta_2+\delta_3 )$ flow driven by $\cW_Y^+$. 

(ii) Both $Y$ and the collection of processes $\cS^-$ defined by  
\begin{equation}
\cS^-_{r,x}(a):= 
\min(\cS_{r,x}(a),Y_x), \quad  r_0\le r\le x , 0\le a< Y_r 
\end{equation}

\noindent are driven by the martingale measure $\cW_Y^-$. In particular, they are measurable w.r.t. to $\cW_Y^-$. 

(iii)  $\cW_Y^+$ is a white noise independent of $\cW_Y^-$.

[Lemma 2nd lemma for passing limit of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] For all $t_1,t_2 \in [0,T]$ with $t_2 \leq t_1$ and $\forall \phi_1, \phi_2 \in \mathcal{V}$ we have 
    \begin{align}
        &\lim_{n \rightarrow \infty } \hat{\mathbb{E}} \left[  \left(\left \langle \hat{M}_{n}(t_1),\phi_1 \right \rangle \left \langle \hat{M}_{n}(t_1),\phi_2 \right \rangle-\left \langle \hat{M}_{n}(t_2),\phi_1 \right \rangle \left \langle \hat{M}_{n}(t_2),\phi_2 \right \rangle \right) h(v_{n|[0,t_2]})\right] \nonumber \\&=\hat{\mathbb{E}} \left[ \left(\left \langle \hat{M}(t_1),\phi_1 \right \rangle \left \langle \hat{M}(t_1),\phi_2 \right \rangle-\left \langle \hat{M}(t_2),\phi_1 \right \rangle \left \langle \hat{M}(t_2),\phi_2 \right \rangle \right) h(v_{n|[0,t_2]}) \right], \; \; h \in  \mathcal{C}([0,T],\mathcal{H}), \nonumber
    \end{align}
    where $\left \langle \cdot , \cdot \right \rangle$ represents duality product in the spaces $\mathcal{V}$ and $\mathcal{V}'$.

[Lemma lem:gradient_L_infinity of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given ${\scaleobj{1}{\square}}_m$ a very-well-connected cube such that $\mathscr{C}_*({\scaleobj{1}{\square}}_m) \subseteq \mathscr{C}_{\infty}$, then the following estimates hold for $\nabla v_{m, q}$.
		\begin{itemize}
			\item For any $e \in E_d(\mathscr{C}_*({\scaleobj{1}{\square}}_m))$, we have 
			\begin{equation}
				|\nabla v_{m,q}(e)| \leqslant \vert q\vert + 4 \osc_{\mathscr{C}_{\infty} \cap {\scaleobj{1}{\square}}_m} \chi_q.
			\end{equation}
			\item For any $e \in E_d(\mathscr{C}_{\operatorname{bc}}({\scaleobj{1}{\square}}_m) \setminus \mathscr{C}_*({\scaleobj{1}{\square}}_m))$, 
			\begin{align}
				|\nabla v_{m,q}(e)| \leqslant \sqrt{d} \vert q\vert \size({\scaleobj{1}{\square}}_\mathcal{P}(e)). 
			\end{align}
		\end{itemize}

[Lemma lem:sign-conjugacy of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] For every $k$ and every sign vector $\varepsilon$,
\begin{equation}
 T_k^{\varepsilon}=J_{k+1}^{\varepsilon}U_kJ_k^{\varepsilon}.
\end{equation}
Consequently, $T_k^{\varepsilon}$ and $U_k$ have the same singular values.

