body:
[Lemma CC of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(U_k)_{k\in \mathbb{N}}$ be a bounded tight sequence in $W^{1,2}(X,y^a)$ such that $U_k$ converges weakly to $U$ in $W^{1,2}(X,y^a)$. Let $\mu$, $\nu$ be two nonnegative measures on $X$ and $M$ respectively and such that
    \begin{equation*}
        \lim_{k\to \infty} y^a |\nabla U_k|^2 = \mu \, ,
    \end{equation*}
    and
    \begin{align*}
        &\lim_{k\to \infty} |U_k (-,0)|^{2^*} = \nu .
    \end{align*}
    Then, there exists an at most countable set $J$ and three families $\{x_j\}_{j\in J} \subset M, \{\nu_j\}_{j\in J}, \{\mu_j\}_{j\in J} \in \mathbb{R}_+$ such that
    \begin{enumerate}
        \item $\nu = |U(-,0)|^{2^*} + \sum_{j\in J} \nu_j \delta_{x_j}$,
        \item $\mu \geq y^a |\nabla U|^2 + \sum_{j\in J} \mu_j \delta_{ ( x_j , 0 ) }$,
        \item $\mu_j \geq \bar{S}(n,\gamma)^{-1} \nu_j^{2/2^{*}}$ for all $j\in J$.
    \end{enumerate}

