body:
[Defi 21 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] For any continuous deterministic function $(\psi_t)_{t\geq 0}$ taking values in $\mathcal{H}^6_{\mathrm{Sym}}(\mathbb{S})$ such that for any $k\in \mathbb{N}^{*}$, $|\langle \psi,e_k\rangle| \leq C k^{-6}$ and let $(\mathscr{J}_t)_{t\geq 0}$ be a deterministic curve satisfying conditions $\fbox{{\bf C1}}-\fbox{{\bf C2}}$.
Then, the integral process $(\int_0^t \psi_r\cdot\mathrm{d}\mathscr{J}_r)_{t\geq 0}$ is defined almost surely as the limit, for the uniform topology on compact subsets:
\begin{align*}
\int_0^t \psi_r\cdot\mathrm{d}\mathscr{J}_r:= \lim_{K\rightarrow \infty}\sum_{k=0}^K \left( \int_0^t \langle \psi_r,e_k\rangle\mathrm{d}\langle \mathscr{J}_r,e_k^{+}\rangle  - \int_0^t \langle \psi_r,e_k\rangle\mathrm{d}\langle \mathscr{J}_r,e_k^{-}\rangle \right).
\end{align*}
Moreover, it satisfies for all $T\geq 0$
\begin{align}
\sup_{t\in[0,T]}\Big| \int_0^t \psi_r\cdot\mathrm{d}\mathscr{J}_r  \Big| \leq C \|\zeta_T\|_{2,-2} \times \sup_{t\in [0,T]}\|\psi_t\|_2.
\end{align}

[Definition of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\geq 1$. Suppose that $\Phi$ is an invariant random (nonnegative) measure with finite intensity $\gamma$. Then 
    \begin{align}
        d_p(\Phi, \gamma\lambda_d) := \inf\bigg\{\BE\bigg[\int\|x\|^p\, &(K_0+L_0)(dx)\bigg] : \nonumber\\ 
        &L,K \text{ invariant probability kernels}, \nonumber\\
        &\Phi = \gamma K\lambda_d, \lambda_d = L\lambda_d,\nonumber\\
        &\int x^{\otimes q}\, (K_0-L_0)(dx)=0\text{ for } q\in\N, q\leq\frac{p}{2}-1\bigg\}.
    \end{align}
    Being even more restrictive, one could also define
    \begin{align}
        \tilde{d}_p(\Phi, \gamma\lambda_d) := \inf\bigg\{\BE\bigg[\int\|x\|^p\, &K_0(dx)\bigg] : \nonumber\\ 
        &K \text{ invariant probability kernel}, \Phi = \gamma K\lambda_d, \nonumber\\
        &\int x^{\otimes q}\, K_0(dx)\text{ deterministic for } q\in\N, q\leq\frac{p}{2}-1\bigg\}.
    \end{align}

[Corollary 21 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $\left(\mu_y\right)_{y\in Y}$ be an arbitrary collection of probability measures on $X$ and $\bar\mu$ an arbitrary probability measure on $Y$.
Then there exist rates $r_N$ as in \eqref{diffr} such that the limiting invariant measure is the prescribed one:
\begin{equation} 
	\lim_{N\to\infty}\pi_N(x,y) \,=\, \bar\mu(y)\; \mu_y(x)\;,\quad (x,y)\in X\times Y\,.
\end{equation}
More precisely:
\begin{itemize}

\item[i)]  reversible rates $r^y(x,x')$ with respect to the prescribed measure $\mu_y(x)$ can be chosen;\\ 
\item[ii)] 
reversible rates $r_x(y,y')$ with respect to $\nu_x(y)$ can be chosen with respect to the measure $\nu_x(y)$ defined as
\begin{equation}
\nu_x(y) := \frac{1}{Z_x}\;\mu_y(x)\; \bar\mu(y)\;,\quad y\in Y
\end{equation}
where $Z_x:=\sum_{y'\in Y} \mu_{y'}(x)\,\bar\mu(y')$; \\ 
\item[iii)] the effective rates $\bar r$ defined by \eqref{eq:weff2} are reversible with respect to the prescribed measure $\bar \mu(y)$. 

As a consequence, the effective invariant measure
\begin{equation} 
\bar\pi\left(M_y\right) \,=\, \bar\mu(y)\;,\quad y\in Y\,.
\end{equation}
\end{itemize}

[Thm 3 of arXiv:2605.28776, 'Limiting distributions of triangle counts in linear preferential attachment models'] Let $m\ge2$ and $\delta>-m$ be fixed. Let $T_n$ be the number of triangles in $\pam(m,\delta)$. We have $$\var(T_{n})\cong s_{n}^{2}.$$ Moreover, there exists a constant $\gamma =\gamma (m,\delta)\in (0,\infty)$ such that the following holds.
 \begin{enumerate}[\upshape (i)]
 \item When $\delta>0$, we have 
 \begin{align*}
 \dwas\left(\frac{T_n-\E T_n}{\gamma {s_n}}, Z\right)\lesssim \frac{1}{\sqrt{\log n}},
 \end{align*}
 where $Z\sim \N(0,1)$.
 \item When $\delta=0$, we have 
 \begin{align*}
 \dwas\left(\frac{T_n-\E T_n}{\gamma {s_n}}, 
\sum_{i=1}^\infty b_{i}\left(\frac{\psi_i^2}{\norm{\psi_i}_2^2}\prod_{j=i+1}^\infty \frac{(1-\psi_j)^2}{\norm{1-\psi_j}_2^2}-1\right)\right)
\lesssim \frac{1}{\sqrt{\log n}}.
 \end{align*}
 \item When $\delta\in(-m,0)$, we have 
\begin{align*}
 \dwas\left(\frac{T_n}{\gamma  s_n}, 
\sum_{i=1}^\infty b_{i}\cdot \frac{\psi_i^2}{\norm{\psi_i}_2^2}\prod_{j=i+1}^\infty \frac{(1-\psi_j)^2}{\norm{1-\psi_j}_2^2}\right)
\lesssim \frac{1}{\sqrt{\log n}}.
\end{align*}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:convergence-test of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] A vector  $\vec\ell\in \mathbb{R}^s$ is of convergent type for the face $\cal F$ if and only if 
\begin{equation}
i +  \sum_{\substack {j \leq s \\[1pt] s(\vec v)_j\leq i}} \ell_j >0
\end{equation}
for all $\vec v\colon \{0,\dots,d\}\to \cal E$ spanning a subset of full dimension and all $1 \leq i \leq d$.

