body:
[Definition d:dir-space of arXiv:2602.05477, 'On the Resistance Conjecture'] We call $(X,d,\mu, \mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$  a regular local $p$-Dirichlet space when the following properties hold:
		\begin{enumerate}  
			\item \textbf{Locally compact}: $(X,d,\mu)$ is a locally compact metric space equipped with a Radon measure $\mu$.
			\item \textbf{Completeness:} 	The space $\mathcal{F}_p$  is a subspace of $L^p(X,\mu)$ and
			$\mathcal{E}_p: \mathcal{F}_p \to [0,\infty)$ is a non-negative function such that $\mathcal{F}_p$ is a Banach space when equipped with the norm $\norm{f}_{\mathcal{F}_p}=(\norm{f}_{L^p}^p+\mathcal{E}_p(f))^{1/p}$.
			\item \textbf{Homogeneity:} For every $f\in \mathcal{F}_p$ there exists a finite non-negative Borel measure $\Gamma_p \langle f \rangle$ on $X$ such that $\Gamma_p \langle f \rangle(X)= \mathcal{E}_p(f)$, and for all $\lambda \in \mathbb{R}$
			\[
			\Gamma_p\langle \lambda f\rangle = |\lambda|^p \Gamma_p\langle f\rangle.
			\]
			The measure $\Gamma_p\langle f \rangle$ associated to $f \in \mathcal{F}_p$ is called the \emph{energy measure of $f$}.
			\item \textbf{Triangle inequality:} For every $f,g\in \mathcal{F}_p$ and every Borel set $A\subset X$, 
			\begin{equation} 
				\Gamma_p\langle f+g\rangle(A)^{\frac{1}{p}}\le \Gamma_p\langle f\rangle(A)^{\frac{1}{p}}+\Gamma_p\langle g\rangle(A)^{\frac{1}{p}}
			\end{equation}
			\item \textbf{Lipschitz contractivity:} For all $f\in \mathcal{F}_p$, $g\in \Lip(\mathbb{R})$ with $g(0)=0$,  we have $g \circ f \in \mathcal{F}_p$ and
			\begin{equation} 
				d\Gamma_p\langle g\circ f\rangle \le \LIP[g]^p d\Gamma_p\langle f\rangle.
			\end{equation}
			\item \textbf{Strong locality:} For every $f\in \mathcal{F}_p$ and any open set $A\subset X$, if $f|_A=c$ $\mu$-a.e., then $\Gamma_p\langle f\rangle(A)=0$. 
			\item \textbf{Weak lower semicontinuity:} For every $f\in L^p(X)$, and any sequence of functions $(f_i)_{i \in \mathbb{N}}$ in $\mathcal{F}_p$ such that $f_i\to f \in L^p(X)$ with $\sup_{i\in \mathbb{N}} \mathcal{E}_p(f_i)<\infty$, then $f\in \mathcal{F}_p$ and
			\begin{equation} 
				\Gamma_p\langle f \rangle(A)\le \liminf_{i\to \infty} \Gamma_p\langle f_i \rangle(A)
			\end{equation}
			for every Borel set $A\subset X$. 
			\item \textbf{Regularity:} $C_c(X)\cap \cF_p$ is dense in $\cF_p$ in the norm $\norm{f}_{\mathcal{F}_p}$ and in $C_c(X)$ in the norm $\|f\|_\infty = \sup_{x\in X} |f(x)|.$
		\end{enumerate}

[Lemma 9 (Occupation bound) of arXiv:2605.09641, 'The Ballot Event for Two-Player Coupon Collection: A Renewal--Catalan Asymptotic'] Let $I=[a,b)\cap\mathbb Z$, with $s_0\le a<b\le d$.  The endpoints $a,b$ need not be integers.  Then
\begin{equation}
        \E_{s_0,g_0}\sum_{n<\tau}\Ind_{\{S_n\in I\}}
        \le
        2(b-a+1)\Prob_{s_0,g_0}(\tau_a<\tau).
\end{equation}

