[Proposition 6 of arXiv:2608.27093, 'Soliton Solutions to the Curvature Flow on the 2-dimensional De Sitter Space and Applicati'] Let $X: I \rightarrow \mathbb{S}^{2}_{1}$ be a spacelike or timelike curve parametrized by arc length $s$. Consider the vectors
	\begin{equation} 
		e_{1}=(-1,0,0),\hspace{0,3 cm} e_{2}=(-1,1,0), \hspace{0,3 cm} \text{e}\hspace{0,3 cm} e_{3}=(0,0,1).
	\end{equation}
	For each $i \in \{1,2,3\}$, define the functions 
	\begin{equation}	
		\alpha_{i}(s)=\langle X(s),e_{i}\rangle, \qquad \tau_{i}(s)=\langle T(s),e_{i}\rangle, \qquad  \eta_{i}(s)=\langle N(s),e_{i}\rangle,
	\end{equation}	
	where $T$ is the unit tangent vector with $\langle T(s), T(s)\rangle=\epsilon$ and $N$ is the normal vector field to $X$. For fixed $a>0$,
	\begin{equation*}
		k(s)=a\tau_{i}(s)=k_{i}(s)
	\end{equation*}
	is satisfied for all $s \in I$ if, and only if, the functions $\alpha_{i}(s)$, $\tau_{i}(s)$ and $\eta_{i}(s)$ satisfy the system
	\begin{equation}
		\left\{\begin{array}{lll}
			\alpha^{\prime}_{i}(s)=\tau_{i}(s),\\
			\tau^{\prime}_{i}(s)=-\epsilon \alpha_{i}(s)-\epsilon a\tau_i(s)\eta_{i}(s),\\
			\eta^{\prime}_{i}(s)=-\epsilon a\tau^{2}_{i}(s),
		\end{array}\right.
	\end{equation}
	such that 
	\begin{equation}
		\alpha^2_{i}(s)+\epsilon\tau^{2}_{i}(s)-\epsilon\eta^2_{i}(s)=
		\left\{\begin{array}{lll}
			-1, \hspace{.3 cm} \text{if} \hspace{.3 cm} i=1,\\
			0, \hspace{.3 cm} \text{if} \hspace{.3 cm} i=2,\\
			1, \hspace{.3 cm} \text{if} \hspace{.3 cm} i=3,
		\end{array}\right.
	\end{equation}
	for all $s \in I$. Moreover, $\eta^{\prime}_{i}(s)$ is a decreasing (respectively increasing ) function if $X$ is  a spacelike curve  (respectively timelike curve).

