[Theorem thm:stable_manifold of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Consider the equation in Theorem (SSRR of the paper), and assume that \(\varphi\) is the cocycle defined for this equation, restricted to \((E_{\omega})_{\omega \in \Omega}\). Furthermore, suppose that \(\{Y_\omega\}_{\omega \in \Omega}\) is a stationary point of this cocycle, and that the assumptions made in Theorem (ASXXZA of the paper) regarding \(A\), $\pi$ and \(G\) are also satisfied. Let \(\{\mu_j\}_{j \geq 1}\) be the Lyapunov exponents corresponding to the linear cocycle \(\psi^{1}_{\omega} := D_{Y_\omega}\varphi^{1}_{\omega}\), and define \(\mu^{-} := \max\{\mu_j : \mu_j < 0\}\).
			Then, there exists a \(\theta_r\)-invariant set of full measure \(\tilde{\Omega}\) and a family of immersed submanifolds \(S^{\upsilon}_{\text{loc}}(\omega)\) of \(E_\omega\), where \(0 < \upsilon < -\mu^{-} \) and \(\omega \in \tilde{\Omega}\), satisfying the following properties for every \(\omega \in \tilde{\Omega}\):
			\begin{itemize}
				\item[(i)] There exist random variables $\rho_{1}^{\upsilon}(\omega)$ and $\rho_{2}^{\upsilon}(\omega)$, which are positive and finite on $\tilde{\Omega}$, such that
				\begin{align}
					\liminf_{p \to \infty} \frac{1}{p} \log \rho_i^{\upsilon}(\theta_{pr} \omega) \geq 0, \quad i = 1,2,
				\end{align}
				and the following inclusions hold:
				\begin{align*}
					\big{\lbrace} \xi_\omega \in E_\omega \, :\, \sup_{m\geqslant 0}\exp(m\upsilon)&\Vert \varphi^{m}_{\omega}(\xi_\omega) - Y_{\theta_{mr}\omega}\Vert_{E_{\theta_{mr}\omega}} < \rho_{1}^{\upsilon}(\omega)\big{\rbrace} \subseteq S^{\upsilon}_{\text{loc}}(\omega)\\
					&\subseteq \big{\lbrace} \xi_\omega \in E_\omega \, :\, \sup_{m\geqslant 0}\exp(m\upsilon)\Vert \varphi^{m}_{\omega}(\xi_\omega) - Y_{\theta_{mr}\omega}\Vert_{E_{\theta_{mr}\omega}}<\rho_{2}^{\upsilon}({\omega})\big{\rbrace}.
				\end{align*}

				\item[(ii)] The tangent space at $Y_{\omega}$ satisfies
				\begin{align*}
					T_{Y_{\omega}}S^{\upsilon}_{\text{loc}}(\omega) = S_{\omega}:=F_{\mu^{-} }(\omega).
				\end{align*}

				\item[(iii)] For $m \geqslant M(\omega)$,
				\begin{align*}
					\varphi^{m}_{\omega}(S^{\upsilon}_{\text{loc}}(\omega)) \subseteq S^{\upsilon}_{\text{loc}}(\theta_{mr}\omega).
				\end{align*}

				\item[(iv)] For $0 < \upsilon_{1} \leqslant \upsilon_{2} < -\mu^{-} $,
				\begin{align*}
					S^{\upsilon_{2}}_{\text{loc}}(\omega) \subseteq S^{\upsilon_{1}}_{\text{loc}}(\omega).
				\end{align*}
				Additionally, for $m \geqslant M(\omega)$,
				\begin{align*}
					\varphi^{m}_{\omega}(S^{\upsilon_{1}}_{\text{loc}}(\omega)) \subseteq S^{\upsilon_{2}}_{\text{loc}}(\theta_{mr}(\omega)),
				\end{align*}
				and consequently, for $\xi_\omega \in S^{\upsilon}_{\text{loc}}(\omega)$,
				\begin{align}
					\limsup_{m\rightarrow\infty}\frac{1}{m}\log\Vert\varphi^{m}_{\omega}(\xi_\omega) - Y_{\theta_{mr}\omega}\Vert_{E_{\theta_{mr}\omega}} \leqslant \mu^{-} .
				\end{align}

				\item[(v)] The following holds:
				\begin{align*}
					\limsup_{m\rightarrow\infty} \frac{1}{m} \log\bigg{[}\sup\bigg{\lbrace}\frac{\Vert\varphi^{m}_{\omega}(\xi_\omega) - \varphi^{m}_{\omega}(\tilde{\xi_\omega}) \Vert_{E_{\theta_{mr}\omega}} }{\Vert \xi_\omega - \tilde{\xi_\omega} \Vert_{E_{\omega}}},\ \ \xi_\omega \neq\tilde{\xi}_\omega ,\ \xi,\tilde{\xi}_\omega \in S^{\upsilon}_{\text{loc}}(\omega)\bigg{\rbrace}\bigg{]} \leqslant \mu^{-} .
				\end{align*}
			\end{itemize}

