[Proposition 34 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Suppose that the functions $b,M$ are chosen as in Proposition~\ref{prop:tightness}. Let $(\xi_n)_{n \in \NN}$ be a sequence in $(0,\xi_c)$ such that $\xi_n \to \xi_c$ as $n \to \infty$. Then, the sequence of metrics $(\widetilde{D}_h^{\xi_n})_{n \in \NN}$ is tight with respect to the local uniform topology on $\CC \times \CC$. Moreover, if $(\xi_{k_n})_{n \in \NN}$ is a subsequence of $(\xi_n)_{n \in \NN}$ such that $(\widetilde{D}_h^{\xi_{k_n}})_{n \in \NN}$ converges in law (with respect to the local uniform topology on $\CC \times \CC$) to some random metric on $\CC \times \CC$, then we have that the following is true. There exists a $\xi_c$-LQG metric $h \mapsto \widetilde{D}_h$ and a subsequence $(\xi_{k'_n})_{n \in \NN}$ of $(\xi_{k_n})_{n \in \NN}$ such that
\begin{equation*}
    \widetilde{D}_h^{\xi_{k'_n}} \to \widetilde{D}_h \quad \text{in probability} \quad \text{as} \quad n \to \infty.
\end{equation*}

[Lemma lem : Topology/GMT/AreaFormula of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $\gamma : \intervalleff0T \rightarrow X$ be a Lipschitz, injective path. Then
	\begin{enumerate}[(i)]
		\item $\hd$-almost every point of $\gamma$ is regular.
		\item For all measurable function $\Phi : X \times \mathbb{R}^d  \rightarrow \mathbb{R}^+$ such that for all $z \in X$, $\Phi(z, \cdot)$ is absolutely homogeneous,
			\begin{equation}

				\int_0^T \Phi\mathopen{}\mathclose\bgroup\originalleft( \gamma(t), \gamma'(t)  \aftergroup\egroup\originalright)\mathrm{d} t
			=\int_\gamma \Phi\p{ z , \frac{\gamma'\p{\gamma^{-1}(z) } }{ \norme[2]{\gamma'\p{\gamma^{-1}(z)} } } } \hd(\mathrm{d} z).
	\end{equation}
	\end{enumerate}

