[Theorem 4 of arXiv:2511.23453, 'Convergence rates of self-repellent random walks, their local time and Event Chain Monte C'] If $Q=\Pi$, then the transition semigroup $(\hat P_t^{(\gamma)})_{t\geq 0}$ satisfies
    \begin{equation}
        \norm{\hat P_t^{(\gamma)}f}_{L^2(\hat\mu)} \leq e^{-\nu (t-T)}\norm{f}_{L^2(\hat\mu)}\qquad\text{for all }f\in L_0^2(\hat\mu)\text{ and }t\geq 0
    \end{equation}
    with $T\in O(n)$ and inverse convergence rate
    $$\nu^{-1}\in O\left(\gamma n^3+\gamma^{-1}n\right).$$ 
    In particular,
    for $\gamma\propto n^{-1}$, the $L^2$-relaxation time is of order $O(n^{2})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Stability of the infimal convolution) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] Let $V,W$ be standard weak transport problems such that $(C_V,W)$ satisfies \Cref{aspt:continuity} and \Cref{aspt:coercivity} for some $r \in [1,p]$. 
    Assume further that $C_{V\Box W}$ admits a $p$-growth bound.
    Let $(\mu_k)_k \subset \cP_p(\mathcal X)$ and $(\nu_k)_k \subset \cP_p(\mathcal Z)$ such that $\mu_k \to \mu$ in $\cP_p(\mathcal X)$ and $\nu_k \to \nu$ in $\cP_p(\mathcal Z)$. Then the following hold:
    \begin{enumerate}[label = (\roman*)]
        \item  We have $V \Box W(\mu_k,\nu_k) \to V\Box W(\mu,\nu)$. Moreover, any sequence of minimizers
        \begin{equation}
            \rho_k \in \argmin\left\{V(\mu_k,\rho) + W(\rho,\nu_k) : \rho \in \cP_p(\mathcal Y)\right\}
        \end{equation}
        is tight.

        \item  Suppose, in addition, that $W$ is $\Wcal_r$-stable. Then there exists a sequence $(\rho_k)_{k \in \N}$ satisfying \eqref{eq:thm.stability.1:VBoxW.attained}, and every such sequence is precompact in $(\cP_p(\mathcal{Y}),\Wcal_r)$. Moreover, all its limit points belong to 
        \begin{equation}
            \argmin\{V(\mu,\rho) + W(\rho,\nu) : \rho \in \cP_p(\mathcal Y) \}.
        \end{equation}
        In particular, if the minimizer in \eqref{eq:thm.stability.argmin} is unique for every $\mu \in \cP_p(\mathcal X)$, $\nu \in \cP_p(\mathcal Z)$, then the map
        \[
            (\mu,\nu) \longmapsto \rho^\circ \in \arg \min \{V(\mu,\rho) + W(\rho,\nu) :  \rho \in \cP_p(\mathcal Y)\},
        \]
        is continuous from $\cP_p(\mathcal X)\times\cP_p(\mathcal Z)$ to $(\cP_p(\mathcal{Y}),\Wcal_r)$.
    \end{enumerate}

[Lemma 19 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] The function $Q_T^\beta(x)$ satisfies the following bounds for $T,\beta>0$ and $x\in\R^3\setminus\{0\}$.
\begin{enumerate}[(i)]

\item $\displaystyle 1 + Q_T^\beta(x) \ge  \frac{\sqrt{T}}{|x| \sqrt{\pi}} e^{-\frac{|x|^2}{4T}} $

\item Fix $L>0$. There exists a constant $C_L>0$ such that for all $T, \beta>0$ with $\beta\sqrt T\le L$, and all $x\in\R^3\setminus\{0\}$,
\begin{align}
Q_T^\beta(x)
\;\le\;
C_L\Big(1+\frac{\sqrt T}{|x|}\Big)\,e^{-4\pi\beta|x|}\,.
\end{align}

\item Fix $L>0$. There exists a constant $C_L>0$ such that for all $T, \beta>0$ with $\beta\sqrt T\le L$, and all $x\in\R^3\setminus\{0\}$,
\begin{align} \nonumber
\big|\nabla Q_T^\beta(x)\big|
\,\le\,&
C_L\,
\bigg[
\frac{1}{|x|}
+\frac{1+\sqrt{T}}{|x|^2}
+\frac{1}{|x|\sqrt{T}}
\bigg]\,
e^{-4\pi\beta|x|} \,.
\end{align}
\end{enumerate}

