[Prop DiffBregDist of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] Assume that $F$ is twice differentiable on $U$ and that $P$ satisfies the  moment  assumption~(equation eq:Integrabilite of the paper), and assigns no weight to hyperplanes.

\medskip
\noindent $(a)$ {\em Case $r=2$}. Then $G_n$ is differentiable at every  $x\!\in U^n$ having pairwise distinct components and 
\begin{equation}
 \nabla G_n (x)= \left[\frac{\partial G_n}{\partial x_i}(x)\right]_{i=1,\ldots,n}={\rm Diag}\big(\nabla^2 F(x_i)\big)_{i=1,\ldots,n} \Big[\int_{C_i(x)}(x_i-\xi)P(\mathrm{d}\xi) \Big]_{i=1,\ldots,n}
\end{equation}
for any Bregman--Voronoi partition $(C_i(x))_{i=1,\ldots,n}$ of $U$ induced by $x$ where ${\rm Diag}\big(\nabla^2 F(x_i)\big)_{i=1,\ldots,n} $ denotes the $dn\times dn$ block diagonal matrix made up with the Hessians of $F$ at the points $x_i$. 

\medskip
\noindent $(b)$ {\em Case $r>2$}. Then $G^F_{r,n}$ is differentiable at every  $x\!\in U^n$ having pairwise distinct components and 
\begin{align}
\nonumber \nabla G^F_{r,n} (x)&= \left[\frac{\partial G^F_{r,n}}{\partial x_i}(x)\right]_{i=1,\ldots,n}\\
 &=\tfrac r2 \big({\rm Diag}\nabla^2 F(x_i)\big)_{i=1,\ldots,n} \left[\int_{C_i(x)}(x_i-\xi)\phi_{_F}(\xi,x_i)^{\frac r2-1}P(\mathrm{d}\xi) \right]_{i=1,\ldots,n}.
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: Gaussian Wasserstein-$p$ upper bound for M/M/1+M of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] Consider SSQ in heavily overloaded regime (ass:heavy_overload of the paper) and $\gamma\leq \gamma_0$, (equation eq: gamma assumption for SSQ W-p of the paper), the Wasserstein-$p$ distance, between law $\mathcal{L}(\tilde{q})$ and standard normal distribution $\mathcal{L}(Z):=\mathcal{N}(0,1)$ satisfies:

\begin{subnumcases}{\mathcal{W}_p(\mathcal{L}(\tilde{q}), \mathcal{L}(Z)) \leq}
    D_{1,\lambda,\mu} \cdot p\sqrt{\gamma} & $p \in [1, 1/\gamma^{1-2\alpha-2\epsilon}]$ \\
    D_{2,\lambda,\mu} \cdot \sqrt{p} & $p \in (1/\gamma^{1-2\alpha}, D_{4,\lambda,\mu}/\gamma)$ \\
    D_{3,\lambda,\mu} \cdot \frac{p\sqrt{ \gamma}}{\log(1+\gamma p/\lambda)} & $p \in [D_{4,\lambda,\mu}/\gamma, \infty)$ 
\end{subnumcases}
\begin{subnumcases}{\mathcal{W}_p(\mathcal{L}(\tilde{q}), \mathcal{L}(Z)) \geq}
    C'_{7, \lambda, \mu} \cdot \gamma \exp\left(-\frac{\lambda/\mu - \ln(\lambda/\mu) -1 }{p\gamma/\mu}\right) & $p \in [1, D_{5,\lambda,\mu}
    /\gamma)$ \\
    D_{4,\lambda,\mu}' \cdot \frac{p\sqrt{\gamma}}{\log(1+\gamma p/\lambda)} & $p \in [D_{5,\lambda,\mu}/\gamma, \infty)$
\end{subnumcases}

Where $\epsilon \in (0,1/2-\alpha)$ is any constants. All other constants involved are defined explicitly in (equation eq: constants for SSQ Wasserstein-$p$ bounds of the paper), (equation eq: Wasserstein-$p$ bound, first regime of the paper), (equation eq: Wasserstein-$p$ bound, second regime of the paper), (equation eq: Wasserstein-$p$ bound, third regime of the paper) and (equation eq: D_4, lambda, mu SSQ of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition stimeHolder of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (H0 of the paper), (H1 of the paper), (H2_0 of the paper), (H3_0 of the paper), let $t>0$ and $\vartheta\in(0,1)$.
Then for every $\gamma\geq-\delta$ there exists
    $(M_{\gamma,\delta, \vartheta})_{\gamma\geq-\delta}$
    such that
    for every $n\in\mathbb N_+$ and 
    $\varphi\in C_b^\vartheta(H_n)$ it holds that
\begin{align}
\|A_n^\gamma D(R_{n,t}\varphi)\|_{C^0_b(H_n;H_n)}&\leq M_{\gamma,\delta,\vartheta}\frac{1}{t^{(1-\vartheta)(\frac12+\gamma+\delta)+\vartheta\max\{0,\gamma\}}}
\|\varphi\|_{C^\vartheta_b(H_n)}\,,\\
\|A_n^\gamma D(R_{n,t}\varphi)\|_{C^\vartheta_b(H_n;H_n)}&\leq  M_{\gamma,\delta,\vartheta}
\frac{1}{t^{\frac12+\gamma+\delta}}
\|\varphi\|_{C^\vartheta_b(H_n)}\,,\\
\|D(A_n^{\gamma}D(R_{n,t}\varphi))
\|_{C^0_b(H_n;\mathscr{L}(H_n))}
&\leq M_{\gamma,\delta,\vartheta}
\frac{1}{t^{1-\frac{\vartheta}{2}+\gamma+\delta(2-\vartheta)}}\|\varphi\|_{C^\vartheta_b(H_n)}\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

