body:
[Lemma lem:bootstrap:IPS:v2 of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\Phi$ be an IPS on $\Sigma^{\mathbb{Z}^d}$ with dependence neighbourhood $0\in N\Subset\mathbb{Z}^d$ and suppose that $\Phi$ admits a stationary Bernoulli measure $\lambda=\lambda_q$.
	Then, for every $0<\varepsilon<\sfrac{1}{2}$, $\mu\in\mathscr{P}(\Sigma^{\mathbb{Z}^d})$, $A,B\Subset\mathbb{Z}^d$, and $t\geq 0$, we have
	\begin{equation}
		D_A(\mu\Phi^t\relto\lambda)\leq\dfrac{\sup_\nu D_B(\nu\Phi^t\relto\lambda)}{\ell\big(B:N_{\varepsilon,t}(A)\big)} + H(\varepsilon) + \varepsilon\abs{A}\log(\sfrac{1}{q_\mathsf{min}}) \;,
	\end{equation}
    where $N_{\varepsilon,t}(A)$ is as in Lemma~(lem:influence-growth of the paper) and $q_\mathsf{min}\coloneqq\min\{q(a): a\in\Sigma\}$.

[Theorem 11 (Fast regret of online truncated posterior) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under the same assumptions of \cref{thm:sequence-statistical}, the truncated posterior computed by  \cref{alg:spectral} satisfies
    \begin{equation}
    \fR\del[1]{(Q_t^{(m)})_{t=0}^{T-1}}
    \lesssim   T^{1/\zeta}+T^{(\zeta+1)/(2\zeta)}m^{(1-\zeta)/2}+Tm^{1-\zeta}. 
    \end{equation}
In particular, when $m\gtrsim T^{1/\zeta}$,
    \begin{equation}
    \fR\del[1]{(Q_t^{(m)})_{t=0}^{T-1}}
    \lesssim T^{1/\zeta}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 18 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] For each $\varepsilon>0$, there is a positive constant $c_\phi(\varepsilon)>0$, depending only on $m$ and $\varepsilon$, such that 
\begin{equation}
    \phi(s) \le \frac{1+\varepsilon}{m-1} s^m + c_\phi(\varepsilon)\,, \quad s\ge 0\,. 
\end{equation}
In addition,
\begin{equation}
    \phi(s)\ge \frac{s^m}{m-1} + 1 - \frac{m}{m-1} s\,, \quad s\ge 0\,. 
\end{equation}

