[Prop 13 of arXiv:2607.27932, '2607.27932'] For any $\xi,H>0$, there exists $T_\xi\in(0,\infty)$, depending only on $\U,\F, \Gamma$ and $\xi$ such that
\begin{equation*}
\lim_{\sigma\to0}\PP\left(\sup_{T_\xi\leq t\leq
\exp\left[\frac{2H}{\sigma^2}\right]}\|X_t-x_{T_\xi,t}^\sigma\|\geq\xi\right)=0=\lim_{\sigma\to0}\PP\left(\sup_{T_\xi\leq t\leq
\exp\left[\frac{2H}{\sigma^2}\right]}\|Y_t-y_{T_\xi,t}^\sigma\|\geq\xi\right)\,.
\end{equation*}

[Proposition 7 of arXiv:2505.16701, 'Open interacting particle systems and Ising measures'] For the local operators $\sigma^{\pm}_{k}$ the ground state transformation with the diagonal measure matrix 
\eqref{hmudef2} yields
\bea 
\hat{\mu}^{-1} \sigma_1^{\pm} \hat{\mu}  
& = & z_{-}^{\pm 1} \sigma_1^{\pm} y^{\pm \hat{n}_{2}} 
  \\

\hat{\mu}^{-1} \sigma_k^{\pm} \hat{\mu}  
& = & z^{\pm 1} \sigma_k^{\pm} y^{\pm(\hat{n}_{k-1}+\hat{n}_{k+1})}  , \quad 2 \leq k \leq L-1
 \\

\hat{\mu}^{-1} \sigma_L^{\pm} \hat{\mu}  
& = & z_{+}^{\pm 1} \sigma_L^{\pm} y^{\pm \hat{n}_{L-1}} 
 .

\eea (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma spacetimeaverage of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathfrak{q}_{\n_{1}}$} on the \abbr{RHS} of (equation eq:qnformI1 of the paper). We have the following (with notation to be explained afterwards):

\begin{align}
[\mathscr{S}^{N}\star(\mathfrak{q}_{\n_{1}}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}&=\sum_{\substack{{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\leq\mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{b}_{{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n_{1}}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\\
&+\sum_{\substack{{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\leq\mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{b}_{{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{T},\mathrm{av}}_{\mathfrak{t}_{\mathbf{Av}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{X},\mathfrak{q}_{\n_{1}}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\\
&+\mathrm{Err}_{1}[\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}]_{\x}.
\end{align}

\begin{itemize}
\item The parameter {\small$\mathrm{M}=\mathrm{O}(1)$} is a positive integer.
\item The coefficients {\small$\mathrm{b}_{{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}$} are deterministic and {\small$\mathrm{O}(1)$}.
\item The term {\small$\mathrm{Err}_{1}[\mathbf{R}^{N}\mathbf{S}^{N}]_{\t,\x}$} is a linear operator in {\small$\mathbf{S}^{N}$} evaluated at {\small$(\t,\x)$}, and for {\small$\mathrm{C}=\mathrm{O}(1)$} is large, we have

\begin{align}
|\mathrm{Err}_{1}[\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}]_{\x}|\lesssim N^{-\frac32}\cdot N^{-1+\delta_{\mathbf{S}}}\sum_{|\w|\lesssim N^{1-\delta_{\mathbf{S}}}}\Big(1+\sum_{|\z|\lesssim1}|\bphi_{\t,\x+\w+\z}|^{\mathrm{C}}\Big)\cdot|\mathbf{R}^{N}_{\t,\x+\w}|\cdot|\mathbf{S}^{N}_{\t,\x+\w}|.
\end{align}

\end{itemize}

[Theorem thm:E[sl] of arXiv:2604.05921, 'Simplicity of random hypergraphs'] Let $R(\cdot)$ be as in (equation def:B of the paper) and let $E^* = \{e \in E: \delta_e^{\textnormal{tail}} = \delta_e^{\textnormal{head}}\}$. We denote $\delta_e = \delta_e^{\textnormal{tail}}=\delta_e^{\textnormal{head}}$ for $e \in E^*$. Then, for a uniformly random directed hypergraph with degree sequence $\vb*{d}$,
    \begin{align}

         \mathds{E}[S_n] &= \sum_{e \in E^*} \frac{(n\mathds{E}[d_U^{\textnormal{in}}]-\delta_e)!(n\mathds{E}[d_U^{\textnormal{out}}]-\delta_e)!}{(n\mathds{E}[d_U^{\textnormal{in}}])!(n\mathds{E}[d_U^{\textnormal{out}}])!} \sum_{\substack{\vb*{a} \in \mathds{N}^{\delta_e}:\\\sum_{i=1}^{\delta_e} ia_i = \delta_e}}  \frac{\delta_e!^2}{\prod_{k=1}^{\delta_e} k!^{2a_k} } \sum_{\alpha(\cdot) \in R(\vb*{a})} (-1)^{\sum_{\vb*{x} \in \mathds{N}^{\delta_e}} (\sum_{i=1}^{\delta_e} x_i - 1)\alpha(\vb*{x})}\nonumber\\
     &\hspace{1cm}
    \times\prod_{\vb*{y} \in \mathds{N}^{\delta_e}} \Bigg( \frac{1}{\alpha(\vb*{y})!} \Big(\frac{n\mathds{E}\big[\prod_{i=1}^{\delta_e} (\mathds{1}_{\{d_U^{\textnormal{out}},d_U^{\textnormal{in}} \geq i\}}\frac{d_U^{\textnormal{out}}!}{(d_U^{\textnormal{out}}-i)!}\frac{d_U^{\textnormal{in}}!}{(d_U^{\textnormal{in}}-i)!})^{y_i} \big] \big(\sum_{i=1}^{\delta_e} y_i-1 \big)!}{\prod_{i=1}^{\delta_e} y_i!} \Big)^{\alpha(\vb*{y})} \Bigg).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2607.02777, 'Hypocoercivity for Hamiltonian Diffusions \\ with Singular Drift'] For $i=1,2$ and $n\in\mathbb{N}$ we have that $\chi_n(\phi_i)$, $\chi_n'(\phi_i)$, $\chi_n''(\phi_i)\in C_c^2(\Omega_i)$ and
		\begin{equation*}
			\chi_n(\phi_i) \to 1 \quad\text{and}\quad \chi_n'(\phi_i),\chi_n''(\phi_i) \to 0
		\end{equation*}
		pointwise on $\Omega_i$ as $n\to\infty$ and uniformly bounded by 1 respectively $C(\chi)$.

