[Proposition prop_upper_bound of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Assume (equation p_cont of the paper) and (equation p_lower of the paper).
\begin{enumerate}[label=\textup{(\alph*)}]

\item  \textup{(Typical convex chain)}
Let $\alpha$ be the constant from Theorem~(thm_uniform_known of the paper). Then
\eeq{ 
\limsup_{n\to\infty} \frac{\mathscr{L}_n}{n^{1/3}} \leqslant \frac{\alpha}{2}J_\star \quad \text{almost surely}.
}

\item  \textup{(Typical convex chains that are far from maximizers)}
For every $\varepsilon>0$, there exists $\theta>0$ such that
\eeq{ 
\limsup_{n\to\infty}\frac{\mathscr{L}_n^\mathsf{far}(\varepsilon)}{n^{1/3}} \leqslant \frac{\alpha}{2}(J_\star-\theta) \quad \text{almost surely}.
}

\item  \textup{(Full convex chain)}
We have
\eeq{ 
\limsup_{n\to\infty}\frac{1}{n}\log\Big[\frac{(3n)!}{n!}\mathbb{P}(\mathscr{L}_n=n)\Big] \leqslant \log\Big(\frac{27 J_\star^3}{4}\Big).
}

\item  \textup{(Full convex chains that are far from maximizers)}
For every $\varepsilon>0$, we have
\eeq{ 
\limsup_{n\to\infty}\frac{1}{n}\log\Big[\frac{(3n)!}{n!}\mathbb{P}\big(\mathscr{L}_n^\mathsf{far}(\varepsilon)=n\big)\Big] < \log\Big(\frac{27 J_\star^3}{4}\Big).
}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

