body:
[Proposition prop:L1contraction_new of arXiv:2512.18598, 'Long-time reverse transportation inequalities for non-globally-dissipative Langevin dynami'] Under Assumption (ass:farfield of the paper), consider the coupling structure (equation eq:coupling of the paper) with (equation eq:reflectednoise of the paper) replaced by (equation eq:reflectnoise1 of the paper). Fix any $a\in \mathbb{R}$ and $\delta \in (0,1)$. Choose
 \begin{equation}
    \eta_t = \textbf{1}_{\{t \in [\delta T, T]\}} 2\sqrt{|X_{\delta T}-X''_{\delta T}|}\frac{aL-\frac{L}{2}}{e^{(aL-\frac{L}{2})(T-\delta T)}-1}\,e^{aL(t-\delta T)}.
\end{equation} 
We take $\eta_t|_{a=\frac{1}{2}} = \lim_{\tilde{a}\rightarrow \frac{1}{2}}\eta_t|_{a=\tilde{a}}$. Then for any $x \neq x'$,
 \begin{enumerate}
\item For $t\in[0,\delta T]$,
\begin{equation}
    \mathbb{E}|X_t-X_t''| \leq C_1e^{-2\nu t}|x-x'|.
\end{equation}
The definitions of $C_1$ and $\nu$ above are the same as in Proposition (prop:L1contraction of the paper).
\item For $t \in [\delta T, T]$,
\begin{equation}
    |X_t - X_t''| \leq e^{L(t-\delta T)}|X_{\delta T}-X''_{\delta T}| \left(1 - \frac{e^{(aL-\frac{L}{2})(t-\delta T)}-1}{e^{(aL-\frac{L}{2})(T-\delta T)}-1}\right)^2\,\,a.s..
\end{equation}
Consequently, 
\begin{equation}
    X_T = X_T''\,\,a.s..
\end{equation}

 \end{enumerate}

