body:
[Lemma lem: probability to reach the fruit at a given time of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $(k, \boldsymbol{\ell},\boldsymbol{\rho}) \in {\ensuremath{\mathcal P}} $. There exist $C_1>0$ and $\varepsilon_1>0$ such that the following holds. Let $\varepsilon\in (0,\varepsilon_1)$. Let $(X_t)_{t\geq 0} = (X_t^{(\varepsilon)})_{t\geq 0} $ be the FIT Markov chain with parameters $(k, \boldsymbol{\ell},\boldsymbol{\rho}, \varepsilon)$. Denote its stationary distribution by $\pi_\varepsilon$. 
    \begin{enumerate}
        \item Let $1\leq i\leq k$ and $\ell_0+1 \leq j \leq \ell_0 + \ell_i-1$. We have
\begin{equation}
    {\ensuremath{\mathbb P}} _{y_j^i} (T_z = \ell_0 + \ell_i - j) \geq 1- C_1\varepsilon.
\end{equation}
In particular, ${\ensuremath{\mathbb P}} _{y_j^i} (T_z \geq \ell_0) \leq C_1\varepsilon$.
        \item Let $1\leq i\leq k$ and $0\leq j \leq \ell_0$. We have
\begin{equation}
    \rho_i(1-C_1\varepsilon) \leq {\ensuremath{\mathbb P}} _{x_j} (T_z = \ell_0 - j +\ell_i) \leq \rho_i(1+C_1\varepsilon).
\end{equation}
    \end{enumerate}

