body:
[Lemma lem:leaf_comonotonic_invariance of arXiv:2609.02659, 'Dimension Dependent Correlation Gap Bounds under Restricted Independence'] For any $\mathbf{x}\in\Delta^\star$, the numerator distribution induced by
$\Delta^\star$ is the comonotonic distribution associated with the
ordering $x_1\le x_2\le x_3\le x_4$, \emph{i.e.},\[
\mathbf{u}
=
(1-x_4)\mathbf{e}_{S_0}
+(x_4-x_3)\mathbf{e}_{S_1}
+(x_3-x_2)\mathbf{e}_{S_2}
+(x_2-x_1)\mathbf{e}_{S_3}
+x_1\mathbf{e}_{S_4}.
\] Moreover, the same numerator
distribution is induced by any sub-simplex containing $\mathbf{x}$
whose vertices are affine combinations of the vertices of
$\Delta^\star$.

[Proposition 9 (Pointwise empirical convergence to the target in $W_2$) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target} and either kernel assumption in Assumption~\ref{ass:ksd-kernel} or Assumption~\ref{ass:W2},
\begin{align}
    \E W_2^2(\mu_t^N,\pi)
    \le{}&
    \frac4\alpha e^{-2\varepsilon\alpha t}\KL(\mu_0\|\pi)
    +\frac{2C^\star}{\varepsilon\alpha^2N}
      \{1-e^{-2\varepsilon\alpha t}\}
    +2\E W_2^2\left(\frac1N\sum_{i=1}^N\delta_{Y_i},\pi\right).

\end{align}

[Lemma 19 (Clipped $\operatorname{ReLU-MLP}$) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $n, D, J_n \in \mathbb{N}_{+}$, and $\boldsymbol{\alpha} \in \mathbb{N}^{J_n \times D}$ with $|\boldsymbol{\alpha}|=\sum_{r=1}^{D}\sum_{j=1}^{J_n}\alpha_{j,r}=n$ (cf.~also Lemma \ref{lem:tensorized_Hermite_poly_approx_on_compact}). Then, for every $\varepsilon \in (0,1)$, positive constant $B>0$, there exists a $\operatorname{ReLU-MLP}$ $\Phi_{\boldsymbol{\alpha}, B, \varepsilon}:\mathbb{R}^{J_n \times D} \to \mathbb{R}$ satisfying:
\begin{itemize}
    \item \textbf{Effective uniform approximation:} $\sup_{\boldsymbol{z} \in[-B,B]^{J_n\times D}}\left| h_{\boldsymbol\alpha}(\boldsymbol{z})-\Phi_{\boldsymbol{\alpha}, B, \varepsilon}(\boldsymbol{z})\right| \le \varepsilon$.
    \item \textbf{Global growth:} $\left|\Phi_{\boldsymbol{\alpha}, B, \varepsilon}(\boldsymbol{z})\right| \le |h_{\boldsymbol\alpha}(\boldsymbol{z})|+1$, for every $\boldsymbol{z}\in\mathbb R^{J_n\times D}$.
\end{itemize}
Moreover, for fixed $B, J_n, D$ and $\boldsymbol{\alpha}$, the $\operatorname{ReLU-MLP}$ $\Phi_{\boldsymbol{\alpha}, B, \varepsilon}$ has $\operatorname{depth}(\Phi_{\boldsymbol{\alpha}, B, \varepsilon}) \in \mathcal{O}(\log_2(Q_n+1)\log(\varepsilon^{-1}))$, $\operatorname{width}(\Phi_{\boldsymbol{\alpha}, B, \varepsilon}) \in \mathcal{O}(Q_n + n)$, and $\operatorname{size}(\Phi_{\boldsymbol{\alpha}, B, \varepsilon}) \in \mathcal{O}((Q_n + n)\log_2(Q_n \vee 2)\log(\varepsilon^{-1}))$.

[Lemma 10 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3} and \eqref{PETNs-3.01} hold. Then, for every $\tau \in \mathbb{R}$ and $D = \{D(t), t \in \mathbb{R}\} \in \mathfrak{D}$, there exist ${T} := {T}(\tau, D) > 0$ and  $\epsilon_{0}\in (0,1)$ such that for all $\epsilon\in (0,\epsilon_{0})$ and $t \geq {T}$, the solution $v$ of \eqref{PEeq-2.15} satisfies
	\begin{align}
		&~~\mathbb{E}\left[|\partial_{z}{v}(\tau, \tau - t, \zeta)|^4\right] + \int_{\tau - t}^\tau e^{-\kappa(\tau - s)}\mathbb{E}\left[|\partial_{z}v(s, \tau - t, \zeta)|^2\|\partial_{z}v(s, \tau - t, \zeta)\|^2\right]{d}s\\ \notag
		&\leq \mathcal{R}_3 + \mathcal{R}_3\int_{-\infty}^\tau e^{-\kappa(\tau - s)}|\partial_{z}g(s)|^{4} {d}s,
	\end{align}

	where $\zeta\in L^4(\Omega,\mathscr F_{\tau-t};\mathcal H)$ with $\mathscr{L}(\zeta) \in D(\tau - t)$, and $\mathcal{R}_3$ is a positive constant independent of $\tau$, $\epsilon$ and $D$.

