[Lemma expansion-curvature-0 of arXiv:2609.00108, 'The double sphere solution in the liquid drop model'] Let $\Sigma_0^{\varepsilon, +,1}$ be the surface parametrized as in (equation defSigma0ve12 of the paper), with $P$ and $Q$ defined as in (equation defPQ of the paper). Let $h = h(r)$ be a $C^{2, \alpha}$-small normal perturbation of $\Sigma_0^{\varepsilon, +,1}$ as in (equation def-np of the paper). Then: for all $r \in (1,2)$ we have
		$$
		\begin{aligned}
			| {\mathcal Q}_{\Sigma_0^{\varepsilon, +,1}} [h] (r)
			| &\lesssim  (|h| + (r-1) |h'|^2 ) \, (r-1) \, (|h''| + |h'|) \\
			&+ |h|^2 + (r-1) |h'|^2 + (r-1) |h| |h'|;
		\end{aligned}
		$$
		for any $r \in [2, \varepsilon^{-\frac12})$ we have
		$$
		\begin{aligned}
			| {\mathcal Q}_{\Sigma_0^{\varepsilon, +,1}} [h] (r)| &\lesssim  ( \frac{|h|}{1+ r^2} + |h'|^2 )  \, ( |h''| + \frac{|h'|}{1+r} )\\
			&+ \frac{|h|^2}{1+ r^6} + \frac{|h'|^2}{1+ r^2} + \frac{|h| \, |h'|}{1+ r^3} ;
		\end{aligned}
		$$
		and any $r \in (\varepsilon^{-\frac12}, \varepsilon^{-1})$
		$$
		\begin{aligned}
			| {\mathcal Q}_{\Sigma_0^{\varepsilon, +,1}} [h] (r)| &\lesssim  (\varepsilon |h| + (1-\varepsilon^2 r^2)^2 |h'|^2) \, ( (1-\varepsilon^2 r^2) |h''| + \varepsilon^\frac12 (1-\varepsilon^2 r^2) |h'|)\\
			&+ \varepsilon^3 |h|^2 + \varepsilon (1-\varepsilon^2 r^2)^2 + \varepsilon^\frac{3}{2} (1-\varepsilon^2 r^2 ) |h| |h'|. 
		\end{aligned}
		$$
		Here ${\mathcal Q}_{\Sigma_0^{\varepsilon, +,1}}$ is the quadratic term obtained in Proposition (generalH of the paper) for the surface $\Sigma_0^{\varepsilon, +,1}$.
		We also recall that $R=\frac{1}{\varepsilon}$.

[Proposition 56 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\bfx = (X,\bbx) \in \scrc^{\alpha}([0,T],V)$ be a rough path for some index $\alpha \in (\frac{1}{3},\frac{1}{2})$, let $f_0 \in \Lip([0,T] \times W,W)$ and $f \in C_b^{2\alpha,2}([0,T] \times W, L(V,W))$ be mappings, and let $\xi \in W$ be arbitrary. Then there exists a constant $K > 0$, depending on $\xi$, $\alpha$, $T$, $\mathbf{X}$, $\| f_0 \|_{\Lip}$ and $\| f \|_{C_b^{2\alpha,2}}$, such that for every solution $(Y,Y') \in \scrd_X^{2\alpha}([0,T],W)$ to the RDE \eqref{RDE} with $Y_0 = \xi$ we have
\begin{align*}
| Y_t | \leq K \quad \text{for all $t \in [0,T]$.}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 125 (Derivatives of logarithmic density) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\angularcoeffinmuweightedspatialcartesian_i^A$ be the $3\times 2$ matrix from  \eqref{E:ANGULARCOEFFINMUWEIGHTEDCARTESIAN}. Then the following identities hold:
\begin{subequations}	
	\begin{align}
		\upmu \Transport \LogDensity & = - X_i \muX v^i - \upmu \angularcoeffinmuweightedspatialcartesian_i^A \Yvf{A} v^i,  \\
		\Lunit \LogDensity & = X_i \Lunit v^i - \angularcoeffinmuweightedspatialcartesian_i^A \Yvf{A} v^i  + \exp(-\LogDensity)\frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^i X_i \\
		\muX \LogDensity & = - X_i \muX v^i - \upmu X_i \Lunit v^i - \upmu  \exp(-\LogDensity)\frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^i X_i 
	\end{align}
Additionally, if $W$ is any $\ell_{t,u}$-tangent vectorfield, we have: 
\begin{align}
	W \LogDensity & = - X_i W v^i - W_i \Lunit v^i - \Speed^{-2}\exp(\LogDensity) X^i W^j \upepsilon_{ijk} \vortrenormalized^k - \exp(-\LogDensity)\frac{p_{;\Ent}}{\overline{\varrho}}W_i \GradEnt^i  
\end{align} 
\end{subequations}Consequently, for any $1\le N \le \Ntop$, we have: 
\begin{subequations}
	\begin{align}
		\left| \tander^{[1,N+1]} \LogDensity \right| & \lesssim \left| \tander^{[1,N+1]} \velocityarray\right| +  \left|\tander^{\le N} (\vortrenormalized,\GradEnt)\right| + \fundbootsmall \left| \tander^{[1,N]} \controlvars\right|   \\
		\left| \comdersmall^{[1,N+1];1} \LogDensity \right| & \lesssim \left| \comdersmall^{[1,N+1];1} \velocityarray\right| + \upmu \left| \tander^{[1,N+1]}\velocityarray\right| +  \left|\tander^{\le N} (\vortrenormalized,\GradEnt)\right| + \fundbootsmall \left| \tandersmall^{[1,N]} \badcontrolvars\right|   \\		
		\left| \comdersmall^{[1,N+1]; 2} \LogDensity \right| & \lesssim \left|\comdersmall^{[1,N+1]; 2}\velocityarray\right| + \upmu \left| \comdersmall^{[1,N+1];\le 1} \velocityarray\right| + \upmu  \left|\tander^{\le N} (\vortrenormalized,\GradEnt)\right| + \fundbootsmall \left|\comderdoublesmall^{[1,N];\le 1} \badcontrolvars\right|
	\end{align}
\end{subequations}

