[Lemm Lemma_YO of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] The following statements hold true.
\begin{align*}
\lim_{\delta{\rightarrow} 0}\norm{J_{\delta}(x)-x}_{\mathcal{K}}=0,\quad x\in {\rm Dom}(F).
\end{align*}
For every $0<\delta<|\zeta_F|^{-1}$ ($0<\delta<\infty$ if $\zeta_F=0$), the function $F_\delta-\zeta_F{\operatorname{I}}_{{\mathcal{K}}}$ is dissipative on ${\mathcal{K}}$. Moreover for every $0<\delta<|\zeta_F|^{-1}$ it holds
\begin{align}
{\left\|J_\delta(x)-x\right\|}_{\mathcal{K}}&\leq \delta\left(\|F(x)\|_K+\max\{0,\zeta_F\}\| x\|_{\mathcal{K}}\right),\qquad x\in {\rm Dom}(F);\\
\|F_{\delta}(x)\|_{\mathcal{K}}&\leq (1+\delta \max\{0,\zeta_F\})(\|F(x)\|_{\mathcal{K}}+2 \max\{0,\zeta_F\}{\left\|x\right\|}_{\mathcal{K}}),\qquad x\in {\rm Dom}(F);\\
{\left\|F_\delta(x)-F_\delta(y)\right\|}_K&\leq \left(2\delta^{-1}+ \max\{0,\zeta_F\}\right){\left\|x-y\right\|}_K,\qquad x,y\in{\mathcal{K}}.\\
{\left\|J_\delta(x)-J_\delta(y)\right\|}_{\mathcal{K}} &\leq {\left\|x-y\right\|}_K,\qquad x,y\in{\mathcal{K}}.
\end{align}
For every $x,y\in \mathcal{K}$ and $0<\delta,\tau<|\zeta_F|^{-1}$ we have
\begin{equation}
{\left\|J_\delta(x)-J_\tau(y)\right\|}_{\mathcal{K}}\leq \zeta_F{\left\|x-y\right\|}_{\mathcal{K}}+ (\delta+\tau)({\left\|F(y)\right\|}_{\mathcal{K}}+{\left\|F(x)\right\|}_{\mathcal{K}}+|\zeta_F|{\left\|y\right\|}_{\mathcal{K}}+|\zeta_F|{\left\|x\right\|}_{\mathcal{K}}).
\end{equation} 
If ${\mathcal{K}}$ is a Hilbert space, then for every $x,y\in {\rm Dom}(F)$ there exists $B:=B(\zeta_F)$ such that for every $\delta,\tau>0$ we have
\begin{equation}
\scal{F_{\delta}(x)-F_\tau(y)}{x-y}_{\mathcal{K}}\leq \zeta_F{\left\|x-y\right\|}_{\mathcal{K}}^2+(\delta+\tau)B({\left\|F(x)\right\|}_{\mathcal{K}}^2+{\left\|F(y)\right\|}_{\mathcal{K}}^2+{\left\|x\right\|}_{\mathcal{K}}^2+{\left\|y\right\|}_{\mathcal{K}}^2)
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop-4.1 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let~$\beta>0$ and assume that~$\{v_k'\}_{k=0}^n$ and~$\{v_k''\}_{k=0}^n$ are bounded uniformly in~$n\ge1$.
Then for all~$n\ge1$ and all $x,y\in\Lambda_n$,
\begin{equation}

\langle\phi_x\phi_y\rangle_{n,\beta}
=\sum_{i=k(x,y)}^n\biggl(\frac1\beta+\frac1{\beta^2}\frac{b+1}{b-1}\,E\bigl[v_{i}'(\phi_{i+1})^2-v_{i}''(\phi_{i+1})\bigr]\biggr) +O(1)
\end{equation}
holds with~$O(1)$ that is bounded uniformly in~$n\ge1$ and~$x,y\in\Lambda_n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2604.23572, '2604.23572'] The mean waiting time $\E\big[W_k^{\PR}\big]$ ($k \in \K$) of
class $k$ customers in the stationary preemptive-resume priority queue
satisfying Assumptions~\ref{assumption-1} to \ref{assumption-3}
is given by

\begin{align*}
\E\left[W_k^{\PR}\right]
&=
\frac{\ds\sum_{\ell \in \K_k^+}
\rho_{\ell} \E[\tilde{H}_{\ell}]}
{(1-\rho_k^+)(1-\rho_{k-1}^+)}
+ 
\frac{\ds\sum_{\ell \in \K_k^+} \rho_{\ell} (\rho_k^+ - \rho_{\ell})}
{2(1-\rho_k^+)(1-\rho_{k-1}^+)}
+
\frac{\rho_{k-1}^+}{1-\rho_{k-1}^+}
\\
&\qquad {}
+
\frac{\ds\sum_{\ell \in \K_k^+}
\rho_{\ell}
\left[
\pi_{\ell}^{({\on})} \rho_{\ell} \left( 1+\E[\tilde{C}_{\ell}] \right)
+
\E[H_{\ell}]
\left(
\E[\tilde{\Lambda}_{\ell}] - \pi_{\ell}^{({\on})} 
\frac{\E[C_{\ell} \Lambda_{\ell}]}{\E[C_{\ell}]}
\right)
\right]
}
{(1-\rho_k^+)(1-\rho_{k-1}^+)}
\\
& \qquad\quad {}
+
\frac{\E[H_k]}{1-\rho_{k-1}^+} \left(
\E[\tilde{\Lambda}_k] - \pi_k^{({\on})}
\frac{\E[C_k \Lambda_k ]}{\E[C_k]} \right)
\\
&\qquad\qquad {}
+
\pi_k^{({\on})}
\left[
\left( 1 + \frac{\rho_k}{1-\rho_{k-1}^+} \right)
\left( 1+\E[\tilde{C}_k] \right)
-
\frac{\E[\Lambda_k(\tilde{C}_k)]}{\lambda_k}
\right],
\quad
k \in \K,
\end{align*}

where $\rho_0^+=0$.

[Theorem 11 (\cite{VeraarWeisStochConv}) of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] Let $\mathcal B$ be a UMD space of type 2 and assume that $A$ has a bounded $H^\infty$-calculus of angle $< \frac{\pi}{2}$. Then, for any $G\in L^0_{\mathcal F}(\Omega;L^p( \mathbb R_+;\gamma(U,\mathcal B)))$, $P \diamond G$ has a continuous modification. Moreover, for all $p \in (0,\infty)$, 
\begin{equation} 
\norm{P \diamond G}_{L^p(\Omega;C(\mathbb R_+;\mathcal B))} \leq \const  \norm{G}_{L^p(\Omega;L^2( \mathbb R_+;\gamma(U,\mathcal B)))},
\end{equation}
where $C_{\themycounter}$ depends on $p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:MPinverse of arXiv:2605.01444, 'From second moments to pairwise negative correlation: \\applications to minimal and unifor'] For any real $m\times n$ matrix $A$, the Moore--Penrose inverse  $A^+$ is the unique $n\times m$ matrix satisfying the four conditions :
	\begin{enumerate}
		\item[(1)] $AA^+A=A$;
		\item[(2)] $A^+AA^+=A^+$;
		\item[(3)] $(AA^+)^{\mathsf T}=AA^+ $;
		\item[(4)] $(A^+A)^{\mathsf T}=A^+A$.
	\end{enumerate}
When $A$ is square and invertible, $A^+=A^{-1}$. In the singular or rectangular case, $A^+$ generalizes the inverse.

[Corollary 17 (First hitting time) of arXiv:2608.26834, 'Small-time annealed large deviations principle for one-dimensional diffusions in a random '] For every $\theta\in(0,1)$, there exist positive constants
		$C=C(\theta)$ and $N=N(\theta)$ such that, for every $R>0$,
		$x,y\in[-R,R]$, and $0<t\le1$, we have
		\begin{equation*}
			P_x^W(T_y \le t; \sup_{0\le s\le t}|X^W(s)| \le R)
			\le Ct^{-N}e^{CM_{R}}
			\exp\left\{-a_\theta\frac{d_W(x,y)^2}{t}\right\},
		\end{equation*}
		where $T_y:=\inf\{t\ge0:X^W(t)=y\}$.

