[Theorem 13 of arXiv:2609.00537, 'Explicit Exponential Sum Estimates and Approximate Functional Equations for the Zeta Funct'] \ 
    \begin{enumerate}
    \item[{\bf Part I.}] Let $f(x)$ be a real function with continuous, positive, and strictly decreasing derivative  $f'(x)$ in $[a,b]$. Let $g(x)$ be a real positive decreasing function with a continuous derivative $g'(x)$. Let $N$ be a non-negative integer with $N< f'(b)$, and define $\delta = 1 - (f'(a)-\lfloor f'(a) \rfloor)$, we have:
    \begin{equation}

        \sum_{a<n \leq b}g(x) e^{2\pi i f(n)} = 
    R_N(a,b) + \mathcal{O}^*\left(T_N(a,b)\right),
    \end{equation}
    where
\begin{align} 

R_N(a,b) =& \sum_{\nu =N}^{\lfloor f'(a) \rfloor} \int_{a}^{b} g(x)e^{2\pi i (f(x)-\nu x)} dx , 
\\
T_N(a,b) = & \frac{|g'(a)|+2\pi g(a) \left(f'(a)-N\right)}{2\pi^2 \left(f'(a)-N\right)} \bigg(\log(1+f'(a)-N)+\gamma +\log(1+\lfloor f'(a) \rfloor) - \frac{\Gamma'}{\Gamma}(\delta) 
\bigg. \nonumber
\\ \bigg.& -\frac1{2(1+\lfloor f'(a) \rfloor )}  -\frac{1}{2(1+f'(a)-N)}\bigg)  + \frac{g(b) |\tilde{S_1}(b,f'(a)-N)| + g(a) |\tilde{S_1}(a,f'(a)-N)|}{2\pi} \bigg. \nonumber
\\ \bigg.  &+ G(a,b) ,
\end{align}
and $G$ and $\tilde{S_1}$ are respectively defined in \eqref{bigO1} and Lemma \ref{lem:geometric}.

In particular, if $a,b\in\mathbb{Z}+\frac12$, the definition of $T_N(a,b)$ simplifies to
\begin{equation}
    \begin{aligned}
       T_N(a,b) =& \frac{|g'(a)|+2\pi g(a) \left(f'(a)-N\right)}{2\pi^2 \left(f'(a)-N\right)} \bigg(\log(1+f'(a)-N)+\gamma +\log(1+\lfloor f'(a) \rfloor) - \frac{\Gamma'}{\Gamma}(\delta) 
        \bigg. \\ \bigg.& -\frac1{2(1+\lfloor f'(a) \rfloor)}  -\frac{1}{2(1+f'(a)-N)}\bigg)  + \frac{ g(a)+g(b)  }{2\pi}  \left(\log 2 + \frac{1}{f'(a)-N} \right).    \end{aligned}
\end{equation}

\item[{\bf Part II.}] If, alongside the assumptions of Part I, we assume the functions $g$ and $f$ are in $C^2(a,b)$ and $|g'|$, $|f''|$, $g''$, and $|g'f'+gf''|$ are all positive and decreasing on $[a,b]$, then the definition of $T_N(a,b)$ simplifies to:
\begin{equation}
\begin{aligned}
  T_N(a, b) = &\frac{g(b) |\tilde{S}_1(b, f'(a)-N)| + g(a) |\tilde{S}_1(a, f'(a) -N)|}{2\pi}+G(a,b)  \\
    &+ \frac{H(b)\mathcal{B}_{f'}(b) + H(a)\mathcal{B}_{f'}(a)}{4\pi^2} 
    + \frac{H_1(a) \mathcal{E}_1 (\delta,f'(a))+ H(a)|f''(a)| \mathcal{E}_2(\delta,f'(a))}{4\pi^3f'(a)}, 
    \end{aligned}
\end{equation}
where $\gamma$ is Euler's constant, and the bounds $G$ and $\tilde{S_1}$ are respectively defined in \eqref{bigO1} and Lemma \ref{lem:geometric}. Here, $H, H_1, \mathcal{B}_{f'}, \mathcal{E}_1$, and $\mathcal{E}_2$ are respectively defined in \eqref{eq:defH(x)}, \eqref{eq:defH_1(x)}, \eqref{def-B},\eqref{auxilliary_error1}, and \eqref{auxillary_error2}.

In particular, if $a,b\in\mathbb{Z}+\frac12$
\eqref{def-TNab-partII} simplifies to
\begin{equation}
    \begin{split}
       T_N(a,b) =& \Big(\frac{\log 2}{2\pi} + \frac{1}{2\pi \left(f'(a)-N\right)}\Big) \left( g(b) + g(a) \right)  
        + \frac{H(b)}{4\pi^2} \mathcal{B}_{f'}(b) + \frac{H(a)}{4\pi^2} \mathcal{B}_{f'}(a) 
        \\& + \frac{H_1(a)}{4\pi^3f'(a)} \mathcal{E}_1(\delta,f'(a))+ \frac{H(a)|f''(a)|}{4\pi^3f'(a)} \mathcal{E}_2(\delta,f'(a)). 
\end{split} 
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:hwi of arXiv:2510.22778, 'Free denoising diffusion models'] For every $\mu$ with finite second moment and $\Phi^{*}(\mu)<\infty$,
\begin{equation}
  \mathcal{D}(\mu\Vert\gamma)\leW_{2}(\mu,\gamma)\sqrt{I(\mu\Vert\gamma)}
  -\tfrac12W_{2}(\mu,\gamma)^{2}.
\end{equation}
In particular (equation eq:hwi of the paper) implies (equation eq:lsi of the paper) by maximising the right-hand side
over $W_{2}$.

[Lemma 19 of arXiv:2608.29726, '\LARGE A Priori Estimates for Singular Fractional Stochastic Burgers Equations'] If \(a,b>0\),
\(a+b>\gamma+1\), then
\begin{subequations}
\begin{equation}
 \int_{\R\times\mathbb Z}
 \frac{\dd\zeta'}
 {\langle\zeta'\rangle_\gamma^a
  \langle\zeta-\zeta'\rangle_\gamma^b}
 \lesssim
 \langle\zeta\rangle_\gamma^{
 -\min\{a,b,a+b-(\gamma+1)\}+}.
\end{equation}
If \(a,b,c>0\) and \(a+b+c>\gamma+1\), then also
\begin{equation}
\begin{aligned}
 \int_{\R\times\mathbb Z}
 \frac{\dd\zeta}
 {\langle\zeta\rangle_\gamma^a
  \langle\zeta'-\zeta\rangle_\gamma^b
  \langle\zeta''-\zeta\rangle_\gamma^c} \lesssim
 \max\{\langle\zeta'\rangle_\gamma,
        \langle\zeta''\rangle_\gamma\}^{
 -\min\{a,b,c,a+b+c-(\gamma+1)\}+}.
\end{aligned}
\end{equation}
\end{subequations}

[Lemma 9 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Proposition~\ref{prop::multiannulu_pf_construction}. 
We denote by $\widehat{\mathsf{P}}=\widehat{\mathsf{P}}(\A_r; \ee^{\ii\bs{\alpha}}, \ee^{\ii\bs{\beta}})$ the measure $\Pind{n}^{(\kappa;\ell)}$ weighted by~\eqref{eqn::ac_RN}:
\begin{align} 
\frac{\prod_{j=1}^n\LFcro{1}^{(\kappa;\ell)}(r; \alpha_j, \beta_j)}{\LFcro{n}^{(\kappa;\ell)}(r; \bs{\alpha}, \bs{\beta})}\one_{\LE_{\emptyset}(\bs{\gamma})}\exp\left(\frac{\mathfrak{c}}{2}\blm(\A_r; \gamma^1, \ldots, \gamma^n)\right). 
\end{align}
We denote $\dot{\bs{\alpha}}_1=(\alpha_2, \ldots, \alpha_n)$ and $\dot{\bs{\beta}}_1=(\beta_n, \ldots, \beta_2)$. 
Then the law of $\bs{\gamma}=(\gamma^1, \ldots, \gamma^n)$ under $\widehat{\mathsf{P}}$ has the following characterization.
\begin{itemize}
\item The marginal law of $\gamma^1$ under $\widehat{\mathsf{P}}$ is the same as $\Pcro{1}^{(\kappa; \ell)}(\A_r; \ee^{\ii\alpha_1}, \ee^{\ii\beta_1-r})$ weighted by Radon-Nikodym derivative
\begin{align}
\frac{\LFcro{1}^{(\kappa;\ell)}(\A_r; \ee^{\ii\alpha_1}, \ee^{\ii\beta_1-r})}{\LFcro{n}^{(\kappa;\ell)}(\A_r; \ee^{\ii\bs{\alpha}}, \ee^{\ii\bs{\beta}-r})}\LZ_{\rainbow}^{(\kappa)}(\A_r\setminus\gamma^1; \ee^{\ii\dot{\bs{\alpha}}_1}, \ee^{\ii\dot{\bs{\beta}}_1-r}). 
\end{align} 
In particular, we have
\begin{align}
\LFcro{n}^{(\kappa; \ell)}(r; \bs{\alpha}, \bs{\beta})=\LFcro{1}^{(\kappa;\ell)}(r; \alpha_1, \beta_1)\Ecro{1}^{(\kappa;\ell)}\left[\LZ_{\rainbow}^{(\kappa)}(\A_r\setminus\gamma^1; \ee^{\ii\dot{\bs{\alpha}}_1}, \ee^{\ii\dot{\bs{\beta}}_1-r})\right]. 
\end{align}
\item The conditional law of $(\gamma^2, \ldots, \gamma^n)$ given $\gamma^1$ is rainbow $\SLE_{\kappa}$ in $(\A_r\setminus\gamma^1; \ee^{\ii\dot{\bs{\alpha}}_1}, \ee^{\ii\dot{\bs{\beta}}_1-r})$. 
\end{itemize}

