[Prop 22 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$ and let $m\geq 1$ be an order function on $\mc{T}_{\A{1},\A{2}}$. Let $p\in S(m,\A{1},\A{2})$ such that $p\geq 0$, $p+i$ is elliptic and admitting an asymptotic expansion $p\sim p_0+\Tilde{h}p_1+\dots$ in $S(m,\A{1},\A{2})$. Then, for all $\psi\in \mathscr{C}^{\infty}_c(\R)$, there exists
    \begin{equation}
        f\in S(1/m,\A{1},\A{2}) \m\m\m\m\m \text{such that}\m\m\m\m\m \psi(p_{N,\alpha_1,\A{2}})=f_{N,\alpha_1,\A{2}}

    \end{equation}
    satisfying
    \begin{equation}
        f\sim \sum_{\nu\in \N}\Tilde{h}^\nu f_\nu \m\m \text{in}\m\m S(1/m,\A{1},\A{2}) \m\m\m\m\m\text{where} \m\m\m\m\m f_\nu\in S(1/m,\A{1},\A{2}).

    \end{equation}
    In particular, we have that $f_0(x,\xi)=\psi\Bigl(p_0(x,\xi)\Bigl)$ and for all $\nu\geq 1$,
    \begin{equation}
        f_\nu(x,\xi)=\sum_{k=1}^{2\nu}g_k(x,\xi,\alpha)\psi^{(k)}\Bigl(p_0(x,\xi)\Bigl) \m\m\m\m\m\text{where} \m\m\m\m\m g_k\in S(1,\A{1},\A{2}).

    \end{equation}

[Theorem thm:hoeffding of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] Let $Z_1,\dots,Z_r$ be independent $\{0,1\}$-valued random variables satisfying $\mathbb{E} Z_i\geq 1/2$.
Then
\begin{equation}
 \mathbb{P}\!\left(\sum_{i=1}^r Z_i<\frac r3\right)
 \leq e^{-r/18}.
\end{equation}
Also,
\begin{equation}
 \mathbb{P}(Z_1=\cdots=Z_r=0)\leq 2^{-r}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Suppose $(N_n,d_n)$ is uniformly doubling with dimension $d$.
	Then
	for all $x \in N_n$ and all $0<r\le R$,
	\begin{align}
		\sup \Big\{
		|A| : A \subseteq B(x,R), \;
		d_n(i,j) \ge r \;\; \forall i \neq j \in A
		\Big\}
		\;\le\;
		2^{2d} \left(1+\frac{R}{r}\right)^d.
	\end{align}

