[Theorem 7 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] For all $p\geq2$, $r\geq 2$ an even integer and $q\in [1,\infty)$, the KLS conjecture, see Conjecture \ref{conj:KLS}, holds for $\mu$ uniform laws on $B_E(S_p^N)$ with $\F=\R, \C,\HH$, $N$ large enough (depending on $p,q,r$) and $f(X)=\mrm{Tr}(X^r)^q$ with constant $4$, \emph{i.e.\@}
	\begin{equation*}
			\Var_\mu f\leq 4\cdot\lambda_\mu \cdot \mathbb{E}_\mu \left[\|\nabla f\|^{2}_2\right].
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:mcG of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For any initial condition ${\tt u}\in\R^{\mcb{n}}$, we define the increasing function $\mathcal{G}_{\tt u}:\R_{\geqslant0}\rightarrow\R_{\geqslant0}$ by 
\begin{equs}
    \mathcal{G}_{\tt u}:t\mapsto  \big(1+t^{36}\big){\| V 
    \|}_{C^{9}(B_0(t+|{\tt u}|))}^6\,.
\end{equs}

[Lemma moyenne of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Let $\Theta$ be the contour defined by $\Theta := \{z \in {\mathbb R}_+^2\,:\, |z| = 1\}$ and $T_\Theta := \inf\{t\geq 0, Z_t \in \Theta\}$ the stopping time at $\Theta$. Then, for all $z_0 \in {\mathbb R}_+^2$ satisfying $|z_0| < 1$,
\begin{equation}
h_{\alpha_0}(z_0) = \int_{\Theta} h_{\alpha_0}(z) {\mathbb P}_{z_0}(Z_{T_{\Theta}} = dz).
\end{equation}

[Lemma 22 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let $S \in \Sym(\Hcal)$ be compact, with eigenvalues $\{\alpha_k\}_{k \in \Nbb}$
	and corresponding orthonormal eigenvectors $\{\phi_k\}_{k \in \Nbb}$. Then $\forall u \in \Hcal$,
	\begin{align}
		\la u, Su\ra = \sum_{k=1}^{\infty}\alpha_k \la u, \phi_k\ra^2.
	\end{align}

[Theorem thm:barbour of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Let $\Lambda \subseteq \Omega$ and $f : \Omega \to \mathbb{R}$ such that the following two conditions hold for some
positive numbers $V$ and $\Delta$, as well as some time $T \in \mathbb{N}$.
\begin{enumerate}[label=(\roman*)]
    \item

    A bound on a proxy for the variance of $f$: for all $x \in \Lambda$,
    \begin{equation}
        \sum_{x' \in \Omega} P(x,x') \sum_{t=0}^{T-1} \mleft(
            \mathbb{E}[f(X_t^x)] - \mathbb{E}[f(X_t^{x'})] \mright)^2 \leq V.
    \end{equation}
    \item

    A bound on the future expected difference, measured by $f$, between chains started at two adjacent initial states:
    for all $x \in \Lambda$, and $x' \in \Omega$ with $P(x,x') > 0$, and for all $t \geq 0$,
    \begin{equation}
        \mleft| \mathbb{E}[f(X_t^x)] - \mathbb{E}[f(X_t^{x'})] \mright| \leq \Delta.
    \end{equation}
\end{enumerate}
Then, for any $x \in \Lambda$, we have
\begin{equation}

    \mathbb{P} \mleft[
        X_t^x \in \Lambda \text{ for } 0 \leq t < T,
        \text{ and }
        |f(X_T^x) - \mathbb{E}[f(X_T^x)]| \geq \lambda
    \mright] \leq 2 \Exp{- \frac{\lambda^2}{2 V + \frac{4}{3} \Delta \lambda}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

