[Proposition prop:local_well_nonlinear of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $4\leq p<+\infty$ and $\theta$ satisfying (hyp_noise of the paper). Then for all $\omega_s\in L^0_{\mathcal{F}_s}\big(\Omega, B^{-\frac{2}{p}}_{g,2,p}\big),$ there exists a unique local p-solution $(\omega,\tau)$ of (equation main_ito of the paper) satisfying $\tau>s$ $\mathbb{P}-a.s.$ and
    \begin{align}
        \omega&\in H^{\theta,p}_{loc}\left([s,\tau);H_g^{-2\theta}\right)\quad \mathbb{P}-a.s. \quad  \text{for all } \theta\in [0,1/2)\\
        \omega&\in C\big([s,\tau);B^{-\frac{2}{p}}_{g,2,p}\big)\quad \mathbb{P}-a.s. 
    \end{align}
    Moreover, the solution $(\omega,\tau)$ instantaneously regularizes in
time and space:
\begin{align}

    \omega\in C^{\theta_0,\theta_1}_{{\rm loc}}\left((s,\tau)\times \mathbb{T}^3;\mathbb{R}^3\right) \quad \mathbb{P}-a.s. \quad \text{for all }\theta_0\in [0,1/2),\ \theta_1<+\infty.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 27 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] The graph $\mathfrak C(\mathbf i,\boldsymbol\kappa,\mathbf d)$ is balanced
at every non-root vertex if and only if, for every $j<n$ with $m_j>0$,
\begin{align}
 I_{j,k}(\boldsymbol\kappa)&\ge\kappa_{t_{j,k}}
 &&(1\le k<m_j),\\
 d_j+I_{j,m_j}(\boldsymbol\kappa)&\ge\kappa_{t_{j,m_j}}.

\end{align}
No condition is required when $m_j=0$, and no condition is required in
rank $n$.

[Lemma lem:shift_X of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that $\eta \in \Omega$.  For any $k, \ell \in {\mathbb{N}}$, $k > \ell$, $h \in {\mathbb{Z}}_{\ge 0}$ and $i \in {\mathbb{Z}}$, we have
                    \begin{align}
                        \xi_{\ell + h}\left(\eta, s_{k + h}\left(\eta, i\right)\right) 
                &= \xi_{\ell}\left(\Psi_{h}\left(\eta\right), s_{k}\left(\Psi_{h}\left(\eta\right), i\right) \right) \\
                &= s_{k - \ell}\left( \Psi_{\ell + h}\left(\eta\right), i \right) - s_{\infty}\left(\Psi_{\ell + h}\left(\eta\right), 0\right)  .
                    \end{align}
                In particular, if $s_{k + h}(\eta, i) = X^{(j)}_{k + h}(\eta,0)$ for some $j \in {\mathbb{Z}}$, then 
                    \begin{align}
                        s_{k - \ell}\left(\Psi_{\ell + h}\left(\eta\right), i \right) = X^{(j)}_{k-\ell}\left(\Psi_{\ell + h}\left(\eta\right),0\right) ,
                    \end{align}
                and thus
                    \begin{align}
                        \xi_{\ell + h}\left(\eta, X^{(j)}_{k + h}\left(\eta,0\right)\right) &= \xi_{\ell}\left(\Psi_{h}\left(\eta\right), X^{(j)}_{k}\left(\Psi_{h}\left(\eta\right),0\right) \right) \\
                        &= X^{(j)}_{k - \ell}\left( \Psi_{\ell+h}\left(\eta\right),0 \right) - s_{\infty}\left(\Psi_{\ell + h}\left(\eta\right), 0\right) \\
                        &= X^{(j)}_{k - \ell}\left( \Psi_{\ell+h}\left(\tilde{\eta}\right) ,0 \right) . 
                    \end{align}

