[Lemma discrete_integral_representation_of_E of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] With the above notation, we have
	\begin{equation}

		\mathscr{E}_{\mathbf{k}}(x,y\mid T,S,N,t\mid \vec z_*)
		=
		\operatorname{\mathrm{sgn}}(y-x)\sum\nolimits_{u=\min(x,y)}^{\max(x,y)-1}
		\mathscr{H}_{\mathbf{k}}(u,z_0\mid T,S,N,t),
	\end{equation}
	where
	\begin{equation}

		\begin{split}
			\mathscr{H}_{\mathbf{k}}(u,z_0\mid T,S,N,t)
			&\coloneqq
			\mathscr{W}_{\mathbf{k}}(u\mid T,S,N,t)
			+2\bigl[
				(z_0-S-t+u+\mathbf{k}+1)^-
				-(z_0-u-1)^-
				\\&\hspace{60pt}
				-(z_0-S-t+u+N+\mathbf{k})^-
				+
				(z_0-u+N-2)^-
			\bigr].
		\end{split}
	\end{equation}

