[Lemma lem:dissipativemomentbound of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Suppose Assumption (ass:dissipative of the paper) holds and $X$ solves (equation eq:main_d of the paper).
Then, for $q\geq  1$, we have 
\begin{equation*}
   \expect{\|X(t)\|^{2q}} \leq 
   \begin{cases}
   \|X_0\|^{2q}e^{-q\alpha_2t}+
   R_q,& \text{if}\ q>1;\\
   \|X_0\|^{2}e^{-2\alpha_2t}+
   R_{1},& \text{if}\ q=1,
   \end{cases}
\end{equation*}
for all $t\geq 0$, where 
\begin{equation*}
   R_q:=\begin{cases}
       \frac{1}{q e}\left(\frac{2\alpha_3}{\alpha_2}\right)^q\left(\frac{q-1}{q}\right)^{q-1},& \text{if}\ q>1;\\
       \frac{1}{e}\frac{\alpha_3}{\alpha_2},& \text{if}\ q=1.
   \end{cases}
\end{equation*}

[Proposition neq gamma/gamma+1 joint invariance of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with zero mean, unit variance innovation sequence $\{\xi_n\}$. Then:
    \begin{align*}
        \left(\overline{\boldsymbol{T}}_{n,\lfloor nt\rfloor}:t\geq 0\right)&\to_{\rm{w}} \left(\mathcal{\overline{W}}(t): t\geq 0\right) \quad \text{in $(D([0,\infty)),\mathcal{D})$,} \quad \text{for $p\in[0,\widehat{p})$},\\
        \left(\widetilde{\boldsymbol{T}}_{n,\lfloor nt\rfloor}: t\geq 0\right)&\to_{\rm{w}} \left(\widetilde{\mathcal{W}}(t): t\geq 0\right) \quad \text{in $(D([0,\infty)),\mathcal{D})$,} \quad \text{for $p=\widehat{p}$},\\
     \left(\boldsymbol{T}_{n,\lfloor nt\rfloor}: t\geq 0\right) &\to_{\rm{w}} \left(\mathcal{W}(t): t\geq 0\right) \quad \text{in $(D([0,\infty)),\mathcal{D})$,} \quad \text{for $p\in(\widehat{p},p_c)$},
    \end{align*}
    where $(\mathcal{\overline{W}}(t) :t\geq 0)$, $(\widetilde{\mathcal{W}}(t) :t\geq 0)$ and $(\mathcal{W}(t) :t\geq 0)$ are continuous $\mathbb{R}^2$ valued centered Gaussian processes, with the covariance kernels given by
    \begin{align*}
        \mathbb{E}(\mathcal{\overline{W}}(s)\mathcal{\overline{W}}(t))&=\boldsymbol{\overline{W}}(s), \quad \text{for } 0\leq s\leq t, \quad \text{when $p\in[0,\widehat{p})$},\\
    \mathbb{E}(\widetilde{\mathcal{W}}(s) \widetilde{\mathcal{W}}(t))&=\widetilde{\boldsymbol{W}}(s), \quad \text{for } 0\leq s\leq t, \quad \text{when $p=\widehat{p}$},\\
         \mathbb{E}(\mathcal{W}(s)\mathcal{W}(t))&=\boldsymbol{W}(s), \quad \text{for } 0\leq s\leq t, \quad \text{when $p\in(\widehat{p}, p_c)$}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition coupling_optimality_definition of arXiv:2509.23086, 'On Optimal Markovian Couplings of L\'evy Processes'] Let $\mu,\nu\in \mathcal{M}(\mathbb R^d)$ be a pair of bounded measures with equal mass: $\mu(\mathbb R^d)=\nu(\mathbb R^d)$. 

    (i) A \emph{coupling measure} is a (bounded) measure $\gamma\in\mathcal{M}(\mathbb R^{2d})$ such that it holds for all measurable $E\subset \mathbb R^{d}$
    \begin{align*}

        \gamma(E\times \mathbb R^d)=\mu(E),\qquad \gamma(\mathbb R^d\times E)=\nu(E). 
    \end{align*}
    Denote $\Gamma(\mu,\nu)$ \emph{the family of all coupling}. 

    (ii) The \emph{2-optimal transport cost between $\mu,\nu$} is defined by
    \begin{align*}
        \mathcal{C}_2(\mu,\nu):=\inf_{\gamma\in\Gamma(\mu,\nu)} \left\langle \gamma,c_2 \right\rangle=\inf_{\gamma\in\Gamma(\mu,\nu)} \int_{\mathbb R^{2d}}\frac 12 |x-y|^2 d\gamma(x,y).
    \end{align*}

    (iii) A \emph{2-optimal coupling} of the pair $\mu,\nu$ is a coupling measure $\gamma_*\in\Gamma(\mu,\nu)$ such that 
    \begin{align*}
        \left\langle \gamma_*,c_2 \right\rangle=\int_{\mathbb R^{2d}} \frac 12 |x-y|^2 d\gamma_*(x,y)&= \mathcal{C}_2(\mu,\nu). 
    \end{align*}

    (iv) A bounded measure $\gamma\in \mathcal{M}(\mathbb R^{2d})$ is \emph{2-optimal} if it is it is 2-optimal w.r.t. its marginal.

[Definition def:lift of arXiv:2607.24705, 'Derangetropy Operators'] For $f \in \mathcal{D}$ define
		$U_{f} : L^{2}(0,1) \to L^{2}(\mathbb{R})$ by
		\begin{equation}
			U_{f}\,g = (g\circ F)\,\sqrt{f}.

		\end{equation}

[Definition 5 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] [Two-parameter $\left(  \mathbf{X,Y}\right)  $-controlled paths] Let $\omega_\mathbf{X}$, $\omega_\mathbf{Y}$ be controls defined on $[a,b]$ and $[c,d]$ respectively. Let  $p$ and $q$
be in $[1,\infty)$ with $\kappa=\left\lfloor p\right\rfloor $ and
$\lambda=\left\lfloor q\right\rfloor $ and assume that $\mathbf{X} \in \Omega G_{p, \omega_{\mathbf{X}}}([a,b], V)$, $\mathbf{Y} \in \Omega G_{q, \omega_{\mathbf{Y}}}([c,d], W)$. Denote by $\boxtimes_{\mathrm{ext}}$ the external tensor product, and write
$\boxtimes$ for $\boxtimes_{\mathrm{ext}}$ in the sequel.
Let
\[
Z:\left[  a,b\right]  \times\left[  c,d\right]  \rightarrow\mathrm{Hom}\left(
T^{<\kappa}\left(  V\right)  \boxtimes_{\mathrm{ext}} T^{<\lambda}\left(  W\right)
,F\right)
\]
and suppose
\begin{align*}
R^{1}  & :\Delta_{\left[  a,b\right]  }\times\left[  c,d\right]
\rightarrow \mathrm{Hom}\left(  T^{<\kappa}\left(  V\right)  \boxtimes_{\mathrm{ext}}
T^{<\lambda}\left(  W\right)  ,F\right)  \text{ and }\\
R^{2}  & :\left[  a,b\right]  \times\Delta_{\left[  c,d\right]  }
\rightarrow \mathrm{Hom}\left(  T^{<\kappa}\left(  V\right)  \boxtimes_{\mathrm{ext}}
T^{<\lambda}\left(  W\right)  ,F\right)
\end{align*}
are defined respectively by the identities
\begin{align}
Z_{t,u}  & = Z_{s,u}\circ\left[  L_{\mathbf{X}_{s,t}^{<\kappa}}\boxtimes_{\mathrm{ext}}
\text{id}_{T^{<\lambda}\left(  W\right)  }\right]  +R_{s,t}^{1}\left(
u\right)  \text{ and}\nonumber\\
Z_{s,v}  & =Z_{s,u}\circ\left[  \text{id}_{T^{<\kappa}\left(  V\right)
}\boxtimes_{\mathrm{ext}} L_{\mathbf{Y}_{u,v}^{<\lambda}}\right]  +R_{u,v}^{2}\left(
s\right)  .
\end{align}
Then we say that $Z$ is a two-parameter $\left(  \mathbf{X,Y}\right)
$-controlled path if there exist finite constants $C_{1}$ and $C_{2}$ such
that for all $a\leq s\leq t\leq b$ and $c\leq u\leq v\leq d$ and any $\eta\in
T^{<\kappa}\left(  V\right)  $ and $\xi\in T^{<\lambda}\left(  W\right)  $ we
have
\begin{equation}
\left \| R_{s,t}^{1}\left(  u\right)  \left[  \eta_{j}\boxtimes_{\mathrm{ext}}
\xi \right]  \right \| \leq C_{1}\omega_{\mathbf{X}}\left(
s,t\right)  ^{\left(  \kappa-j\right)  /p}\left \| \eta_{j}
\right \| \| \xi \|
\text{, }
\end{equation}
for all $\eta_{j}\in V^{\otimes j}$, $j\in\lbrack0:\kappa)$ and if also
\[
\left\| R_{u,v}^{2}\left(  s\right)  \left[  \eta \boxtimes_{\mathrm{ext}}
\xi _{k}\right]  \right\| \leq C_{2}\omega_{\mathbf{Y}}\left(
u,v\right)  ^{\left(  \lambda-k\right)  /q} \left\| \eta \right\| \left\| \xi_{k}\right\|,
\]
for all $\xi_{k}\in W^{\otimes k}$, $k\in\lbrack0:\lambda).$

[Proposition prop: rand_series_ample of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Suppose that $E\to{\boldsymbol{T}}$ is a topological  metric vector bundle over the compact metric space ${\boldsymbol{T}}$. Let  ${\boldsymbol{X}}\subset C^0(E)$  be an ample  Banach space  of sections of $E$ embedded continuously  in $C^0(T)$. 

Suppose that $(u_n)_{n\in {{\mathbb N}}}$ is a sequence of sections  in ${\boldsymbol{X}}$ such that $\spa\big\{ u_n,\;\;n\in {{\mathbb N}}\,\big\}$ is dense in ${\boldsymbol{X}}$ and exists $\alpha>0$  such that
\begin{equation}
\Vert u_n\Vert_{{\boldsymbol{U}}}=O(n^\alpha)\;\;\mbox{as $n\to\infty$}.
\end{equation}
Fix a sequence of positive real numbers $(\lambda_n)_{n\geq 0}$ such that 
\begin{equation}
\liminf_{n\to \infty}\frac{\lambda_n}{n^\beta}>0, 
\end{equation}
for some  $\beta>0$.  Let $\mathfrak{a}\in \EuScript{S}({\mathbb R})$ be an even Schwartz  function such that $\mathfrak{a}(0)=1$. Fix a sequence of  $\mathrm{i.i.d.}$ standard normal random variables $(X_n)_{n\geq 0}$. Then the following hold.

\begin{enumerate}

\item For any $R >0$ the random series  
\begin{equation}
\sum_{n\in {{\mathbb N}}} \mathfrak{a}\big(\,  \lambda_n/R\,\big) X_n u_n
\end{equation}
converges  $\mathrm{a.s.}$ in ${\boldsymbol{X}}$. Denote by $\Phi^R$ the resulting continuous  Gaussian section  of $E$.

\item There exists $R_0$ such that $\forall R>R_0$ the  Gaussian section $\Phi^R$ is ample.

\end{enumerate}

