[Lemma 7 of arXiv:2605.15718, 'Mean-field derivation of a two-dimensional signal-dependent parabolic-elliptic Keller-Sege'] Let $T >0$. Under the assumptions \ref{ass_ks} it holds:
$\forall k \in [1,\infty) : \exists  C>0 : \forall i \in \N,  \varepsilon >0 : $
\begin{align*}
\ept \Big( \sup_{t\in [0,T] } | \bar{X}^\varepsilon_i - \hat{X}_i |^{2k}(t) \Big) \leq  C \varepsilon^{2k}.
\end{align*}

[Corollary 18 ({\cite[Corollary 4.14) of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] {savtoa}}]
		Let   $\alpha:\mathbb{R}\mapsto (0,1)$ be piece-wise constant taking values $0<\alpha_1<\alpha_2<\dots<\alpha_n<1$. Assume that $A=\{x\in\mathbb{R}:\alpha(x)=\alpha_1\}$ is a finite union of disjoint intervals such that $\mathpzc{l}({A})\in(0, +\infty)$ and $\min\{\lim_{x\to +\infty}\alpha(x);\lim_{x\to -\infty}\alpha(x)\}=\alpha_j$, for some $j\in\{2,\dots,n\}$. If $2\alpha_1<\alpha_j$ then 
		\begin{equation}
			\lim_{t\to +\infty}\mathds{P}^{(x,0)}({B(L(t))\in A})=1.
		\end{equation}
		Otherwise, if $2\alpha_1>\alpha_j$ and $A_j=\{x\in \mathbb{R}:\alpha(x)=\alpha_j\}$, then
		\begin{equation}
			\lim_{t\to +\infty}\mathds{P}^{(x,0)}({B(L(t))\in A_j})=1.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:asympvar improvement of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $P\in \mathcal{L}(\pi)$ be $\pi$-reversible. Let $G$ be a locally compact topological group with Haar measure $\mu$ that acts on $\mathcal{X}$, and assume that $\pi$ is $G$-invariant. Let $A:=-L$ for simplicity of presentation. We further assume that marginals of $\nu$ on both coordinates are the Harr measure $\mu$, that is, $g,h\sim\mu$ and $(g,h)\overset{D}{=}(h^{-1}, g^{-1})$ so that $P_{da}(G,\nu) \in \mathcal{L}(\pi)$ (recall Proposition (prop:inheritance of properties of the paper)). The following statements hold:
    \begin{enumerate}[label=(\roman*)]
        \item If $f\in V'$, 
        \begin{equation*}
            v(f, P_{da}(G,\nu)) = v(f, P)-2\left\|\mathbf{P}_{A^{-1/2}V^\perp}A^{-1/2}[f]\right\|_\pi^2,
        \end{equation*}
        and $v(f, P_{da}(G,\nu))=v(f, P)$ iff $f\in AV'\cap V'$, where $AV':=\{A\phi: \phi\in V'\}$.

        \item Assume further that $P$ is compact. The worst-case asymptotic variance of $P_{da}(G,\nu)$ is at least no larger than that of $P$, that is,
        \begin{equation*}
            \sup_{f\in L_0^2(\pi), \|f\|_\pi=1} v(f, P_{da}(G,\nu))=\frac{2-\lambda(P_{da}(G,\nu))}{\lambda(P_{da}(G,\nu))}\leq \frac{2-\lambda(P)}{\lambda(P)}=\sup_{f\in L_0^2(\pi), \|f\|_\pi=1} v(f, P).
        \end{equation*}
    \end{enumerate}

