[Definition redchain of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] We inductively define the map $C:{\mathcal T}_b\to \mathbb{N}$ by setting $C(\bullet)=1$ and
		\begin{align}
			C(\rho)=\sum_{\rho'\in{\mathcal R}^-(\rho)}C(\rho')\,,
		\end{align}
		where the set of binary trees ${\mathcal R}^-(\rho)$ has been introduced in Definition (Def: operations binary trees2 of the paper).

[Proposition of arXiv:2504.04860, 'Stochastic differential equations driven by fractional Brownian motion: dependence on the '] Let  $0 <a < b <1$, $1/2< 1-\alpha < a < H < b$ and
 		\begin{align*}
 			\widehat{B}_t^H := B_t^{1/2} + \int_{1/2}^H \partial_h B_t^{h} \,\mathrm{d} h, \qquad H \in [a,b], \quad t \in [0,T].
 		\end{align*}
 		Then 




 		for all $\omega \in \Omega$ the map \begin{center} $ [a,b] \ni H \mapsto \widehat{B}^H(\omega) \in W_2^{1-\alpha}([0,T];\mathbb{R})$ \end{center} is  Fr\'echet differentiable with derivative $\partial_H B^{H}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma grandes vitesses of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Let $s_0>0$ fixed, large enough. Then, the following uniform estimates, with respect to $\eta$,  hold: \smallskip

\noindent 1.  For all $\gamma \in (\frac{d}{2},\frac{d+1}{2}]$ and for $\nu \in (\gamma-\frac{d+1}{2},\gamma-\frac{d-1}{2})$,  one has
\begin{equation}
\left\| |s_1|^{\frac{1}{2}}|s|_\eta^{-\nu} (H_\eta - c_\eta m_\eta) \right\|_{L^2(\{|s_1| \leqslant s_0\})} + \big\| s_1 H_\eta \big\|_{L^2(\{|s_1| \geqslant s_0\})} \lesssim 1 ,
\end{equation}
2.  For all $\gamma \in (\frac{d+1}{2},\frac{d+4}{2})$,  one has 
\begin{equation}
\left\|\frac{H_\eta - c_\eta m_\eta}{|s|_\eta} \right\|_{L^2(\mathbb{R}^d)} + \big\| s_1 H_\eta \big\|_{L^2(\{|s_1| \geqslant s_0\})} \lesssim 1 .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition e:pnfi of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] {\rm 

\smallskip\noindent{\bf Principle of  no future information} (PNFI). 
Let $P_A$ be a probability on $(\Omega, {\mathcal F})$ which satisfies (PN).
$P_A$ satisfies (PNFI) if whenever $0 \le n \le M$, and 
$G \in \sigma( V_n, \dots , V_M, U)$, then
\begin{equation} 
  {P_A}(G | S=n) = {\mathbb P}(G).   
\end{equation}
}

