[Lemma lem:law_cont_pre of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] For each deterministic subset $S \subseteq \BR$ of Lebesgue measure zero, the subset
\begin{equation*}
\left\{r > 0 : \BP\!\left\lbrack D_{\Gamma_{V_r}}^{V_r}(T_r, B_r) \in S\right\rbrack > 0\right\}
\end{equation*}
has Lebesgue measure zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 (\textit{A priori} bounds) of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $p>1$. Let $K \subset \R$ be a compact set.
There exists $C>0$ such that, for any $N\geq 2$, $\alpha\in[0,1]$ and $q \geq 1$, the following holds.
\begin{enumerate}
	\item For any $f \in \cC^1(\R)$ with $\supp f \subset K$,
	\begin{equation*} 
		\E_\alpha\left[\abs{L_N(f)}^q\right]
		\leq \left( C\sqrt{q N \log N} \norme{f}_{\cC^1} \right)^q.
	\end{equation*}

	\item For any $f \in \cC^2(\R)$ with $\supp f \subset K$,
	\begin{equation*} 
		\E_\alpha\left[\abs{A_N(f)}^q\right]
		\leq \left( Cq N \log N \norme{f}_{\cC^2} \right)^q.
	\end{equation*}

\end{enumerate}

[Proposition prop:proper of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] \am{Following Johan's comments, I've put this result in (cor:cdtn-proper-zcoup of the paper).}

    \js{Perhaps merge this with (cor:cdtn_push_forward of the paper).}
    \am{Now that we have added other conditions like in (prop:existpropcoupfinite of the paper) or (prop:existpropcoup1D of the paper) that involve the mass given by $\mu$ to some sets too, I think it may be more clearer to keep (cor:cdtn_push_forward of the paper) as a separate result since it is of another nature (condition on the support of the zero-coupling $\gamma$).} 
    \textcolor{darkteal}{\small\sffamily\upshape [Johan: {Yes, agreed.}]}
    Let $\mu, \nu \in \mathrm{M}_{0}(\mathbb{R}^d)$ and suppose the following two properties hold:
    \begin{enumerate}[label=(\roman*)]
        \item $\forall y \in \operatorname{spt} \nu \setminus \left\{0\right\} : \exists x \in \operatorname{spt} \mu : \langle{x,y}\rangle > 0$;
        \item $\exists \alpha > 0 : \forall \lambda > 0 : \mu(\lambda \,\cdot\,) = \lambda^{-\alpha} \mu(\,\cdot\,)$.
    \end{enumerate}
    \js{This is a corollary to (prop:cdtn-proper-zcoup of the paper) I believe: conditions (i) and (ii) imply the condition in that proposition. Indeed, under (i), we can find a small ball centred at $x$ with positive mass, and, making the ball small enough, the ball is contained in $H_+(y,\epsilon)$ for some $\epsilon>0$. Shrinking the ball to zero (multiplying it by $\lambda>0$ with $\lambda\to0$), it remains within the cone $H_+(y,\epsilon)$ while its mass blows up to infinity, and thus $\mu(H_+(y,\epsilon))=\infty$.}
    If $\gamma \in \Gamma_{0}(\mu,\nu)$ has monotone support, then $\gamma$ is proper. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2608.29316, 'Powers of the Dirac Operator on $S^1\times S^{n-1}$'] The order $2k+1$ conformally covariant differential operator $A_{2k+1}$ on the spinor bundle over $M$,
\begin{equation*}
\begin{split}
&A_{2k+1}=\sqrt{-1}\a^0\cdot Z(2k+1)\\
&\quad=\sqrt{-1}\a^0\cdot\prod_{l=0}^{k}(-\sqrt{-1}\a^0\dc-k+2l)\cdot\prod_{m=0}^{k-1}(-\sqrt{-1}\dc\a^0-(k-1)+2m),
\end{split}
\end{equation*}
has the leading term $(-1)^k\cdot\dc^{2k+1}$. And the square of $A_{2k+1}$ acts as
\begin{equation*}
\prod_{l=-k}^k (f+J+l)(-f+J+l)\text{ on }V(f,j,\X,\e).
\end{equation*}

