[Definition 2 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $\mathfrak{F}\subset B(\X)$ be a family of measurable function.
    \begin{enumerate}[label=(\roman*)]
        \item $\Phi$ is \textit{asymptotically stable with respect to $\mathfrak{F}$} if it has a unique invariant measure $\mu\in\mathcal{P}(\X)$ such that $\mathfrak{F} \subset L^1(\mu)$ and for all $x\in\X$ and all $f\in\mathfrak{F}$,
        \begin{equation*}
        \lim\limits_{t\rightarrow\infty}\left|P_tf(x)-\langle f,\mu \rangle\right|=0.
        \end{equation*}

        \item $\Phi$ is \textit{mean ergodic with respect to $\mathfrak{F}$} if it has a unique invariant measure $\mu\in\mathcal{P}(\X)$ such that $\mathfrak{F} \subset L^1(\mu)$ and for all $x\in\X$ and all $f\in\mathfrak{F}$,
        \begin{equation*}
        \lim\limits_{t\rightarrow\infty}\left|Q_tf(x)-\langle f,\mu \rangle\right|=0.
        \end{equation*}

         \item $\Phi$ is \textit{uniformly asymptotically stable with respect to $\mathfrak{F}$} if it has a unique invariant measure $\mu\in\mathcal{P}(\X)$ such that $\mathfrak{F} \subset L^1(\mu)$ and for all $x\in\X$,
        \begin{equation*}
            \lim\limits_{t\rightarrow\infty}\sup_{f\in\mathfrak{F}}\left|P_tf(x)-\langle f,\mu \rangle\right|=0.
        \end{equation*}

         \item $\Phi$ is \textit{uniformly mean ergodic with respect to $\mathfrak{F}$} if it has a unique invariant measure $\mu\in\mathcal{P}(\X)$ such that $\mathfrak{F} \subset L^1(\mu)$ and for all $x\in\X$,
        \begin{equation*}
            \lim\limits_{t\rightarrow\infty}\sup_{f\in\mathfrak{F}}\left|Q_tf(x)-\langle f,\mu \rangle\right|=0.
        \end{equation*}
    \end{enumerate}

[Cor gradient-chessboard-estimate of arXiv:2609.01499, 'On the rigidity of sloped height functions in $d\ge 3$ \\ and non-crossing surfaces'] Let $R$ be a block of $\Lambda$, and for each $R$-local gradient function $f$ (i.e., function only of the gradients of $\phi$ on edges of $R\times \mathbb T_L^{d-2}$), define its chessboard seminorm as 
    \begin{align*}
        \|f\|_{R\vert \Lambda} = \mu_{L,\mathfrak{s}}^\nabla \Big( \prod_{\tau\in T_{\Lambda}^R} \tau f\Big)^{1/|T_\Lambda^R|}
    \end{align*}
    Then for $A \subset T_{\Lambda}^R$ and bounded $(f_\tau)_{\tau\in A}$ that are $R$ local, 
    \begin{align*}
                \mu_{L,\mathfrak{s}}^\nabla\Big(\prod_{\tau \in A} \tau f_\tau\Big) \le \prod_{\tau \in A} \|f_{\tau}\|_{R\vert \Lambda}\,.
    \end{align*}

