[Proposition USMR of arXiv:2605.28194, 'Delayed Blow-up in 3D Fluids via Pseudo-Transport Noise'] Fix $a\in [-1,0)$ and $p\in [2,\infty)$. Let $s,T,\tau$ be defined as above. Then there exists a unique solution to (equation Stokes-v of the paper) on $(s,\tau)$, which satisfies the following estimate: 
		\begin{itemize}
			\item[(1).] If $T<\infty$, then there exists $C_1=C_1(\nu,p,T-s)$ such that
			\begin{align*}
				&\mathbb{E}\bigg[ \sup_{t\in [s,\tau]}\|v^N(t)\|_{X_{tr}}^p\bigg] + \mathbb{E}\bigg[ \int_{s}^{\tau}\|v^N(t)\|_{X_{1}}^p\,{\,\rm d} t\bigg]\\
				&\leq C_1 \mathbb{E}\Big[\|v_s^N\|_{X_{tr}}^p\Big] + C_1\mathbb{E}\bigg[\int_{s}^{\tau}\Big(\|f(t)\|_{X_0}^p + \|g(t)\|_{L^p(\gamma(l^2;X_{1/2})}^p\Big)\,{\,\rm d} t\bigg].
			\end{align*}
			\item[(2).] If $v^N\in L^p(\Omega\times (s,\tau);X_{0})$, then there exists $C_2=C_2(\nu,p)$ such that
			\begin{align*}
				&\mathbb{E}\bigg[ \sup_{t\in [s,\tau]}\|v^N(t)\|_{X_{tr}}^p\bigg] + \mathbb{E}\bigg[ \int_{s}^{\tau}\|v^N(t)\|_{X_{1}}^p\,{\,\rm d} t\bigg]\\
				&\leq  C_1\mathbb{E}\bigg[\int_{s}^{\tau}\Big(\|f(t)\|_{X_0}^p + \|g(t)\|_{L^p(\gamma(l^2;X_{1/2})}^p\Big)\,{\,\rm d} t\bigg]\\ 
				&\quad+C_2 \mathbb{E}\Big[\|v_s^N\|_{X_{tr}}^p\Big] + C_2\mathbb{E}\bigg[ \int_{s}^{\tau}\|v^N(t)\|_{X_{0}}^p\,{\,\rm d} t\bigg].
			\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

