[Definition 6 of arXiv:2609.02147, '2609.02147'] Let $\lambda\geq 0$, $p>2$ and $H$ be a half-space.  We say that a solution $u$ of \eqref{eqneH}
	\begin{itemize}
		\item 
		is stable if
		\[
		Q_{\lambda,u}(\varphi) \coloneq \int_{\R^N} |\nabla \varphi|^2 + \lambda\varphi^2 - (p-1)\chi_{{H}}|u|^{p-2}\varphi^2 \,dx\ge 0 
		\quad \text{for all $\varphi \in C^1_0(\R^N)$};
		\]
		\item 
		is stable outside a compact set $K$ if $Q_{\lambda, u}(\varphi ) \ge 0$ for any $\varphi \in C_0^1(\R^N \setminus K)$;
		\item 
		has Morse index $m_{\lambda,H}(u)$ equal to $k$ if $k$ is 
		the maximal dimension of a subspace $W \subset C_0^1(\R^N)$ so that $Q_{\lambda,u}(\varphi)< 0$ for any $\varphi \in W \setminus \{0\}$.
	\end{itemize}

[Lemma 5 of arXiv:2609.03116, '\bf \boldmath On the reconstruction of $n$-quasigroups of order $4$ and upper bounds on th'] Let $n \geq 2$, and $(A,G'''_n,p)$ be a partial $n$-quasigroup. Then
\begin{enumerate}
\item if $(A,G'''_n,p)$ has more than one extension then all the extensions are cubical;
\item if $(A,G'''_n,p)$ has more than two extensions then it has a bicubical extension.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 1.2 of arXiv:2412.00708, 'Stochastic PDE approach to fluctuating interfaces'] We have
\begin{align}  
b_G^N(\eta,\varphi) & = \frac{K}{N^d} \sum_{p\in{\mathbb{T}}_N^d} 
\bar c_{p}(\eta)\varphi\left(\tfrac{p}N\right), \\

\Gamma_G^N(\eta,\varphi) & = \frac{K}{N^{2d}} \sum_{p\in{\mathbb{T}}_N^d} 
c_{p}(\eta) \varphi\left(\tfrac{p}N\right)^2.
\end{align}
where
\begin{align}  
\bar c_p(\eta) := c_p(\eta) (1-2\eta_p) = c_p(\eta) \Big(1_{\{\eta_p=0\}}
- 1_{\{\eta_p=1\}}\Big).
\end{align}

