body:
[Proposition prop:V-sb of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Recall that $\{V(t,x), t \ge 0, x \in \mathbb{R}^d\}$ and $\theta_2$ are defined in (equation e:de-V of the paper) and (equation e:theta12 of the paper), respectively.

\begin{enumerate}[(1)]
 \item (Small ball probability in time). Assume the conditions (equation e:DL of the paper) and (equation e:tilde-U-exist of the paper) hold. Assume additionally either $\beta+\gamma-2\le0$
 or \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
  Then, there exists a constant $C>0$ such that for every $x \in \mathbb{R}^d$,
  \begin{equation*}
    \mathbb{P}\bigg\{\sup_{t\in[0,1]}|V(t,x)-V(0,x)|\le\varepsilon \bigg\}\ge \exp\left(-\frac{C}{\varepsilon}\right) \text{ for all }\varepsilon>0.
  \end{equation*}
  \item (Small ball probability in space). Assume the conditions (equation e:DL of the paper) and (equation e:hat-U-exist of the paper) hold. For $\lambda=(\alpha-d+H)\wedge1$,
  there exists a constant $C>0$ depending on $t>0$ such that
  \begin{equation*}
    \mathbb{P}\bigg\{\sup_{x\in[-1,1]^d}|V(t,x)-V(t,0)|\le\varepsilon \bigg\}\ge \exp\left(-\frac{C}{\varepsilon^{d/\lambda}}\right) \ \text{ for all }\varepsilon>0.
  \end{equation*}
  \item  (Space-time joint small ball probability). Assume the condition (equation e:DL of the paper) and (equation e:U-exist of the paper). Assume additionally either $\beta+\gamma-2\le0$ or
  \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
    For $\lambda=(\alpha-d+H)\wedge1$, there exists a constant $C>0$ such that
  \begin{equation*}
    \mathbb{P}\bigg\{\sup_{(t,x)\in[0,1]\times[-1,1]^d}|V(t,x)|\le\varepsilon \bigg\}\ge \exp\left(-\frac{C}{\varepsilon^{1+d/\lambda}}\right)\ \text{ for all }\varepsilon>0.
  \end{equation*}
\end{enumerate}

