[Lemma lem:independence-across-disjoint-balls of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] For each $M>0$, $p,q \in (0,1)$, and $s>0$, there exists $n_* = n_*(M,p,q,s) \in \BN$ such that the following is true. Let $x_1,\ldots,x_n \in \partial \BD$ with $n \geq n_*$. Let $r>0$. Suppose that $|x_j - x_k| \geq 2(s+1) r$ for all distinct $j,k \in [1,n]_{\BZ}$. Let also $\Psi$ be a GFF on $\BD$ with boundary conditions given by a measurable function bounded by $M$. Let $E_1,\ldots,E_n$ be a family of events such that each $E_j$ is measurable with respect to the $\sigma$-algebra generated by $\Psi|_{B_r(x_j) \cap \BD}$. Suppose that $\BP[E_j] \geq p$ for all $j \in [1,n]_{\BZ}$. Then
	\begin{equation*}
		\BP\!\left\lbrack\bigcup_{j = 1}^n E_j\right\rbrack \ge q. 
\end{equation*}

[Prop main moment of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] Suppose that
\begin{equation}

k_n = O\left(n^{\frac{1}{30} - \epsilon}\right) \text{ for some $\epsilon>0$}.
\end{equation}
Then
\begin{equation}

\lim_{n \to \infty} \sum_{\underline{n} \in B(n,G)} E(\underline{n}) = 1. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm eq:B2_0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let $k_i > -\frac12$, $1 \le i \le d$. Then for $f$ being a polynomial of degree at most $n$ on ${\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}$, 
\begin{align}
 \sum_{1 \le i< j \le d_1} & \left \| \frac{1}{\sqrt{1-|\bm y|}}  D_{i,j}^{(\bm x)} f \right \|_{{\boldsymbol{\kappa}}}^2   + 
  \sum_{1\le i< j \le d_2} \left\| (\partial_{y_j} - \partial_{y_j}) f \right\|_{{\boldsymbol{\kappa}}} ^2 \\
    & + 
   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 
   \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2. \notag
\end{align}
Moreover, the inequality is sharp in the sense that the equality is attainable by some polynomial of degree $n$, and 
so are the next two inequalities,
\begin{align}
 \sum_{1 \le i< j \le d_1}  \left \| \frac{1}{\sqrt{1-|\bm y|}}  D_{i,j}^{(\bm x)} f \right \|_{{\boldsymbol{\kappa}}}^2   
    & +   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 \\
    & \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2, \notag
\end{align}
\begin{align}
  \sum_{1\le i< j \le d_2} \left\| (\partial_{y_j} - \partial_{y_j}) f \right\|_{{\boldsymbol{\kappa}}} ^2 & + 
   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 \\
  & \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2. \notag
\end{align}

[Lem 8 of arXiv:2608.27880, 'Precise universal edge asymptotics for planar $\beta=2$ Coulomb gases with radial external'] For  \(t\in\mathbb{R}\) fixed, set  $\widetilde{a}(t)=t_0 + \frac{\sqrt{\widetilde{\gamma}_n}}{\sqrt{\alpha n}}+\frac{t }{\sqrt{\alpha n\widetilde{\gamma}_n}}$ and 
\[
\widetilde{A}(t) = \{ z \in \mathbb{C} : |z| > \widetilde{a}(t)\}.
\]  
Define \[
\widetilde{J}_{k}(t) = \int_{\widetilde{A}(t)} \exp(-n V(|z|))  |z|^{2k} \, dz
\]  
for $0\le k\le n-1.$
Then, as \(n \to \infty\),  
\[
\widetilde{J}_{n-k}(t)\sim\frac{
  2\pi  t_0^{2n}e^{-nV(t_0)}
  \bigl(1+o((\log n)^{-1})\bigr)
}{
  \sqrt{\alpha n \widetilde{\gamma}_n}(\widetilde{a}(t))^{2k-1}
  (
    1+\frac{t}{\widetilde{\gamma}_n}
    +\frac{2k}{t_0\sqrt{\alpha n \widetilde{\gamma}_n}})
}
\exp(-\frac{\widetilde{\gamma}_n}{2}
  (1+\frac{t}{\widetilde{\gamma}_n})^2
  ).
\]
uniformly on $|t|\lesssim (\log n)^{1/4}$ and $1\le k\lesssim \sqrt{n\log n}.$

[Lemma 8 of arXiv:2607.12667, 'Phase Transition of Eigenvalues of Covariances from the Spiked Mixture Model in High-dimen'] Let $\X \in \mathbb{R}^{d\times n}$ have \ac{iid} Gaussian entries $\mathcal{N}(0,1)$. Partition the columns as $X = \begin{bmatrix}
    \X_1 & \X_2
\end{bmatrix}$, with $\X_1 \in \mathbb{R}^{d\times n_1}$, $\X_2 \in \mathbb{R}^{d\times (n-n_1)}$, and $n_1 \sim B(n,\pi_1)$ an independent random variable sampled from the Binomial distribution. Set
\begin{align*}
    \Sb_n &:= \frac{\X\X^\mathsf{T}}{n}, &&\R_n(z):= (z\I- \Sb_n)^{-1}, \text{and } &&\A_n(z) := \R_n(z)\frac{\X_1\X_1^\mathsf{T}}{n_1},
\end{align*}
where $z \in \mathbb{C}\setminus \{\lambda_1(\Sb_n), \ldots, \lambda_d(\Sb_n)\}$.

Assume $d,n \to \infty$ with $d/n \to \gamma \in (0, \infty)$. Then, 
\begin{align*}
    \frac{1}{d}Tr(\A_n(z)) \xrightarrow[]{\text{a.s.}} T(z),
\end{align*}
where $T(z) = \int_t \frac{t}{z-t} d\mu_{\text{MP}(\gamma)}(t)$ is the $T$-transform of the \acl{MP} law of parameter $\gamma$. 
Moreover, this convergence is uniform on $\mathcal{K}(\eta) = \{z\in \mathbb{C},\: d(z,[a,b])> \eta\}$ for all real scalars $\eta>0$.

