[Cor of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Assume that $D(\mathcal F_{\beta})\cap X^{a}_{p}\neq \emptyset$ and  let $\mathsf{P}_\beta\in X^{a}_{p}$ be the unique minimizer of $\mathcal F_{\beta}$ on $X^{a}_{p}$. Put $\Pi_\beta:= \mathsf{gap}(\mathsf{P}_\beta)$.
   Then for any $\mathsf{P}\in X^{a}_{p}\cap D(\mathcal F_{\beta})$
   \begin{align*}
       \frac{\beta }{2a^{\frac{2-p}{p}}} \mathscr W_{gap,p}^2( \mathsf{gap}(\mathsf{P}),\Pi_\beta)\leq \mathcal F_{\beta}(\mathsf{P})-\mathcal F_{\beta}(\mathsf{P}_\beta)\leq \frac{a^{\frac{2-p}{p}}}{2\beta } \abs{\partial \mathcal F_{\beta}}^2(\mathsf{P}).
    \end{align*}
    Moreover, any curve of maximal slope $(\mathsf{P}_t)_{t>0}$ w.r.t. $\abs{\partial \mathcal F_{\beta}}$ in $X^{a}_{p}$ satisfies for every $t\geq t_0>0$
    \begin{align*}
        \frac{\beta }{2a^{\frac{2-p}{p}}}\mathscr W_{gap,p}^2( \mathsf{gap}(\mathsf{P}_t),\Pi_\beta)\leq \mathcal F_{\beta}(\mathsf{P}_t)-\mathcal F_{\beta}(\mathsf{P}_\beta)\leq (\mathcal F_{\beta}(\mathsf{P}_{t_0})-\mathcal F_{\beta}(\mathsf{P}_\beta))e^{-2\beta a^{\frac{p-2}{p}}(t-t_0)}.
    \end{align*}
Moreover, for $0<\beta<\beta'$ 
\begin{align*}
       \mathscr W_{gap,p}^2(\Pi_{\beta},\Pi_{\beta'})\leq \frac{2(\beta'-\beta)}{\beta}\max\left(\int f( \mathsf{s}_0)^{\frac{p}{p-2}}\Pi_\beta(d \mathsf{s}) ,\int f( \mathsf{s}_0)^{\frac{p}{p-2}}\Pi_{\beta'}(d \mathsf{s}) \right)^{\frac{2-p}{p}}\mathcal W^{int}(\mathsf{P}_{\beta})
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:single-concentration of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds,   $\Exp ( X^2) < \infty$, and $\Exp X =0$. There exists $\varepsilon_0 \in (0,1)$ such that the following holds. 
Take $\varepsilon \in (0,\varepsilon_0)$, and let $u_\varepsilon > 1$ be as given in Lemma~(lem:t_visit_good_prob of the paper).
Then, for every $u \in (1, u_\varepsilon)$ and every $s > u$,
there exist $c>0$ (depending on $\varepsilon$) and $x_0 >0$ such that, for all $x>x_0$, 
with $k_x: = \lceil (2 + 7\varepsilon) (s-1)x \rceil$, 
\begin{equation}

    \max_{t \in {\mathbb Z} \cap [ x,ux]} \Pr\left(K^+_{\sigma_x,k_x}(t,x,s)<(s-1)x\right)  \leq {\mathrm{e}}^{-c(s-1)x},
    \end{equation}
    and 
    \begin{equation}
        \max_{t \in {\mathbb Z} \cap [ x,ux]} \Pr \left( K^-_{\sigma_x,k_x}(-t,x,s)< (s-1)x\right)\leq {\mathrm{e}}^{-c(s-1)x}. 
    \end{equation}

[Theorem HKUB of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Given a metric measure space $(M, d, \mu)$ such that there exist some $c>0, \alpha>0$ such that  $c^{-1}r^\alpha \le \mu(B(x,r))\le cr^\alpha$ for all $x\in M$ and $r>0$. Let $X$ be a stochastically complete diffusion on $M$ such that the heat kernel of $X$ is continuous and satisfies the on-diagonal estimate
$$
p(t,x,x)\le C t^{-\alpha/\beta}, \quad \text{for all }x\in M, \, t>0.
$$
Let $B(x, r)$ denote a metric ball of radius $r$ centered at $x \in M$. The following three conditions are equivalent:
\begin{enumerate}[(a)]
\item The off-diagonal sub-Gaussian-type heat kernel estimate
\begin{equation}
p(t,x,y)\le \frac{C}{t^{\alpha/\beta}}\exp\left\{-C\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta /(\beta -1)}\right\},\quad \text{for all }t>0, \, x\in M;
\end{equation}
\item 
$$
{\mathbb{E}}^x\left[\tau_{B(x,r)}\right]\simeq r^\alpha, \quad \text{for all }x\in M,\, r>0;
$$
\item The tail estimate of the exit time:
\begin{equation}
{\mathbb{P}}^x\left[\tau_{B(x,r)}\le t\right] \le C\exp\left\{-C\left(\frac{r}{t^{1/\beta}}\right)^{\beta /(\beta -1)}\right\},\quad \text{for all }t>0, \,r>0
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.03961, 'On the exponential sum over squarefree integers'] Let $N\ge2$, let $\alpha\in\R$, and let $a\in\Z$ and $q\in\N$ satisfy
\begin{equation}
  (a,q)=1,\qquad \bigg|\alpha-\frac aq\bigg|\le\frac1{q^2}.
\end{equation}
Then
\begin{equation}
  |S(\alpha)|\ll\left(\frac Nq+q\right)(\log 2N)^{5},
\end{equation}
where the implied constant is absolute. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 32 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] For any \( \varphi \in C_c^\infty(\{ u \in \mathfrak{g}^{(l)} : \|u\|_{\mathrm{HS}} < r \}) \), one has
\begin{equation*}
\int_{\mathfrak{g}^{(l)}} \varphi(u)\, du = \int_{\mathbb{R}^N} dy \int_{M_{x,y}} K(v,x)\varphi(v)\, m_{x,y}(dv),
\end{equation*}
where the kernel \( K \) is given by
\begin{equation}
K(v,x) = \left( \det(JF_l(v,x) \cdot JF_l(v,x)^*) \right)^{-1/2},
\end{equation}
$JF_l(v,x):\mathfrak{g}^{(l)}\to \mathbb{R}^N$ is the Jacobian of $F_l(\cdot,x)$ at $v\in\mathfrak{g}^{(l)}$ and we define \( m_{x,y} = 0 \) if \( M_{x,y} = \emptyset \). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:stoZeta of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix $\omega$ supported on $[-1,2]$ and equal to one on $[0,1]$. There exists a smooth function of polynomial growth $P:\R_{\geqslant0}^2\rightarrow\R_{\geqslant0}$ such that for every $\eta>0$ we have
\begin{equs}
{\talloblong \zeta \talloblong}_{6}\lesssim P\Big({\talloblong \omega\xi \talloblong}_{4}
,\sup_{{\eps,\mu}\in(0,1]}\mu^{2-2H+\eta}\norm{Q_\mu(\1_{\geqslant0}\xi_\eps)}_{L^\infty([0,1])}\Big)<\infty
\,.
\end{equs}
Moreover, there are limiting objects $(\zeta^\tau_{0,\mu})^{\tau\in\mathcal{T}}_{\mu\in(0,1]}$ such that $\zeta^\tau_{\eps,\mu}\rightarrow\zeta^\tau_{0,\mu}$ as $\eps\downarrow0$ in the topology induced by the above norm.

Finally, note that the estimate (equation eq:boundZeta of the paper) combined with (equation eq:boundXi of the paper) implies moment bounds on the non-stationary force coefficients. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:IntroDK of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] In the setting of Assumptions~(ass:IntroSetting of the paper) and~(ass:QPPIntro of the paper), suppose further that~$\mssW$ is a diffusion with generator~$\mssL$.
Then,~$\mu_\bullet$ is the unique analytically weak martingale solution to the \textsc{spde}
\begin{equation}
\mathop{}\!\mathrm{d} \mu_t = \mathsf{div}(\sqrt{\mu_t }\, \xi)+\sum_{x\in \mu_t} \mssL'\delta_x \mathop{}\!\mathrm{d} t\,\mathrm{.}
\end{equation}
Furthermore, if~$\mu_0=\tfrac{1}{n}\sum_{i=1}^n \delta_{x_i}$, then~$\mu_t= \tfrac{1}{n}\sum_i^n \delta_{X^i_{n t}}$ for all~$t>0$ and $\left(x_i\right)_{i\leq n}\subset M$, and~$\mu_\bullet$ is the unique analytically weak martingale solution to the \emph{$\mssL$-driven Dean--Kawasaki equation} on~$M$
\[
\mathop{}\!\mathrm{d}\mu_t = \mathsf{div}(\sqrt{\mu_t}\, \xi) + n\,\mssL' \mu_t \mathop{}\!\mathrm{d} t\,\mathrm{.}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:B1part of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For  any $0<\kappa<\frac{d-2}{2}$, we have
     \[\lim_{R\to\infty}
     \sum_{n=2}^{\infty}
     \kappa^{2n} c_d^n\mathcal{J}^{(n)}(R)=0.
     \]

