[Lemma 28 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let \cref{ass:gaussian-stable-selected} hold, i.e. $q_N\to q_0$. There are
  an integer $s_\ast$, a compact interval $I_\ast\Subset(0,1)$, constants
  $\delta_\ast>0$ and $\kappa<1$, and $N_0<\infty$ such that, for all
  $N\geq N_0$,
  \begin{equation}
    q_{t,N}\in I_\ast\quad\mbox{for every }t\geq s_\ast,
    \qquad
    \inf_{t\geq s_\ast}
    \operatorname{dist}(q_{t,N},\partial I_\ast)
    \geq
    \delta_\ast,
  \end{equation}
  and
  \begin{equation}
    \sup_{q\in I_\ast}\abs{V_A'(q)}\leq\kappa.
  \end{equation}

[Corollary 45 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Assume the regenerative hypotheses of Section~5 and let $k_t\in\N^d$ satisfy $|k_t-t\lambda|_1=o(t)$ for some $\lambda\in\Delta_d$. Then

\begin{equation*}
\frac{\mathcal R_c(k_t)}{t}\xrightarrow[t\to\infty]{} a_c\kappa(\lambda)=\overline c\rho_\lambda
\end{equation*}

in probability, and almost surely under the regenerative construction. If, in addition, $|k_t-t\lambda|_1=o(\sqrt t)$ and the second-moment assumptions of the central limit theorem in Section 5 hold, let $W=(W_Y,W_L,W_R)$ be the Brownian motion associated with the cycle vector $(Y_1,L_1,R_1(c))$ and put $I=\mathcal I(\lambda)$. Then

\begin{equation*}
\frac{\mathcal R_c(k_t)-a_c\kappa(\lambda)t}{\sqrt t}
\xrightarrow[t\to\infty]{d}
W_R(\kappa(\lambda))+
a_c\min_{r\in I}\left\{-\frac{W_{Y,r}(\kappa(\lambda))}{m_r}\right\}.
\end{equation*}

Moreover,

\begin{equation*}
\frac{\mathcal R_c(k_t)-\overline c N(k_t)}{\sqrt t}
\xrightarrow[t\to\infty]{d}
\Normal\left(0,\kappa(\lambda)\Vv_{\mathfrak a}\left[R_1(c)-\overline cL_1\right]\right).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:spectral-entropy of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] The \emph{spectral entropy} of the relaxation trajectory at step $k$ is
\begin{equation}
S_{\mathrm{spec}}(k) := -\sum_{i=2}^n p_i(k) \log p_i(k),
\end{equation}
where $p_i(k) = n_i(k)/E_k$ is the modal distribution defined in (equation eq:modal-distribution-def of the paper).

