[Lemma 19 of arXiv:2606.29131, '2606.29131'] Let $\phi_1^\e:\R^d \times\T^d\to \R$ be the solution to \eqref{e2-3aa}, and define $\Psi^\e:\R^d \to \R$ by
$\Psi^\e(x):=\phi_1^\e\left(x,\e^{-1} x \right)$. Then,
\begin{equation}
\varphi(\e)^{-1}\sL_\e \Psi^\e(x)=-F_1^\e\left(x,\e^{-1} x \right)+\bar F_1^\e(x)+G_1^\e\left(x,\e^{-1} x \right)
+\lambda \varphi(\e)^{-1}\phi_1^\e\left(x,\e^{-1} x \right),\quad x\in \R^d,
\end{equation}
where $G_1^\e:\R^d\times \T^d\to \R$ is defined by \eqref{l2-2-2}.
Moreover, for every $k\ge 0$, there exist positive constants $C_1(k)$ and $C_2(k)$ such that for all $\e\in (0,1)$, $x\in \R^d$ and $y\in \T^d$,
\begin{equation}
\begin{split}
|\nabla_x^k  G_1^\e(x,y)|&\le C_1(k)\xi_{2,\beta_0}(\e)\sum_{i=k}^{k+2}\left(\sup_{y\in \T^d}\|\phi_1^\e(\cdot,y)\|_{\M_{\beta_0},i}
+\sup_{y\in \T^d}\|\nabla_y\phi_1^\e(\cdot,y)\|_{\M_{\beta_0},i}\right)
(1+|x|)^{-d-\beta_0}\\
 &\le C_2(k)\xi_{2,\beta_0}(\e)(1+|x|)^{-d-\beta_0},
\end{split}
\end{equation}
where $\xi_{2,\beta_0}(\e)$ is defined by \eqref{e1-8a}.

[Theorem 104 (Auxiliary fixed-sample critical boundary) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Assume $T>0$ and $C\ne0$.  Let $G_C\sim N(0,C)$ and
$a_{C,T}=T\mathbb E\|G_C\|/\pi>0$.  On one event of probability one,
\begin{equation}
 s_N(\mathfrak D_T(B^C))\sim\frac{a_{C,T}}{N}.

\end{equation}
Moreover, $\zeta_{\mathfrak D_T(B^C)}$ extends meromorphically to
$\operatorname{Re}z>1/2$, has no pole there except $z=1$, and
\begin{equation}
 \operatorname*{Res}_{z=1}\zeta_{\mathfrak D_T(B^C)}(z)=a_{C,T}.

\end{equation}
For every $r\ge1$ the tensor power satisfies
\begin{equation}
 s_N\!\left(\mathfrak D_T(B^C)^{\otimes r}\right)
 \sim\frac{a_{C,T}^r}{\Gamma(r)}
       \frac{(\log N)^{r-1}}{N},
 \qquad
 \zeta_{\mathfrak D_T(B^C)^{\otimes r}}(z)
 =\zeta_{\mathfrak D_T(B^C)}(z)^r.

\end{equation}

[Theorem thDVtrap of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Consider the mapping $I_W:{\mathcal M }_1(\mathbb{R}^d)\to [0,\infty]$,
    \begin{equation}
    I_W(p):=
        \begin{cases}
            \|\nabla \phi\|_2^2+\langle W,\phi^2\rangle, \text{ if } \frac{{\rm d} p}{{\rm d} x}=\phi^2 \in H^1(\mathbb{R}^d)\\
            \infty, \text{ otherwise.}
        \end{cases}
    \end{equation}
    Then, $\overline{J}(p)=\beta I_W(p)$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2603.28093, 'Random Stability of Random Variables'] Take a random variable $N$ with values $0, 1, 2, \ldots$ with distribution $P$. A probability measure $Q$ on $\mathbb R$, or, equivalently, a random variable $X \sim Q$, is called {\it $N$-stable} or, equivalently, {\it $P$-stable}, if there exists a $c > 0$ such that the following equality in law holds: 
\begin{equation}

X_1 + \ldots + X_N \stackrel{d}{=} cX,
\end{equation}
where $X_1, X_2, \ldots \sim Q$ are independent copies of $X$, independent of $N$.

[Proposition 53 (Universal weak-trace area bound) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] If \(V_T\leq K\) almost surely, then for \(q>1\) and \(z\geq0\),
\begin{equation}
 \mathbb E\exp\!\left(q\sup_{t\leq T}\mathfrak P_{A_t}(z)\right)
 \leq\left(\frac q{q-1}\right)^q
 \exp\!\left(\frac{q(2q-1)}2zK\right).

\end{equation}
Consequently, for every finite \(r>0\),
\begin{equation}
 \left\|\sup_{t\leq T}\|A_t\|_{1,\infty}\right\|_{L^r}
 \leq C_rK,

\end{equation}
where \(C_r\) is independent of \(H,M,K\), and \(T\).

