\mathbb{E}  \Big[ \sup_{s \in[t, T]} e^{q\lambda \phi_s^{\varepsilon, t, x, y}}\left|U_s^{\varepsilon, t, x, y}\right|^q \Big] 
+E\left(\int_t^T e^{2\lambda \phi_s^{\varepsilon, t, x, y}}\left|Z_s^{\varepsilon, t, x, y}\right|^2 d s\right)^{q/2} <+\infty .
\end{eqnarray}

