[Proposition 7 of arXiv:2604.06122, 'REM universality for linear random energy'] Assume that Assumption \ref{assum:1} holds, and fix $\lambda^*>1$ and $\e\in (0,\tfrac{1}{2})$. There exists $N_{\e}>0$ such that, for any $n>N_{\e}$, $\Gae$ $h \in \mathfrak{L}^{\e}_n$, and any
\been{

C \in (\e \Gamma_n(h), (1-\e)\Gamma_n(h)),
}
there exists a set $\mathfrak{R}_{n,\lambda^*}(h)$ such that the following statements hold:
\begin{itemize}
\item for any $x\in \mathfrak{R}_{n,\lambda^*}(h)$
\been{

\Ps(\{\sigma:\,H_n(h,\sigma)\geq \tilde A_n(h)+x\})\leq \sqrt{\frac{ M''_n(h,\tilde\Lambda_n(h))}{ M''_n(h,\tilde\Lambda^{x}_n(h))}} \frac{1}{\tilde \Lambda^{x}_n(h)}e^{-C-\tilde \Lambda_n(h)x }(1+o(1));
}
\item for any $x\in \mathfrak{R}_{n,\lambda^*}(h)$
\been{

 \Ps(\{\sigma:\,H_n(h,\sigma)\geq \tilde A_n(h)+x\})\geq \sqrt{\frac{ M''_n(h,\tilde\Lambda_n(h))}{ M''_n(h,\tilde\Lambda^{x}_n(h))}}\frac{1}{\tilde \Lambda^{x}_n(h)}e^{-C-\tilde \Lambda^{x}_n(h)x }(1+o(1)).
}
\end{itemize}
Here $\tilde A_n(h)$, $\tilde \Lambda_n(h)$ and $\tilde \Lambda^{x}_n(h)$ are $h-$measurable random variables such that, if $h \in \mathfrak{L}^{\e}_n$ and $x\in \mathfrak{R}_{n,\lambda^*}(h)$, they are solutions of the following coupled equations
\been{

\begin{cases}
\aled{
&M^*_n(h, \tilde A_n(h))+\frac{1}{2}\log(2\pi M''_n(h,\tilde\Lambda_n(h)))=C\quad \textup{and}\quad \tilde A_n(h)\in (0, \Sigma_{n}(h)),\\
&M'_n(h,\tilde \Lambda_n(h))= \tilde A_n(h),\\
&M'_n(h,\tilde \Lambda^{x}_n(h))= \tilde A_n(h)+x.
}
\end{cases}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

