body:
[Defi 20 of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] Suppose $t\in\Z$. Set $t':=t-\lfloor\frac{n\log n}{k}\rfloor$, and $\gamma_t:=\exp(-kt'/n)$. Let $\nu_{n,k}^t$ denote the measure on $\S_n$ defined by the following sampling process: first, sample $M_t\in\{0,1,\ldots,n\}$ according to the distribution $\mathbf{P}[M_t=x]=\mathbf{P}(\Pois(\gamma_t)=x)/\mathbf{P}(\Pois(\gamma_t)\le n)$, then sample a uniformly random subset $S_t$ of size $M_t$ in $[n]$. Finally,
\begin{enumerate}
\item When $k$ is odd, sample a uniformly random element of $\A_{[n]\backslash S_t}$ and view it as an element of $\A_n$ by fixing all of the elements in $S_t$.
\item When $k$ is even, and $t$ is odd, sample a uniformly random element of $\A_{[n]\backslash S_t}^c$ and view it as an element of $\A_n^c$ by fixing all of the elements in $S_t$.
\item When $k$ is even, and $t$ is even, sample a uniformly random element of $\A_{[n]\backslash S_t}$ and view it as an element of $\A_n$ by fixing all of the elements in $S_t$.
\end{enumerate}

[Definition def:Seg-classes of arXiv:2605.16086, 'Loop pruning and downward deviations for maximum local time of discrete-time simple random'] For any finite set $E$ of loops, we call a finite path \(s'\) \textit{\(E\)-pruned} if \(\mathsf{Prune}(s',E)=s'\). Notice that, if \(\mathbf{s}'=\mathsf{Prune}(\mathbf{s},E)\), then every retained prefix \(\mathbf{s}'[0,m]\) is \(E\)-pruned.
Let \(\mathsf{Seg}(E)\) denote the collection of finite \(E\)-erasable paths.
For an \(E\)-pruned finite path $s'$, define
\begin{align}
\begin{aligned}
	\mathsf{Seg}(s',E):=\big\{\eta\in \mathsf{Seg}(E): N_n(s'\circ_t \eta,E)\ge |s'|\quad\forall\,n\in[|s'|,|s'|+\left\lvert \eta \right\rvert]\big\}.	
\end{aligned}
\end{align}

We further set
\begin{align}
\begin{aligned}
	\mathsf{Seg}^{\otimes}(s',E)&:=\prod_{m=0}^{\left\lvert s' \right\rvert} \mathsf{Seg}(s'[0,m], E).
\end{aligned}
\end{align}

[Prop 4 of arXiv:2607.04943, '\textbf{Approximation of Random Differential Equations Driven by Physical Brownian Motion '] Let $\we:=\sqrt{\ep}\ve.$ For each $0\leq t\leq T$ and $p\geq 1$, there exists a constant $C_{p,T}$ such that
		\begin{equation*}
			\supe\supt\|\we_t\|_p\leq C_{p,T}.
		\end{equation*}
		Equivalently,
		\begin{equation*}
			\supe\supt\|\ve_t\|_p\leq C_{p,T}\ep^{-1/2}.
		\end{equation*}

