[Prop eq:OP_BSig of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > - \frac12$, ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with $k_j > -1$, $1 \le j \le d_2$, define 
\begin{equation} 
 \bm Q_{\bm j, \bm k, m}^n(\bm x,\bm y) = \hat {\bm L}_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) |\bm y|^m 
      \bm B_{\bm k, m}^\mu \left(\frac{\bm x}{|\bm y|}\right),
\end{equation}
where $\alpha = 2 \mu + d_1-1$. Then
$\{\bm Q_{\bm j, \bm k, m}^n: |\bm k| = m, \, |\bm j| = n-m, \, \bm k \in {\mathbb N}_0^{d_1}, \, \bm j \in {\mathbb N}_0^{d_2}, 0\le m \le n\}$ 
is an orthogonal basis of ${\mathcal V}_n\big({\mathbb B}^{d_1}\!\! \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma}\big)$. 
Moreover, the norm square of $\bm Q_{\bm j, \bm k, m}^n$ is given by 
\begin{equation} 
   \bm h_{\bm j, \bm k, m}^{n; \mu,{\boldsymbol{\kappa}}}  

       =  (2\mu+d_1)_{2m} \bm h_{\bm k,m}^{\mu, {\mathbb B}}  
       \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+2m), \triangle}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:convergegeneral of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi$ be the discrete uniform distribution, $P \in \mathcal{S}(\pi)$ and $Q \in \mathcal{Q}$ be a permutation matrix. Let $\Pi$ be the matrix where each row equals to $\pi$. We have
	\begin{itemize}
		\item(One-step contraction measured by $D^{\pi}_{KL}$) \begin{align*}
			D^{\pi}_{KL}(P \| \Pi) &= D^{\pi}_{KL}(P Q \| \Pi) = D^{\pi}_{KL}(Q P \| \Pi) = D^{\pi}_{KL}(Q P Q\| \Pi).
		\end{align*}

		\item(KL-divergence Dobrushin coefficient)
		\begin{align*}
			c_{KL}(P) = c_{KL}(PQ) = c_{KL}(QP) = c_{KL}(QPQ).
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 30 of arXiv:2605.31088, 'On couplings for kinetic Langevin diffusions'] For $x\geq0$ we have
    \begin{equation}

        \frac{x}{1+x}\leq 1-e^{-x} \leq\frac{2x}{2+x},
    \end{equation}
    \begin{equation}

        \frac{6-2x}{6+4x+x^2}\leq e^{-x}\leq\frac{6}{6+x^3},
    \end{equation}
    \begin{equation}

        0\leq\frac{1-e^{-2x}}{2x}-e^{-x}\leq\frac{2}{3}x^2.
    \end{equation}
    In addition, for $a\geq b\geq0$ we have
    \begin{equation}

        2ax(1+e^{-x})-4b(1-e^{-x})\geq \frac{2ax^3}{6+4x+x^2},
    \end{equation}
    \begin{equation}

        2ax-4b(1-e^{-x})+b(1-e^{-2x})\leq 2(a-b)x+\frac{4}{3}bx^3.
    \end{equation}
    \begin{equation}

        2ax-2b(1-e^{-x})-b(1-e^{-x})^2\geq\frac{24ax^3+13ax^4+2ax^5}{(6+4x+x^2)^2}.
    \end{equation}

