body:
[Lemma N+1s-NE-PIT of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $t \in \mathop  \cap \limits_{j = 0}^q \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, the combination
\begin{equation*}
\left( {{u_{q,n + 1}},{v_{q,n + 1}},{\mathfrak{p}_{q,n + 1}},{\mathring{R}_{q,n + 1}},{S_{q,n + 1}},{\mathfrak{P}_{q + 1,n + 1}}} \right)
\end{equation*}
fulfills the $\left( {n + 1} \right)$-step Newton--Euler--Reynolds system
\begin{equation*}
\left\{ {\begin{array}{*{20}{l}}
{\partial _t}{v_{q,n + 1}} + \mathrm{div} \left( {{u_{q,n + 1}} \otimes {u_{q,n + 1}}} \right) + \nabla {\mathfrak{p}_{q,n + 1}} = \mathrm{div} \left( {{\mathring{R}_{q,n + 1}} + {S_{q,n + 1}} + {\mathfrak{P}_{q + 1,n + 1}}} \right),\\
{u_{q,n + 1}} = {v_{q,n + 1}} + \mathfrak{W}_q,\\
\mathrm{div}\,   {u_{q,n + 1}} = 0 .
\end{array}} \right.  
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm-OR01 of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] For $Z\in\mathcal X$ and $n\in\mathbb{N}$, we have
\begin{align*}
\lim_{\eta\to\infty}\left\{\eta-\left(\mathbb{E}[(\eta-Z)_+^n]\right)^{1/n}\right\}=\mathbb{E}[Z].
\end{align*}
As a result, for $X,Y\in\mathcal X$ and $n\in\mathbb{N}$,
$X\ge_n Y$ implies $\mathbb{E}[X]\ge \mathbb{E}[Y]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem defbsc of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\Omega$ be a region, and let $\Gamma_1$, $\Gamma_2$, and $\Gamma_3$ be Jordan curves in $\Omega$ that are nested from innermost $(\Gamma_1)$ to outermost $(\Gamma_3)$, and can be continuously deformed into one another within $\Omega$. Let $F({\mathbf u}, {\mathbf v})$ be a meromorphic function with
\begin{itemize}
    \item simple poles at $u_i = v_j$ for all $i$ and $j$,
    \item simple zeros at $u_i = u_j$ and at $v_i = v_j$ for all $i \neq j$,
    \item symmetry in $u_1, \ldots, u_m$, and separately in $v_1, \ldots, v_n$.
\end{itemize}
Then, 
\begin{equation}  \begin{split}
    &\int_{\Gamma_1^m} \mathrm{d} {\mathbf u} \int_{\Gamma_2^n} \mathrm{d} {\mathbf v}  \, \, F({\mathbf u}, {\mathbf v})  
    =  \sum_{i=0}^{m\wedge n}  (-2\pi \mathrm{i})^i i! \binom{m}{i} \binom{n}{i}   \int_{\Gamma_3^{m-i}} \mathrm{d} u_{i+1}\cdots \mathrm{d} u_m \int_{\Gamma_2^n} \mathrm{d} {\mathbf v}  \, \, \res_{u_1=v_1, \cdots, u_i=v_i} F({\mathbf u}, {\mathbf v}).
\end{split} \end{equation}

