body:
[Lemma lem:weighted-Sekigawa-divergence of arXiv:2609.00840, 'Kählerity of complete almost-Kähler gradient shrinking Ricci solitons'] Let $(M^{2m},g,J,\omega,f)$, $m\geq2$, be a complete almost-K\"ahler
	gradient shrinking Ricci soliton. Then, for $V=\nabla f$ and $W=JV$, we have
	\begin{equation}
		\begin{aligned}
			&\divergence\!\left\{
			e^{-f}\left[
			\nabla|\nabla\omega|^2
			+|\nabla\omega|^2V
			-8\zeta^\sharp
			+2\left(
			\ast^{-1}
			\frac{W^\flat\wedge\chi\wedge\omega^{m-2}}{(m-2)!}
			\right)^\sharp
			\right]\right\}\\
			&\qquad=
			e^{-f}\left(
			8|\widetilde{\mathcal R}^{\prime\prime}|^2
			+|\nabla^{\ast}\nabla\omega|^2
			+|\phi|^2
			+2\lambda|\nabla\omega|^2
			\right).
		\end{aligned}
	\end{equation}

[Definition def:sol_gen_MKV_den of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] A (general) solution to D-MKV$(b,\sigma)$ is a triple $( W, (\mathcal{F}_t)_t, X)$ which is a solution to MKV$({\bf b}^*,{\boldsymbol\sigma}^*)$, with ${\bf b}^*,{\boldsymbol\sigma}^*$ given by (equation eq:def_b_sig_dens of the paper)-(equation eq:density_standard of the paper), and such that
\begin{equation}
[X_t] \in AC(\mathbb{R}^d), \qquad t> 0. \vspace{-10pt}
\end{equation}

[Lem 10 of arXiv:2609.03653, 'The derived set of multiple star polylogarithms'] Let $m=n+1$.  Then
\begin{equation}
0\leq A_{\bf k}(n)-A_{\bf p}(n)
\leq 1-A_{\{1\}^{r}}(n).
\end{equation}
In particular, the oscillation of $A_{\bf k}(n)$ among all infinite extensions of a fixed prefix of length $r$ tends to zero as $r\rightarrow+\infty$, uniformly in the prefix.

[Theorem 15 of arXiv:2607.04193, 'Onsager--Machlup Functionals for Generalized Newtonian Equations of Motion with Time-Varyi'] Let $H \in (1/4, 1)$, and let $(X,Y)$ be the solution to the stochastic system \eqref{fir} with coefficients satisfying Assumption \((A)\). For any reference path $\phi-y_0 \in \mathcal{H}^\sigma_H([0,1];\mathbb{R}^n)$ and its associated state $\psi$ satisfying the coupling \eqref{sec} with $\psi_0 = x_0$, the OM functional of $Y$ with respect to the H\"{o}lder norm $\Vert \cdot \Vert_{\beta}$ (with $\max\{H-1/2,0\} < \beta < H-1/4$) is given by
\begin{equation}
    J(\phi) = \frac{1}{2}\int_0^1 \left| (K_H^\sigma)^{-1} \left( \phi_\cdot - y_0 - \int_0^\cdot b_v(\psi_v, \phi_v) \, dv \right)(s) \right|^2 ds + \frac{d_H}{2} \int_0^1 \, \nabla_y \cdot b_s(\psi_s, \phi_s) \, ds, 
\end{equation}
where the constant $d_H= \sqrt{\frac{2H\Gamma(H+1/2)\Gamma(3/2-H)}{\Gamma(2-2H)}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma databound of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix {\small$\delta>0$}. If {\small$\kappa$} is large enough, then with high probability, we have (for all {\small$\x\in\Z$}) that

\begin{align}
\exp(-\tfrac{\kappa|\x|}{N})\mathbf{Z}^{N}_{0,\x}+\exp(-\tfrac{\kappa|\x|}{N})\mathbf{S}^{N}_{0,\x}\lesssim N^{\delta}.
\end{align}

[Theorem of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Assume $\varepsilon=o(\delta)$. Under certain assumptions on  coefficients, for given initial values $x\in\mathbb{R}^n, y\in\mathbb{R}^m$,  $\{X^\varepsilon\}_{\varepsilon\in(0,1)}$ satisfies the LDP with the good rate function $I$ given by
	\begin{align*}
		{I(\varphi)=\begin{cases}\frac{1}{2}\int_0^T\big|Q_2^{-1/2}(\varphi_{t},\mathscr{L}_{\bar{X}_t},\nu^{\mathscr{L}_{\bar{X}_t}})(\dot{\varphi}_t-\bar{b}(\varphi_t,\mathscr{L}_{\bar{X}_t}))\big|^2dt,&\varphi \in \mathscr{H} ,\\[3mm]
				+\infty,&{\rm{otherwise}},
		\end{cases}}
	\end{align*}
	where
	$\mathscr{H}:=\{ \varphi : \varphi_0=x, \varphi~\text{is absolutely continuous}\}$, and
	\begin{align*}			Q_{2}(\varphi_{t},\mathscr{L}_{\bar{X}_{t}},\nu^{\mathscr{L}_{\bar{X}_t}}):=\int_{\mathbb{R}^m}\sigma(\varphi_{t},\mathscr{L}_{\bar{X}_{t}},y,\nu^{\mathscr{L}_{\bar{X}_t}})  \pi_1 \pi_1^*\sigma ^{*}(\varphi_{t},\mathscr{L}_{\bar{X}_{t}},y,\nu^{\mathscr{L}_{\bar{X}_t}}) \nu^{\mathscr{L}_{\bar{X}_t}}(dy).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem1444 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((init of the paper)), and let $r\ge 2$ and $p>1$. Then
  \begin{equation} \label{1444.1}
	\frac{d}{dt} \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^\frac{p}{r}
	+ a \cdot \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^\frac{p}{r}
	\le a^{1-p} \cdot \bigg\{ \int_\Omega |\nabla v|^r \bigg\}^\frac{p}{r}
	\qquad \mbox{for all } t\in (0,T_{max}).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2512.19517, 'Spiking and Resetting'] Let $e^\varepsilon_2$ be the stopping time defined by 
\begin{equation}

\begin{split}
e^\varepsilon_2 = \inf \{ t \ge e_1^\varepsilon \; ; \; X_t^\varepsilon =0 \} \ .
\end{split}
\end{equation}
We have that
\begin{equation}

\begin{split}
\lim_{\varepsilon \to 0} \mathbb P (e^\varepsilon_2 > t)  = e^{f(1) t}  \ ,
\end{split}
\end{equation}
i.e. $(e^\varepsilon_2)_{\varepsilon>0}$ converges in law to an exponential random variable with parameter $-f(1)$.

