[Theorem 9 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Assume that there exists $\epsilon_1\in(0,\epsilon_0]$ such that the following conditions hold.
	\begin{itemize}
		\item[(U1)] For every $\epsilon\in[0,\epsilon_1]$, $\Phi^\epsilon$ has a $\mathfrak D$-pullback random attractor $\mathcal A^\epsilon$.

		\item[(U2)] The family
		\begin{align*}
			\mathcal C(\omega)
			=
			\overline{
				\bigcup_{\epsilon\in[0,\epsilon_1]}
				\mathcal A^\epsilon(\omega)
			}^{\mathbb X}
		\end{align*}
		belongs to $\mathfrak D$, and $\mathcal C(\omega)$ is compact for every $\omega\in\Omega$.

		\item[(U3)] For every $t\geq0$, $\omega\in\Omega$ and compact set $C\subset\mathbb X$,
		\begin{align*}
			\sup_{z\in C}
			d_{\mathbb X}\big(
			\Phi^\epsilon(t,\omega)z,
			\Phi^0(t,\omega)z
			\big)
			\longrightarrow0
			\qquad\text{as }\epsilon\to0.
		\end{align*}
	\end{itemize}
	Then, for every $\omega\in\Omega$,
	\begin{align}
		\operatorname{dist}_{\mathbb X}\big(
		\mathcal A^\epsilon(\omega),
		\mathcal A^0(\omega)
		\big)
		\longrightarrow0
		\qquad\text{as }\epsilon\to0.
	\end{align}

