[Lemma lem.divinverses of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $M\in\mathbb{N}$.
		\begin{enumerate}
			\item[\rm(i)] For every $s\in(0,1)$ there exists $C=C(d,s)<\infty$ such that, for every $g\in L^2(\square_M)$, there exists $G\in H^1(\square_M;\mathbb{R}^d)$ with $\nabla\cdot G=g$ in $\square_M$ and
			\begin{equation}
				3^{sM}\|G\|_{\underline H^s(\square_M)}\le C 3^M\|g\|_{\underline L^2(\square_M)}\, .
			\end{equation}
			\item[\rm(ii)] For every $s\in(0,1/2]$ there exists $C=C(d,s)<\infty$ such that, for every $g\in\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-s}(\square_M)$ with $\langle g,\mathbf 1\rangle_{\square_M}=0$, there exists $G\in H^s(\square_M;\mathbb{R}^d)$ satisfying 
			\begin{equation}
				\Xint-_{\square_M}\nabla\varphi\cdot G=-\langle g,\varphi\rangle_{\square_M}\qquad\text{for every }\varphi\in C^\infty(\overline{\square_M})\, ,
			\end{equation}
			and
			\begin{equation}
				\|G\|_{\underline L^2(\square_M)}+3^{sM}[G]_{\underline H^{s}(\square_M)}\le C 3^{(1-s)M}\|g\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-s}(\square_M)}\, .
			\end{equation}
		\end{enumerate}

[Theorem thm:poles of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] Set
\begin{equation}
\phi_{N}(s):=\Bigg(1-\frac{\binom{N-s}{d}}{\binom{N}{d}}\Bigg)^{-1}=\Bigg(1-\prod_{j=0}^{d-1}\left(1-\frac{s}{N-j}\right)\Bigg)^{-1}
\end{equation}
and
\begin{equation} 
Q_{N}(s):=1-\prod_{j=0}^{d-1}\left(1-\frac{s}{N-j}\right).
\end{equation}
Then, the poles of $\phi_N(s)$ are the zeros of the polynomial $Q_N(s)$. Clearly, $s=0$ is a simple pole of $\phi_{N}(s)$. Moreover, if \(d\) is odd, then the only real pole is \(s=0\). In case where \(d\) is even, then the only real poles are
    \[
    s=0
    \qquad\text{and}\qquad
    s=2N-d+1;
    \]
In particular, all poles of $\phi_N(s)$ are simple. The $d-1$ nonzero zeros of $Q_{N}(s)$ are denoted as $\omega_{1,N},\, \omega_{2,N},\cdots,\omega_{d-1,N}$ (for all positive integer values of $d$; when $d=1$ there are none, and $s=0$ is the only pole). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2607.23585, 'The one-period Kyle model has one equilibrium'] If $(\phi,P)$ is a quasi-equilibrium, then
	\begin{equation}
		\phi(v)=\frac{\sigma}{\tau}(v-\mu)
		\qquad\text{for Lebesgue-almost every }v\in\R\,,
	\end{equation}
	and
	\begin{equation}
		P(Y_\phi)=\mu+\lambda Y_\phi
		\qquad\text{almost surely}\,,
	\end{equation}
	where
	\[
		\lambda
		=\frac{\Cov(V,Y_\phi)}{\Var(Y_\phi)}
		=\frac{\tau}{2\sigma}\,.
	\]

