[Proposition 38 (Summed deterministic diagonal) of arXiv:2607.10813, '2607.10813'] Let $a,b\in\mathfrak C$ with $a\ne b$, $0<s<1-2\beta_b$ and $0<\sigma<1$.  The dyadic series
\begin{equation}
  \cD^{a;b}w
  :=\sum_N\sum_{Q\le c_{\mathrm{ap}}N}
  \cD^{a;b}_{N,Q}P_Qw
\end{equation}
converges as a bounded deterministic operator
\begin{equation}
  \cD^{a;b}:E_T^{2,\sigma}
  \longrightarrow
  C_TH^{s-1}\cap L_T^\infty B_{2,\infty}^{\sigma-1}.
\end{equation}
Moreover,
\begin{equation}
  \norm{\cD^{a;b}}_{E_T^{2,\sigma}\to L_T^1B_{2,\infty}^{\sigma-1}}
  \le T
  \norm{\cD^{a;b}}_{E_T^{2,\sigma}\to L_T^\infty B_{2,\infty}^{\sigma-1}},
\end{equation}
so the Besov source norm tends to zero as $T\downarrow0$ on bounded diagonal classes.

[Theorem 1 (Geometric-burst tradeoff) of arXiv:2607.20823, 'Fluctuation impossibility results for stochastic burst networks'] Suppose Assumption~\ref{ass:S-standing} holds and every $K_i$ has the positive
geometric law \eqref{eq:positive-geometric-main}.  Then
\begin{equation}
        \sum_{i=1}^N
        \frac{F_{X_i}-\kappa_i}{\tau_i\kappa_i}
        \ge0.

\end{equation}
Consequently, if one component lies below its geometric-burst baseline, then
at least one other component must lie strictly above its own. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2606.09691, '\textsc{Degenerate Diffusions on Continuum Percolation and Hamilton-Jacobi-Bellman Equatio'] Let $G\subset\R^d$ be open and bounded, and let $(X_t)_{t\geq0}$ be a symmetric Markov process as in Lemma \ref{lemma Dirichlet}, with invariant measure $\mu$ equal to the normalized Lebesgue measure on $G$. Assume that the sample paths are continuous. Suppose there exists a function $f:G\to\R$ such that
\begin{enumerate}
\item $|f(x)|\to\infty$ as $x\to\partial G$,
\item $\|f\|_{L^2(\mu)}^2+\mathcal E(f,f)<\infty$.
\end{enumerate}
Then, for $\mu$-almost every starting point $x\in G$, we have 
\begin{equation}
P_x(\tau_{\partial G}<\infty)=0,
\qquad
\mbox{where}
\qquad
\tau_{\partial G}:=\inf\{t\geq0:X_t\in\partial G\}.
\end{equation}

[Prop triple hodge formulas 1 of arXiv:2609.02409, 'Membranes and Maps'] For $n\in\{1,2,3\}$, we have
    \begin{equation}

        \mathsf{H}(\epsvec[-1]{[n]} ; \epsvec{[3]} ; u)
        =
        \frac{
            \bigl( \sum_{i=1}^n \epsilon_i^{-1} \bigr)^{n-3}
        }{
            u^2 \bigl( \prod_{j=1}^3\epsilon_j \bigr) \bigl( \prod_{i=1}^n\epsilon_i \bigr)
        }
        \left( \frac{\sin(u/2)}{u/2} \right)^{p_n(\epsvec{[3]})} \,,
    \end{equation}
    where
    \begin{equation}
        p_n(\epsvec{[3]})
        =
        n - 2 +
        \left(\sum_{j=1}^3\epsilon_j\right) \left(\sum_{i=1}^n\epsilon_i^{-1}\right) \,.
    \end{equation}

[Lemma 18 of arXiv:2609.04153, '\vspace*{-3cm}Smooth autonomous fast dynamo action on the three-torus'] For every constant vector $c\in\mathbb C^2$ and every
$\sigma\in[0,1]$, one has
\begin{equation}
\|N^{-2} \mathcal{M}_{N,0} c-N^{-2}c\|_{H^{-\sigma}}
\lesssim
N^{-\sigma}|c|.
\end{equation}
Consequently, if $\sigma=r+\delta$, then
\begin{equation}
\|N^{-2} \mathcal{M}_{N,0} c\|_Y
\lesssim
N^{-(r+\delta)}|c|.
\end{equation}

[Cor of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{cor:sup.norm}
  For all $\epsilon>0$, there exists some
  $\alpha=\alpha(\epsilon,\lambda)>1$ such that
  \begin{align*}
    \mathbf{P}\biggl( \sup_{0<\rho<\alpha^n}\abs[\big]{D_\rho-\min(\rho,\rho_{\mathtt{FE}})} > \epsilon \biggl)\to 0.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 26 (Asymptotic variance of a chaotic component) of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] For $q\in \N$ with $q\geq 2$.

If $q<d/(2\nu)$, as $L\rightarrow\infty$ we have
	\begin{equation}

		\Var(F_L[q])= \frac{L^{-q}}{\beta_0^q} c_d\,q!\varphi_q^2\,
		\int_{-1}^1\widehat \beta^q(u)\di \mu(u)\,(1+o(1))\,\,\,.
	\end{equation}
where $c_d$ is given in~\eqref{eq::cd} and $\widehat\beta$ is given in~\eqref{beta-hat-sparse}.

If $q\ge \frac{d}{2\nu}$, and $q$ is even whenever $\kappa$ is odd, we have
\begin{align}
		\Var(F_L[q]\,\asymp \,
		\begin{cases}
			L^{-q}\,\log L\,\, &\textnormal{if } q=d/(2\nu) \\
			L^{-\frac{d}{2\nu}}\,\, &\textnormal{if }q>d/(2\nu)
		\end{cases}
		\qquad\,.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 (Ginibre recurrent memory coefficients) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] For every fixed $k,\ell\geq0$,
\begin{equation}
\frac1n\Tr\!\left(
A_n^k(A_n^\ell)^\top
\right)
\xrightarrow{L^1}
\tau_{k,\ell}.

\end{equation}

