[Lemma thm_Altmeyer of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $X$ be a sticky Brownian motion of stickiness parameter $\rho>0$, defined on the filtered probability space
	$(\Omega,\bF,(\bF_t)_{t\ge 0},\Prob_x) $ such that $\Prob_x $-a.s., $X_0=x $.
	Then, it holds that, for all intervals $U$ (including singletons),
	\begin{equation}

		\frac{1}{n} \sum_{i=1}^{[n\cdot]} \indicb{\hfprocess{X}{}{i-1} \in U}
		\xrightarrow[n \longrightarrow  \infty]{\Prob_x\text{-}\mathrm{ucp}} \int_{0}^{\cdot} \mathbbm{1}_{\{X_s \in U\}} \,\mathrm{d} s. 
	\end{equation}
	In particular, taking $U=\{0\} $, it yields that
	\begin{equation}
		\frac{1}{n} \sum_{i=1}^{[n\cdot]} \indicb{\hfprocess{X}{}{i-1} = 0} \xrightarrow[n \longrightarrow  \infty]{\Prob_x\text{-}\mathrm{ucp}}
		\int_{0}^{\cdot} \mathbbm{1}_{\{X_s = 0\}} \,\mathrm{d} s =  \rho \loct{X}{0}{}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] For every $p\geq3$, the system
\begin{equation}
\left\{
\begin{aligned}
 C_\beta^1(m,q)&=0\\
 D_\beta^1(m,q)&=0\\
 \beta^2p(p-1)q^{p-2}
 \frac{\E\cosh^{m-4}(Y_qg)}{\E\cosh^m(Y_qg)}&=1
\end{aligned}
\right.,

\end{equation}
has a unique solution $(\beta,m,q)\in(0,\infty)\times(0,1)^2$.
We denote it by $(\beta_2^p,m_2^p,q_2^p)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:X-Y of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Let $X,Y$ be two random variables with
\[
{\mathbb E}\, X = {\mathbb E}\, Y =0, \quad
\mathop{\rm Var}\nolimits X = \mathop{\rm Var}\nolimits Y=1, \quad
{\mathbb E}\, |X|^{\textcolor{black}{2+{\varepsilon}}},{\mathbb E}\, |Y|^{\textcolor{black}{2+{\varepsilon}}} < C_{X}^{\textcolor{black}{2+{\varepsilon}}}.
\]
Assume that for $r=Y-X$ one has ${\mathbb E}\, |r|^{\textcolor{black}{2+{\varepsilon}}}<C_{r}^{\textcolor{black}{2+{\varepsilon}}}$. Then for any $t\in {\mathbb R}$ one has
\begin{equation}
{|\varphi_{X}(t)- \varphi_{Y}(t)|} \le \textcolor{black}{5} C_r^{{\varepsilon}} C_X^{2}  \cdot {|t|^{\textcolor{black}{2+{\varepsilon}}}}
\end{equation}

