[Lem 6 (Rate function) of arXiv:2608.18276, 'The branching random walk in a uniform magnetic field : magnetization concentration and ov'] Let $\Lambda^*(a,m):=\sup_{(t,\theta)\in\R^2}\{ta+\theta m-\Lambda(t,\theta)\}$
be the Legendre transform of the function $\Lambda$ defined by Equation \eqref{eq:Lambda}. Then, for all $a\in\R$ and $m\in(-1,1)$,
\begin{equation}

\Lambda^*(a,m)=\frac{a^2}{2}-s(m),
\end{equation}
where $s$ is the binary entropy defined in Equation \eqref{eq:binary-entropy}. The supremum is attained at $(t,\theta)=(a,\arctanh m)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:3.2 of arXiv:2604.19294, 'On the maxima of Littlewood polynomials on $[-1,1]$'] For every $A\geqslant1$ there exists $C_A>0$ such that the following holds. Let $(\varepsilon_k)_{k\geqslant0}$ be a sequence of independent Rademacher random variables. One can couple standard Brownian motion $(B_s)_{s\geqslant0}$ with $(\varepsilon_k)_{k\geqslant0}$ so that
\[
    \mathbb{P}\Big(\max_{0\leqslant k\leqslant n}\Big|\sum_{j=0}^k\varepsilon_j-B_k\Big|>C_A\log n\Big)
    \leqslant C_A n^{-A}
\]
for all $n\geqslant2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Caffarelli--Silvestre extension for the Vladimirov--Taibleson operator) of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Let $f\in \mathcal{S}(\mathbb{Q}_p^n)$ and $s>0$. Consider the following extension problem
\begin{align*}
    \begin{cases}
    \Delta_w\varphi(v)=0,&v\in \mathcal{T}_{p^n};\\
    \displaystyle\lim_{k\to+\infty}\varphi_k(\boldsymbol{x})=f(\boldsymbol{x}),&\boldsymbol{x}\in\mathbb{Q}_p^n;\\
    \displaystyle\lim_{k\to-\infty}\varphi_k=0.&
\end{cases}
\end{align*}
The last boundary condition is understood as an end limit: $\varphi(v)\to0$ along every sequence of vertices $v\to\infty$. Here $w_{v_{k-1},v_k}=p^{k(s-n)}$ and, in horocyclic coordinates, $v_k=(\boldsymbol{x},k)$ with $k\in\mathbb{Z}$ and $\boldsymbol{x}\in\mathbb{Q}_p^n/p^k\mathbb{Z}_p^n$. This problem has a unique bounded weighted-harmonic solution that is continuous on the end compactification. Moreover, $\varphi_k\to f$ uniformly and in $L^2(\mathbb{Q}_p^n)$ as $k\to+\infty$. Define the deformed boundary normal derivative by
\begin{align*}
        \partial_{n,s}^{(p)}\varphi(\boldsymbol{x})=\lim_{k\to+\infty}p^{(k+1)s}\left(f(\boldsymbol{x})-\varphi_k(\boldsymbol{x})\right),
    \end{align*}
where the limit exists pointwise and in $L^2(\mathbb{Q}_p^n)$. The resulting Dirichlet-to-Neumann map is the Vladimirov--Taibleson operator:
    \begin{align*}
    \partial_{n,s}^{(p)}\varphi(\boldsymbol{x})=D^sf(\boldsymbol{x}).
\end{align*}
The solution also satisfies the energy identity
\begin{align*}
    \mathcal{E}[\varphi]=&\sum_{k\in\mathbb{Z}}p^{ks}\int_{\mathbb{Q}_p^n}|\varphi_k(\boldsymbol{x})-\varphi_{k-1}(\boldsymbol{x})|^2d\boldsymbol{x}\\
    =&\frac{1}{2}\sum_{u\in \mathcal{T}_{p^n}}\sum_{v\sim u}w_{uv}|\varphi(u)-\varphi(v)|^2\\
    =&(1-p^{-s})\int_{\mathbb{Q}_p^n}f(\boldsymbol{x})D^sf(\boldsymbol{x})d\boldsymbol{x}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 ($L^4$-energy estimate) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Under the assumptions and with the notation of Proposition~\ref{prop:itoformulaL4}, 
 a.s.\ for all $t\in[0,T]$
    \begin{align}
        \frac{1}{4}\|u(t\land \sigma_m)\|_{L^4}^4 &\le \frac{1}{4}\|u_0\|_{L^4}^4 +
         3 \inttm\intsO |u|^2 \grad u \cdot \grad \Delta u \dx\ds + 3 \inttm\intsO |u|^2 \grad u \cdot [- 3u^2 \grad u + \grad u] \dx\ds \nonumber\\
        &\phantom{\le } + M_{t\land \sigma_m} + \frac{3C_\psi}{2} \inttm\intsO |u|^2 (1+|u|^2 + |\grad u|^2)  \dx \ds,
    \end{align}
    for $M_t \ce \sum_{n \geq 1} \intt\intsO |u|^2 u \psi_n(u, \grad u) \dx \dWsn$, which is a local martingale with quadratic variation satisfying for all $\varepsilon>0$ and $t\in [0,T]$
    \begin{equation}

     \E\big[[M]_{t\wedge \sigma_m}^{1/2}\big]\le  \varepsilon\E\bigg[\sup_{s\in[0,t\land \sigma_m]} \|u(s)\|^4_{L^4}\bigg]
    +\frac{L}{4\varepsilon}\E\Big[\inttm  \intsO \big(|u|^2+|u|^4+|u|^2|\grad u|^2\big)\dx\ds\Big].
    \end{equation}

[Lemma 29 of arXiv:2609.02878, '2609.02878'] There are $o\in\cR$ and $B<\infty$ such that, with
$r(x)=d(o,x)$,
\begin{equation}
                         |\nabla f|(x)\le\frac12r(x)+B
                         \qquad(x\in\cR).
\end{equation}
If $\Psi_a=\operatorname{Fl}_{\nabla f}^a$, then for every $a\ge0$,
\begin{equation}
                     r(\Psi_a x)+2B\le e^{a/2}(r(x)+2B)
\end{equation}
after increasing $B$ if necessary.

[Theorem T:path main of arXiv:2507.01236, 'Disintegration theorem for multifunctions, \\ with applications to empirical Wasserstein d'] Consider the unit interval $\mathfrak{X} = [0,1]$ with its Euclidean metric $d$ and let $\mu$ be an absolutely continuous probability measure on $\mathfrak{X}$ with density $f$ satisfying
\begin{equation}

c \leq f(x) \leq C\mbox{\rm \ for every $x \in \mathfrak{X}$},
\end{equation}
where $0 < c \leq C < \infty$. 
Given $\alpha \in (0, \infty)$ and $n\in\mathbb{N}$, let
\begin{equation}

r(n)\equiv r(n,c, \alpha) := 4 c^{-1} \sqrt{(2 + \alpha) \frac{\ln n}{n}}.
\end{equation}
Then there exists $n_0\equiv n_0(c,C,\alpha)$ such that $n\geq n_0$ implies that $(\mathfrak{X},d,\mu)$ is $(n^{-\alpha},r(n))$-disintegrable.

