[Coro OU of arXiv:2411.11552, 'Convergence rate of Smoluchowski--Kramers approximation with stable Lévy noise'] For the Ornstein-Uhlenbeck process
		\begin{equation}
			Z^\epsilon(t):=\int_{0}^{t} e^{-\epsilon^{-1}(t-s)}dL(s),
		\end{equation}
		or equivalently,
		\begin{equation}
			dZ^\epsilon(t)=-\epsilon^{-1}Z^\epsilon(t)+dL(t),\quad Z^\epsilon(0)=0,
		\end{equation}
		we have
		\begin{equation}
			\limsup_{\epsilon\to0}\mathbb{E}\sup\limits_{0\leq t\leq T}|Z^\epsilon(t)|>0.
		\end{equation}

