[Proposition P:flat-to-point-geodesic-localization of arXiv:2607.17113, 'Two-time spatial decorrelation for the flat KPZ fixed point'] Fix $0<s<t$ and $\eta \in (0,1)$. One can choose a measurable time-$s$
  optimizer $Y_x$ in (equation E:variational of the paper) such that, for $|x| \ge 1$,
  \begin{equation}
    \mathbb{P}(|Y_x-x|>\eta |x|)
    \le C\exp\{-c |x|^3\}.

  \end{equation}

[Lemma 8 (Fourth moments from a positive Stein kernel) of arXiv:2608.27657, '\bfseries Stein Kernels and Normal Approximation\\ for Log-Concave Bilinear Forms'] Let \(Y\) be centered with finite second moments, and suppose that \(Y\)
admits a symmetric positive-semidefinite Stein kernel
\(\tau\in L^2\).  Then
\begin{equation}
  \E|Y|^4
  \leq 9n\,\E\|\tau(Y)\|_{\HS}^2.
  \tag{4.1}
\end{equation}

[Lemma lem:Description of arXiv:2607.14062, 'Gilbert's disc model conditioned on the square lattice'] Let $k\geq1$ be such that $s_{n_k}= s_{n_k+2}= \hspace{.1cm}\rightarrow\hspace{.1cm}$ and $s_{n_k+1}= s_{n_k+3} = \hspace{.1cm}\uparrow\hspace{.1cm}$. Then, 
\begin{itemize}
    \item if $n_{k+1} - n_k = 2l$ with $l\geq1$, then between the points $u_{n_{k}+1}$ and $u_{n_{k+1}+1}$, the path alternates between the patterns  $(\hspace{.1cm}\rightarrow\hspace{.1cm},\hspace{.1cm}\uparrow\hspace{.1cm})$ and $(\hspace{.1cm}\rightarrow\hspace{.1cm},\hspace{.1cm}\downarrow\hspace{.1cm})$, i.e.,
    $$\forall m\in\{2,\ldots, 2l+1\}, \quad s_{n_k + m} =
    \begin{cases}
        \hspace{.1cm}\rightarrow\hspace{.1cm} & \text{if } m = 0 \mod 2,\\
        \hspace{.1cm}\downarrow\hspace{.1cm} & \text{if } m = 1 \mod 4,\\
        \hspace{.1cm}\uparrow\hspace{.1cm} & \text{if } m =3 \mod 4.
    \end{cases}
    $$
    \item if $n_{k+1} - n_k = 2l+1$ with $l\geq1$, then between the points $u_{n_{k}+1}$ and $u_{n_{k+1}+2}$, the paths alternates between the patterns $(\hspace{.1cm}\rightarrow\hspace{.1cm},\hspace{.1cm}\uparrow\hspace{.1cm})$ and $(\hspace{.1cm}\leftarrow\hspace{.1cm},\hspace{.1cm}\uparrow\hspace{.1cm})$, i.e., 
    $$\forall m\in\{2,\ldots,2l+2\}, \quad s_{n_k + m} = 
    \begin{cases}
        \hspace{.1cm}\uparrow\hspace{.1cm} & \text{if } m  = 1 \mod 2,\\
        \hspace{.1cm}\leftarrow\hspace{.1cm} & \text{if } m  = 0 \mod 4,\\
        \hspace{.1cm}\rightarrow\hspace{.1cm} & \text{if } m  = 2 \mod 4.
    \end{cases}
    $$
\end{itemize}
	In particular, for any $k \geq 1$,
	$$s_{n_{k+1}} = \left\{
	\begin{array}{ll}
		\hspace{.1cm}\rightarrow\hspace{.1cm} &\mbox{ if } n_{k+1} - n_k \mbox{ is even},\\
		\hspace{.1cm}\uparrow\hspace{.1cm} &\mbox{ if } n_{k+1} - n_k \mbox{ is odd}.  
	\end{array}
	\right.$$

[Theorem thm:K of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let (asn:b of the paper) and (asn:sigma of the paper) hold. Let $\chi\in\mathrm{Cut}_d$, $p\in[1,\infty)$, $\theta\in[0,1]$, $\ell\in\{1,\ldots,d\}$ and let $X$ and $Y$ be two solutions to (equation eq:main of the paper). For $f\in \mathcal{C}^1$ define the two-parameter process
\begin{equ}
K_{s,t}=\int_s^t(B_r^\ell-B_s^\ell)\Big(\chi_\rho(X_r-Y_r)f\big(\theta X_r+(1-\theta)Y_r\big)\Big)\,dr.
\end{equ}
Then there exists a constant $C=C(\alpha,p,d,\lambda,H,\|\sigma\|_{\mathcal{C}^5},C^X_{D, p}, C^X_{S, 2p}, C^Y_{D,p}, C^Y_{S, 2p})$ such that
\begin{equ}
\|K_{s,t}\|_{L^p(\Omega)}\leq N\|f\|_{\mathcal{C}^{\alpha-1}}|t-s|^{1+\alpha H}.
