[Thm 21 of arXiv:2607.27932, '2607.27932'] Let $\underline H_0$ and $\mathcal M_0$ denote respectively the minimum and minimizer set of $H_0(\lambda)=\widetilde H_0(\lambda,\lambda)$.
		 Then,
		for any~$\delta>0$,
		\begin{equation}

			\begin{aligned}
				&\lim_{\sigma\to0}\PP\left(\exp\left[\frac{2}{\sigma^2}\left(\underline H_0-\delta\right)\right]<C(\sigma)<\exp\left[\frac{2}{\sigma^2}\left(
				\underline H_0+\delta\right)\right]\right)=1,
			\end{aligned}
		\end{equation}
		and
		\begin{equation}
			\lim_{\sigma\to0}\PP\left(\mathrm{dist}\big(X_{C(\sigma)},\mathcal M_0\big)\le \delta\right)=1.
		\end{equation}

