body:
[Mydef def:marked of arXiv:2608.12954, 'Rainbow percolation'] Fix integers $m\ge 1$ and $n,s>m$ with $|n-s|\le m$ (the overhang lengths of a
rainbow and its inner span), and set $D_k:=\min(n+k, s+m-k)$ for
$1\le k\le m-1$ (the caps of $B$, as in (lem:contain of the paper) with $\ell=n$, $r=s$).
The \emph{marked model} on the vertex set $\{0,1,\dots,n+m\}$ has independent radii $R^\sharp_v$ for $v\in \{0,\dots,n+m\}$ with Pareto distribution of shape 1 and scale $x_m\in (0,1)$ as follows
\begin{itemize}
  \item $R^\sharp_0=\infty$ (image of the outer endpoint $a$: an edge $\{0,u\}$
        exists iff $R^\sharp_u\ge u$);
  \item $R^\sharp_u$ i.i.d.\ Pareto for $1\le u\le n-1$ (interior of the overhang);
  \item $R^\sharp_n$ Pareto conditioned on $[m,n)$ (near inner endpoint, image of $c$);
  \item $R^\sharp_{n+k}$ Pareto conditioned on $[x_m,D_k)$ for $1\le k\le m-1$
        (interior of the rainbow, capped by $B$);
  \item $R^\sharp_{n+m}$ Pareto conditioned on $[m,s)$ (far inner endpoint, image of $d$),
\end{itemize}
with the edge rule $\{u,v\}\in E$ iff $|u-v|\le R^\sharp_u\wedge R^\sharp_v$. For
$1\le i\le n-1$ the \emph{marked gap event} is
\[
   \{\text{gap}^\sharp\text{ at }i\}
   :=\{\not\exists  0\le j\le i<k\le n+m \text{ with } |k-j|\le R^\sharp_j\wedge R^\sharp_k\}.
\]

[Lem 2 of arXiv:2604.25964, 'Strong convergence rate of Euler-Maruyama approximations in temporal-spatial H\"older-norm'] (A Lyapunov estimate) 
 Let $V\in C^{1,2}([0, T]\times \mathbb{R}, [0, \infty)), \alpha \in L([0, T], [0, \infty))$ with $\int_0^T \alpha (t) dt<\infty,$ let $\tau: \Omega\to [0, T]$ be a stopping time, let the coefficients $\mu, \sigma, \gamma$ be continuous functions and let $X: [0, T] \times \Omega \to \mathbb{R}$ be the c\`adl\`ag and adapted  solution process to the equation \eqref{eqn1} with sample paths satisfying
\begin{align}

        & \dfrac{\partial V}{\partial t} (t \land \tau, X_{t \land \tau}) + \dfrac{\partial V}{\partial x} (t \land \tau, X_{t \land \tau}) \mu (X_{t \land \tau})+ \dfrac{1}{2} \dfrac{\partial^2 V}{\partial x^2}(t \land \tau, X_{t \land \tau}) \sigma^2 (X_{t \land \tau}) \notag \\
        & \quad + \int_{\bR_0} \left[ V(t \land \tau, X_{t \land \tau} + \gamma (X_{t \land \tau})z ) - V(t \land \tau, X_{t \land \tau}) - \dfrac{\partial V}{\partial x}(t \land \tau, X_{t \land \tau}) \gamma (X_{t\land \tau}) z \right] \nu (dz) \notag \\
        & \leq \alpha (t \land \tau) V(t \land \tau, X_{t \land \tau}), \quad \mathbb{P} \text{-a.s. for all } t \in [0,T].
    \end{align}
    Then,
\begin{align*}
    \mathbb{E}\left[V(\tau, X_{\tau})\right] \leq \exp \left( \int_0^T \alpha(s) ds \right) \mathbb{E} [V(0, X_0)] \in [0,\infty].
\end{align*}

