[Lemma 23 of arXiv:2510.24244, 'Statistical properties of Markov shifts: part II-LLT'] Define $\Delta_{j,\ell}=H_{j,\ell+1}\circ T_{j+\ell}-H_{j,\ell}-(H_{j+\ell+1}\circ T_{j+\ell}-H_{j+\ell})$. Then
\begin{equation}
 \lim_{\ell\to\infty}\sup_{j}\|\Delta_{j,\ell}\|_{j+\ell,\omega}=0.   
\end{equation}

[Lemma lem:PCneighbors of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Let $P$ be either $P_{\lambda,\zeta}$ or $P_{\lambda, \zeta, H}$, and let $S \subseteq \Omega$ be closed under taking vertex subsets or edge subsets, respectively. Furthermore, suppose there is a $\rho > 0$ such that every $y,z \in S$ with $\mathrm{dist}(y,z) = 1$ admits a coupling of $(Py,Pz)$ such that
\begin{equation}
\mathbb{E}[\mathrm{dist}(Py,Pz)] \leq 1 - \rho.
\end{equation}
Then $P$ is $\rho$-contractive on $S$.

[Theorem 13 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] Assume that $\hat{R}_n>0$ is the solution to
\begin{equation}
\begin{split}
 \lambda\bigl(g_{n-1}^{\circ}(E[e^{R\xi}]) - 1\bigr) = cR,
\end{split}
\end{equation}
then the ruin probability admits the asymptotic representation
\begin{equation*}
\begin{split}
 \Pi_n(x)\sim C_ne^{-\hat{R}_nx}\quad\text{as} \quad x\to+\infty,
\end{split}
\end{equation*}
where
\begin{equation}
\begin{split}
 C_n=\frac{c-\lambda^nm}{\lambda^nE[\xi e^{\hat{R}_n\xi}]\prod_{i=1}^{n-1}g_i^{\circ}(E[e^{\hat{R}_n\xi}])-c}.
\end{split}
\end{equation}

