body:
[Proposition 2 (Entropy disturbance from restriction) of arXiv:2609.01043, 'From Truncation to Commitment:\\ Persistent Context in Uniform Discrete Diffusion'] For every categorical law $Q$ and retained set $A$ with $Q(A)>0$,
\begin{equation}
 \left|\Ent(Q(\cdot\mid A))-\Ent(Q)\right|
 \le \Phi_V(-\log Q(A)).

\end{equation}
The function $\Phi_V$ is nondecreasing and concave on $[0,\infty)$.

[Theorem T:Dalang of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume that
  \begin{align*}
    \alpha >0, \quad
    \beta  \in (0,2],   \quad
    H      \in [1/2,1), \quad \text{and} \quad
    \ell   \in (0,2d).
  \end{align*}
  We have the following three cases (see Figure~(F:Dalang of the paper))
  \begin{enumerate}[\rm (i)]

    \item If either $\beta \in (0,2)$ and $\gamma \geq 0$ or $\beta = 2$ and
          $\gamma > 1$, then we have
          \begin{subequations}
            \begin{align}
              K(\alpha,\beta,\gamma;H,\ell;\nu,d) <\infty
               & \quad\Longleftrightarrow\quad \rho_0 = \beta + \gamma - 1 + H -\frac{\ell \beta}{2\alpha} >0 \quad \text{and}\quad \ell < 2\alpha \\
               & \quad\Longleftrightarrow\quad 0 <\ell < 2\alpha + \frac{2\alpha}{\beta}\min\left(0, \gamma + H -1\right). 
            \end{align}
          \end{subequations}

    \item If $\beta = 2$ and $\gamma = 0$, then
          \begin{align}
            K(\alpha,2,0;H,\ell;\nu,d) <\infty \quad\Longleftrightarrow\quad
            0 < \ell < \left(1/2+H\right) \alpha.
          \end{align}

    \item If $\beta = 2$ and $\gamma \in (0, 1]$, then
          \begin{align}
            K(\alpha,\beta,\gamma;H,\ell;\nu,d) <\infty \quad\Longleftarrow\quad
            0 < \ell <  \min\left(2, \gamma+H+1/2\right) \alpha .
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] A function $\rho \in L^1_\loc(I\times \R^d)$ is a (weak) solution of
\eqref{CE}
if $\rho \v \in \boldsymbol{L}^1_\loc(I\times \R^d)$ and
for any $\Phi \in C^1_c(I\times \R^d)$ the following holds:

\begin{equation}

\int_I \int_{\R^d} \rho(t,x) \d_t \Phi(t,x) \, dx \,dt
+ \int_I \int_{\R^d} \rho \v \cdot \nabla_x \Phi(t,x) \, dx \,dt = 0.
\end{equation}

[Corollary 39 of arXiv:2608.30570, '2608.30570'] Under the assumption of Theorem \ref{thm-DJ}, there exists a constant $C>0$ depending on $\Lambda$ and $\delta$ such that for any $J\in{\mathcal J}$, the following estimate holds:
		\begin{equation}
			|\nabla\sin\alpha_J|^2(x) \leq C|x|^{-\frac{\beta}{4}},\ \  \ all \ |x|\geq R_2+2.
		\end{equation}
In particular, on $\Sigma_j$, we have
		\begin{equation}
			|\nabla\sin\alpha_{I_j}|^2(x) \leq C|x|^{-\frac{\beta}{4}},
		\end{equation}
for all $|x|\geq R_2+2$, where $I_j\in{\mathcal J}$ is given by Theorem \ref{prop-alpha-decay}. (Proof in the paper; no proof environment follows the statement in the TeX.)

