[Definition of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}$ and $\phi,\psi \in \Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}), S\otimes {\mathfrak l}}$.
  \begin{enumerate}
  \item
    The \defined{stress-energy tensor}
    $T_{\phi,\psi} \in \Gamma\paren{X{\backslash} Z,\Hom(S^2TX,\mathbb{R})}$ is defined by
    \begin{equation*}
      T_{\phi,\psi} (v,w)
      \coloneq
      -\frac18\paren{\Inner{\gamma(v)\nabla_w\phi,\psi} + \Inner{\gamma(w)\nabla_v\phi,\psi}
      + \Inner{\gamma(v)\nabla_w\psi,\phi} + \Inner{\gamma(w)\nabla_v\psi,\phi}}.
    \end{equation*}
  \item  
    Define
    $\mu(\phi,\psi) \in \Omega^1\paren{X{\backslash} Z,{\mathfrak o}_{\mathrm{C\ell}}(S)}$
    by
    \begin{equation*}
      \mu(\phi,\psi)
      \coloneq
      \frac12\bar\gamma^*\paren*{\phi\Inner{\psi,-} + \psi\Inner{\phi,-}}.
    \end{equation*}
    with $\bar\gamma^*$ denoting the adjoint of the linear map $\bar \gamma \mskip0.5mu\colon\thinspace T^*X \otimes {\mathfrak o}_{\mathrm{C\ell}}(S) \to \Sym(S)$ defined by $\bar\gamma(\alpha\otimes \xi) \coloneq \gamma(\alpha^\sharp)\xi$.
    \qedhere
  \end{enumerate}

[Proposition 23 of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] There exists~$C > 0$ such that the following holds for~$\lambda$ small enough.
	Let~$k,\ell \in \mathbb N$ with~$k \ge 2$ and~$\ell \ge k-1$. Let~$Q(k,\ell)$ be the probability that there is an infection path in~$\mathcal G$ started at the root, having ordered trace~$\Gamma$ satisfying the following properties:
	\begin{itemize}
		\item $\Gamma$ has length~$\ell$ and visits~$k$ distinct vertices;
		\item the last vertex of~$\Gamma$ is distinct from all other vertices;
		\item all vertices of~$\Gamma$ are blue.
	\end{itemize}

	Then, taking~$M(\lambda,k,\ell)$ as in~\eqref{eq_def_of_M_f},
\begin{equation*}
	Q(k,\ell) \le \begin{cases}
		CM(\lambda,k,\ell)\cdot \lambda^{1+a}&\text{if $\ell$ is even};\\
		CM(\lambda,k,\ell)\cdot \lambda&\text{if $\ell$ is odd}.
	\end{cases}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

