[Lemma 14 of arXiv:2607.10102, 'Dynamical mean-field limit and replica-symmetric free energy for the orthogonally-invarian'] In addition to the conditions of Lemma \ref{lemma:tti}, suppose that
\begin{equation}
\sum_{p \geq 1} |\kappa_{p+1}|(v_*-q_*+\eps)^p<\alpha
\end{equation}
for some constant $\eps>0$ and the limits $v_*,q_*$ defined in Lemma
\ref{lemma:tti}. Then:
\begin{enumerate}[(a)]
\item $r_g:[0,\infty) \to \R$ is continuous on $[0,\infty)$ and
continuously-differentiable on $(0,\infty)$, with
\begin{equation}
\int_0^\infty |r_g(\tau)| \d \tau<\alpha
\end{equation}
and $\int_0^\infty |r_g'(\tau)|\d\tau<\infty$.
Furthermore, for some $C,c>0$ and all $t \geq s \geq 0$ and $\tau \geq 0$,
\begin{equation}
\begin{gathered}
|R_g(t,s)| \leq Ce^{-c(t-s)}, \qquad |r_g(\tau)| \leq Ce^{-c\tau},\\
|R_g(t,s)-r_g(t-s)| \leq Ce^{-cs}, \qquad
\int_0^t |R_g(t,s)-r_g(t-s)| \d s \leq Ce^{-ct}.
\end{gathered}
\end{equation}
\item $c_g:\R \to \R$ is continuous, symmetric, and positive-semidefinite on
$\R$, twice continuously-differentiable on $(0,\infty)$, and has
a right derivative $c_g'(0^+)=\lim_{\tau \to 0^+} c_g'(\tau)$ at $\tau=0$.
We have the fluctuation-dissipation relation
\begin{equation}
r_g(\tau)={-}c_g'(\tau) \text{ for all } \tau>0,
\qquad r_g(0)={-}c_g'(0^+).
\end{equation}
Furthermore $\cR_\Lambda(v_*-q_*) \geq 0$ and
$q_*\cR_\Lambda'(v_*-q_*) \geq 0$, and we have
\begin{equation}
\begin{gathered}
c_g(0)=\cR_\Lambda(v_*-q_*)+q_*\cR_\Lambda'(v_*-q_*),
\qquad
\lim_{\tau \to \infty} c_g(\tau)=q_*\cR_\Lambda'(v_*-q_*),\\
\qquad |C_g(t,s)-c_g(t-s)| \leq Ce^{-c\min(s,t)},
\qquad |c_g(\tau)-q_*\cR_\Lambda'(v_*-q_*)| \leq Ce^{-c\tau}.
\end{gathered}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:population-saddle of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] For all sufficiently large $N$, equation (equation eq:population-saddle of the paper)
has a unique solution $w_N>2\tau_N$.  Moreover,
\begin{align}
 \frac{w_N}{A_N}
 &=1+O(A_N^{-2})+O(e^{-c\tau_N}),                      \\
 R_N
 &=2A_N+O(A_N^{-1})+O(e^{-c\tau_N}).                  
\end{align}
More precisely,
\begin{equation}
 w_N=A_N+\frac{3\sigma^2}{2A_N}+o(A_N^{-1}),
 \qquad
 R_N=2A_N+\frac{\sigma^2}{A_N}+o(A_N^{-1}).
\end{equation}
In particular, $w_N\sim A_N$ and $R_N\sim2A_N$.

[Lemma of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[lemma]{lemma:cutoffsolnorm}
    The function $\tilde{U}$ satisfies 
    \[\|\tilde{U}\|_{L^2(V_N)}=O(N),\ \|\nabla \tilde{U}\|_{L^2(V_N)}=O(1),\ \|\Delta \tilde{U}\|_{L^2(V_N)}=O(N^{-\lambda/2}).\]

