[Theorem Unified Linear Convergence of Projected BW-GD of arXiv:2609.03762, '\vspace*{-2cm} Projected Riemannian Gradient Descent for the Bures--Wasserstein Barycenter'] Let $f \in \{f_1, f_2\}$ be the objective function with unique optimum $S_\star \in [\alpha I, \beta I]$ and $\kappa = \beta/\alpha$.
        For any feasible initial point $S_0 \in [\alpha I, \beta I]$ (additionally invariant, $S_0 \in \mathcal{P}$, when $f = f_2$), the iterates $\{S_t\}_{t \geq 0}$ of Projected BW-GD with unit step size satisfy
        \begin{equation}
            f(S_t) - f(S_\star) \le \left( 1 - \frac{1}{\kappa^{3/2}} \right)^t (f(S_0) - f(S_\star)).
        \end{equation}
        For the barycenter this improves to $(1 - \kappa'^{-3/2})$ on the refined interval ((Rem:RefinedConstants of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_tau0_tail of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] There exist constants $C_6 \geq 1$ and $L_0 \in \mathbb{N}$ such that the following holds. For sufficiently small $\zeta > 0$, for any $\delta \in (0,1]$ and $\mathbb{P}_\zeta \in \mathscr{M}_{\gamma,\delta}(\zeta)$, for all $k \in \mathbb{N}$ such that $k \leq \log_2 (1/\zeta) - L_0$, 
\begin{equation}
\mathbb{P}_\zeta(\tau_0 > C_6 (2^k \zeta)^{2-2\gamma}) \leq 2^{-k}.
\end{equation}

[Prop superprop of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] There exist $\widehat{T}>T_0$ such that
\begin{equation*}
\Psi_{1}=\zeta_1 (t)\psi_1+\zeta_{1}'(t)(\nu_1(t)\Gamma+\xi_1+\frac{M_2}{2}\psi_1)\in C^{1}((T_0,\infty); H^{1}_{0}(B_{1}^2))
\end{equation*}
satisfies $\Psi_1=0$ on $\partial B_1\times (\widehat{T},\infty)$ and
\begin{equation*}

(\partial_{t}+\mathcal{E})\Psi_{1}\ge -\min\{\lambda^{*}e^{u^{*}}r^{4}e^{\mu_1 t}\mathcal{F}(r^{-4}e^{-\mu_1 t}\Psi_{1}),
-L\zeta_{1}'(t)\delta^{-2}(t)\}
\end{equation*}
in $B_{1}^{2}\times (\widehat{T},\infty)$. Moreover, we obtain
\begin{equation*}
\Psi_{1}(r)\ge \frac{-L\zeta'_{1}(t)}{2\psi_1(0)}\psi_1(r) \quad \text{in $B_{1}^{2}$} \quad\text{and}\quad \Psi_{1}(\delta)\le -2L\zeta_{1}'(t)
\end{equation*}
for any $\widehat{T}<t$.

