[Lemma independence over F_p^n of arXiv:2609.04072, 'Oort's conjecture for split unitary Shimura varieties'] Let $x_1,...,x_g \in \overline{\mathbb{F}}_p$ be linearly independent over $\mathbb{F}_{p^n}$, and let $\varepsilon_1,...,\varepsilon_g \in \mathbb{F}_{p^n}$. Let $k \leq g-2$ and consider the $g \times (k+2)$-matrix

\begin{align}
    \begin{pmatrix}
        x_1 & x_1^{\sigma^n} & \cdots & x_1^{\sigma^{kn}} &\varepsilon_1 \\
        x_{2} & x_2^{\sigma^{n}} & \cdots & x_2^{\sigma^{kn}} &\varepsilon_2 \\
        \cdots & \cdots & \cdots & \cdots & \cdots \\
        x_g & x_g^{\sigma^{n}} & \cdots & x_g^{\sigma^{kn}} &\varepsilon_g 
    \end{pmatrix}
\end{align}
Then the rank of this matrix is not maximal if and only if $\varepsilon_i =0$ for all $i=1,\dots,g$.

[Proposition prop:ik-plus-em-is-k of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] $\textbf{IK} + \varphi \lor \neg \varphi = \textbf{K}$.
  \begin{proof}
    ($\subseteq$) Trivial.
    ($\supseteq$)
    We first show that $\textbf{IK} + \varphi \lor \neg \varphi \vdash \textsf{Dual}_\Box$.
    The following derivations prove it in both directions.
    \begin{center}
      \AxiomC{$ $}
      \RightLabel{\scriptsize{Prop.\ (prop:ik-partial-duality-2 of the paper)}}
      \UnaryInfC{$\neg \Diamond \neg \varphi \to \Box \neg \neg \varphi$}

      \AxiomC{$ $}
      \UnaryInfC{$\varphi \lor \neg \varphi$}
      \UnaryInfC{$\neg \neg \varphi \to \varphi$}
      \RightLabel{\scriptsize{$\textsf{M}_\Box$}}
      \UnaryInfC{$\Box \neg \neg \varphi \to \Box \varphi$}

      \RightLabel{\scriptsize{Syll.}}
      \BinaryInfC{$\neg \Diamond \neg \varphi \to \Box \varphi$}
      \DisplayProof
    \end{center}
    \begin{center}
      \AxiomC{$ $}
      \RightLabel{\scriptsize{Prop.\ (prop:ik-partial-duality of the paper) (2)}}
      \UnaryInfC{$\Diamond \neg \varphi \to \neg \Box \varphi$}
      \UnaryInfC{$\neg \neg \Box \varphi \to \neg \Diamond \neg \varphi$}

      \AxiomC{$ $}
      \UnaryInfC{$\Box \varphi \to \neg \neg \Box \varphi$}

      \RightLabel{\scriptsize{Syll.}}
      \BinaryInfC{$\Box \varphi \to \neg \Diamond \neg \varphi$}
      \DisplayProof
    \end{center}
    We note that the second derivation does not use $\varphi \lor \neg \varphi$ and thus is possible in $\textbf{IK}$ and even in $\textbf{WK}$.
    Then, $\textbf{IK} + \varphi \lor \neg \varphi \supseteq \textbf{K}_\Box + \textsf{Dual}_\Box = \textbf{K}$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

