[Lem 54 (\hspace{-0.05em}{{\cite[Proof of Proposition~2) of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] {lalley2000rate}}}]

    For all shuffle process with pile size $\vec\bn$, suppose that there exists $H(\vec\bn)\subset [N]$ such that (with $E(H)$ the subgraph of the path graph induced by vertex set $H$):
		\begin{equation}

		\begin{aligned}
			|H(\vec\bn)|&\geq N^{1/2} \\
			|\partial H(\vec\bn)|&\leq 2|H|^{1/2}\\
			\mathbb P\left[|E(G)\cap E(H(\vec\bn))|\geq |H(\vec\bn)|^{\frac{1}{2}+\delta}\right]&\to 1.
		\end{aligned}
		\end{equation}
	Then if $\nu \sim \bP(\vec\bn, K)$ and $K\leq (\widetilde C_{\mu}-\eps) \log N$, we have
	\begin{equation}

        \nu\Big(\#\{i\in H: \sigma(i)<\sigma (i+1)\}\leq |H(\vec\bn)|/2+|H(\vec\bn)|^{1/2+{\delta/2}}\Big)
        \to 0,
    \end{equation}  
        where the limit is uniform for all $\vec\bn$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-Step 1 of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Let $(a_k)_{k\ge 2}$ be the sequence defined in (equation eqn-a_n of the paper).
Let $z \in \mathscr{Z}_T$ and $(z_n)$ be a $\mathscr{Z}_T$-valued sequence  such that
\begin{align}
z_n \to z \mbox{  in } \mathscr{Z}_T  \mbox{ as $n \to \infty$}.
\end{align}

Then, for every  $m\in \mathbb{N}$ and every integer $k> 2$ we have
\begin{equation}
\begin{aligned}
    &\lim_{n\to \infty} \int_0^t \int_{Y} a_k(P_m F(s,z_n(s),y))\, \nu (\mathrm{d} y) \, \mathrm{d}s \\
&  \hspace{2truecm}= \int_0^t \int_{Y} a_k(P_m F(s,z(s),y))\, \nu (\mathrm{d} y) \, \mathrm{d}s
\end{aligned}
\end{equation}
and 	
	\begin{equation}
	\begin{aligned}
    &
    \lim_{n\to \infty} \int_0^t \int_{Y} a_k(P_n F(s,z_n(s),y))\, \nu (\mathrm{d} y) \, \mathrm{d}s 
    \\ &  \hspace{2truecm}
    = \int_0^t \int_{Y} a_k(F(s,z(s),y)) \, \nu (\mathrm{d} y) \, \mathrm{d}s.
	\end{aligned}
    \end{equation}

