[Def Surface tension of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $L,M\geq 1$ and $\beta>0$. The surface tension of the model on $\mathcal{R}(L,M)$ at inverse temperature $\beta$ is defined as
\begin{equation}
    \boldsymbol{\tau}^{L,M}(\beta):=-\frac{1}{L^{d-1}}\log  \frac{\mathbf{Z}^{+,-}_{\mathcal{R}(L,M),\beta}}{\mathbf{Z}^{+,+}_{\mathcal{R}(L,M),\beta}}.
\end{equation}
Moreover, we also define
\begin{equation}
    \boldsymbol{\tau}^L(\beta):=\liminf_{M\rightarrow \infty}\boldsymbol{\tau}^{L,M}(\beta), \qquad \boldsymbol{\tau}(\beta):=\liminf_{L\rightarrow \infty}\boldsymbol{\tau}^{L}(\beta).
\end{equation}

[Proposition 1 of arXiv:2506.19273, 'A large deviation view of \emph{stationarized} fully lifted blirp interpolation'] Let vectors $\m = [\m_1 ]$, $\p=[\p_0,\p_1,\p_2]$,  and $\q=[\q_0,\q_1,\q_2]$ be such that  $\p_0\geq \p_1\geq \p_2=0$ and $\q_0\geq \q_1\geq \q_2=0$. For $k\in\{1,2\}$  let the elements of $G\in\mR^{m \times n},u^{(4,k)}\in\mR^1,\u^{(2,k)}\in\mR^{m\times 1}$, and $\h^{(k)}\in\mR^{n\times 1}$ be independent standard normals. Set $a_k=\sqrt{\p_{k-1}\q_{k-1}-\p_k\q_k}$, $b_k=\sqrt{\p_{k-1}-\p_k}$, $c_k=\sqrt{\q_{k-1}-\q_k}$, and  ${\mathcal U}_k=[u^{(4,k)},\u^{(2,k)},\h^{(k)}]$. Let sets ${\mathcal X}=\{\x^{(1)},\x^{(2)},\dots,\x^{(l)}\}$, $\bar{{\mathcal X}}=\{\bar{\x}^{(1)},\bar{\x}^{(2)},\dots,\bar{\x}^{(l)}\}$, and ${\mathcal Y}=\{\y^{(1)},\y^{(2)},\dots,\y^{(l)}\}$  (with $\x^{(i)},\bar{\x}^{(i)}\in \mR^{n}$ and $\y^{(i)}\in \mR^{m}$), real scalars $\beta$, $p$, and $s$ (with $\beta,p\geq 0$), and function $f_{\bar{\x}^{(i_3)}} (\cdot): \mR^n\rightarrow \mR$ be given. One then has for function
\begin{equation}
\psi( t)  =  \mE_{G,{\mathcal U}_2} \frac{1}{p|s|\sqrt{n}\m_1}
\log \lp  \sum_{i_3=1}^{l}  \lp  \mE_{{\mathcal U}_1} \lp \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3 )}} \rp^{s}\rp^{\m_1} \rp^p \rp,
\end{equation}
with
\begin{eqnarray}
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T(b_2\u^{(2,1)}+b_2\u^{(2,2)})\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(a_1u^{(4,1)}+a_2u^{(4,2)}) +\sqrt{1-t}\|\y^{(i_2)}\|_2(c_1\h^{(1)}+c_2\h^{(2)})^T\x^{(i)}
\nonumber \\
& &
   + f_{\bar{\x}^{(i_3)}  } (\x^{(i_1)}) ,
 \end{eqnarray}
that
\begin{eqnarray}
\frac{d\psi(t)}{d\p_1}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \phi^{(1,\p)}\nonumber \\
\frac{d\psi(t)}{d\q_1}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \phi^{(1,\q)},
 \end{eqnarray}
where $\phi$'s are as in (\ref{eq:cpt8}).

[Lemma l: taylor series of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $\varepsilon>0$. Suppose that $f\in L^1(\R^d, \C)$ is chosen such that $\hat{f}\in\cC_c^{d+1}$ with $\hat{f}(k)=0$ for all $k\in B_\varepsilon^c$. Then
    \begin{equation}
        f(y+ x) = \sum_{q=0}^\infty \frac{1}{q!} f^{(q)}(y) x^{\otimes q}, \quad x,y\in\R^d,
    \end{equation}
    and there is a $c>0$ such that
    \begin{equation}
        \int\sup_{u\in B_1} \|f^{(q)}(x+u)\|\, dx \leq c (q+1)^{d+1}\varepsilon^q,\quad q\in\N_0.
    \end{equation}
    \begin{proof}
        The first part of the assertion, i.e., that~(equation e: taylor series f of the paper) holds, directly follows from the Paley-Wiener theorem, as it implies that $f$ is an entire function; see, e.g.,~[Stein_Weiss_1971]. Additionally, we use a Paley-Wiener-type argument in the following to show that there exists a $c>0$ such that 
        \begin{equation}
            \|f^{(q)}(x)\| \leq c (q+1)^{d+1}\varepsilon^q\frac{1}{\max(\|x\|^{d+1}, 1)}.
        \end{equation}
        Then the second part follows as well.

        Let $\varepsilon>0$, suppose that $f\in L^1(\R^d, \C)$ such that $\hat{f}\in\cC^{d+1}_c$ with $\hat{f}(k)=0$ for all $k\in B_\varepsilon^c$, and define $f_\varepsilon:=f(\tfrac{\cdot}{\varepsilon})$. We obtain that $\hat{f_\varepsilon}(k)=\varepsilon^d \hat{f}(\varepsilon k), k\in\R^d$, and hence that $\hat{f_\varepsilon}(k)=0$ for all $k\in B_1^c$. Further, $f^{(q)}(x) = \varepsilon^{q} f_\varepsilon^{(q)}(\varepsilon x)$ for $q\in\N_0, x\in\R^d$, and
        \begin{equation*}
            \frac{1}{\max(\varepsilon^{d+1}\|x\|^{d+1}, 1)} \leq \max(\varepsilon^{-(d+1)}, 1)\frac{1}{\max(\|x\|^{d+1}, 1)}, \quad x\in\R^d.
        \end{equation*}
        Since $\max(\varepsilon^{-(d+1)}, 1)$ can be a part of the constant, this transformation allows us to assume $\varepsilon=1$ without loss of generality. Now let $q\in\N_0$, $i\in\{1,...,d\}$, and $x\in\R^d$ with $x_i\neq0$. Then, using Plancherel's theorem and $d+1$ times partial integration,
        \begin{align*}
            \|f^{(q)}(x)\| &= \frac{1}{(2\pi)^d}\bigg\|\int \widehat{f^{(q)}}(k) e^{-i\langle k, x\rangle}\, dk\bigg\|\nonumber\\
            &= \frac{1}{(2\pi)^d}\bigg\|\int_{B_1} k^{\otimes q} \hat{f}(k) e^{-i\langle k, x\rangle}\, dk\bigg\|\nonumber\\
            &= \frac{1}{(2\pi)^d|x_i|^{d+1}} \bigg\|\int_{B_1} \partial_i^{d+1}\big(s\mapsto s^{\otimes q} \hat{f}(s)\big)(k) e^{-i\langle k, x\rangle}\, dk\bigg\|\nonumber\\
            &\leq \frac{\kappa_d}{(2\pi)^d|x_i|^{d+1}} \sup_{k\in B_1}\bigg\|\partial_i^{d+1}\big(s\mapsto s^{\otimes q} \hat{f}(s)\big)(k)\bigg\|.
        \end{align*}
        Further, for $k\in B_1$, we have
        \begin{align*}
            \bigg\|\partial_i^{d+1}\big(s\mapsto s^{\otimes q} \hat{f}(s)\big)(k)\bigg\| &= \bigg\|\sum_{n=0}^{d+1} \binom{d+1}{n}\partial_i^{n}\big(s\mapsto s^{\otimes q}\big)(k) \partial_i^{d+1-n}\hat{f}(k)\bigg\|\nonumber\\
            &= \bigg\|\sum_{n=0}^{\min(d+1, q)} \binom{d+1}{n}\frac{q!}{(q-n)!}\big(e_i^{\otimes n}\otimes k^{\otimes (q-n)}\big) \partial_i^{d+1-n}\hat{f}(k)\bigg\|\nonumber\\
            &\leq (q+1)^{d+1} \sum_{n=0}^{d+1} \binom{d+1}{n} \bigg\|\partial_i^{d+1-n}\hat{f}(k)\bigg\|.
        \end{align*}
        The fact that $\hat{f}\in\cC^{d+1}$ implies that there is a $c_1>0$ independent of $i$ and $k$ such that
        \begin{equation*}
            \sum_{n=0}^{d+1} \binom{d+1}{n} \bigg\|\partial_i^{d+1-n}\hat{f}(k)\bigg\| \leq c_1, \quad k\in B_1.
        \end{equation*}
        Therefore, for $x\in\R^d\setminus\{0\}$,
        \begin{equation*}
            \|f^{(q)}(x)\| \leq \frac{\kappa_d c_1(q+1)^{d+1}}{(2\pi)^d\|x\|_\infty^{d+1}} \leq \frac{\sqrt{d}\kappa_d c_1(q+1)^{d+1}}{(2\pi)^d\|x\|^{d+1}}.
        \end{equation*}
        It remains to find a bound for small $x$, which is much simpler, as
        \begin{equation*}
            \|f^{(q)}(x)\| = \frac{1}{(2\pi)^d}\bigg\|\int_{B_1} k^{\otimes q} \hat{f}(k) e^{-i\langle k, x\rangle}\, dk\bigg\|\leq \frac{\kappa_d}{(2\pi)^d}\sup_{k\in B_1} \|\ha (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 26 (evolution of the gradient; Li--Yau estimate) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Along the flow, each $u := f_i^2$ satisfies

	\begin{equation}
		\big( \partial_t - \Delta \big)\, \big| \nabla u \big|^2 \;=\; -\, 2\, \big| \nabla^2 u \big|^2 \,,
	\end{equation}

	and consequently the Li--Yau quantity \cite{LY} $| \nabla u |^2 / u$ is uniformly bounded:

	\begin{equation}
		\sup_{\widehat{M}} \frac{| \nabla u |^2}{u} (\cdot, t) \;\leq\; C_0 \;:=\; \max \left\{ \sup_{\widehat{M}} \frac{| \nabla u |^2}{u} (\cdot, 0) \,, \; 4\, p_i \right\} \qquad \text{for all } t \in [0, T) \,.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

