[Lemma 35 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exist a sequence $\{\varepsilon_n\}_{n \in \mathbb{N}} \subset (0,1)$ and a nonnegative function
$v_{\text{{\tiny $\delta$}}} \in W^{1,2}(0,T\,;L^2(\Omega)) \cap L^\infty (0,T\,;H^1(\Omega))$ such that the following convergences hold as $n \to \infty$\,:

\begin{gather}

\varepsilon_n \downarrow 0,\\

z_{\text{{\tiny $\delta,\!\varepsilon_n$}}} \longrightarrow v_{\text{{\tiny $\delta$}}} \quad \text{in} \quad C([0,T]\,;L^2(\Omega)),\\

v_{\text{{\tiny $\delta,\!\varepsilon_n$}}} \longrightarrow v_{\text{{\tiny $\delta$}}} \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)).
\end{array}
\right.
\end{gather}

[Definition 1 (Sign-balanced sequences of functions) of arXiv:2604.22567, 'Sign-balance of random Laplace eigenfunctions'] $\, $

\begin{enumerate}[i.]

\item For $x\in \Mcc$ and $r>0$ below the injectivity radius $\inj(\Mcc)$ of $\Mcc$, the \textit{defect} of a measurable function $f:\Mcc\rightarrow\R$ on $B_{r}(x)$ is 
\begin{equation}

\Dc(x;r)=\Dc_{f}(x;r) := \frac{1}{|B_{r}(x)|}\int\limits_{B_{r}(x)} H(f(y))dy \in [-1,1],
\end{equation}
where $H(\cdot)$ is the sign function 
\begin{equation}

H(t)= \begin{cases}
1 &t\ge 0 \\ -1 &t<0
\end{cases} = \id_{\cdot \ge 0}(t) - \id_{\cdot < 0}(t).
\end{equation}
 \item Let $\{r_{j}\}\subseteq \R_{>0}$ be a sequence of positive numbers, and $f_{j}:\Mcc\rightarrow\R$ a sequence of measurable functions. The \textit{sign-imbalance} of $f_{j}$ at scale $r_{j}$ is 
\begin{equation}

\Bc(f_{j};r_{j}):= \sup\limits_{\substack{x\in\Mcc}}|\Dc_{f_{j}}(x;r_{j})| \in [0,1].
\end{equation}
We say that the $f_{j}(\cdot)$ are \textit{sign-balanced} above the scale $r_{j}$ if
\begin{equation}

\lim\limits_{j\rightarrow \infty} \sup_{r \ge r_j} \Bc(f_{j};r) = 0.
\end{equation}
\end{enumerate}

[Proposition prop:cone-Jacobi of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] With respect to the coordinates $(t,q)\in\mathbb R\times\Lambda$,
\begin{equation}
 J_{F,\mathcal C}
 =\frac{\sqrt2}{2}e^{-2t}
 \left[4\phi''(1)(\partial_t^2+\partial_t)+\Delta_\Lambda+2\right].
\end{equation}
If
\begin{equation}
 -(\Delta_\Lambda+2)\varphi_j=\lambda_j\varphi_j,
\end{equation}
then the indicial exponents of the mode $e^{\beta t}\varphi_j$ are
\begin{equation}
 \beta_j^\pm
 =-\frac12\pm\frac12
 \sqrt{1+\frac{\lambda_j}{\phi''(1)}}.
\end{equation}
For the constant mode $\lambda_0=-2$, these are
\begin{equation}
 \beta_0^+=-\mu,
 \qquad
 \beta_0^-=\mu-1.
\end{equation}

