[Lemma cuttimes of arXiv:2411.13505, 'Capacity of loop-erased random walk'] We have
\begin{equation}
	\begin{split}
		\lim_{n\rightarrow\infty}\mathbb{E}\left[|n-\rho_{n(\log n)^{-1/3}}|\right]=\lim_{n\rightarrow\infty}\mathbb{E}\left[|(\log n)^{1/3}n-\ell_n|\right]=0.
	\end{split}
\end{equation}
Furthermore, there exists $C>0$ such that for all $n$ and all $m$ such that $|n-m|\geq (\log m)^{-6}m$,
\begin{equation}
	\mathbb{P}(\text{there are no cut times between $n$ and $m$})\leq C\frac{\log\log m}{\log m}.
\end{equation}

[Theorem 14 (Finite space-time condition for non-symmetric interactions) of arXiv:2604.15753, 'The truncation property and continuity for \\ the long-range contact process on $\mathbb{Z'] Let $\lambda \in \Lambda$  satisfy  $\lambda_{o,y} =\mathcal{O}( \|y\|^{-\alpha})$ for some $\alpha>2d+1$,
 and let $\delta>0$ so that $\phi(\lambda,\delta)>0$. Then there is $r>1$ so that the following holds: for every  $\epsilon > 0$ there are choices of $A \subset \bZ^d$ finite and $L \in (0,\infty)^d$, $T\in (0,\infty)$ and $\theta =(0,\dots,0,\theta_d) \in \bR^d$ such that 
\begin{align}
\tag{C3}
 & \bP_{\lambda,\delta} \left(\exists x\in B_{L,T}^{\theta}  \colon A(x) \subset \leftidx{_{B_{2L,T+1}^{\theta}}}{A}{_{T+1}^{A}} \right) \geq 1-\epsilon;
 \\ &    \tag{C4}
      \bP_{\lambda,\delta} \left( \exists (x,t)  \in S_{L,T,2r LT}^{\theta,A,\pm} \colon A(x) \subset  \leftidx{_{B_{2(1+r)LT,T+1}^{\theta}}}{A}{_{t+1}^{A}} \right) \geq 1-\epsilon.
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 18 of arXiv:2609.02331, 'Metastability of Interacting Stochastic Systems with Countably Many Metastable States: Bey'] For all $x\in\mathscr{V}$ and $T,\epsilon>0$, there
exist compact sets $\mathcal{K}_{N}$, $N\ge1$ such that
\begin{equation}
\left\{ y\in\mathscr{V}:\xi^{y}_{N}\in\mathcal{K}_{N}\quad\text{for some}\enspace N\ge1\right\} \quad\text{is a finite set},
\end{equation}
and
\begin{equation}
\limsup_{N\to\infty}\mathbb{Q}^{N}_{\xi^{x}_{N}}\left[\mathcal{H}_{\Omega_{N}\setminus\mathcal{K}_{N}}\le T\right]<\epsilon.
\end{equation}

[Cor cA3 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] For any $q\in (0,p)$
\begin{equation}\begin{aligned}
\sup_{t\in[t_k, t_{k+1})} \mathbf{E}^{(N)}_{t_1,\dots,t_N}\Big[\|\Delta_t^n\|^q\Big|\mathcal{F}_{t_k}\Big]
\leq_C \|\Delta_{t_k}^n\|^q
& + h_n^{(\frac{p-q}{\chi}\wedge q) + (1\wedge\frac{q}{2})}(1+\|X_{t_k}^{(n)}\|^p)
+ h_n^{\frac{p-q}{\chi}\wedge q}(1+\|X_{t_k}^n\|^{p})\\
&+ h_n^{1\wedge\frac{q}{2}}  (U_{t_k}^n)^q
+h_n^{(\frac{p-q}{\chi }\wedge q)   +(1\wedge\frac{q}{2})} (U_{t_k}^n)^{(p-q)\wedge (q\chi)}
+h_n^{1\wedge\frac{q}{2}}
\end{aligned}\end{equation}
for $n$ large enough uniformly over
$N\in\mathbb{N}_0$, partitions $\{t_1,\dots, t_N\}$,  and $k=0, \dots, N$.

