[Definition definition-KMP of arXiv:2507.19222, 'Convergence of the KMP model to the KPZ equation'] The KMP model $\left(\eta(t,x)_{x\in \mathbb{Z}}\right)_{t \geqslant 0}$ is a continuous-time Markov process defined on the state space $\Omega=\mathbb{R}_{+}^{\mathbb{Z}}$. The infinitesimal generator is given by 
    \begin{equation*}
        \mathcal{L}=\sum_{x\in \mathbb{Z}}\mathcal{L}_{x,x+1}\,,
    \end{equation*}
    where the action of the linear operators $\mathcal{L}_{x,x+1}$ on local functions $f:\Omega\to \mathbb{R}$ reads
    \begin{equation*}
    \begin{split}
 \left(\mathcal{L}_{x,x+1}f\right)(\eta)=\int_{0}^{1}&\left[f(\ldots,\eta(x-1),\,p(\eta(x)+\eta(x+1)),\,(1-p)(\eta(x)+\eta(x+1)),\,\eta(x+2),\ldots)\right.
 \\&\left.\quad-f(\eta)\right]\frac{p^{\alpha-1}(1-p)^{\alpha-1}}{\text{B}(\alpha,\alpha)}dp \,.
  \end{split}
 \end{equation*}

[Proposition 9 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $p,q \geq 0$ and $\lambda, \gamma> 0$. Then, for $x,b \in [0,a]$, we have that
			\begin{align}
				\E_x \Bigl( \ee^{-q T_{b,U}^{-,\gamma} - p \int_0^{T_{b,U}^{-,\gamma}} 1_{\left\{U_s<b\right\}} \mathrm{d} s} \; \1_{\{T_{b,U}^{-,\gamma} < T_{a,U}^{+,\lambda}\}}\Bigr) &=   \frac{\int^\infty_0 \ee^{-\varphi_{q+\lambda}y}\, \Bigl( \gamma \int^b_0 \overline{w}_b^{(q+\gamma_p,-\gamma_p)}(y+a;u) \dd u\Bigr) \dd y}{\int^\infty_0 \ee^{-\varphi_{q+\lambda}y} \,  \overline{z}_b^{(q+\gamma_p,-\gamma_p)}(y+a) \dd y} \overline{z}_b^{(q+\gamma_p,-\gamma_p)}(x) \notag \\
				&\quad - \gamma \int^b_0 \overline{w}_b^{(q+\gamma_p,-\gamma_p)}(x;u) \dd u , 


			\end{align} 
			where $\overline{w}_b^{(\cdot, \cdot)}$ and $\overline{z}_b^{(\cdot, \cdot)}$ are defined in Eqs.~\eqref{eq:SecondGenFunc-RefractedWTilde1} and \eqref{eq:SecondGenFunc-RefractedZTilde1}, respectively.

