body:
[Defi def:wattsstrogatz of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] Let $n > 1$ be an integer, $K$ a positive even integer with $K<n$, and $p \in [0,1]$. The Watts--Strogatz random graph of size $n$ with parameters $(K,p)$, denoted $WS_n(K,p)$, is constructed as follows:

\begin{enumerate}
    \item \textbf{Initial lattice.}  
    Let $V_n = \{1,2,\dots,n\}$ denote the set of vertices of $WS_n(K,p)$. Arrange the vertices on a clockwise cycle. Each vertex $i \in V_n$ is connected to its $K/2$ nearest neighbors on each side, forming a regular ring lattice of degree $K$.

    \item \textbf{Rewiring step.}  
    For $i = 1,2,\dots,n$ in increasing order, and for each edge $\{i,j\}$ such that $j$ is one of the $K/2$ rightmost neighbors of $i$ (taken in increasing order), independently with probability $p$, rewire the edge $\{i,j\}$ as follows: remove the edge $\{i,j\}$ and add the edge $\{i,k\}$, where $k$ is chosen uniformly at random from the set of vertices in $V_n \setminus \{i,j\}$ that are not adjacent to $i$.
\end{enumerate}

[Lemma lem:gaussian_tail_scaled of arXiv:2607.27810, 'Perturbed Beta Corners Process'] In the setting of (thm:crystallization_scaled of the paper) there are
$C,c,\beta_1>0$, depending only on $N$, $\mathbf{z}$ and $\mathsf{a}$,
such that
\begin{equation}

	\mathbb P\Bigl(\sqrt{\beta}\hspace{1pt}\max_{i,k}|y_i^k(\beta)-\bar{\mathsf{y}}_i^k|\ge s\Bigr)
	\le C\hspace{1pt} e^{-c\hspace{1pt} s^{2}}
	\qquad\text{for all }s>0\text{ and }\beta\ge\beta_1.
\end{equation}

[Lem 1 of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] For any simple path $\gamma = (x_t,y_t)$, if $\gamma|_{[0,1]}$ has infinite radius of convergence for its log-signature and $x_t\in[-1,1]$ for all $t\in[0,1]$, then looking at any fixed horizontal level $y=a$ of the image $\gamma([0,1])$, we only have the following two cases: 
\begin{itemize}
       \item The right street copies the left street. In the sense that for any $x\in(0,1)$, $(x,a)\in\gamma([0,1])$, we have $(x-1,a)\in\gamma([0,1])$. For any $x\in(-1,0)$, $(x,a)\in\gamma([0,1])$ we have $(x+1,a)\in\gamma([0,1])$.

       \item Both capture the missing points of the other. In the sense that for any $x\in(0,1)$, $(x,a)\notin\gamma([0,1])$, we have $(x-1,a)\in\gamma([0,1])$. For any $x\in(-1,0)$, $(x,a)\notin\gamma([0,1])$, we have $(x+1,a)\in\gamma([0,1])$.
\end{itemize}

[Theorem thm:main:IPS:ergodicity of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\Phi$ be a $d$-dimensional IPS with clock rate~$1$ and a strictly positive local transition rule $\varphi\colon\Sigma^N\times\Sigma\to(0,1)$, and suppose that $\Phi$ admits a stationary Bernoulli measure $\lambda$.
	Then, there exist constants $\alpha,\beta>0$ 
	such that
	\begin{equation}
		\norm[\big]{(\mu\Phi^t)_J - \lambda_J}_\mathsf{TV} \leq \alpha\mathrm{e}^{-\beta t} n^{d/2}
	\end{equation}
	for every initial measure $\mu$, every finite region $J\subseteq\mathbb{Z}^d$ with diameter~$n$, 
	and every $t\geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2609.01447, '2609.01447'] Let $m\ge1$ be an integer.  For all $x,y\in L_{2m}(\mu)$,
\begin{equation}
 \|x^m-y^m\|_2
 \le
 m\max\{\|x\|_{2m},\|y\|_{2m}\}^{m-1}
 \|x-y\|_{2m}.
\end{equation}
If $m$ is odd, then
\begin{equation}
 \|x^m-y^m\|_2
 \ge 2^{-(m-1)}\|x-y\|_{2m}^m.
\end{equation}
If $m$ is even, then every $a,b\in\R$ satisfy
\begin{equation}
 |a-b|^{2m}
 \le
 4^m\bigl(
 |a^m-b^m|^2+|a|^m|a-b|^m
 \bigr).
\end{equation}

[Lm Expectation G almost Expectation  tilde G of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] We have 
    \begin{equation}
        \sup_{t \in [0,T]}|\mathbb{E}\Tilde{G}(M(t)/\sqrt{n},\theta(t))-\mathbb{E} G(M(t)/\sqrt{n},\theta(t))| \lesssim e^{-c\frac{n}{\log(n)}},
    \end{equation}
    for sufficiently large $n$.

