[Corollary cor:main:mixing-time of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\Phi$ be a $d$-dimensional PCA or IPS with a strictly positive local transition rule $\varphi\colon\Sigma^N\times\Sigma\to(0,1)$, and suppose that $\Phi$ admits a stationary Bernoulli measure $\lambda$.
	Then,

	\begin{equation}
		t_\mathsf{mix}(J,\varepsilon) \leq

			\frac{d}{2\beta}\log n + \frac{\log\alpha - \log\varepsilon}{\beta}
	\end{equation}
    for every $J\subseteq\mathbb{Z}^d$ with diameter~$n$,
	where $\alpha$ and $\beta$ are the constants in Theorems~(thm:main:PCA:ergodicity of the paper) or~(thm:main:IPS:ergodicity of the paper), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 21 (Local Discrepancy) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] The local discrepancy of $\emprashomonset$, at a test instance x, is the average fraction of conflicting predictions between models in $\emprashomonset$ over samples $\localtest_1,\dots.,\localtest_{\nogaussianpts} \in \ltwohsphere(x,\sigma)$,and the prediction of a reference model at x, and is defined as,
\begin{align}
     \localdisagens(x) = \frac{1}{\abs{\emprashomonset}}\sum_{h_k \in  \emprashomonset}\frac{1}{{\nogaussianpts}}\sum_{j=1}^{\nogaussianpts}\Indic{h_k(\localtest_j) \ne h_{0}(x)},
\end{align}
where we choose the reference model as $h_{0}(x) = \Indic{\frac{1}{\abs{\emprashomonset}}\sum_{f_k \in  \emprashomonset}f_k(x) \ge \frac{1}{2}}$

[Definition 26 (Acoustical subsets of spacetime) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define the following ``acoustical subsets'' of spacetime:
\begin{subequations}
\begin{align}
\Sigma_{t'} 
& \eqdef 
\{(t,x^1,x^2,x^3) \in \R\times\R\times\T^2 \ | \ t = t'\}, 

	\\
\nullhyparg{u'} 
& \eqdef \{(t,x^1,x^2,x^3) \in \R\times\R\times\T^2 \ | \ u(t,x^1,x^2,x^3) = u'\}, 

	\\
\ell_{t',u'} 
& 
\eqdef 
\Sigma_{t'} \cap \nullhyparg{u'} 
= 
\{(t,x^1,x^2,x^3) \in \R\times\R\times\T^2 \ | \ t= t',\ u(t,x^1,x^2,x^3) = u'\}. 

\end{align}
\end{subequations}Given real numbers $u_1 \leq u_2$ and $t_1 \leq t_2$, we define the following ``truncated'' subsets of spacetime:
\begin{subequations}
\begin{align}
\Sigma_{t'}^{[-\rightu,\leftu]} 
& \eqdef \Sigma_{t'} \cap \{(t,x^1,x^2,x^3) \in \R\times\R\times\T^2 \ | \ u_1 \leq u(t,x^1,x^2,x^3) \leq u_2 \}, 

	\\
\nullhyparg{u'}^{[t_1,t_2]} 
& \eqdef \nullhyparg{u'} \cap \{(t,x^1,x^2,x^3) \in \R\times\R\times\T^2 \ | \ t_1 \leq t \leq t_2 \}.

\end{align}
\end{subequations}

[Proposition eigenvector-rescaling-constant-on-each-lumped-point of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] Let $v \in \mathbb{R}_+^{\mathcal{Y}}$. The following two statements are equivalent.
\begin{enumerate}[$(i)$]
    \item[(i)\xspace] For any  irreducible lumpable matrix $F \in \mathcal{F}_{ \kappa}^+(\mathcal{Y}, \mathcal{E})$, $v$ satisfies \begin{equation*}
\diag(v) F \diag(v)^{-1} \in \mathcal{F}_{\kappa}^{+}(\mathcal{Y}, \mathcal{E}).
    \end{equation*}
    \item[(ii)\xspace] 
    For any $x \in \mathcal{X}$, $v$ satisfies  $v(y_1) = v(y_2)$ for any $y_1, y_2 \in \mathcal{S}_{x}$.
\end{enumerate}

